local Text_CollectionHall = readonly({
  CollectionHall_100308_Title = {
    Text = "帕拉黛斯號"
  },
  CollectionHall_100309_Title = {Text = "畸世繪"},
  CollectionHall_100310_Title = {
    Text = "不朽極晝"
  },
  CollectionHall_100442_Desc = {
    Text = "<Title:簡介>\n出生於人類富商家庭，體內卻流淌著食屍鬼的血。半人半食屍鬼的血脈給了他獨特的天賦，讓他能夠看到常人所不能看到的世界。那個世界瘋狂，荒誕，絢爛的色彩讓他無法自拔。\n幾乎沒有猶豫，皮克曼選擇用畫筆記錄下他所看到的一切。他沉浸其中，在日復一日的描繪中擁有了純熟的畫技。\n主流的審美將皮克曼徹底拋棄，沒有人能夠接受他那套瘋狂的論調。皮克曼常常為此難過，但他從來沒有放棄過。\n最終，皮克曼擁抱融蝕，徹底覺醒了食屍鬼的血脈。他離開人類世界，來到食屍鬼的王城。終有一天，他要將真實世界裡那些奇幻瘋狂的景象，一一呈現在世人面前。"
  },
  CollectionHall_100442_LockTip = {
    Text = "喚醒「皮克曼」後解鎖"
  },
  CollectionHall_100458_Desc = {
    Text = "把煩惱暫時放下，讓疲倦快快遠離。\n讓我們在溫暖的篝火旁，稍稍休息一下吧。"
  },
  CollectionHall_100458_LockTip = {
    Text = "完成意識潛遊「不朽極晝」"
  },
  CollectionHall_100458_Title = {
    Text = "篝火溫憩"
  },
  CollectionHall_100459_Desc = {
    Text = "燃燒吧，燃燒吧，將屬於你的一切，盡數燃燒吧。\n然後在那無盡的烈火中，開啟你和世界的葬禮吧！"
  },
  CollectionHall_100459_LockTip = {
    Text = "完成意識潛遊「不朽極晝」"
  },
  CollectionHall_100459_Title = {
    Text = "烈火中的葬禮"
  },
  CollectionHall_100460_Desc = {
    Text = "“我說過了，無論以哪種方式，我都要將大家帶回家。”\n“我會燃燒屬於我的一切，然後……\n”用這來自群星的業火，將這虛假、污穢、混沌的世界燃燒殆盡！“\n”我以凱蒂古拉之名宣告！“\n”天將拂曉！“"
  },
  CollectionHall_100460_LockTip = {
    Text = "完成意識潛遊「不朽極晝」"
  },
  CollectionHall_100460_Title = {
    Text = "燃燒一切的拂曉"
  },
  CollectionHall_100461_Desc = {
    Text = "癲狂的死狀如萬花筒般迴旋，源自疾病與屍體的腥甜氣息是最好的熏香，你們隔著無數赴死之人遙遙舉杯——若死亡是註定，就讓我們歡欣地奔赴這場舞會，在舞步的最後一拍共同墜入地獄的大門。"
  },
  CollectionHall_100461_LockTip = {
    Text = "完成意識潛遊「燃燒的群宴」困難難度"
  },
  CollectionHall_100461_Title = {
    Text = "紅酒、鮮花與華麗之死"
  },
  CollectionHall_100462_Desc = {
    Text = "很久很久以前，她是宇宙中獨裁的帝王，一切所見的都歸於她的御下。\n很久很久以後，她的眼中只能看見漫無邊際的塵埃，從此她所掌管的，只剩荒蕪與寂寞。"
  },
  CollectionHall_100462_LockTip = {
    Text = "完成意識潛遊「燃燒的群宴」"
  },
  CollectionHall_100462_Title = {
    Text = "掌管荒蕪的女王"
  },
  CollectionHall_100463_Desc = {
    Text = "她猖獗、暴戾、喜怒無常，同時她亦寬仁、博學、充滿智慧。\n她是荒淫的暴君，也是羔羊的庇護者，她賜予你愛，也賜予你死。這片土地上的一切生靈都要匍匐在她的腳下，尊敬地高呼她的名號。\n在女王的舞會上盡情沉醉吧，然後與她一起，沉入永恆的黑色火焰。"
  },
  CollectionHall_100463_LockTip = {
    Text = "完成意識潛遊「燃燒的群宴」"
  },
  CollectionHall_100464_Desc = {
    Text = "假如死前只能做最後一件事，那就跳舞吧。\n飲下甘醇的美酒，咽下香甜的煎肉，在狂歡的樂曲中盡情飛旋。\n要這世界在眼中最後的倒影，仍閃爍著迷醉的金光。"
  },
  CollectionHall_100464_LockTip = {
    Text = "完成意識潛遊「燃燒的群宴」困難難度"
  },
  CollectionHall_100465_Desc = {
    Text = "她總在湖中看到輝煌的舊日。\n風化的記憶如虛假的夢境，夢裡她坐在無邊廢墟之中，目睹屬於她的一切都如幻影一般模糊消散。\n在連那個夢境也將被忘記的時候，吹笛的使者穿過迷霧而來，引領她走向逝去之人的歸途。"
  },
  CollectionHall_100465_LockTip = {
    Text = "完成意識潛遊「燃燒的群宴」"
  },
  CollectionHall_100466_Desc = {
    Text = "群星間永不熄滅的存在再次睜開雙眼，將不朽的力量投射至這顆渾濁、污穢卻無比蔚藍的星球，\n與那四十億年前，遮天蔽日的太陽降臨時一模一樣。"
  },
  CollectionHall_100466_LockTip = {
    Text = "完成意識潛遊「不朽極晝」"
  },
  CollectionHall_100466_Title = {
    Text = "四十億年的再會"
  },
  CollectionHall_116205_Title = {
    Text = "再見永無鄉"
  },
  CollectionHall_116601_LockTip = {
    Text = "需要通關限時活動「極晝的終夜：交融的苦血」任一關卡"
  },
  CollectionHall_116601_Title = {
    Text = "極晝的終夜：交融的苦血"
  },
  CollectionHall_116868_Title = {
    Text = "再見，永無鄉"
  },
  CollectionHall_117619_Title = {
    Text = "天邊之外·下"
  },
  CollectionHall_117621_LockTip = {
    Text = "通關意識潛遊「天邊之外·下」任一關卡解鎖"
  },
  CollectionHall_117621_Title = {Text = "淨化"},
  CollectionHall_117957_LockTip = {
    Text = "限時幻衣活動 「不發糖就搗蛋」中完成免費抽取解鎖"
  },
  CollectionHall_117957_Title = {
    Text = "幽靈故事會"
  },
  CollectionHall_117958_Desc = {
    Text = "她遊離於記憶和過往之外，她穿過死和生的淤泥，靜默地與你重逢。"
  },
  CollectionHall_117958_LockTip = {
    Text = "完成調查行動7-19解鎖"
  },
  CollectionHall_117958_Title = {
    Text = "在棺槨中重逢"
  },
  CollectionHall_117959_Desc = {
    Text = "詩歌，情感，回憶，道德……一切都是累贅。這個道理，詩人們從不明白。"
  },
  CollectionHall_117959_LockTip = {
    Text = "完成特遣紀錄「玫瑰的棲居」困難難度"
  },
  CollectionHall_117960_Desc = {
    Text = "她堅持要單獨出演，否則就要給你一槍。\n但最後她獲得了一位好學生，還有一匹狼。"
  },
  CollectionHall_117960_LockTip = {
    Text = "完成異夢視界「再見永無鄉」"
  },
  CollectionHall_117960_Title = {
    Text = "獨角劇碼"
  },
  CollectionHall_117961_Desc = {
    Text = "吃啊，埃弗！看啊，埃弗！\n瘋狂和真實之間，由色彩與藝術架構出的橋樑！\n只有我們兩個在這裡，只有我們能見到真相！"
  },
  CollectionHall_117961_LockTip = {
    Text = "完成意識潛遊「畸世繪」"
  },
  CollectionHall_117961_Title = {
    Text = "歡迎你！埃弗！"
  },
  CollectionHall_117962_Desc = {
    Text = "每寫下一段詩句，便會長出一片花瓣吧，她想。\n她用生命澆灌字句，當最後的詩篇完成，她們便能回到曾經的花園。"
  },
  CollectionHall_117962_LockTip = {
    Text = "完成特遣紀錄「玫瑰的棲居」困難難度"
  },
  CollectionHall_117962_Title = {
    Text = "最後的詩篇"
  },
  CollectionHall_117963_Desc = {
    Text = "他已決意拋下此端，往彼端去。\n與他告別，但不要將祂遺忘。\n祂會提醒你，祂會注視你，那狂悖的瘋子、天才的畫師，和夜空中高懸的月亮。"
  },
  CollectionHall_117963_LockTip = {
    Text = "完成意識潛遊「畸世繪」"
  },
  CollectionHall_117963_Title = {
    Text = "往彼處去"
  },
  CollectionHall_117964_Desc = {
    Text = "引吭吧，起舞吧，當蜜和乳在火光旁交融。\n那終焉已愈發近了，以足攀援，以臂交纏，以頸傾吻——繁衍！繁衍！在母樹的廕庇之下，終有種嗣會獲得垂憐！"
  },
  CollectionHall_117964_LockTip = {
    Text = "完成調查行動7-19解鎖"
  },
  CollectionHall_117965_Desc = {
    Text = "戰勝我們，殺死我們。然後，拯救我們。"
  },
  CollectionHall_117965_LockTip = {
    Text = "完成調查行動·困難8-10解鎖"
  },
  CollectionHall_117965_Title = {
    Text = "命運將至"
  },
  CollectionHall_117966_Desc = {
    Text = "有一位小姐的手臂被伸縮繩串起，有一位小姐和另一位死掉兩次的小姐一起，製造出了一個虛假的亡魂。"
  },
  CollectionHall_117966_LockTip = {
    Text = "完成特遣紀錄「狩獵愉快！」"
  },
  CollectionHall_117967_Desc = {
    Text = "女王的肉身被融蝕侵襲，亞蘭的子民在黃沙中流亡。\n光陰從縫隙間被見證，由故去者，見證命運未能奈何亞蘭的數百年。"
  },
  CollectionHall_117967_LockTip = {
    Text = "完成調查行動·困難7-12解鎖"
  },
  CollectionHall_117967_Title = {
    Text = "百年見證"
  },
  CollectionHall_117969_Desc = {
    Text = "那不可名狀，無法反抗，癡愚盲目的存在。\n它已浮起，它已半醒，它已顯露恐怖而龐大的威壓。"
  },
  CollectionHall_117969_LockTip = {
    Text = "完成調查行動·困難8-10解鎖"
  },
  CollectionHall_117969_Title = {
    Text = "抗神權柄"
  },
  CollectionHall_117970_Desc = {
    Text = "噤聲，前行。序曲早已奏響。\n我會伴你走向，註定的、無上的、至美的終章。"
  },
  CollectionHall_117970_LockTip = {
    Text = "完成調查行動8-14解鎖"
  },
  CollectionHall_117971_Desc = {
    Text = "也許需要特別註釋，意思是在比賽裡這是兩條注意事項。\n既不要謙讓你的對手，更不要謙讓你的隊友。"
  },
  CollectionHall_117971_LockTip = {
    Text = "完成異夢視界「再見永無鄉」困難難度"
  },
  CollectionHall_117971_Title = {
    Text = "禁止謙讓"
  },
  CollectionHall_117972_Desc = {
    Text = "西岱的繁花向您發來邀請，邀請您與它們一同走入這場夢境。"
  },
  CollectionHall_117972_LockTip = {
    Text = "完成特遣紀錄「玫瑰的棲居」"
  },
  CollectionHall_117972_Title = {
    Text = "詩中世界"
  },
  CollectionHall_117973_Desc = {
    Text = "「騎士精神」隊，有1/4的騎士精神，和3/4的戰鬥狂魔。"
  },
  CollectionHall_117973_LockTip = {
    Text = "完成異夢視界「再見永無鄉」"
  },
  CollectionHall_117973_Title = {
    Text = "美德騎士與巨魔"
  },
  CollectionHall_117974_Desc = {
    Text = "舊日的女王，被遺忘的女王，她依然在無邊孤寂中等待。\n等待著她的血與種，被帶向湮滅後的新世界。"
  },
  CollectionHall_117974_LockTip = {
    Text = "完成調查行動7-19解鎖"
  },
  CollectionHall_117974_Title = {
    Text = "畸變豐穰之種"
  },
  CollectionHall_117975_Desc = {
    Text = "花園是一道謎題，玫瑰是她的答案。"
  },
  CollectionHall_117975_LockTip = {
    Text = "完成特遣紀錄「玫瑰的棲居」"
  },
  CollectionHall_117975_Title = {
    Text = "獻給春天的花束"
  },
  CollectionHall_117976_Desc = {
    Text = "陽光透過花房的玻璃照在奧爾拉的臉上。她穿過陽光，來到睡意朦朧的奧爾拉身前。\n每次喚醒她的時候，她都將玫瑰藏於身後。"
  },
  CollectionHall_117976_LockTip = {
    Text = "完成特遣紀錄「玫瑰的棲居」"
  },
  CollectionHall_117977_Desc = {
    Text = "她將花園的故事寫入詩頁。\n她將花園的故事投入火堆。"
  },
  CollectionHall_117977_LockTip = {
    Text = "完成特遣紀錄「玫瑰的棲居」"
  },
  CollectionHall_117977_Title = {
    Text = "詩頁的餘燼"
  },
  CollectionHall_117978_Desc = {
    Text = "沒有貧窮、饑餓、疾病、背叛。那是只有花與詩的西岱，那是隻屬於她們的樂土。"
  },
  CollectionHall_117978_LockTip = {
    Text = "完成特遣紀錄「玫瑰的棲居」"
  },
  CollectionHall_117978_Title = {
    Text = "幻想樂土"
  },
  CollectionHall_117979_Desc = {
    Text = "如果第一幕出現了一支槍，它在最後就會響。\n你已經構思好重逢時，要向她訴說的故事。\n那是一個夢，夢的開始墜落了一枚明亮的太陽，夢的結局墜落了一枚漆黑的太陽。"
  },
  CollectionHall_117979_LockTip = {
    Text = "完成異夢視界「再見永無鄉」困難難度"
  },
  CollectionHall_117979_Title = {
    Text = "墜落的太陽"
  },
  CollectionHall_117980_Desc = {
    Text = "蜜釀已經斟滿，貴客已經到場，請為勒姆瓦希帶來新的種子，請盡情歡享浸透欲望的熱情！"
  },
  CollectionHall_117980_LockTip = {
    Text = "完成調查行動7-19解鎖"
  },
  CollectionHall_117980_Title = {
    Text = "情熱時分"
  },
  CollectionHall_117981_Desc = {
    Text = "時間、生息、虛無、命運。\n所有晦澀的夢境，空茫的現實，平等地匯進洪流，消若無跡，一往無前，往海中去。"
  },
  CollectionHall_117981_LockTip = {
    Text = "完成調查行動·困難7-12解鎖"
  },
  CollectionHall_117981_Title = {Text = "歸向海"},
  CollectionHall_117982_Desc = {
    Text = "她在沙中踏出黑色漣漪，她牽引你、捉住你，把種種從荒蕪中託寄給你。\n今晚的月亮遮掩了一個華美晦澀的秘密，她既在舞中解答你的疑惑，也以一舞留給你更多謎題。"
  },
  CollectionHall_117982_LockTip = {
    Text = "完成調查行動7-19解鎖"
  },
  CollectionHall_117982_Title = {
    Text = "銀沙海之舞"
  },
  CollectionHall_117983_Desc = {
    Text = "給予叛逆者以寵溺，祂惡趣味的犧牲品，也分享了祂的惡習。"
  },
  CollectionHall_117983_LockTip = {
    Text = "完成特遣紀錄「狩獵愉快！」"
  },
  CollectionHall_117983_Title = {
    Text = "拷貝惡習"
  },
  CollectionHall_117984_Desc = {
    Text = "噩兆與樂音交織降臨，他亦敵亦友，他撲朔迷離。"
  },
  CollectionHall_117984_LockTip = {
    Text = "完成調查行動8-14解鎖"
  },
  CollectionHall_117984_Title = {
    Text = "命運前奏之曲"
  },
  CollectionHall_117985_Desc = {
    Text = "捕捉每一個音符，落在正確的節奏上。\n小心，注意，面對挑剔的指揮家，行差踏錯會讓你落入萬劫不復的境地。"
  },
  CollectionHall_117985_LockTip = {
    Text = "完成調查行動8-14解鎖"
  },
  CollectionHall_117985_Title = {
    Text = "踏對節拍"
  },
  CollectionHall_117986_Desc = {
    Text = "用一朵玫瑰，來換一首詩吧。\n在人們荒寂的心臟裡，玫瑰正殷紅地棲居。"
  },
  CollectionHall_117986_LockTip = {
    Text = "完成特遣紀錄「玫瑰的棲居」困難難度"
  },
  CollectionHall_117987_Desc = {
    Text = "我們為您準備了一個完美的假期，包括沙灘、陽光、排球賽，舊朋友和新朋友。\n請務必做好防曬，如果太陽從天空墜落，不用驚慌失措，這是正常現象。"
  },
  CollectionHall_117987_LockTip = {
    Text = "完成異夢視界「再見永無鄉」"
  },
  CollectionHall_117987_Title = {
    Text = "倫蒂尼恩之夏"
  },
  CollectionHall_117988_Desc = {
    Text = "你既不擅長音樂，也不喜歡解謎。\n但他平靜且優雅地將你編織進交響，神秘而失禮地拋出了他的謎語。"
  },
  CollectionHall_117988_LockTip = {
    Text = "完成調查行動8-14解鎖"
  },
  CollectionHall_117988_Title = {
    Text = "指揮家的謎語"
  },
  CollectionHall_117989_Desc = {
    Text = "可憐的、狂妄的、不知天高地厚的狼。\n他和其他客人一起被扔在了休息室，在一場短暫安寧的賭局裡。\n失去了習以為常的好運氣，他輸掉了超過一萬雷歐坊。"
  },
  CollectionHall_117989_LockTip = {
    Text = "完成特遣紀錄「狩獵愉快！」"
  },
  CollectionHall_117989_Title = {Text = "壞牌"},
  CollectionHall_117990_Desc = {
    Text = "一樣的禮帽，一樣的玫瑰，一樣的笑聲。\n帷幕已經拉起，觀眾已經就位，來吧，來吧，來找一找，兇手是從黑霧中掉出的哪一位？"
  },
  CollectionHall_117990_LockTip = {
    Text = "完成特遣紀錄「狩獵愉快！」"
  },
  CollectionHall_117991_Desc = {
    Text = "好的日常總是要由噩夢開始，在墓園結束。\n哦，這就是生活，甜美的生活。"
  },
  CollectionHall_117991_LockTip = {
    Text = "完成特遣紀錄「狩獵愉快！」困難難度"
  },
  CollectionHall_117992_Desc = {
    Text = "握住我的手吧。\n當手指相碰的時候，我將贈你一個春天。"
  },
  CollectionHall_117992_LockTip = {
    Text = "完成特遣紀錄「玫瑰的棲居」"
  },
  CollectionHall_117992_Title = {
    Text = "兩個人的春日"
  },
  CollectionHall_117993_Desc = {
    Text = "一次突然的造訪，一次體貼的造訪，一次幸福的造訪。\n是相似的朋友，是不相似的朋友。\n哦，朋友，朋友，每個人都需要朋友。我要用什麼來招待你，我的朋友？"
  },
  CollectionHall_117993_LockTip = {
    Text = "完成意識潛遊「畸世繪」"
  },
  CollectionHall_117994_Desc = {
    Text = "棺材裡爬出的輪盤賭，雪夜裡窮追不舍的過去。\n開一局，再一局，狼的皮毛和好運氣，會帶來一個陽光明媚的下週一。"
  },
  CollectionHall_117994_LockTip = {
    Text = "完成特遣紀錄「狩獵愉快！」"
  },
  CollectionHall_117994_Title = {
    Text = "狼的下週一"
  },
  CollectionHall_117995_Desc = {
    Text = "亞蘭的子民行遍了大漠，他們生於此，他們長於此，他們註定要繁榮於此處，註定要消亡於此處。"
  },
  CollectionHall_117995_LockTip = {
    Text = "完成調查行動7-19解鎖"
  },
  CollectionHall_117995_Title = {
    Text = "豐穰的末路"
  },
  CollectionHall_117996_Desc = {
    Text = "好孩子，乖寶貝，聖河會安撫你夭折的啼哭，聖河會託抱你流逝的魂靈。"
  },
  CollectionHall_117996_LockTip = {
    Text = "完成調查行動7-19解鎖"
  },
  CollectionHall_117996_Title = {
    Text = "還於聖河"
  },
  CollectionHall_117997_Desc = {
    Text = "花園的殘屑與往事的灰燼落在這片小小的土地上。它們在悲哀的回憶裡漫天飄揚，它們在狂熱的野心裡煙消雲散。"
  },
  CollectionHall_117997_LockTip = {
    Text = "完成特遣紀錄「玫瑰的棲居」困難難度"
  },
  CollectionHall_117997_Title = {
    Text = "花園往事"
  },
  CollectionHall_117998_Desc = {
    Text = "詭譎將藝術家的靈感飼育，生長，生長，畫師用色彩將真實解構，癲和癡在凌亂線條中生長。"
  },
  CollectionHall_117998_LockTip = {
    Text = "完成意識潛遊「畸世繪」"
  },
  CollectionHall_117998_Title = {
    Text = "前沿藝術"
  },
  CollectionHall_117999_Desc = {
    Text = "有一個地方只能在仲夏夜夢境中到達，那是我們得以重聚的永無鄉。"
  },
  CollectionHall_117999_LockTip = {
    Text = "完成異夢視界「再見永無鄉」"
  },
  CollectionHall_117999_Title = {
    Text = "永無鄉假日"
  },
  CollectionHall_118000_Desc = {
    Text = "畫家已尋覓到那恐怖的藝術，他掀開繪布，在投身前，邀友人赴一場色彩爆炸的癲狂奇旅。"
  },
  CollectionHall_118000_LockTip = {
    Text = "完成意識潛遊「畸世繪」"
  },
  CollectionHall_118000_Title = {
    Text = "瘋畫奇旅"
  },
  CollectionHall_118001_Desc = {
    Text = "祂們擁抱著血脈、手足、愛人、摯友，他們獻出自我，消融進一場黑甜的復生。\n祂們的骨歸於母樹，祂們的肉淌入聖河。"
  },
  CollectionHall_118001_LockTip = {
    Text = "完成調查行動·困難7-12解鎖"
  },
  CollectionHall_118001_Title = {Text = "母親"},
  CollectionHall_118002_Desc = {
    Text = "熾烈的太陽快要死去了，風裹挾砂礫將它熄滅。\n沉墜的太陽落下了，落向天與沙的交界。"
  },
  CollectionHall_118002_LockTip = {
    Text = "完成調查行動7-19解鎖"
  },
  CollectionHall_118002_Title = {
    Text = "墜往黃沙"
  },
  CollectionHall_118003_Desc = {
    Text = "為何一場大火就能燒毀所有的誓言？\n為何在詩歌的世界裡也充滿了苦難？"
  },
  CollectionHall_118003_LockTip = {
    Text = "完成特遣紀錄「玫瑰的棲居」"
  },
  CollectionHall_118003_Title = {
    Text = "對立的修辭"
  },
  CollectionHall_118004_Desc = {
    Text = "溯源之途，以生命壘砌，向它咆哮，抵禦不可違背的偉力。將血脈還於亞蘭，將豐穰還於亞蘭！"
  },
  CollectionHall_118004_LockTip = {
    Text = "完成調查行動7-19解鎖"
  },
  CollectionHall_118004_Title = {
    Text = "風暴之壁"
  },
  CollectionHall_118005_Desc = {
    Text = "這是真實，這是狂魘，這是暗面，這是夢境。\n瘋子和天才交替著喃喃低語，細些，再細些——不要挪開你的眼睛。"
  },
  CollectionHall_118005_LockTip = {
    Text = "完成意識潛遊「畸世繪」"
  },
  CollectionHall_118005_Title = {
    Text = "步入迷亂"
  },
  CollectionHall_118006_Desc = {
    Text = "極寒，詭計，大雪，全都擾亂不了野獸的嗅覺。"
  },
  CollectionHall_118006_LockTip = {
    Text = "完成特遣紀錄「狩獵愉快！」"
  },
  CollectionHall_118006_Title = {Text = "嗅覺"},
  CollectionHall_118007_Desc = {
    Text = "提高警惕，不是只有老夥計會用靴子狠狠踢你的……排球。"
  },
  CollectionHall_118007_LockTip = {
    Text = "完成異夢視界「再見永無鄉」"
  },
  CollectionHall_118007_Title = {Text = "新夥計"},
  CollectionHall_118008_Desc = {
    Text = "不不不不不不不，梭哈不是為了贏。\n梭哈的重點就是梭哈，梭哈就是為了梭哈。"
  },
  CollectionHall_118008_LockTip = {
    Text = "完成特遣紀錄「狩獵愉快！」困難難度"
  },
  CollectionHall_118008_Title = {
    Text = "名偵探的梭哈"
  },
  CollectionHall_118009_Desc = {
    Text = "近了，那死的神靈，終的吐息，傳奇但未為眾知的過往，凝窒而輕描淡寫的別離。"
  },
  CollectionHall_118009_LockTip = {
    Text = "完成調查行動·困難7-12解鎖"
  },
  CollectionHall_118009_Title = {
    Text = "先驅者的喪鐘"
  },
  CollectionHall_118010_Desc = {
    Text = "自她口中降下的，是神諭抑或王旨，是天恩抑或私心。\n樹魂與傀儡共鳴，許諾她永恆孤獨的空寂。"
  },
  CollectionHall_118010_LockTip = {
    Text = "完成調查行動·困難7-12解鎖"
  },
  CollectionHall_118010_Title = {
    Text = "無聲神諭"
  },
  CollectionHall_118011_Desc = {
    Text = "我已遺忘祂的身形，我已遺忘祂的名姓。\n但我將拋卻私心，我願化為銀蟻，待祂歸返，待祂重臨。\n待她將我擁入懷中，待她否認那聲歎息。"
  },
  CollectionHall_118011_LockTip = {
    Text = "完成調查行動·困難7-12解鎖"
  },
  CollectionHall_118011_Title = {
    Text = "為已逝者"
  },
  CollectionHall_118012_Desc = {
    Text = "花園的草地上，她們仰望雲朵隨著風變幻。\n柯蕾特，你看，那兩朵追逐的雲彩，是蝴蝶夫人與毛毛蟲先生正在跳舞。"
  },
  CollectionHall_118012_LockTip = {
    Text = "完成特遣紀錄「玫瑰的棲居」"
  },
  CollectionHall_118012_Title = {
    Text = "如彩雲相逐"
  },
  CollectionHall_118013_Desc = {
    Text = "無人銘記她的過往，無人知曉她的耳語。\n她貼近命定之人，呼吸織纏，形影相依。\n俯首，引頸。"
  },
  CollectionHall_118013_LockTip = {
    Text = "完成調查行動7-19解鎖"
  },
  CollectionHall_118013_Title = {
    Text = "她願引頸"
  },
  CollectionHall_118014_Desc = {
    Text = "請閉眼，讓吻落在指間。\n因她對你如此傾心，因漫長的旅程或會使你疲憊，卻不會使你猶疑。"
  },
  CollectionHall_118014_LockTip = {
    Text = "完成調查行動7-19解鎖"
  },
  CollectionHall_118015_Desc = {
    Text = "人總是容易在黃昏時陷入恍惚與沉默，因為所剩無幾的太陽，因為尚未被消耗殆盡的好時光。"
  },
