  CollectionHall_118605_Desc = {
    Text = "徒勞者恐懼變化，恐懼事物超出掌控，在最深層的地方，他歇斯底里地恐懼著失去。\n 他一次次地吹響哨子，想要通過哨音控制所有，但他沒能留住任何東西。"
