  },
  CollectionHall_118627_Desc = {
    Text = "利維坦的骸骨庇佑著祂所選定之人，所向披靡，不死不滅。"
  },
  CollectionHall_118627_LockTip = {
    Text = "可於活動「貪戮角逐」中解鎖"
