  },
  CollectionHall_118630_LockTip = {
    Text = "可於調查行動星辰篇3-5中解鎖"
  },
  CollectionHall_118630_Title = {
    Text = "思維的瘡"
  },
  CollectionHall_118631_Desc = {
    Text = "莫絲女士強硬地說這就是造物。\n「壞人、咬他！」"
  },
  CollectionHall_118631_LockTip = {
    Text = "可於活動「默斯克斯的呼喚」中解鎖"
  },
  CollectionHall_118633_Desc = {
    Text = "「血月高升，群骸當舉杯共飲。」"
  },
  CollectionHall_118633_LockTip = {
    Text = "可於活動「死靈的美學」中解鎖"
  },
  CollectionHall_118633_Title = {
    Text = "<OrangeQuality:骸骨杯盞>"
  },
  CollectionHall_118636_Desc = {
    Text = "信函上文字不斷變化，始終化為無法拒絕的渴求。"
  },
  CollectionHall_118636_LockTip = {
    Text = "可於活動「雨鎮幽影」中解鎖"
  },
  CollectionHall_118636_Title = {
    Text = "<OrangeQuality:千面邀請函>"
  },
  CollectionHall_120344_Title = {
    Text = "你我終將重逢"
  },
  CollectionHall_120463_LockTip = {
    Text = "可於調查行動4-15中解鎖"
  },
  CollectionHall_120463_Title = {
    Text = "記錄無罪"
  },
  CollectionHall_120464_LockTip = {
    Text = "敬請期待"
  },
  CollectionHall_120464_Title = {
    Text = "貪吃錢包"
  },
  CollectionHall_120465_LockTip = {
    Text = "可於調查行動4-5中解鎖"
  },
  CollectionHall_120465_Title = {
    Text = "哢吱作響"
  },
  CollectionHall_120466_LockTip = {
    Text = "可於調查行動3-10中解鎖"
  },
  CollectionHall_120466_Title = {
    Text = "無聲電報"
  },
  CollectionHall_121154_Title = {Text = "樂園"},
  CollectionHall_121341_Desc = {
    Text = "<Title:簡介>\n接納孕育「聖嬰」職責的「王女」，現如今已是蹈海者教內舉足輕重的「神母」。\n她也曾經是奔向自由的淑女，和彌薩格所記錄的墨菲一樣踏上索納尼爾號的逃亡旅程。\n但在不存在守密人的世界裡，命運折斷了年幼天鵝高貴的頸項。\n倒錯的血脈不由分說不由抵抗地糾纏著她，即便放任軀體死亡也不能倖免。她強撐場面說出一句又一句「我是尊貴的神母」，都只是對自己的暗示與說服。\n只能服從、只有服從。服從虛妄的神諭，服從荒誕的命運，然後從無盡的苦澀中，勉強回味到那一絲幻想的甘甜。"
  },
  CollectionHall_121341_LockTip = {
    Text = "喚醒「誕妄·墨菲」後解鎖"
  },
  CollectionHall_121341_Title = {
    Text = "誕妄·墨菲"
  },
  CollectionHall_121381_Desc = {
    Text = "你用一千顆橡果交換了一個來自異界的故事。\n一個關於英雄與魔神，守望與堅持的故事。\n一個關於無奈與不舍，舊朋友與新朋友的故事。\n一個曾經來過的故事。"
  },
  CollectionHall_121381_LockTip = {
    Text = "完成多維連接「逆轉回合」"
  },
  CollectionHall_121381_Title = {
    Text = "萬象旅店的迴響"
  },
  CollectionHall_121382_Desc = {
    Text = "很久很久以後，他與他終於有了一首被傳唱的吟遊詩。\n關於死而復甦的救贖，關於一體雙生的靈魂。"
  },
  CollectionHall_121382_LockTip = {
    Text = "完成異夢視界「天邊之外·下」"
  },
  CollectionHall_121382_Title = {
    Text = "無翅鳥之詩"
  },
  CollectionHall_121383_Desc = {
    Text = "少年為短暫的一切，付出了被索償的代價。\n如今，只剩靜默的權柄與他相伴。\n王要睡去了，他在夢中迎來世界的盡頭。"
  },
  CollectionHall_121383_LockTip = {
    Text = "完成意識潛遊「加冕之日」"
  },
  CollectionHall_121383_Title = {
    Text = "無邊苦寂的王土"
  },
  CollectionHall_121384_Desc = {
    Text = "她們圍繞著你，她們敬慕著你，她們陪伴著你。\n她們向創世神揚帆。"
  },
  CollectionHall_121384_LockTip = {
    Text = "完成調查行動9-11解鎖"
  },
  CollectionHall_121384_Title = {
    Text = "向創世神揚帆"
  },
  CollectionHall_121385_Desc = {
    Text = "那是一雙由摧折中重生的羽翼，那是一雙以犧牲換來自由的羽翼。\n命運的預言已經應驗了，他在悔痛中起誓，血債要以血來償。"
  },
  CollectionHall_121385_LockTip = {
    Text = "完成異夢視界「天邊之外·下」"
  },
  CollectionHall_121385_Title = {
    Text = "暴風起時"
  },
  CollectionHall_121386_Desc = {
    Text = "荒誕與混沌的夢境伊始之初，祂就註定會面對祂的宿命。\n但祂已經歷了太多，也定義了太多。\n祂已決意以人類能夠保持的最大理智，注視自己的起源，那至高的神祇。"
  },
  CollectionHall_121386_LockTip = {
    Text = "完成調查行動9-11解鎖"
  },
  CollectionHall_121386_Title = {
    Text = "原初宿命之戰"
  },
  CollectionHall_121387_Desc = {
    Text = "得到、失去、斬斷、犧牲。\n英雄付出了全部全部的代價，庇護珍寶的權柄即是祂的報償。"
  },
  CollectionHall_121387_LockTip = {
    Text = "完成調查行動9-13解鎖"
  },
  CollectionHall_121387_Title = {
    Text = "無目之瞳"
  },
  CollectionHall_121388_Desc = {
    Text = "他以王冠加諸己身，他以鐐銬加諸己身。\n那是短暫虛幻的暖意，那是註定覆滅的往日榮光。"
  },
  CollectionHall_121388_LockTip = {
    Text = "完成意識潛遊「加冕之日」"
  },
  CollectionHall_121389_Desc = {
    Text = "儘管局面對你不利，但你的嘴角已經微微揚起。\n“我的回合，抽卡！”\n不管是在萬象旅店還是在彌薩格，\n小看輔助的傷害能力可都是要吃大虧的啊！伊格娜蒂絲！"
  },
  CollectionHall_121389_LockTip = {
    Text = "完成多維連接「逆轉回合」"
  },
  CollectionHall_121389_Title = {
    Text = "屬於我的逆轉時刻！"
  },
  CollectionHall_121390_Desc = {
    Text = "一個完整的傳奇不能缺少化敵為友。"
  },
  CollectionHall_121390_LockTip = {
    Text = "完成調查行動·困難9-10解鎖"
  },
  CollectionHall_121390_Title = {
    Text = "敵人，友人"
  },
  CollectionHall_121391_Desc = {
    Text = "從今往後，你將以守密人的稱號，與萬萬千千的彌薩格師生同在。"
  },
  CollectionHall_121391_LockTip = {
    Text = "完成調查行動·困難9-11解鎖"
  },
  CollectionHall_121392_Desc = {
    Text = "我們或許是亙古中的轉瞬，狂流中的砂礫。\n然而常世便是我們珍貴的永恆，因為無論世界如何瘋狂混亂——\n人類的尊嚴，會建立於理性的光輝之上。"
  },
  CollectionHall_121392_LockTip = {
    Text = "完成調查行動9-11解鎖"
  },
  CollectionHall_121392_Title = {Text = "常世頌"},
  CollectionHall_121393_Desc = {
    Text = "勇者們一頭撲進了童話，每一個童話都一樣，動物、魔鬼、仙女和未知的彼方。\n越過短暫的自由和虛假的想往，童話的盡頭，藏著一顆被強加於他的假心臟。"
  },
  CollectionHall_121393_LockTip = {
    Text = "完成異夢視界「天邊之外·下」"
  },
  CollectionHall_121393_Title = {
    Text = "飛入星河"
  },
  CollectionHall_121394_Desc = {
    Text = "這裡是位於異世界時空裂隙之中的萬象旅店。\n連接著不同宇宙的傳送門，閃爍著浩瀚的星光，歡迎著你的到來。\n等等……這是給咱守密人幹哪兒來了？"
  },
  CollectionHall_121394_LockTip = {
    Text = "完成多維連接「逆轉回合」"
  },
  CollectionHall_121394_Title = {
    Text = "歡迎來到萬象旅店！"
  },
  CollectionHall_121395_Desc = {
    Text = "彌薩格的利刃會為你取得這場對弈的勝利。\n你和搭檔之間的羈絆堅不可摧。\n哪怕你們有一天身處於不同宇宙，也一定無法改變這一點。"
  },
  CollectionHall_121395_LockTip = {
    Text = "完成多維連接「逆轉回合」"
  },
  CollectionHall_121395_Title = {
    Text = "彌薩格利刃！"
  },
  CollectionHall_121396_Desc = {
    Text = "“每日試訓沒有做？不如先來一盤萬象牌吧！”\n“融災禁區沒有打？不如先來一盤萬象牌吧！”\n“這是相位對弈，不是萬象牌！一千顆橡果我會收集給你看的！”"
  },
  CollectionHall_121396_LockTip = {
    Text = "完成多維連接「逆轉回合」"
  },
  CollectionHall_121396_Title = {
    Text = "一起來玩萬象牌吧！"
  },
  CollectionHall_121397_Desc = {
    Text = "呼喚我的名字，在被遺忘的黎明之前。"
  },
  CollectionHall_121397_LockTip = {
    Text = "完成調查行動·困難9-11解鎖"
  },
  CollectionHall_121397_Title = {
    Text = "來自遺忘@2"
  },
  CollectionHall_121398_Desc = {
    Text = "“快來跟我簽訂契約，成為卡牌大師吧！”\n這位來自異世界的龍族美少女向你發出了熱情而莫名其妙的邀請。\n為了讓這個相位空間的小意外儘快回復正常，你別無選擇。"
  },
  CollectionHall_121398_LockTip = {
    Text = "完成多維連接「逆轉回合」"
  },
  CollectionHall_121398_Title = {
    Text = "老闆娘，伊格娜蒂絲！"
  },
  CollectionHall_121399_Desc = {
    Text = "後來者會在沉重的饋贈下，找到這麼一行腳註。\n唯一逃避當英雄的人成為了英雄，珍視朋友的孩子只剩下唯一的朋友。"
  },
  CollectionHall_121399_LockTip = {
    Text = "完成意識潛遊「加冕之日」"
  },
  CollectionHall_121399_Title = {
    Text = "餘將獨行"
  },
  CollectionHall_121400_Desc = {
    Text = "脫離主，直面主，忤逆主。\n你的故事無人知曉，你的記憶與世長存。"
  },
  CollectionHall_121400_LockTip = {
    Text = "完成調查行動9-13解鎖"
  },
  CollectionHall_121400_Title = {
    Text = "創世癡愚之主"
  },
  CollectionHall_121401_Desc = {
    Text = "一切都不再有意義，因此你得以站在這裡。\n一切曾經的過往，就是你所定義的全部的意義，所以你站在了這裡。"
  },
  CollectionHall_121401_LockTip = {
    Text = "完成調查行動9-13解鎖"
  },
  CollectionHall_121401_Title = {
    Text = "存在主義"
  },
  CollectionHall_121402_Desc = {
    Text = "通向祂們的小徑，遠離祂們的小徑。\n一切即將分別，一切即將終結，一切即將伊始。\n門扉前的身影自此開始了漫長的等待，等待銀鑰指引你的歸途。"
  },
  CollectionHall_121402_LockTip = {
    Text = "完成調查行動9-13解鎖"
  },
  CollectionHall_121402_Title = {
    Text = "通向祂們的小徑"
  },
  CollectionHall_121403_Desc = {
    Text = "祂們的可能性線條，分離、收束、崩散。\n直到迎來了唯一的救世主，直到終於邁入了唯一的終局。"
  },
  CollectionHall_121403_LockTip = {
    Text = "完成調查行動·困難9-10解鎖"
  },
  CollectionHall_121403_Title = {
    Text = "唯一的終局"
  },
  CollectionHall_121404_Desc = {
    Text = "幼王接受了這筆交易。\n他說，我的國將安然無恙。"
  },
  CollectionHall_121404_LockTip = {
    Text = "完成意識潛遊「加冕之日」"
  },
  CollectionHall_121405_Desc = {
    Text = "這片破碎的時空裂隙之中曾經坐落著傳說中的萬象旅店。\n曾經連接著不同宇宙的傳送門，曾經閃爍著浩瀚的星光，曾經歡迎著每一位卡牌大師的到來。\n而你，是這一切存在過的證明。"
  },
  CollectionHall_121405_LockTip = {
    Text = "完成多維連接「逆轉回合」"
  },
  CollectionHall_121405_Title = {
    Text = "再見了，卡牌大師！"
  },
  CollectionHall_121406_LockTip = {
    Text = "完成調查行動9-13解鎖"
  },
  CollectionHall_121406_Title = {
    Text = "終焉凝注"
  },
  CollectionHall_121407_Desc = {
    Text = "戰士、復仇者、奴隸、主人、商人。\n相同的立場？不同的立場？相同的立場。"
  },
  CollectionHall_121407_LockTip = {
    Text = "完成調查行動9-11解鎖"
  },
  CollectionHall_121407_Title = {
    Text = "多重性戰歌"
  },
  CollectionHall_121408_Desc = {
    Text = "你知道，你沒有在為什麼偉大的事情作戰。\n為了逃課，為了作業，為了甜點，為了朋友，為了火爐，為了虛度時光。\n你只是一個平凡的，為平日赴死之人。"
  },
  CollectionHall_121408_LockTip = {
    Text = "完成調查行動·困難9-11解鎖"
  },
  CollectionHall_121408_Title = {
    Text = "為平日赴死之人"
  },
  CollectionHall_121409_Desc = {
    Text = "動物，所有的高等動物，都難以避免地被社群行為所控。\n然而她親身奔赴死亡，如願解構真相。\n一名瘋狂的、絕世的天才，她寧願親手引來毀滅，她恩賜眾生免於吞食名為希望的砒霜。"
  },
  CollectionHall_121409_LockTip = {
    Text = "完成調查行動9-13解鎖"
  },
  CollectionHall_121409_Title = {
    Text = "社群行為解構"
  },
  CollectionHall_121410_Desc = {
    Text = "祂從高天送來源源不斷的苦水，彙聚，彙聚。\n最終橫亙成我們血肉交融之前，註定要溯及的那條河流。"
  },
  CollectionHall_121410_LockTip = {
    Text = "完成異夢視界「天邊之外·下」"
  },
  CollectionHall_121411_Desc = {
    Text = "祂們以重逢的預期告別。\n因這是一位至珍者，因這是一場並非命定的至珍者之死。"
  },
  CollectionHall_121411_LockTip = {
    Text = "完成調查行動9-11解鎖"
  },
  CollectionHall_121412_Desc = {
    Text = "休息一下，喘口氣吧。\n即使面對的課題是世界末日，也不是每個人都有機會同時面對三位如此重磅級的導師。"
  },
  CollectionHall_121412_LockTip = {
    Text = "完成調查行動9-13解鎖"
  },
  CollectionHall_121412_Title = {
    Text = "劇幕中場"
  },
  CollectionHall_121413_Desc = {
    Text = "一千顆橡果的故事，總要由第一顆開始。\n在相位對弈中，你每打出一張卡牌，\n伊格娜蒂絲的眸中便莫名掠過一縷金色的回憶流光。"
  },
  CollectionHall_121413_LockTip = {
    Text = "完成多維連接「逆轉回合」"
  },
  CollectionHall_121413_Title = {
    Text = "無限續杯！"
  },
  CollectionHall_121414_Desc = {
    Text = "瘋狂，毀滅的前奏，這是有序世界的底層邏輯。\n祂會毀滅嗎，世界會毀滅嗎？\n無人知曉。\n但創世神面前，瘋狂正在滋養出祂與世界的新生。"
  },
  CollectionHall_121414_LockTip = {
    Text = "完成調查行動9-11解鎖"
  },
  CollectionHall_121414_Title = {
    Text = "瘋狂賦格"
  },
  CollectionHall_121415_Desc = {
    Text = "世界上最不講道理的是什麼？\n祂沒有目的，無關恩怨，不辨善惡。\n祂只想在醒來時把夢境中生出的一切，全都化為齏粉。"
  },
  CollectionHall_121415_LockTip = {
    Text = "完成調查行動9-13解鎖"
  },
  CollectionHall_121415_Title = {Text = "齏粉"},
  CollectionHall_121416_Desc = {
