  CollectionHall_124127_LockTip = {
    Text = "完成調查行動·困難 星辰篇4-10解鎖"
  },
  CollectionHall_124127_Title = {Text = "墜下"},
  CollectionHall_124128_Desc = {
    Text = "孩童並不屬於母親，祂已打定主意，所有人都要留在這裡。\n留在祂永恆延續的甜蜜樂園。"
