  },
  CollectionHall_124129_Title = {Text = "假臍帶"},
  CollectionHall_124130_Desc = {
    Text = "3.14159@2，3.141592@3，3.14159265@4……\n雪地裡永無終結的圓，殘忍的、永遠不會結束的圓周率。"
  },
  CollectionHall_124130_LockTip = {
    Text = "完成調查行動·困難 星辰篇4-10解鎖"
  },
  CollectionHall_124131_Desc = {
    Text = "你又來晚了一些，別停留，再快，再快一點。\n快趕往下一個結局。"
  },
  CollectionHall_124131_LockTip = {
    Text = "完成調查行動 星辰篇4-16解鎖"
  },
  CollectionHall_124131_Title = {
    Text = "某一個結局"
  },
  CollectionHall_124132_Desc = {
    Text = "擁抱我吧，我的寶貝，我的……父親，我的命運。"
  },
  CollectionHall_124132_LockTip = {
    Text = "完成調查行動·困難 星辰篇4-10解鎖"
  },
  CollectionHall_124132_Title = {
    Text = "在他女兒黑暗的子宮中"
  },
  CollectionHall_124133_Desc = {
    Text = "天空將要亮了，讓我們作別昨日。\n作別昨日的苦痛、荒誕、迷惘，\n迎接一個更明亮的，天各一方的明天。"
  },
  CollectionHall_124133_LockTip = {
    Text = "完成調查行動·困難 星辰篇4-10解鎖"
  },
  CollectionHall_124133_Title = {
    Text = "在黎明時告別"
  },
  CollectionHall_124134_Desc = {
    Text = "她與現實之間，她與虛妄之間，豎起了一面小小的盾牌。\n麵粉、雞蛋、檸檬、蜂蜜、糖、泡打粉、黃油烘烤成的盾牌。"
  },
  CollectionHall_124134_LockTip = {
    Text = "完成調查行動 星辰篇4-16解鎖"
  },
  CollectionHall_124134_Title = {
    Text = "麵糰盾牌"
  },
  CollectionHall_124135_Desc = {
    Text = "這個世界一如往常，孩子依賴母親，孩子也對母親說謊。"
  },
  CollectionHall_124135_LockTip = {
    Text = "完成調查行動 星辰篇4-16解鎖"
  },
  CollectionHall_124135_Title = {
    Text = "敘謊者和絃"
  },
  CollectionHall_124136_Desc = {
    Text = "神誕生的第七日。\n哦，神啊，神啊……\n不過是荒謬的錯誤與虛假的謊言。"
  },
  CollectionHall_124136_LockTip = {
    Text = "完成調查行動·困難 星辰篇4-10解鎖"
  },
  CollectionHall_124137_Desc = {
    Text = "睡吧，睡吧，海的嬰孩，讓漆黑的月光照在你沉暗的襁褓上，讓千年億年的沉夢就此淪入永恆虛妄。"
  },
  CollectionHall_124137_LockTip = {
    Text = "完成調查行動 星辰篇4-16解鎖"
  },
  CollectionHall_124138_Desc = {
    Text = "逃跑吧，兩條魚躍入了水面。\n它們暫時拋卻了一切，試圖瞞著世界與彼此相伴流亡。"
  },
  CollectionHall_124138_LockTip = {
    Text = "完成調查行動 星辰篇4-16解鎖"
  },
  CollectionHall_124139_Desc = {
    Text = "父親誕下女兒，女兒孕育父親。\n虛妄、倒錯、她所墜入的循環往復的命運。"
  },
  CollectionHall_124139_LockTip = {
    Text = "完成調查行動 星辰篇4-16解鎖"
  },
  CollectionHall_124139_Title = {
    Text = "虛妄倒錯之孕"
  },
  CollectionHall_124140_Desc = {
    Text = "什麼比死亡和疼痛更可怕？\n這對你來說不算一個難以解答的問題。"
  },
  CollectionHall_124140_LockTip = {
    Text = "完成調查行動 星辰篇4-16解鎖"
  },
  CollectionHall_124140_Title = {
    Text = "回到原點"
  },
  CollectionHall_124141_Desc = {
    Text = "她和她有她和她的虔誠，他和他有他和他的反叛和忠心。\n她編織一個彌天大謊，他和他和她和她陪她演戲。\n家，大家組成了甜蜜而不可分割的家。"
  },
  CollectionHall_124141_LockTip = {
    Text = "完成調查行動 星辰篇4-16解鎖"
  },
  CollectionHall_124142_Desc = {
    Text = "讓我們呼喚那由海中上浮的神國的名字——利莫里亞，利莫里亞。"
  },
  CollectionHall_124142_LockTip = {
    Text = "完成調查行動 星辰篇4-16解鎖"
  },
  CollectionHall_124142_Title = {Text = "海國"},
  CollectionHall_124224_LockTip = {
    Text = "通關多維連接「銀與血的洗禮」任一關卡解鎖"
  },
  CollectionHall_124224_Title = {
    Text = "茉夏的異世界調查記錄"
  },
  CollectionHall_124395_Desc = {
    Text = "在蘿坦此生最為痛苦與滿足的那天，她手中的利刃如風暴襲向眼前的神明。巨劍與利維坦如星球般宏偉的身軀一同，在這風暴中寸寸碎裂。\n將鮮血的王冠贈予那位騎士團的奴隸後，作為交換，蘿坦只提了一個要求：她需要一把新的武器。\n懷著對蘿坦的畏懼與崇敬，新國王命人取下利維坦的骨頭，為她鑄造了一對無與倫比的巨劍。在六國最優秀的鐵匠們日以繼夜的鑄造淬煉中，一頭死去神明的屍骨，在弒神者的手中重獲新生。\n一位值得被銘記的對手曾見證過這雙不滅的劍刃。他的巨錘劈碎了蘿坦的鎧甲與巨劍，裂紋如蛛網般在劍身蔓延，乳白的碎片飛濺在血色的空氣裡，如同她刺向利維坦的那天。他以為自己找到了破綻。然後，他看到蘿坦重新在他面前站起，那柄本應碎裂的巨劍刺穿他的胸膛，吮吸他的血肉。新的骨骼從碎裂處湧出，比先前更加尖銳，更加緻密。斷面拔節生長，如同荒野中瘋長的荊棘。他清晰地感知到，自己的生命正被那白骨鑄就的利刃咀嚼、吞嚥。\n原來，那曾經吞噬星天的巨獸從未死去。自契約簽訂的那一刻，祂便與她融合為一。每當蘿坦提起巨劍，劍身的骨棘便開始綻放，用它銳利的尖刺向對手發出殘忍的歡呼。\n它是她的武器。她是它的雙足。她與它，從始至終都陷於同一種渴望。她們不死不滅，永無饜足。\n從不停息的戰場，是她們唯一的歸宿。"
  },
  CollectionHall_124395_Title = {
    Text = "不滅的飢骨"
  },
  CollectionHall_124397_Desc = {
    Text = "許多年後，面對伏地祝禱的蹈海者，誕妄·墨菲會回想起，「母親」為她講起藍環章魚故事的那個遙遠的下午。\n罐中的造物柔軟而炫目，奇異的幽藍在水中浮動，誘使幼小的她不由自主地靠近。\n而彌利亞姆卻撫摸她的頭，帶著不容拒絕的力道讓她看向昏暗船艙的角落——一具蹈海者的屍身疲軟地癱倒在地，呈現出一種被毒素吮吸殆盡後的虛無蒼白。\n「謹記，海洋裡最寧靜、也最致命的，往往是最美麗的那種。」\n玻璃罐的冷光映亮她慈悲的側影，誕妄·墨菲只感到一種被美麗包裹的恐懼。\n\n歲月跟隨星辰的節律悄然流逝，誕妄·墨菲一如往日驕縱，卻也學會了沉默與觀察。\n「利莫里亞，利莫里亞……」\n直至祭壇之上，那張一向平靜溫柔的面龐逐漸被瘋狂浸染，她這才恍然，原來自己從未真正認識過彌利亞姆。那只撫摩她頭頂的、溫柔的母親的手，也會為神國的敵人施以最嚴厲的懲戒。\n彼時，記憶深處被封存的恐懼驟然復甦，最終凝固成一種冰冷的認知——她的仁慈不過是偽裝的腕足，而溫柔外表幻化成的美麗藍環，正是見血封喉的毒素本身。\n\n時至今日，虛無的神明終為誕妄·墨菲加冕。她俯視著匍匐的蹈海者，迎上彌利亞姆目光中那一絲未曾泯滅的、近乎荒誕的期頤，彷彿再度看見了那個在玻璃罐前，凝視著美麗生物而戰慄的、渺小的自己。"
  },
  CollectionHall_124397_Title = {
    Text = "藍環毒素"
  },
  CollectionHall_124400_Desc = {
    Text = "不知名的瘟疫吞噬了城鎮與村莊，嗜戰的人們在動盪中盡情殺戮，鐵與血的交響沸騰癲狂。\n出於恐懼，或利用恐懼。\n恐懼是無形的敵人，古老的敵人，致命的敵人。\n他是一個不合格的騎士，他敗給了恐懼。\n然而曾鄭重許下的誓言仍然迴蕩耳畔，一年又一日，穿過早已虛無的故鄉。\n「我將仁慈地對待弱者，我將勇敢地面對強敵。」\n黑夜藏匿了行兇者的腳印，尖叫和哭泣的洪流淹沒街巷，人群如同驚慌失措的羊群。\n「我將毫無保留地對抗惡人，我將為不能戰鬥者而戰。」\n槍尖染血，銀盾鏽蝕，影子饜足地微笑，群鴉盤旋頂空，瞳仁中有魔鬼的閃光。\n「我將幫助那些需要我幫助的人。」\n「是他，他來了。」人們低聲囁嚅，恐懼扭曲了他們的臉龐，「空心的怪物，復仇的鬼魂，自死亡的深潭歸來，要將他的敵人拖入怨恨的黑沼。」\n是他。他並未忘記，他從未忘記。\n為何要堅持？倘若萬物終將消亡，哪怕是榮耀與信仰。\n為何要退縮？既然無論命運如何嘲弄，人都唯有屈膝順從。\n難道只為忠於忠誠，獻於奉獻？\n公國最後的騎士徒勞發問，靈魂同殘軀一樣荒蕪，恐懼的餘污肆意流淌，匯聚成毀滅的汪洋。\n可空盪盪的胸腔依舊緘默不語，失落的答案還不知去向。"
  },
  CollectionHall_124400_Title = {
    Text = "往日如影隨形"
  },
  CollectionHall_124404_Desc = {
    Text = "那是我與父親移居海城的第二年、伊芙蓮在信中的哭訴使我心煩意亂、我已決意同她分別。這是由絲綢與烏木裝潢的富饒之地、所有食腐者都嗅到了它沉睡時的混亂、紙鈔的面值能換來等重的黃金、掌握了那些航線、就能以極小的成本撬動千萬倍的財富。\n然而伊芙蓮、也許是源於她晦澀難追的怪異血統導致的神經質、這個女人堅信所謂先祖的傳訊、東方有祂們的旁支所信奉的邪異神明、如同深海中的某種魚類、會懸垂下招搖美味的餌、將獵物引入一場難以察覺的緩慢進食。\n她錯了、海城沒有半絲來自海的鹹味。\n只有層層疊疊、馥郁到令人迷醉、又心生恐懼的白玉蘭。\n令我和父親同時陷落的白玉蘭。\n當我看到她的時候、那個名為「徐」的女人的身影出現在我視線中的第一秒、我就永遠不再可能從這片古老的陸地脫身了。\n她令人想要靠近、她令人想要占有、她令人想要@3\n她令人令人令人令人令人想要想要想要想要想要\n切碎割開砍碎永遠永遠永遠永遠永遠……@2@3@2！！\n啊、我為什麼來到這裡？我要帶走什麼？我是……誰？\n不再重要了、她邀請了我、我坐在那座大宅的桌前。\n早已與我一樣瘋狂的父親、臉上掛著乖順的笑、琳瑯滿目的配菜擺滿餐桌、顯得金屬帶蓋餐盤格格不入。\n徐逆著光線坐在夕陽中、光暈為她鑲上了一層絨絨的金邊、慢慢地、那把黑扇放下了。\n像伊芙蓮、像我幼時的玩伴、像朦朧間的艷遇……像我的母親。\n那是一張如同廟宇裡鎏金神像般端方美麗的臉。\n我沒有聽見吮吸聲、也沒有嗅到父親身上傳來的腥味、只是痴迷地注視著那張臉、以及那張臉的主人伸出一隻素白的手、揭開餐盤、撿拾出合適的肉、她用兩根細木棍將它鉗起、抬高。\n她喚我、烘烤過後的動物油脂滴在我的嘴角。\n「小先生、你該吃些東西。」\n\n我溫順而木訥地張開嘴。\n玉蘭花已經開了、它在簌簌地向我懸垂。\n——「無名者手記」\n"
  },
  CollectionHall_124404_Title = {
    Text = "玉蘭之餌"
  },
  CollectionHall_124405_Desc = {
    Text = "「以理智為明燈，就能驅散人生的迷霧。」\n曾幾何時，茉夏曾經聽過這樣的話。\n或許是某次梭羅公司的技術人員在調試驅霧燈時脫口而出的感慨？又或許是某次去菲林根餐廳時某個路人的調侃？\n茉夏已經忘記了，她能夠清晰想起的，就是聽到這句話時，自己臉上的慣用社交微笑，和藏在這笑容之後的嘲諷。\n「明燈？哈，什麼老掉牙的古董，現在人們都用手電筒。」\n她並非不知道這只是一種比喻，她只是不屑於理解。\n因為總有一天，她會死亡。而死亡之後，什麼理智，什麼迷霧，都不存在了——她會徹底從這個世界解脫。\n這是合理且必然的推測。她需要做的，只是享受這個「必然」到來前的過程。\n但從沒有人告訴過她，「必然」也會遭遇「意外」。\n相似的迷霧，相似的困境，可這裡沒有驅霧燈，沒有調查團，沒有任何她熟悉的東西。她的斧子能夠斬斷世間的怪物，卻斬不斷自身的孤獨與困惑化為的迷霧。\n她可以回去嗎？她會回去嗎？到底什麼時候可以回去……\n一個又一個問題自她的內心浮起，像是無形的深水，慢慢吞噬她的心靈。此時此刻，她心中唯一的，全部的想法，就是——\n保持理智。\n不要發瘋！不要發瘋！不要發瘋！\n無論是面對那個世界的迷霧，這個世界的迷霧，還是自己內心的迷霧。\n為了，再次回去。"
  },
  CollectionHall_124405_Title = {
    Text = "理智明燈"
  },
  CollectionHall_124407_Desc = {
    Text = "七歲生日那天，父親將一台名為「摩伊賴」的紡輪放在她膝上。那名字屬於三位早已無人祭拜的命運女神，而紡輪本身卻光滑嶄新，銅軸泛著金屬光澤，冷冽而沉重。\n從那時起，阿拉克涅拿起了命運之輪，不是出於選擇，而是因為那些無心說出的話語總在日後應驗，她無法忽視這命中注定的責任。\n從那時起，她便一直編織著，日復一日，看命運的絲線在精密的紡輪上無聲轉動，為世人織出初吻的顫抖、戰馬的嘶鳴、嬰兒的第一聲啼哭，以及墓碑上粗糙的刻痕。\n從那時起，她在萬千交錯的絲線中挑選那些「更好的」走向，讓漆黑的瘟疫提前退潮，讓歷史躲過戰火，讓文明於廢墟中重建……而與此同時，她也編織出那些通向瘋狂、背叛或永恆黑夜的絲線，只為維系那張橫跨時空的命運之網。\n「什麼才是更好的？」\n沉默的紡輪不會回答，只是繼續旋轉。好的、壞的，新生或是訃告，在同一根絲線上交替浮現。彼時年輕的她尚不知自己的宿命為何物，卻已在無數線頭的盡頭，望見世界的終局。\n「如果世界無法逃避毀滅的宿命……」\n「不，我愛這個世界。」\n阿拉克涅凝視著紡輪，將未說出口的想法舍棄。\n「那麼……我的宿命呢？」\n她喃喃自語，唯有空蕩的回音在四壁間遊蕩。\n……\n數不清多少文明在命運之網上崛起又崩塌，金字塔在沙中沉睡，飛船掠過星海，語言更迭如季節輪轉，神明的名字被寫進塵封的辭典……而她始終坐在那裡，轉動手中的紡輪，看著人類一遍遍重演希望與毀滅的循環。\n直到某天，一聲輕喚超越永恆的監牢與萬古的寂靜。\n「姐姐……」\n她終於收回投向末日的視線，閉眼望向涅芙蕾亞，她身體裡的另一個自己——那雙新生兒般純淨的眼睛裡，沒有審判、沒有恐懼，只有全然的信任，像一張尚未落筆的白紙。\n那一刻，阿拉克涅終於知曉，愛與責任、恨與毀滅，一切在命運面前並無區別。於是，她將那些被自己親手剪斷、舍棄的回憶，那些本該發生卻從未降臨的痛楚、遺憾與失落，編織成一縷絲線，作為最沉重也最溫柔的禮物，系在涅芙蕾亞的手腕上。\n「離開這裡吧，涅芙蕾亞。」阿拉克涅微笑，「你自由了。」\n阿拉克涅不再需要看清自己的宿命。因為在七歲那年拿起紡輪的瞬間，她就已選擇了未來的走向。而宿命的紡輪，將靜靜轉動，見證她即將投身其中、永無謝幕的戰鬥。"
  },
  CollectionHall_124407_Title = {
    Text = "宿命紡輪"
  },
  CollectionHall_124410_Desc = {
    Text = "吃掉吃掉吃掉吃掉……\n幻惑的魇思。\n碾碎碾碎碾碎碾碎……\n大海的喃喃自語。\n摧毀！摧毀！！摧毀！！！摧毀！！！！\n無法抑制的瘋狂。\n「莫絲好餓。」\n少女吞下滴淌鮮血的肉塊、可無論吃多少都無法緩解胃裡的虛無。\n「莫絲好渴。」\n少女咽下散發腥腐的海水、可無論喝多少都無法解除喉嚨的乾澀。\n「莫絲好困。」\n少女殴打麻木清醒的自己、可無論睡多久都無法抑制思維的疲憊。\n因為只有純粹的破壞、才能滿足體內的祂。\n「但是、莫絲、不要！」\n可少女拒絕了宿命的呼喚、特製的鋼鐵成了她無法退下的牢籠。\n她將自己打造成堅不可摧的監獄、用名為自己的拘束、囚禁了來自深海的瘋狂。\n「莫絲、關住了、壞蛋！」\n至此、自AF 1■■出現、吞噬無數生靈的大漩渦默斯克斯、於AF 31■、徹底歸於靜默。\n\n\n\n\n"
  },
  CollectionHall_124410_Title = {
    Text = "被囚禁的瘋狂"
  },
  CollectionHall_124413_Desc = {
    Text = "書架上除了枯燥的研究文獻之外，還有幾本看起來很有趣的兒童讀物。\n《灰姑娘》、《白雪公主》、《美人魚》、《長髮公主》……它們的主人為何會將這些書收在書架上——如今已無從得知。\n那些故事編織著與現實截然不同的情節。「王子」、「公主」、「愛」……這些詞語令少女的心怦然悸動。\n夜空中閃爍的無數光芒傾灑向大地，彷彿即將匯成一條流淌的光之河。\n在灑落的月光中，少女悄悄踮起腳尖，假裝踩上一雙透明的玻璃鞋。彷彿一直在期盼著——這深沉、孤寂的漫漫長夜終將破曉……"
  },
  CollectionHall_124413_Title = {
    Text = "淤泥裡的童話"
  },
  CollectionHall_124414_Desc = {
    Text = "游走在商船和商船間，總是把身形藏在破舊布褂陰影裡的老巫師說，羅盤會把人們引領到祂該去的地方，水手們嬉鬧著嘲笑她帶著草藥味的廢話，丟下五個雷歐坊，換走這個精緻的黃銅裝飾物。\n然後他們停靠在後來失去了名字的小鎮港口，龐托斯喜歡這個故事，羅盤的主人喜歡龐托斯。\n當然，沒有人不喜歡幽默、開朗，來去瀟灑得像一陣風的龐托斯。\n它原本應該是很好的紀念，是龐托斯轉贈給他親愛的外甥以後，開啟對遙遠彼方的遐想的鑰匙——但它讓龐托斯找不到他，龐托斯不允許，也絕不會讓他的生活有另一種可能性。\n當許多年過去，龐托斯在月色中穿行過無數個黑夜，尋覓著那個應當回到厄波揚斯的身影的時候，他是這麼想的。\n哦，那個徒勞的，保護性的法術離開他了，龐托斯現在可以把他帶回來。\n只是龐托斯還不知道，「羅盤會把人們引領到祂該去的地方」，如同每條船都有自己的航線，不同的人總是會選擇不同的方向。"
  },
  CollectionHall_124414_Title = {
    Text = "指向歧路的羅盤"
  },
  CollectionHall_124415_Desc = {
    Text = "「您要買一支火柴嗎？」冬夜，手腳凍得通紅的女孩呢喃著，「一支，就一支火柴就好。」\n「抱歉噢，我不會買你的火柴，」純白的身影微微躬身，遮住了冬季的月亮，「相反，我還要賣給你一些東西。」\n「可是，我沒有錢……」\n「沒關係。相信仙女的賜福吧，你很快就能賣出火柴了。」\n白衣的仙女將一顆糖果塞進女孩的手裡，然後貼近女孩耳畔。\n「看見街對面那個穿著皮毛大氅的中年女人了嗎？抓住她的衣角，拼命哭，說好心的太太，天太冷了，我的奶奶生了重病，如果不能吃上一頓飽飯，馬上就要病死了，求求您了，給我點錢吧。」\n「可是，奶奶很久以前，就已經離開我了……」\n「那更好了！你就試著模仿那個時候的感覺，哭得真一點……」\n「如果她還是小氣不肯掏錢，我也還有辦法。這種大年夜還在室外徘徊的人，家庭肯定不幸福。那你就補上，奶奶是我唯一的親人了，今天可是大年夜，誰也不想孤零零一個人，求求您，美貌的太太，只要三分錢，讓我能早點賣完火柴，回去和奶奶團聚吧。」\n「火柴是一分錢……」\n「剩下兩分錢，一分是我的抽成，還有一分錢要供奉給它。」卡拉布搖了搖手中的魔法棒，沉睡的白色幼蟲如水波般流淌。\n「別想那麼多，相信仙女的賜福就好了，這招一定百試百靈。記得啊，她掏錢出來之前，千萬不要鬆手。如果失敗了，我們再去找下一個孤獨的闊太太就好了。放心吧，在這個世道上，手頭有餘錢的女人足夠餵飽我們兩個人。」\n百試百靈的方法為什麼會失敗，已經沒人想去追究了。總之，在更新了一百八十二套話術後，小女孩的火柴成功售罄。\n在真實的「仙女教母」沒有出現的故事裡，偽造的仙女同樣拯救了瀕臨凍斃、貧窮可憐的女孩。\n可喜可賀，可喜可賀。"
  },
  CollectionHall_124844_Desc = {
    Text = "<Title:簡介>\n來自泰穆蘭的神秘少女。據其描述，原本是當地大學的準大學生，因一場「命運般的浪漫邂逅」成為霧境調查團的前鋒。\n在繁星黎明會的「霧災事件」裡，茉夏意外被召喚到此世，後在銀與血的儀式中，她經受洗禮，從人類轉化為喚醒體，並終結「霧災事件」。\n置身於不屬於自己的世界的她，仍舊尋求著回去的方法，但同時，她也對這個世界的未來充滿了興趣，渴望見證「世界的結局」。"
  },
  CollectionHall_124844_LockTip = {
    Text = "喚醒「茉夏」後解鎖"
  },
  CollectionHall_125443_LockTip = {
    Text = "需要通關限時活動「海城舊聞：玄女無相」任一關卡"
  },
  CollectionHall_125443_Title = {
    Text = "海城舊聞：玄女無相"
  },
  CollectionHall_126315_LockTip = {
    Text = "需要通關限時活動「織者自縛：木偶的舞台」任一關卡"
  },
  CollectionHall_126315_Title = {
    Text = "織者自縛：木偶的舞台"
  },
  CollectionHall_126425_LockTip = {
    Text = "可於調查行動星辰篇4-1中解鎖"
  },
  CollectionHall_126471_Desc = {
    Text = "茉夏早已習慣了迷霧的存在。\n無論是多麼難纏的迷霧，多麼危險的迷霧，她總能從其中平安走出。\n這次也一樣。\n她終會走出新世界的迷霧，回到屬於自己的維度。\n無論要付出怎樣的代價。"
  },
  CollectionHall_126471_LockTip = {
    Text = "完成多維連接「銀與血的洗禮」"
  },
  CollectionHall_126471_Title = {
    Text = "揭開新世界的迷霧"
  },
  CollectionHall_126472_Desc = {
    Text = "迷霧總有消散之時。\n彼時，響徹於霧靄裡的慘叫會消散，流淌在祭壇上的血跡會被拭淨。\n迷途的靈魂將得到解脫，找到正確的路途——\n前往閃耀的繁星，或留存於真實的大地。"
  },
  CollectionHall_126472_LockTip = {
    Text = "完成多維連接「銀與血的洗禮」"
  },
  CollectionHall_126472_Title = {
    Text = "迷霧消散之時"
  },
  CollectionHall_126473_Desc = {
    Text = "宇宙孕育了世界，世界孕育了生命。而不同世界的生命，又孕育出了不同的規則與理念。\n當他們交鋒時，廝殺的從來都不止是兩個軀體，兩個意志，兩個生命。\n那是永恆平行又突然相交的、兩個宇宙的碰撞。"
  },
  CollectionHall_126473_LockTip = {
    Text = "完成多維連接「銀與血的洗禮」"
  },
  CollectionHall_126473_Title = {
    Text = "信念的爭鋒"
  },
  CollectionHall_126474_Desc = {
    Text = "任務結束後，我將與過去的自己道別。\n道別那些熟悉又回不去的過往，道別泰穆蘭和身為人類時期的自己。\n我將懷念那充滿迷霧的世界。\n此後，我將以新的身分，存活於這迷霧消散的世界，這充滿趣味的恐怖世界。"
  },
  CollectionHall_126474_LockTip = {
    Text = "完成多維連接「銀與血的洗禮」困難難度"
  },
  CollectionHall_126474_Title = {
    Text = "霧語者的新生"
  },
  CollectionHall_126475_Desc = {
    Text = "殘酷的世界下，一個人的靈魂輕易便可焚燒殆盡。\n於是我們向他人和世界求索，親情，愛情，友情，思鄉之情……\n那觸摸不到的感情，就此化為不可看見的力量，延續著的生命，讓人們在這個世界燃燒得久一些，更久一些……"
  },
  CollectionHall_126475_LockTip = {
    Text = "完成多維連接「銀與血的洗禮」"
  },
  CollectionHall_126475_Title = {
    Text = "殘酷的生存智慧"
  },
  CollectionHall_126476_Desc = {
    Text = "亙古的繁星見證了世界的誕育、成長與繁榮，它也必將見證世界的終結。\n渴求生存的人們啊，存活的唯一方法，並不在我們的腳下，並不在背叛我們的大地上，而在我們的頭頂，那永恆的繁星閃耀之地。"
  },
  CollectionHall_126476_LockTip = {
    Text = "完成多維連接「銀與血的洗禮」"
  },
  CollectionHall_126476_Title = {
    Text = "繁星閃耀之地"
  },
  CollectionHall_126477_Desc = {
    Text = "拯救世界不是她的風格，而這裡，也不是她的世界。\n但她聽到了守密人的聲音，看到了守密人為了拯救世界做出的巨大犧牲。\n被人拼儘性命守護的世界，不該毀滅。\n至少在這一刻，不該由她親自毀滅。"
  },
  CollectionHall_126477_LockTip = {
    Text = "完成多維連接「銀與血的洗禮」困難難度"
  },
  CollectionHall_126477_Title = {
    Text = "無法理解的選擇"
  },
  CollectionHall_126906_LockTip = {
    Text = "通關意識潛遊「扇下夜談」任一關卡解鎖"
  },
  CollectionHall_126989_Desc = {
    Text = "<Title:簡介>\n她真正的來源，已然無從考證，最早關於這位古老「神明」似是而非的記載，可以追溯到數千年前。\n每個人看向她時，都會看到不同的面貌，實際上有著不知不覺污染對方記憶的能力，能把自己的形象潛移默化地融入對方的記憶中，最終使對方將自己認知為唯一重要的人。\n和其他大多數喚醒體不同，她幾乎沒有屬於人類的感情和視角。\n她是一個念頭，一腔狂想，一縷霧——她被感知為徐，被感知為劉、李、錢、張，她生於歡愉，也追逐來自於源源不斷的混亂的歡愉。\n但她並非完全不可理解，難以名狀的存在，被她所選定的個體，為她帶來極致愉悅的那些個體，會有機會窺探到那個能真正將其界定，不會與其他稱呼一樣變換無常的名諱。\n「千扇玄女」。"
  },
  CollectionHall_126989_LockTip = {
    Text = "喚醒「徐」後解鎖"
  },
  CollectionHall_127110_Desc = {
    Text = "雙手大劍長而沉重，在足夠的力道下足以將人斬成兩段。\n\n匕首輕便靈巧，便於隱藏，非常適合出其不意的攻擊。\n\n彎刀弧線華美，刀刃鋒利，劈砍時可以輕鬆嵌入皮肉，拉開一道深深的口子。\n\n槍械快而霸道，弩箭無聲且迅速，各種各樣的金屬部件在燈光下閃著冷酷的光。十歲的拉蒙娜站在掛滿了一牆的武器前，臉上是不符合年齡的成熟與慎重。\n\n「你想選哪個？」養父——不，是撫養自己長大的父親——的聲音從身後傳來，「選好了，我去給你物色老師。」\n\n哪個呢？大劍的沉重既是優點也是缺點；匕首難以應對較長的武器；彎刀雖然長，但切割總是會帶來很多不必要的損傷；槍械噪音太大，弩箭容易彈藥耗盡。\n\n在彌薩格訓練場旁觀了這麼多天，她知道自己能一眼看出作戰雙方的弱點，並能近乎直覺地計劃好攻擊路線。那些需要大量經驗積累才能知道的東西，在她這裡只需一秒便能推演出來。不，她要的不是這些。她需要一個更精確的，能夠用最少的力造成最大的傷害的武器。\n\n女孩思索片刻，從一旁搬來一個凳子，站在上面將手伸向掛在高處的細劍。\n\n細長優雅，靈活輕便，可以很准確地造成傷害——沒錯，就是它，它符合她的一切要求。"
  },
  CollectionHall_127110_Title = {
    Text = "溯洄時計"
  },
  CollectionHall_127111_Desc = {
    Text = "「當一個世界走向末日時，會發生怎樣的樂子？」\n茉夏不知道，但她期待著。\n這種期待和之前都不同，這次可不是什麼打幾個古物的小樂子，是以一個世界為衡量尺度的研究和調查。而這研究與調查中，最重要也最核心的，是一個人——\n彌薩格守密人。\n「我會拯救這個世界……」\n「這個世界，一定不會走向崩毀的命運……」\n那個心懷理想，身負一個世界興亡的人這樣做出承諾。作為回應，茉夏知道自己應該露出感動的表情，這是人類社會約定俗成的社交禮儀。\n但她不想再偽裝了，或者說，在觀看過守密人直面@4，以自身為代價拯救一個世界後，她覺得沒有必要對經歷過宇宙恐怖的人做出偽裝。\n「偽裝」是人類社會的遊戲規則，體面卻無聊，而宇宙……宇宙真實且直白——\n要麼生存，要麼毀滅。\n所以，她對守密人的回答也真實且直白。\n「我不在乎這個世界是否會得到拯救，或者毀滅……比起這些，我更好奇你。」\n我好奇你是否能夠踐行理想，還是會摧折在追求理想的道路中。\n也好奇這個世界是會回應你的願望，還是不可避免的走向毀滅。\n無論是哪一種，都會是盛大且不可多得的樂子。\n我會始終期待著那一天……\n用我的眼睛，我的斧頭，等待著。"
  },
  CollectionHall_127111_Title = {
    Text = "狂戮至世界盡頭"
  },
  CollectionHall_127112_Desc = {
    Text = "「記憶是什麼？」\n「是你遺忘的東西。」\n\n莉莉有一個健忘的媽媽。\n她會忘記叫莉莉一起吃飯，會忘記給莉莉喂藥，甚至還會忘記莉莉的名字。\n「該怎麼辦呢？」\n莉莉坐在病床上，故作深沉地歎了一口氣。\n這樣的媽媽可真不省心啊。\n\n後來，莉莉將自己的名字寫在一個木牌上，每天掛在胸前。\n這樣總該記住她了吧？\n一開始，媽媽還能笑著說她多此一舉，那只是長期勞累導致的併發症。\n\n漸漸地，她開始困惑、不耐：\n「莉莉……莉莉是什麼？」\n琥珀色的雙眼注視著莉莉，帶著一絲隱隱的審慎。\n原來，當文字的意義也被遺忘，這般依靠語言暫時維繫的和睦終將一去不返。\n\n莉莉抱住媽媽。\n母女倆的心跳聲只隔著短短几英寸，她卻感到孤獨極了。\n\n那天以後，莉莉將木牌收起，不再向媽媽撒嬌，也不再提醒她自己已經餓了好多天。\n她是行將就木的病患，麻木地等待死神的宣判。\n她是隔岸觀火的看客，遠遠地看著自己被注射、被麻醉、被擺弄成任何媽媽希望她成為的樣子。\n母女間那些愉快的話語、柔軟的擁抱……\n那些閃爍著夢幻泡泡的愉快回憶，都被莉莉小心翼翼地鎖在心裡。\n只有在某些疲憊的夜晚，她才捨得將它們拿出來，輕輕舔舐。"
  },
  CollectionHall_127113_Desc = {
    Text = "高聳的塔樓轟然倒塌，由不同時空不同種族的學者寫下的書籍散落一地，只一瞬間，大大小小的黑色三角就覆蓋在每一本書，每一塊磚上，並迅速連成一片向四周擴散。\n黑色黏液如同岩漿一般在整齊的街道上流淌，人們尖叫著，哭喊著，試圖逃離這可怕的災難。不少人試圖乘坐交通工具逃離，卻在慌亂中撞上建築或其他出了事故的飛船及車輛；更多的人來不及反應，只能徒步向遠離黏液的方向跑去，卻被其他同樣驚恐的人推倒在地，最終被黏液同化。孩子站在街邊大聲哭泣，幾個年輕人躲在僅存的建築物內，妄想著這樣就能躲過死亡。\n「明明沒有預兆，為什麼，為什麼！」\n「為什麼沒有人警示我們！」\n「@1，是融蝕！救命啊！」\n「快進行意識遷移！只有這樣才——啊！」\n「@2，快用儀器！」一個聲音說，「我們幫你拖延時間！」\n「不要！我——」\n「我們已經被@1了，而你，你還有希望。」一個溫和的聲音回道，「活下去，@2，活下去。然後——」\n\n溫柯爾猛地睜開眼，她身邊是高高摞起的書籍，好幾個滿是咖啡漬的馬克杯。不遠處的黑板上貼著或大或小的備忘錄和筆記，還寫著一條演算到一半的公式。凌亂的房間的角落，中央，以及她所在的巨大儀器旁都放著燈，將整個辦公室照得無比明亮。\n她沉默了一會兒，將身體更多地縮在定位儀上，繼續中斷了的演算。"
  },
  CollectionHall_127113_Title = {
    Text = "無法完成的演算"
  },
  CollectionHall_127114_Desc = {
    Text = "疼痛，劇烈的疼痛充斥著她的全部感官。\n\n金屬製的潛水服在水壓之下不值一提，外殼向內凹陷，螺絲崩裂，有什麼抵住了她的腹腔，有什麼刺穿了她的臂膀。冰冷的海水從潛水服破損的地方擠了進來，唯有使用了加厚金屬的頭盔還勉強維持著原樣，為她保留了一些綿薄的氧氣。\n\n透過頭盔僅有的窺探窗，她看到外面的海水由碧藍變成墨藍，再由墨藍變得漆黑。呼吸帶來的水汽凝結在玻璃上，漩渦的隆隆聲逐漸遠去，成為耳朵中殘存的幻影。她漸漸感受不到自己的四肢，呼吸也變得愈發沉重。\n\n她猜測自己應該暈過，寒冷、失血、缺氧，每一個都足以讓她意識模糊。同時她無法確定，因為無論她如何眨眼，面對的都是一樣的黑暗。\n\n這裡是光線無法抵達的地方，是大海深處未有人探知的領域。\n\n一種遲鈍的興奮最後攪動了一下她的血液——未知的領域，最後的冒險。她這也算完成夢想了吧？儘管她現在什麼都看不見。\n\n腳踝處傳來古怪的觸感，她下意識低頭望去，發現黑暗之中，似乎有什麼東西順著她的小腿向上攀登。是奇特的深海生物嗎，怎麼比海水還要冰冷？怎麼……在這樣的黑暗之中，她似乎能看到它的輪廓？\n\n漆黑的，蠕動的，如同泥漿一樣的……\n這是什麼？她在哪裡？她……是誰？"
  },
  CollectionHall_127114_Title = {
    Text = "記憶螺旋"
  },
  CollectionHall_127115_Desc = {
    Text = "（以下回答節選自克萊門汀的診療手冊，僅供參考）\n\n1. 凱刻斯。\n2. 16，17……？天知道。\n人死了以後還會管這些沒用的幹嘛？\n3. 一個破漁村，你不可能在任何地圖上查到它的名字。\n4. 我不想說。\n5. 怪胎。醜八怪。蠢豬。傻@1……這些比較常見。\n6. 閃閃發光的黃金鯰魚臉，簡稱鯰魚臉。\n7. 下雨天。\n8. 我不知道。下雨的時候，我會在沙灘上走來走去……\n有幾年了吧，就看看遠方，不幹別的。\n9. 我說了我#%不知道@1滾！！\n-------\n14. 唔……或許是奧恩叔叔曾告訴我，他會在下雨的時候，駕駛一搜大帆船來接我「回家」……\n15. 是的，他履行了自己的諾言……\n我在海底漂了好幾天，又渴又餓，全身都在痛……\n然後我看見奧恩叔叔和他的白色大帆船。\n他整個人，哦不，準確來說，是他的骨頭掛在帆船的桅杆上——他也蛻變失敗了。\n然後我用盡最後的力氣漂了過去，坐在桅杆上陪著他。\n16. 我們說好要一起回家的。"
  },
  CollectionHall_127115_Title = {
    Text = "傷痛之鰭"
  },
  CollectionHall_127116_Desc = {
    Text = "「人們於潮來時誕生，於潮退時死亡」\n這是在寧菲亞的家鄉一直流傳的傳說。\n\n塞瓦達的鄉民不懼死亡，在他們看來，生命的萌芽與凋零就像潮起潮落，都是自然的一部分。\n他們熱愛藍天、大海、成群翻飛的海鷗，還有迎著朝陽盛開的馬蹄蓮。\n他們厭惡蒸汽、鐵軌，以及一切人工干涉痕跡太重的事物——對生命的干涉也包含在列。\n人為地斬斷自己的生命，在塞瓦達人看來是不可接受的。\n\n寧非亞並不是一個典型的賽瓦達人。\n比如說，她總是被沉船的氛圍所吸引。\n一艘死去的沉船是無數生命的家園：魚、水草、各種貝類……\n在這裡，生與死以一種神秘、聖潔的方式交織在一起。\n寧菲亞滿懷平靜靠近沉船，彷彿邁入一座無比莊嚴的大教堂。\n\n在父親帶她外出旅行散心的歲月中，寧菲亞曾看過一部五幕劇。\n關於那部劇的內容，寧菲亞早已模糊，似乎講了一位古代帝王的一生。\n他生前戎馬倥傯，征戰南北，卻死於可恥的陰謀。\n她記得裡面的一句臺詞：\n<Italic:懦夫在未死以前，就已經死過好多次；勇士一生只死一次。>\n\n多年以後，當寧菲亞步入冰冷的海水，卻因對生的眷念而痛苦不已時，腦中便飄過那句話：\n「勇士一生只死一次……」\n於是她擦乾眼淚，最後一次向父母道別，這才向心中的沉船繼續行進。\n她將成為自己的勇士。"
  },
  CollectionHall_127116_Title = {
    Text = "腐朽贈禮"
  },
  CollectionHall_127117_Desc = {
    Text = "@1年6月5日\n阿爾比諾從融蝕裂隙中帶回來了一些稀有的銀芯。真有他的。\n改良了一下提純的方法。\n這次通入了足量二氧化碳和氯氣，低溫蒸發、結晶……\n一些機械的步驟，沒什麼好記錄的。\n\n@1年6月6日\n切除實驗體024的內臟及肢幹。\n這是阿爾比諾從診所裡帶回來的素材，已生成13個融蝕孔洞，最大直徑8mm。\n切割OS-106號融蝕怪物贅生物。\n根據各項測試資料的比對，它與024之間的共鳴相性最高。\n唯一的問題……那些觸腕有些過於「活潑」了。\n我想很長時間內我都不願意再吃章魚了。\n希望最後的結果別令我失望。\n\n@1年6月6日\n嫁接實驗成功，實驗體各項生命體征消失。\n這是常有的情況，只需要確保嫁接部位沒有擴散感染。\n送入觀察室觀察一週，接下來就不是我的工作了。\n今天在「內部期刊」上讀到兩篇抨擊活人喚醒體實驗的檄文。\n不用說，署名一看就是我在彌薩格的老朋友們。\n真可笑啊，這些老古板但凡肯挪動一下他們肥大的屁股，去實驗室稍微走走，就會知道我的結論是無可撼動的。\n024的實驗將成為一次絕佳的反擊。\n\n@1年6月22日\n兩星期過去了，024的各項體征依然不穩定——或者這麼說吧，她體內的人格正在以細胞有絲分裂的速度瘋狂增殖。\n實驗以一種匪夷所思的方式宣告失敗。\n把024送去蠟像館吧，我不需要它每天守著我，好讓我時刻回想起自己的愚蠢與輕率。"
  },
  CollectionHall_127117_Title = {
    Text = "畸體回噬"
  },
  CollectionHall_127118_Desc = {
    Text = "那是一顆銀白、澄澈、纖塵不染的心。\n它由純銀製成，在機械結構的心臟中有序搏動。\n也曾被血肉侵蝕，也曾因污泥染垢。\n但在死亡的陰霾籠罩之時，它終究回歸了本初的形貌。"
  },
  CollectionHall_127118_Title = {
    Text = "純銀的初心"
  },
  CollectionHall_127119_Desc = {
    Text = "時間流轉，對星球初生之時的記憶，蘿坦已經不大記得清了。\n她只記得，自己是被選中的生靈。\n\n那是發生在一切概念誕生前的故事。\n「生命」尚未扎根發芽，「神明」也遠在天垓之外。\n在這團無序的星雲中，混沌與混沌碰撞，物質在衝擊與攪動中日漸成型。\n星子攫取著塵埃，岩石隆起成山的形狀，大氣沉降為大片水澤。\n然後，這裡被宣告成為一顆「星球」。\n\n混沌的靈魂囿於時間的牢籠中，衝撞著新生的土壤。\n無法控制暴虐的本性，受破壞欲的操縱，祂推垮了無數山脈，填平了無數河澤。\n然後——「神明」跨越了遠星，降臨在了荒蕪的行星。\n\n「神明」帶來了文明的種子，也將混沌的靈魂禁錮在了「秩序」的軀體中。\n「與我……做一個約定吧。」\n面對咆哮的混沌之靈，白紗的「神明」絮絮訴說著。\n「偉大的文明將在這裡誕生。」\n「你將與無為的智者相遇，將與彷徨的利刃交鋒……在未來，你將不再受破壞與毀滅的控制。」\n「在那天到來前……在我們重逢前，替我守護這裡。」"
  },
  CollectionHall_127119_Title = {
    Text = "星天之獸"
  },
  CollectionHall_127120_Desc = {
    Text = "他被大公指名成為騎士時，僅在世界上見證了七個四季。 \n\n大公一時興起逗弄小孩的玩笑話，卻被所有人當了真。\n騎士們訓練他的騎射武藝，女官教導著他的禮儀，公主也信任並依靠著這名小小騎士。\n\n漫步在亞奎丹與峽谷的曠野高原上，年輕的騎士牽著公主的馬。公主無力地趴伏在馬背上，不可視的黑暗正在吞噬她的身體。\n\n「公主，我們不能再往前了。」\n穿過這道峽谷，越過這條河流，就會離開養育他們的土壤。\n戰火在外界蔓延，敵人隔岸對豐沃的土地虎視眈眈。\n憑著天塹之隔，小小的土地得以苟延殘喘地活著，維持著「國家」的尊嚴。\n在峽谷的這頭，他們見證了對岸的覆滅與苦痛。\n無辜者的祈求與悲痛墜入了河流，成為了勝者詩篇的一部分。\n\n無論是多偉大的國度，都將無法阻攔地被捲入歷史。\n\n敵人斬下了稚嫩的雙手，他不再能舉起槍與盾。\n敵人踩碎了脆弱的雙膝，讓他只能眼睜睜看著鐵騎砸開行宮的大門。\n騎士掙扎著咬在了敵軍戰馬的腿上，卻並未能阻止敵人的暴行。\n\n然後，他第一次看見了公主口中的「黑色瘟疫」。\n\n洪水般的黑液衝出行宮大門，沒過鐵騎們的腿甲，卻無人一人因此而停下。\n洶湧的「黑色瘟疫」灌進了口鼻，嗆入了肺腑，他卻仍不想在這裡倒下。\n再然後，那無比熟悉的聲音直接在腦海響起。\n「你做的已經夠多了……我最忠實的騎士。」\n\n最後，眼前只剩空白一片。"
  },
  CollectionHall_127120_Title = {
    Text = "騎士之心"
  },
  CollectionHall_127121_Desc = {
    Text = "祂們脫胎於人類對未知的想像，卻沒有想像中的歇斯底里與張牙舞爪。\n\n祂們是理智的，祂們是冷靜的。\n\n祂們為未來而來，為存續而來。\n\n祂們是最反常、最難以置信的奇蹟。\n\n起初，祂們的聲音有如蟲鳴。但在完全能夠理解祂們的思考後，那聲音便沉寂了下來。\n\n但此後，聲音的主人們試圖左右她所做的每一個決定。\n\n以喚醒體之身甦醒的第一年，她學會了與腦子裡的聲音相處。\n\n她潛入意識，成為格式塔的一部分，攫取所需要的資訊與知識，最後安然抽身，回到現實。\n\n在「黑色瘟疫」找上這具身體時，她也是這麼做的。\n\n她要將身體與知識、記憶、靈魂摘離，讓大腦成為不朽的個體。\n\n手術完成後，她險些進入了生動又奇妙的睡眠中——但只消數秒，她的思維便重新開始了運作。\n\n她清楚地知道，自己正在接近那超越了形式、力量與對稱性混沌中的絕對毀滅。"
  },
  CollectionHall_127122_Desc = {
    Text = "人們總是喜歡以自身的尺度去規定邊框、確定符號。\n世界局限在人類的肉身之中，是多麼的狹隘、愚昧又可悲。\n她早早地捨棄了肉身，卻依然不能觸碰到真實的邊界。\n知識的長河混亂無盡，而黑色的虛無已再次追上了她。\n她靜靜地與之對視，如果任何有形的一面都無法窺到世界的全貌，那虛無的背後是否才是真正的答案？\n她用自己的生命做出了此生最瘋狂的豪賭。\n她終於看見了終焉。\n真相的大門豁然洞開，世界的面貌轉瞬顛倒。\n原來如此，原來如此。\n她迫切地想讓所有人都看到這虛無的真實，從徒勞的掙扎中解脫。\n曾經她站在浪尖，引領著世界前進。\n如今她依舊揮舞著牧羊的皮鞭，步履輕快地將世界引入深淵。\n人們驚恐地驅逐了她，將她視為邪惡的瘋子。\n真奇怪，她想。\n可我眼中的你們也是這樣。\n"
  },
  CollectionHall_127122_Title = {
    Text = "墜入虛無的人偶"
  },
  CollectionHall_127123_Desc = {
    Text = "不必害怕死亡。那只是肉體將靈魂交還給夜色的過程，如潮水退去，歸於幽深的安寧。徹底地消散於融蝕，淪為無人知曉、毫無意義的存在才是真正的恐怖。\n她死得並不安詳。\n枯槁的身軀早已僵冷，血液與融蝕液混合，凝結如暗紅色的玻璃。可她年輕的靈魂仍在喉嚨深處顫抖，那一絲未曾消散的意識，如煙霧滯留在骨縫間。像一隻脆弱的、折翼的美麗蝴蝶。\n杜勒賽因靜靜地走入房間，腳步未驚動塵埃。他在她身旁跪下，視線輕柔地略過她緊閉的眼、未展的指節，以及不安晃動的靈魂。\n「我還活著嗎？」\n「這黑暗會把我吞掉嗎？」\n他不言語，只是伸出手，將她皸裂的手指一根根展開，像是為一朵顫抖的花瓣撫平摺痕。沒有憐憫、也沒有責備，只有平和而寧靜的耐心，像是世間最公正、最莊嚴的神明，賦予她安詳的權利。刹那間，她彷彿抵達了永恆的寧靜。\n於是純淨的芳香在他們交握的手中逸散，他俯身，滿足而莊重地在她的指背落下一吻。那吻落下的瞬間，死亡的最後一道回聲一點點拉長，直到融為飄在空中的一道清風，如暴風后的湖泊，全然寂靜。沒有疑問，沒有怨恨，沒有恐懼。她終於歸屬死亡本身。\n「我會記住你。」\n他直起身，凝視她如今徹底歸於寧靜的模樣。恍惚中，尖牙刺入皮膚，他聽到了賽琳涅的聲音。\n「我相信你，兄長。」\n她是幸運的，在杜勒賽因的記憶中，她將獲得永恆的安息。"
  },
  CollectionHall_127124_Desc = {
    Text = "你第一次見到活的魔像，是在女學者的家裡。\n「直到現在，她依然令我驚訝。對我而言，她就是宇宙本身。」\n魔像對你露出機械的微笑，嘴裡吐出含混不清的囈語。\n你望著她灰色的眼眸，彷彿置身一片洶湧的灰色海洋，粼粼的波光正從一個地平線爬到另一個地平線。\n\n臨走前，女學者遞給你一本破舊的小冊子，上面記載著製作魔像的訣竅。\n當天夜晚，你攤開它研讀潦草的公式和咒語，腦海里卻滿是魔像那難以捉摸的微笑。\n你再也沒能忘了她。\n\n數日後，你尋了個藉口再次拜訪。\n你跨過堆積如山的書籍、器具、骨架，撥開厚重的帷幕與纏繞的蛛網，最後蹲在魔像身前。\n女學者蜷縮在角落裡。不過幾日的功夫，她形容枯槁，眼裡早已失卻光芒。\n「你還是來了……和他們一樣。」\n女學者虛弱地咳嗽。\n「是啊……我來了。」\n你拾起魔像的手不斷親吻。\n微涼的指尖在你的脖頸處輕輕摩挲，伴隨細微的疼痛，你閉上雙眼。\n\n醒來時，你沐浴在溫暖的白色日光下，身體伴隨柔和的海浪起伏不定。\n你感到前所未有的輕盈，彷彿靈魂早已拋卻肉身。\n你轉過頭，看到一顆顆灰黑色的頭顱。\n它們嚎哭、扭曲，像一朵朵黑色的野花，星羅棋佈地點綴在灰色的原質海洋上。\n「不——」\n喉嚨嘔出黑色的粘液，你再也動彈不得。\n原來你也成為了那些頭顱的一份子。\n\n「@2年6月，著名煉金術師羅馬林·路德維希被發現離奇死於自家書房，頭顱不翼而飛，與之一同失蹤的，還有那本神秘的煉金術手冊……」\n\n（以上內容記載於彌薩格圖書館《煉金術逸聞》卷二冊）"
  },
  CollectionHall_127124_Title = {
    Text = "至為珍貴的藏品"
  },
  CollectionHall_127125_Desc = {
    Text = "時至今日，卡斯托爾也無法說出自由真正的釋義。\n他常常覺得自己是雙子之中更愚笨的那個，從少年時便木訥地跟隨在波呂克斯身後，聽弟弟說著一個又一個天馬行空的奇思妙想。\n在枯燥而麻木的修行生活中，他以為擁有那一抹輕鬆的亮色已經是最幸福的事，直到於麗埃特下令對波呂克斯進行定期的改造儀式。\n無盡的痛苦盡數傾瀉在波呂克斯一人的頭上，卡斯托爾茫然無措地陪在弟弟的身旁，看著那張飛揚的面龐上笑容越來越稀少，而自己想不到任何能做的事。\n「你知道自由是什麼意思嗎？」深夜之中，波呂克斯捧著那本早被二人翻爛的手抄本，靜靜地問卡斯托爾。\n卡斯托爾搖了搖頭。\n「那麼，你想去看看外面的世界嗎？哥哥。」\n卡斯托爾悚然怔愣，他似乎明白了波呂克斯想要追求的東西，那些他從未見過的、只存在於乾癟的文字中、存在於自己想像之外的東西。\n他為這樣大逆不道、驚世駭俗的想法所深深震撼，他沉默著，或許過了很久，或許只過了幾個呼吸，他便毫無恐懼地點了點頭。\n即便那要對抗整個教會，即便那要獻出自己的生命。\n於是，一雙鳥兒飛出了從未走出的牢籠，可惜他們從未想過，自由的代價會是如此不可承受之重。\n獵人的槍聲響過，鳥兒便從空中墜落。\n卡斯托爾才剛剛嘗到自由的味道，便眼睜睜看著弟弟那飛往自由的翅膀被生生地拔掉。\n面對於麗埃特恐怖的怒火，面龐蒼白而顫抖的弟弟背著人群，向自己露出了不曾屈服的笑。\n「堅持下去，為了自由。」\n卡斯托爾不停回想著波呂克斯那句無聲的口型，直到他在昏沉的折磨中將那兩個信仰般的字咀嚼成烙印後，他才再次與波呂克斯相逢。而這時他愕然發現，那始終在前方引領著自己的人，已經無情地將這兩個字拋下了。"
  },
  CollectionHall_127126_Desc = {
    Text = "風雨交加的夜晚，神明的女兒孤獨地坐在舷窗下。\n冰冷的月光照在襁褓上，流淌黑色黏液的聖嬰在其中安睡。\n神明的女兒唱起一支搖籃曲。\n「睡吧，睡吧，海的小寶貝。」\n「你的搖籃是黑色的月亮。」\n「把群星吞入夢鄉。」\n歌聲亦是禱詞，深海的魚群隨之彙聚。\n整艘航船宛如巨型的祭壇，恰似她誕下聖嬰的那天。\n剖開自己的胸膛，摘除淋漓的骨肉，以生命報償養育的恩情與種族的宿命。\n她的犧牲沒有換來渴求的自由，死亡不是永恆的安眠，只是悲劇的開始。\n自那之後，她的安寧只來自夜晚。\n「睡吧，睡吧，海的小寶貝。」\n當這支搖籃曲結束的時候，偉大的神國會刺破海面，從波濤洶湧的汪洋中升起。\n懷抱著這樣虛妄的幻想，墨菲也輕輕地合上了眼睛。"
  },
  CollectionHall_127127_Desc = {
    Text = "他始終苛責著自己，也用苛責逼走了所有的同伴，他本以為他將永遠獨自走下去，去追求音樂的極致。\n高處不勝寒，他接受了這注定的命運。\n直到他聽到了那個人的演奏。\n那個人的演奏與完美毫不相干，過於隨性的音樂如同那個人本身，偶爾會出現與曲譜出入的手誤，甚至會忽然忘記了某一部分。這時他的雙手總會即興彈出巧妙生動的琴音，博得滿堂驚喜與讚美。\n他注視著那個人，彷彿注視著音樂的精靈在音符間恣意撥弄玩耍。\n這就是被父親稱作天賦的東西吧。誠然，他與所有人一樣被深深吸引，但他無法改變他的腳步。\n他是那樣平庸愚笨的人，只能走上這樣一條辛苦鋪就的路。\n所有人追隨那個人而去，而他也與之漸行漸遠。\n他是渴望與他親近的，但他除了演奏什麼都不會。\n要如何與他相談，該用什麼樣的曲譜才能得他的青睞。\n他編撰著曲譜，如同斟酌開場白。直到他再也沒有開口的機會。\n深重的悔恨淹沒了他，所有的一切忽然失去了意義。\n眼中只剩下那封未完成的信，要寄給那個已離去的靈魂。\n他嘔心瀝血，終於倒在了那張曲譜面前，夢中依然沒有觸碰到那道路盡頭的光芒。\n如果我註定無法走到那路的盡頭，那我一生的執著又是為了什麼？\n有悠遠的笛音從那道光芒中傳來，安撫了他充滿質問的靈魂。\n恍惚中他拾起那笛，知曉了他真正的使命。\n用他永不停歇的演奏，帶來永恆的安寧。\n"
  },
  CollectionHall_127127_Title = {
    Text = "永恆安魂曲"
  },
  CollectionHall_127128_Desc = {
    Text = "哪怕沒有前面一截人生的記憶，從你並不發達的肌肉也可以看出，你之前一定不是什麼熱愛運動或暴力的那類人。\n你實在想不通彌薩格對調查員定下的戰鬥標準為何如此之高、如此全面。\n難道調查員的重點不在於調查兩個字，不在於智慧的頭腦、縝密的邏輯與一點恰如其分的好運嗎？\n每次被拉蒙娜從宿舍的被窩中準時拖起，站在空蕩蕩的操場上面對一輪又一輪的攻擊時，你就格外想念朵爾教授那充滿諷刺的邏輯學課程。即使是成山的作業和最令人脫髮的試卷，也比戰鬥訓練中一次次被毆打和跌倒的痛苦要溫柔太多。\n第19次，你被那柄封堵了所有行動路線的刺劍逼得失去了平衡，向後一屁股栽倒在地，感到渾身骨頭即將散架。\n氣喘吁吁中，你頹然抹去額頭的汗水，說什麼也不肯再起來了。\n拉蒙娜沒有任何意外的神色，她挽出一個漂亮的劍花收起了劍，鞋跟清脆地踏響著向你走來。你兩眼一閉，決心抱頭承受所有的指責與批評。\n意外的是，沒有任何敲打或謾罵到來，三秒之後你睜開眼睛，只有一張淡淡的笑臉湊在你的面前。\n拉蒙娜微微彎下腰，一隻被潔白手套包裹的手掌向你伸來。\n「其實你已經很努力了，我知道。但我們要面對的永遠是未知的恐懼與危險，哪怕是我，也會有顧及不到的意外時刻。」\n「就當是為了讓我放心一點，再來一次吧，搭檔。」"
  },
  CollectionHall_127128_Title = {
    Text = "搭檔特訓"
  },
  CollectionHall_127129_Desc = {
    Text = "人是一種喜歡歌唱的生物，對荒星人而言也是如此。\n旋律自喉中自由湧出，無需任何意圖和目的。\n它們被風拆成散落的音符，再隨情緒一起凋零。\n據說，在沙漠中，所有流浪部族都擁有屬於自己的歌謠。\n荒星人卻遺落了自己的歌謠。\n\n隨著歌謠一起遺落的，還有名字。\n沒人知道荒星原本的名字。\n這是受到詛咒的星球。乾旱、風暴、饑荒……\n各式各樣的災厄競相登場，終於將荒星徹底拖垮。\n衣著華麗的大人物乘坐方舟離去，荒星成了名副其實的荒星，只剩下那些不被祝福的底層人。\n他們都被遺棄了。\n\n自那以後，荒星人決定，他們不需要歡笑，不需要詩，也不需要歌謠。\n他們將銘記被遺棄的苦與痛，周而復始地蠕行在白色的沙漠之中，直到星球毀滅的那一刻。"
  },
  CollectionHall_127129_Title = {
    Text = "被縛的歌謠"
  },
  CollectionHall_127130_Desc = {
    Text = "大多數時候，死亡總是悄無聲息地到來，在人類的意識還尚未來得及反應的時候，死神就會悄然逼近，收走那鮮嫩脆弱的生命。\n不過，相傳在不為人知的某處沙漠中，存在一名琥珀色的死神。她會在發出宣告後，用琥珀的火，琥珀的槍，帶來琥珀色的死亡。\n男人站在月夜的沙海上，持握槍械的手正不停顫抖。他目不轉睛地盯著凱蒂古拉那琥珀色的身影，不敢有絲毫鬆懈。\n冷汗從他額頭滴下，落到身後每一個人的心中，他帶來的人很多，但此刻有用的卻很少。\n他不理解，不過是按照委託去劫掠一個早已無人的倉庫，卻為何會迎上傳說中的死神。\n「你說那死神？不過是之前的無聊謠言罷了。」\n凱蒂古拉若無其事地說著。\n「我曾將它們刷成琥珀色，或許你還能在上面找到一些未脫落的漆料？」\n她大方地向面前之人展示手中的雙槍。\n「槍口處琥珀色的火焰是撒了某種特殊物質。」\n她的手指深入槍膛，旋轉一週後帶出了些許不知名粉末。\n「所謂的死神，只是曾經的我打造出的一個形象。」\n「它強大，神秘，無所不能。」\n「它可以幫我威懾那些無能的宵小之徒。」\n她傲慢地說著，絲毫不在意眼前之人那愈發兇狠的目光。\n她旁若無人地說著，全然不覺危險已經逼近。\n當那槍彈向她傾瀉而出時，她的眼中露出震驚和茫然。\n隻為遮掩潛意識中那抹興奮與瘋狂。\n…………………………\n槍聲停息，一切都如她所想。\n她站在戰場中央，身邊的一切都滿布焦痕。\n凱蒂古拉只做了兩個動作——舉槍，射擊。\n她舉起長槍時，死神便舞至萬物身後，平等地降下死亡預兆。\n她扣動扳機後，火焰便席捲一切，為世界獻上琥珀色的花海。\n「它們伴隨我走過了許多年月，見證了無數鮮血和死亡。」\n「它們曾被迫披上謊言的外衣，用來遮掩我的弱小無力。」\n「現在，它們不再是謠言了。」"
  },
  CollectionHall_127131_Desc = {
    Text = "「你後悔了嗎？」\n從琳瑯的琉璃盞中蘇生的古老神明嗅聞著她、虛無縹緲地繚繞在她的肩頭、將窗推開、送來伴隨淺淡香氣的夜風。\n「我一蹙眉、連綿城牆上便會燃起狼煙。我一展顏、四面的流水就會載來奇珍和異獸、蜜釀和珍饈。我是整個王朝最珍貴的寶物、我為什麼要後悔？」\n她因為微醺而面色泛紅、咯咯笑著、埋在絲綢和皮毛堆起的高床軟枕中昏昏欲睡。\n……\n「你後悔了嗎？」\n附生在一縷線香上的古老神明和他對談、若有似無的煙氣流瀉下樓閣、勾勒出已舒展開萼片的花蕾。\n「他們鬥得焦頭爛額、我只用坐享其成、爬得越高摔得越狠。哪像我、應有盡有、誰後悔都輪不到我啊。」\n他嬉皮笑臉地又滿上一壺酒、信手順來軟枝、逗籠裡叫聲正歡的蟲豸。\n……\n「你後悔了嗎？」\n從井中爬出的古老神明在她耳邊竊笑、繚繞的霧拂過她的頭髮、將一朵飽滿的白玉蘭從枝頭晃落。\n「我有愛、有牽絆、有日落歸家時的熱粥、也有歡聚相慶時的美酒、我怎麼會後悔呢、我當然不後悔呀。」\n她拈起花貼在鬓角、暖黃燭影隨著她的裙沿搖曳、她的目光殷切地黏在窗邊、望向她等待的歸人。\n……\n「你後悔了嗎？」\n狼狽逃亡的裙釵沾滿宮門前污穢的泥點、昨日殷勤獻禮的侍衛彷彿聽不見她的哀哭求告、兩道冰冷的劍戟交錯落下、封鎖了她僅存的生路。\n霧氣悠悠地嘆息、然後一朵紅梅花綻開在雪地裡、又由下一場雪徹底掩埋。\n……\n「你後悔了嗎？」\n從檀木箱傾瀉出的南海珠璣撞碎在青磚上、琳瑯擲地的脆響竟比往日奏響的絲管更加悅耳。\n他最珍愛的、日日懸於案前鑑賞的字畫滾落堂前、妙手絕筆的墨痕山水被刀尖挑破、恰如他視而不見的戰火荼毒的社稷江山。\n霧氣嘲弄地繚繞、然後一把火起、那雕樑與畫棠都湮滅成前朝的餘燼。\n……\n「你後悔了嗎？」\n她念在舌尖的名字的主人再也沒有回來、遠方河邊枯骨、枕上美人。\n他做了天子門生公主賢婿？他流連花叢十年不返？他葬身流民腹中作了災後餘糧？\n霧氣曖昧地低吟、卻不曾給予她苦苦追問的答案。\n\n王朝鼎盛時最珍貴的寶物、會成為王朝傾覆時最珍貴的陪葬。\n家族繁榮時最悠閒的寵兒、會成為家族敗落時最理想的棄子。\n而最後一個故事、世間實在是太多太多了。"
  },
  CollectionHall_127132_Desc = {
    Text = "陰沉的雲籠罩在倫蒂尼恩上空，隔絕了月光。午夜的鐘聲已經敲響，高聳的煙囪仍在噴出高溫的黑煙與水汽。雪花沾了風中的塵埃，還未落地就已經染上暗淡的灰色，它飄飄搖搖地落在路燈上，幾乎是瞬間就被燈火的熱度融化，向下滴落在路過的女孩身上。\n女孩穿著褐色衣裙，過大的袖管被草率地挽起，露出兩條瘦骨嶙峋的手臂。她艱難地小跑著，時不時提一提衣袖，努力追趕走在前方的女人。\n女人側頭瞥向女孩，嘖了一聲：「動作快點，不要以為你走得慢了就不用去了。」\n「好、好的，媽媽，」女孩趕緊跑到女人身旁，嘴裡還喘著氣，「對不起，媽媽。」\n「不要叫我媽媽！」女人一把抓住女孩的手臂，拖拽著女孩加快了腳步，「吸人血的廢物，要不是你，我哪裡至於淪落到這個破地方。」\n「對不起……」\n「閉嘴，沒用的東西。」女人的指甲嵌入女孩的手臂，掐出一排深深的痕跡，「我告訴你，從今往後工坊才是你的家，也不要想著什麼出來找我，我就是死都不想看見你，聽到了嗎？」\n「我……我知道了。」女孩低著頭，落下的淚水被鞋子踏過，與骯髒的雪水一同消失在石板路上。遠處的工廠拉響了放工的笛聲，一隻野貓竄過巷道，細碎的動靜隱沒在兩人的腳步聲中。她們轉過街角，走過晾了衣服，散發著潮氣的後院，終於在一個有著金屬大門的建築前停了下來。\n「你就在這兒等著吧，」女人的聲音非常平穩，甚至帶上了一絲木然，「天亮了裡面的人就出來了，他們會收留你的。\n別跟上來，不然你看我打不打死你。」\n女人轉身離開，同樣瘦削甚至有些佝僂的身影很快消失在了黑暗之中。女孩無助地捏著自己的手，一邊望著女人離開的地方，一邊用袖子擦去臉上的淚水。\n昏黃的燈光從她身後出現，將鐵門和她的影子拉長，一隻手落在了女孩肩上，將女孩嚇了一跳。\n「可憐的孩子，怎麼一個人在這兒？」來人是一個年輕女性，穿著修女一般的衣袍，「來，莎拉姐姐帶你進去。很快就不冷了。」"
  },
  CollectionHall_127132_Title = {
    Text = "冬夜追憶"
  },
  CollectionHall_127133_Desc = {
    Text = "「我的成名作嗎？嗯——這麼好奇呀，好吧好吧，畢竟是VVIP的要求。不過，普通的講述未免太不符合我魔術大師的名號了，讓我用一場盛大的表演來向你展示吧！\n來來來，請在貴賓席落座，充滿金錢與背叛的懸疑快樂魔法回憶秀，即將開演！」\n-------\n一聲響指，燈光亮起，卡茜亞的魔術帽懸浮在半空，黃色的開口一開一合，竟然傳出了卡茜亞的聲音。\n「沒有很久以前，在一個不怎麼遙遠的地方，有一個馬戲團，馬戲團裡有兔子、有小丑、有獅子、有大象——」\n隨著帽子的抖動，從裡面掉落一隻兔子，一個小丑，一頭獅子，一頭大象。伴奏的鼓點愈發急促，伴隨禮炮炸響的砰砰聲，穿著華麗戲服的卡茜亞從帽子裡鑽了出來，並反手將帽子戴在了自己頭上。\n「最重要的是，有一位天賦異稟，才華過人的魔術師學徒！」\n-------\n學徒的成長伴隨著掌聲，甚至成功吸引了一位穿著華麗的投資人。奇怪的是，自從投資人與他們一同旅行後，兔子、小丑、獅子、大象……很多人和動物都一個接一個地不見了蹤影。舞臺上空了大半，學徒卻彷彿亦無所覺，她重複著原本的生活，直到投資人將一杯酒遞到她的面前。\n學徒喝下酒水，暈了過去，舞臺隨之一黑，微弱的歎息從黑暗中飄出。\n「那是我第一次明白遺憾。」\n-------\n「但是，遺憾怎麼夠？我還想要知道資助人先生哭的時候是什麼感覺，觀眾笑的時候是什麼感覺，我想知道更多，更多。這時候——\n我睜開了眼睛。」\n紙製禮花在空中炸開，碎片飄飄揚揚，卡茜亞突然出現在舞臺中央，她敲了敲帽檐，禮帽張開嘴，突出一片炫目的光。\n「我睜開了眼睛，然後發現，所有情感都是光，都可以收納到我的魔術帽中。\n現在請放輕鬆，我親愛的貴賓，接下來的環節一點也不會疼，只會讓你有一點麻木，感到生活有一點無趣……」"
  },
  CollectionHall_127133_Title = {
    Text = "快樂魔法秀"
  },
  CollectionHall_127134_Desc = {
    Text = "克萊門汀並不是一個堅強的孩子，所以在患上怪病，被病痛與逐漸逼近的死亡折磨時，她總是會在深夜驚醒，無聲哭泣。\n而每次哭泣後的第二天，她的床頭便會出現一個「禮物」。\n幾塊包裝華麗的糖、時下流行的髮飾、憨態可掬的毛絨熊……\n但最讓她印象深刻的，是一個蟲蛹標本。\n彼時，她已經病入膏肓，無法下床，只能費力地將那標本舉到半空中，瞪大眼睛望著透光蟲蛹裡的生命。\n那生命已經安眠，但那生命也獲得了永生。\n而她，瀕臨真正的死亡。\n想到這裡，她的淚水無聲滑落。但一雙手，替她擦乾了眼淚。\n「不要哭，克萊門汀。總有一天，你也會像這些蟲蛹，獲得新生。」\n「我會讓你獲得新生的。」\n父親從不會說謊，至少，不會對她說謊，所以克萊門汀對這句話深信不疑。\n她信任著自己的父親，因此進入那座褻瀆山脈時，她義無反顧，因此忍受血肉溶解的劇痛時，她毫無怨言。\n因為她相信這一切都是獲得新生的代價與必要過程。\n等所有的痛苦與絕望過去，她會痊癒，會回到那個被稱為「家」的地方，與她唯一的親人，團聚。"
  },
  CollectionHall_127134_Title = {
    Text = "隱沒的痛楚"
  },
  CollectionHall_127135_Desc = {
    Text = "她從不做夢。\n\n年輕的雕塑家學徒篤信絕對的理性與秩序，一如她冰冷的作品。\n可見到它的第一眼起，她就被迷住了。\n柔軟、純粹——那是完美的著色原料。\n她在月光下忙碌著，將黑色的粘液從亂葬崗帶回工作室。\n\n一週後，名為《@2》的雕塑在博覽會展出。\n當天夜晚，她聽到來自遠方的海浪聲。\n她第一次做夢。\n靜靜的晨光下，覆滿塵埃的海底宮殿酣然入睡。\n她穿行在白色的珊瑚叢中，呼吸中皆是孤獨與遺忘的氣息。\n\n醒來後，她的手指正在蜷縮、發黑，最後長出了白色的珊瑚。\n她聞了一遍又一遍，感受著其中來自遠古，無數生物的喃喃低語。\n那是真正柔軟的化石。\n她神經質地笑了起來——原來這就是做夢啊。\n她將自己關在工作室，開始忘我創作。\n倒模、泥塑、著色……\n混亂的、有序的。無機的，有機的。\n\n她將永遠做夢。"
  },
  CollectionHall_127136_Desc = {
    Text = "母親。母親。\n墨菲早已丟失了與之相關的大部分記憶。\n有人說，瀕死的母親護著她，鮮血嗆進了她的喉嚨裡。\n然後人們衝上前，蠻橫地將她們分離。\n就在那個瞬間，墨菲看見了母親的面容。那張臉神情狂亂，卻是很美的。\n記事以後，她有了一個新的「母親」。\n溫和，審慎，她會滿足墨菲所有無理的需求，卻保持著不遠不近的距離。\n在墨菲以為她們的關係會一直這樣下去，就像彌利亞姆的表情永遠不變一樣時，她被高高托舉上漆黑的王座，於夢中見到那散發著磷光的「卵」。\n它在暗夜中閃閃發光，像眼睛，又像星星。縹緲的歌聲環繞在聖所四周：\n<Italic:自他女兒的@1中，@1的神祗降臨@1……>\n她被賦予一項與她有關又無關的偉大使命：成為讓神明復生的母親。\n真奇怪啊。她尚且不明白何為母親，何為女兒，卻要開始學習做一名「母親」。\n墨菲想起了那張狂亂的美麗臉龐，想起了舌尖上甜而苦澀的滋味。\n那個美麗的人，是不希望我如此向墳墓墜落的，是嗎？"
  },
  CollectionHall_127136_Title = {
    Text = "隱秘的誕生"
  },
  CollectionHall_127137_Desc = {
    Text = "關於旺達的確切來歷，坎布裡安的鄉民眾說紛紜。\n\n有人說，他親眼見到旺達坐著一塊巨大的石頭墜入湖畔。\n有人說，她是來自勒姆瓦希的女法老，他曾在木乃伊身上見過一模一樣的脊刺。\n還有人說，她是來自弗蘭高地的女公爵，在連續克死四任丈夫後，繼承了鉅額的財產。\n……\n\n傳言如風般散去，鄉民們繼續耕作、紡織、推磨。\n在那些困苦的年月裡，沉重的稅賦是高懸頭頂的利刃，斬斷一切橫生的枝節與綺念。\n只是……每每路過女王棲息的湖區，叢林掩映中傳來的樂音還是輕易勾住了大家的心。\n那是不該出現在這裡的旋律。\n它太愉悅、太慵懶，以至於顯得邪惡，宛若惡魔低語。\n\n「來吧，拋開這一切。」\n「慈悲的王端坐於湖中央，祂靜待盲眼僕從的侍奉……」\n\n於是，在一個無風的夜晚，疲憊的鄉民放下農具，決定滿足一下偷跑的好奇心。\n他繞過樹林，穿過小橋，道路兩旁鮮花盛開，他連看都不看一眼。\n他看到綠色的湖泊。\n它與低垂的星空相連，邊沿聳立著一座古老的城堡。\n\n頭戴荊棘的女王端坐於湖中央，耐心地等待前來朝聖的子民。\n她伸出手，享受著來自凡人的親吻與膜拜。\n烏雲散去，明月升起。\n女王將脊刺刺入他的背脊。\n麻痺的液體沿著血管蔓延，他跪在地上，被砍掉四肢，被剜掉雙眼。\n\n至此，來自大地的沉重引力再也無法將他吸附，他所有的詩與夢都只繫於那位女王。\n他終於迎來自己的命運。"
  },
  CollectionHall_127138_Desc = {
    Text = "「終日苦行之人啊，祈盼這份禮物能夠溫暖你的靈魂，願父神的仁愛撫慰你心中的苦痛，為你帶來香甜的美夢。」\n銀霜夜將盡，燭火低垂。久違地擱置了沉重的石板，薩爾瓦多脫下莊重肅穆的長袍，換上了一身暖和的紅絨裝扮。為了明日的冬渡節，他特意去到達芙黛爾的小店，為彌撒格的學生們準備了驚喜。\n「這是最後一份禮物了……」\n薩爾瓦多靜坐在校園角落的舊椅上，因疲憊而無意識地墜入了夢境。\n那是一個香甜的美夢。腳邊的禮盒不知為何悄然打開——四枚薑餅人倏然躍出，糖霜點就的眼眸灼灼生輝，肉桂與丁香的氣息在冷冽空氣裡旋舞成圈。\n香氣喚醒了塵封的記憶，他彷彿回到了幼年時的教堂回廊，融化的太妃糖在舌尖傳遞出甜蜜的信號。那些被苦痛與瘟疫侵染的祝福，正隨這甜膩的圓舞曲悄然復甦。\n……\n與此同時，四個偷偷摸摸的的身影悄悄接近了陷入睡夢中的薩爾瓦多。\n「主人……主人會把我們當成是壞孩子嗎……」\n「呼呼——奧瑞塔太好奇啦！快打開呀~一個，兩個……哇，好多薑餅人呀！」\n「你、你……把名字說出來了，萬一……他們會討厭我們的……！」\n「嘿嘿，我們可沒有想偷拿哦！都是布朗幹的啦！」\n薩爾瓦多聽見小薑餅人們嘰嘰喳喳地交談著，感受到一個薑餅人躍上膝頭，肉桂的呼吸拂過他佈滿皺紋的手背。\n不，不是夢中的薑餅人，而是現實中頑皮的孩子們。薩爾瓦多能夠想像到孩子們偷偷打開禮物盒時，臉上洋溢著的幸福笑容。為了這瞬間的美好、幸福與安寧，他甘願承擔一切苦痛。\n「哦……我的鬍子，這是在拿鬍子跟頭髮打結嗎？」\n薩爾瓦多裝作依舊熟睡的樣子，讓孩子們繼續這快樂的「秘密行動」。"
  },
  CollectionHall_127139_Desc = {
    Text = "你和拉蒙娜從未約定再次相見。\n門扉在眼前緩緩合攏的刹那，你們心中劃定的別離的時限，已是註定的永恆。\n\n所以，當她在時光的罅隙裡，轉瞬即逝的相逢裡輕輕勾起你的小指……\n這已經是預期之外、足夠幸運的重逢。\n「你一點都沒有改變。」她說。\n\n為了這一句話語，為了指尖微弱的溫度……縱然遙隔兩個世界，你仍願傾盡所有，飛躍銀河與她相見。\n明年今日，勾指起誓。"
  },
  CollectionHall_127139_Title = {
    Text = "你我終將重逢"
  },
  CollectionHall_127140_Desc = {
    Text = "「撤退，撤退！」\n「往@3撤！動作快！」\n「救命，救救我！不要丟下我！」\n「別管他了，趕緊撤退——艾爾瓦！」\n手持銃刃的士兵一個健步衝了出去，炮火在她身側炸響，士兵的廝殺聲，慘叫聲，急促的戰爭號角響成一片。血液染黑了泥土，散發著連硝煙的氣味都無法蓋過的濃重腥味，倒在地上的士兵們眼神空洞，不論是哪個顏色的軍服，都在此刻變成了刺眼的紅。\n艾爾瓦咬著牙，頂著一個又一個向她攻來的人向前。她能看見了，那個呼救的年輕人，他被按在地上，雙手同時用力努力格擋住來自一名高大敵軍的匕首。\n爆裂的槍鳴與劇烈的疼痛同時造訪，不遠處的敵人緩緩倒下，艾爾瓦立刻回身揮刀，忍著腿部的疼痛向前用力撞去，趁著敵人失去平衡的瞬間一把貫穿了對方的胸膛，同時按下扳機。\n子彈打入軀體濺起血肉，她隨意抹了一把臉，回頭想要確認年輕人的安全，卻發現對方已經不知何時離開了。\n她低頭看去，一把刀從她的左膝上方貫穿了她的腿，溫熱的血液汨汨流淌。\n她從披風上撕下一條布綁在腿根勉強限制血流，將銃刃當做臨時拐杖一瘸一拐地跟上部隊。"
  },
  CollectionHall_127140_Title = {
    Text = "堅韌意志"
  },
  CollectionHall_127141_Desc = {
    Text = "歷史向來是贏家的一言堂，母樹消亡、國家傾覆，有關過去的一切都在悄然發生著改變。\n詩人傳唱著尼尼微美人的故事，旅人圍坐篝火側耳傾聽。\n\n「穿越銀色的沙漠，異國美人闖入了尼尼微\n天河之水從她的肩頭滑落，西奈珍珠從她的眼中墜下\n金黃雙瞳之中，凝視異度國土的過去\n蜜色肌膚之上，書寫尼尼微的未來」\n\n後來呢？這位美人成為王后了嗎？\n年邁詩人彈撥著七絃琴，發出一聲悠長歎息。\n\n「她是迷藥，眾生為之傾倒。\n她是猛毒，沁入王臣肺腑。\n她是洪水，蒼生無可逃脫。\n她是黑色瘟疫的使臣，她帶來疫病、噩夢、死亡和尼尼微的末日。」\n\n琴尚未放下，酒桌邊站起一人，引來眾酒客側目。\n那人纖長的指間漏下幾枚酒錢，金銀滾落，叮噹作響。\n她所行之處，目光追隨，燈火閃爍。\n\n「時間荏苒……但無妨，祂不會回應這些胡言亂語。\n終有一天，你們會理解祂的慈悲與寬厚……正如我所理解的那樣……」\n她推開酒館破舊的小門，如同推開一尊珠寶匣，月光落在裸露的肩頭，映照出琳琅的光。\n那被月光寵愛著的美人，確實有著如蜜的肌膚。"
  },
  CollectionHall_127142_Desc = {
    Text = "當她從花房中睜開眼的時候，大火已經席捲了整座花園，來到她的身前。\n花房的門鎖從外面鎖上了，空氣中彌漫著濃烈的酒精與油脂的味道。她大聲呼喚柯蕾特的名字，直到聲音被煙霧嗆得嘶啞，回應她的也只有火焰的呼嘯聲。\n她感到慶倖。還好柯蕾特出門了，否則這樣大的火，她也會有危險。\n她感到難過。人生的最後時刻，她沒有能夠見到摯友最後一面。當柯蕾特回來，看到被燒毀的花園和自己，一定會很難過吧？\n她感到遺憾。她們的生活正變得好起來，可這火焰將為她們劃上句號。\n燃燒。房子在燃燒。天空在燃燒。樹葉在燃燒。花瓣在燃燒。花園中所經歷的一幕幕場景在她面前演繹、流轉：她帶她來到花園，她遞給她玫瑰，她用一天的勞作為她帶來柔軟的麵包。她們嬉戲，追逐，躺在寧靜的陽光下，暢想著住進伯爵夫人房間的那一天。\n燃燒。過往在燃燒。未來在燃燒。花園帶著所有的故事所有的情愫，瘋狂地燃燒著。\n淚水從她臉上滑落，在火焰的炙烤下，很快消失不見。\n她感到美。在詩歌中，痛苦與遺憾是美的。她四處尋找，找到了被火焰侵蝕殆盡的紙與筆。\n感激，眷戀，不舍，祝福，美。她要把這最美好的這一切，都留給柯蕾特。\n「……致柯蕾特。奧爾拉，於火中。」\n詩箋的句尾，她留下了最後的落款。\n百米外，花園對面的道路上，柯蕾特似乎感應到了什麼。她抬起頭，猛烈的火光映照著她的臉。\n淚水從她臉上滑落，在火焰的炙烤下，很快消失不見。"
  },
  CollectionHall_127142_Title = {
    Text = "詩箋的句尾"
  },
  CollectionHall_127143_Desc = {
    Text = "他們在黑暗的河流中划行，蒼白，沉默，疲憊不堪。\n朦朧的霧氣伸長觸手，將他們拉入黑暗，徘徊在沒有盡頭的永夜中。\n\n後來，他們看到了一束光。\n那是來自遙遠岸邊的曦光，它忽明忽滅，卻足以照亮暗淡的靈魂。\n於是他們循著光，笨拙地劃出黑暗，來到破曉的黎明面前。\n也來到你們面前。\n\n或許這只是一次短暫的相逢，但他們用力揮舞雙手，竭力呼喊。\n所有人都沐浴在神聖的曦光下，所有人都在笑著。\n他們說——\n願每一個相聚的瞬間都如節日般珍貴。\n願真誠的心永不停止跳動。\n願銀鑰指引前行。"
  },
  CollectionHall_127143_Title = {
    Text = "極夜與破曉"
  },
  CollectionHall_127144_Desc = {
    Text = "風從四面八方湧來，你手持蠟燭站在迷宮入口。\n你有些迷茫。\n似乎上一秒，你還在彌薩格的食堂裡，聽夏洛特講一些關於圖書館地底迷宮的傳說。\n而現在，你穿著睡衣，睡眼惺忪地行走在一個接一個的甬道裡。\n「夏洛特，夏洛特……」\n伴隨窸窸窣窣的響動，白色的蜘蛛潮水般湧入。\n它們凝結成蒼白的少女。她坐在肉塊雕砌的鞦韆上，一蕩一蕩的。\n\n「你來了。」她說。\n「我來找夏洛特，我的朋友。她迷路了，我要找到她……」\n你幾乎就要哭出聲來。\n少女咯咯笑了起來。她跳下鞦韆，走到你面前。\n「你忘了嗎，我們的交易……」\n女孩伸手撫上你的肚子，恍然大悟。\n「對哦。你早已成為我的子嗣，所以什麼都不記得了。」\n「子嗣……？」\n你低頭感受著你們肌膚相處的地方。\n溫暖的觸感如蛛網般深入皮下，再蔓延到血管的最深處。\n少女神秘地眨了眨眼，湊近你耳邊輕聲說：\n「夏洛特，就在你的肚子裡呀。」"
  },
  CollectionHall_127144_Title = {
    Text = "蒼白後裔"
  },
  CollectionHall_127145_Desc = {
    Text = "巨大的舞臺上，一個少女正在舞蹈。\n她頭髮緊緊地梳成一個髮髻，頭上點綴著潔白的羽毛和小巧的王冠，純白的舞裙隨著她的動作展開，在哀婉的提琴聲中轉了一圈又一圈。\n手臂舒展，足尖點地，白天鵝低垂長頸，向王子訴說自己的悲傷與哀愁。\n年幼的莉茲微張著嘴，看著台上輕盈優雅的少女，那是她的堂姐，在她出生以前就到她家裡來，在她祖母手下接受嚴格的訓練。平日裡總是樸素而且安靜的堂姐從未如今天這般鮮活，她就像一隻即將振翅而去的天鵝，而她，他們，劇院裡的所有人，都傾倒在她的陰影之下。\n她的心跳越來越快，越來越快——多麼令人羡慕！她也想成為那只天鵝，在永恆的舞臺上長久地留下屬於自己的倒影。她知道自己做得到，難道祖母不曾在她不注意的時候稱讚過她的腿又長又直嗎？難道她那做了多年首席的表姐不曾說過，她極有舞蹈天賦嗎？沒錯，只要她開始，只要她穿上足尖鞋，人們一定會從遙遠的城市前來觀看演出，她將是本世紀最偉大的舞者，芭蕾藝術的璀璨明星！\n那時的她還不知道，等待自己的，只有熾熱的火焰。"
  },
  CollectionHall_127145_Title = {
    Text = "旋轉，旋轉"
  },
  CollectionHall_127146_Desc = {
    Text = "這是你來到彌薩格的一年後。 你仍然記得你從那場大爆炸中醒來後，第一次踏入這所學校的那一天。你被髮放了合身而規整的校服，擁有了獨屬於自己的宿舍，第一次參觀餐廳並吃光了兩摞餐盤。 所有輕鬆的時刻在這一天戛然而止，轉眼你就因過於貧瘠的知識和嬰兒般光滑的腦回路，被勒令就讀為期一年的預科班。 語言學習，體能特訓，銀芯能力測試，特種生物常識補充……在飽受折磨之後，你的成績好壞參半，你那不及格的雷歐通用語成績和一次性連結了三個喚醒體的壯舉讓你在校園中名動一時。 幸運的是，出於你特殊的能力與卓絕的天賦，你還是迅速達到了一位調查員的能力標準，不必再繼續延長預科的時長。至於你那些參差不齊的短板，就由那些逐漸默契的夥伴們替你補習與兜底。啊，這裡雖然盛產魔鬼，那也是一群可靠溫柔的魔鬼。 這裡常常多雲、落雨、少有晴天，無數被遺忘的和將被遺忘的人們始終堅守、犧牲、不斷前進。 在這樣諸事如常的一天，彌薩格迎來了又一年的開學日。 你對著鏡子整理好校服的衣領，撫平每一絲褶皺，而後推開了宿舍樓的大門。 「哈欠，終於來了，我都快睡著了。」 「你是在宿舍裡學習抱窩嗎？新生。」 你衝蘿坦訕笑一聲，對著那個足以引起你生理恐懼的粉色身影縮了縮脖子，躲到了一旁笑著的拉蒙娜和奧吉爾身後，五道影子在清晨的校園裡搖晃著拉長。 「走吧，搭檔。」 「從今天起，你就正式成為彌薩格的一員了。」"
  },
  CollectionHall_127146_Title = {Text = "開學日"},
  CollectionHall_127147_Desc = {
    Text = "沿著泰姆河一路向下，向右拐至貝克曼街，繼續行走大約一百英尺，你就能在那不起眼的角落看到「萊克偵探事務所」。\n\n作為倫蒂尼恩破案率最高的偵探事務所，這裡沒有塞滿專業書籍的大書架，沒有貼滿剪報的牆面，也沒有精緻的下午茶。\n你大機率只會撞見門前掛著的「有事外出」標牌以及趴在一旁的疲憊老狗。\n\n若是運氣好點，在某個天氣晴朗的週日上午，你興許能等到宿醉歸來的名偵探先生。\n此時他剛結束上一把賭局，兜裡沒剩幾個錢，你可以盡情向他提出你的無理委託：尋找貓咪、解救入了邪教的老母親、搜集丈夫的外遇證據……\n只要你有，他就能接。\n\n「我享受瀕死前的瞬間，所以我註定會成為一名賭徒。」\n「那成為偵探呢？恕我直言，我看不出尋找貓咪和瀕死之間的相關性。」\n「不，你不明白……尋找真相的過程本身就已足夠迷人，不論大小。就像……」\n「就像奔赴一場和死亡的約會。」"
  },
  CollectionHall_127147_Title = {
    Text = "好運時間"
  },
  CollectionHall_127148_Desc = {
    Text = "波呂克斯做了一個夢。\n他夢見自己身披銀色的鎧甲，從一位威嚴的國王手中接過一柄光潔如月的長劍。\n而後他跨上高大的白馬，奔赴向一個洞窟之中，當他深入地底，洞口的樹木都簌簌地發出細微的呢喃。\n洞窟的深處潛藏著一團暗綠色的陰影，那是一個高大如肉山的怪物，它怪異的雙眼冒出綠色的光芒。\n「危害國家的怪物啊，我不能允許你再威脅我們神聖的國度，今日，我將用這柄正義之劍將你消滅！」\n那怪山顫抖著，似乎在回應一般，發出恐怖的吼叫。\n波呂克斯聽不懂它的語言，也無意聽懂它的話語，他舉起寶劍，與那散發著邪惡氣息的怪物戰鬥起來。怪物的觸手遍及洞穴昏暗的邊界，與光輝的長劍碰撞出鏗鏘的脆響。\n如每一個英雄故事的結尾一樣，英勇的騎士跨上怪物的後背，在怒喝中將劍尖插入了怪物的胸膛。\n怪物頹然倒下，波呂克斯在如釋重負的喘息中，怔愣凝視著劍下慢慢擴散的痕跡——那醜陋邪惡之物的身軀中，怎會流淌著如此溫熱鮮紅的血液？\n他從夢中猛地驚醒，那鮮血沾染雙手的黏膩觸感彷彿揮之不去，他的餘光忽然看到了那本被卡斯托爾珍藏的舊書，正小心地被藏在床後的縫隙。\n他將那本書隨意地翻開，恰巧是卡斯托爾常常翻閱的那一篇騎士故事，在書頁的正中，他看到這樣的一句預言：\n「當邪惡的怪物被勇士擊敗，人人將見天空中有異象，日頭要變為黑暗，月亮要變為血。」\n波呂克斯皺了皺眉，不屑地將這本舊書扔回原位，在月光下喃喃祈禱起來。\n「神的僕人被差遣到這裡來為你們賜福，使你們洗脫罪孽，從黑暗中歸向光明，和一切純潔的義人同入淨土……」\n持燈者並未關照祂虔誠的侍從，噩夢帶來的不安仍在那顆心臟深處顫動，那是他沉眠的靈魂在夢中默默地哭泣。"
  },
  CollectionHall_127148_Title = {
    Text = "扭曲的騎士詩"
  },
  CollectionHall_127149_Desc = {
    Text = "<Bold:1月24日>\n身上臭烘烘的。\n今天和特蕾莎管家乘車回家時，路過南安普區。\n這不是一次愉悅的體驗。\n那是個危險的地方@2有些傢伙身上長了奇怪的傷口，像是三角形的孔洞。\n特蕾莎管家說這是主降臨給異教徒的懲罰。\n\n<Bold:2月22日>\n發燒一個月。\n今天總算吃了點東西。是新鮮的牛排，鮮嫩、多汁……\n對，多汁。\n紅色的@2腥甜@2美味\n家裡所有的鏡子都被收了起來，連波比都不敢看我。\n嘻嘻。他們都不知道，晚上的時候，我能從窗戶的投影中看到自己的模樣。\n我的臉上、脖子上、胸口上……從上到下，密密麻麻，\n長滿了黑色@2三角形\n\n<Bold:3月17日>\n我的眼膜就像被罩上了一層紅色的細紗。\n世界變成了血的顏色@3\n父親站在血霧裡朝我大喊大叫，這是他第一次用這麼大的聲音和我說話。\n他離我很近，聲音卻離我很遠。我聞到絕望、厭惡和血。\n不要@2帶我走，不要……"
  },
  CollectionHall_127150_Desc = {
    Text = "埃裡溫人居住在灰色的石之城裡，毗鄰綠色的大湖。\n\n大湖沒有名字，早在埃裡溫人有記憶起，它便存在於此。\n相傳，邪惡的女妖被封印在湖水深處。\n她與大湖同樣古老，是鴻蒙初開之時被粗魯塑造的可怖存在。\n天真又膽怯的埃裡溫人懼怕女妖，他們試圖討好女妖，確保她能永遠安靜地待在湖底。\n\n「應該做點什麼呢？」\n「是啊，做點什麼呢？」\n「那就跳舞吧！無論如何，跳舞總是好的。」\n\n於是，每逢凸月，埃裡溫人聚集在湖畔，面對紙草做成的偶像翩然起舞。\n彼時月明星稀，一切和平。\n\n數百年後，埃裡溫人忘記了歷史，忘記了寓言，也忘記了偶像。\n在石之城建城的千年慶典上，他們放肆歡笑，暢飲美酒。\n嘈雜的聲音投入湖中，就像石頭入水，以無窮無盡的圓圈從湖中央蔓延，最終觸及深處的存在。\n於是，恰逢凸月，埃裡溫人聽到了聲音範圍之外的聲音，見到了視覺範圍之外的月亮和火焰。\n他們最終也成為寂靜的一部分。\n\n這些無限空間內的永恆寂靜使埃裡溫人充滿恐懼。\n他們被迫像神秘主義者一樣端坐不動，眼見新的族群在他們面前放肆歡笑，暢飲美酒，來來去去，周而復始。\n所以宇宙會永遠繼續膨脹，星系會越來越遠，所有事物都會消亡。\n事情就是這樣。\n埃裡溫人是否為此感到孤獨一點也不重要。"
  },
  CollectionHall_127150_Title = {
    Text = "無聲歡宴"
  },
  CollectionHall_127151_Desc = {
    Text = "女孩睜開眼，發現自己身處一片黑暗之中。\n「喂！」她大喊，「有人嗎？」\n回聲在看不見邊界的空間中飄飄搖搖，逐漸散去，女孩深吸一口氣，再次大喊：「姐姐，布朗，西區佬！」\n「有人嗎——」\n比先前音量更大的問句遙遙飄遠，又緩緩歸來。幾縷熒藍的光彷彿被回聲牽引由遠及近，它們由無數懸浮飛舞、細如塵埃的粒子構成，如蛇一般在空中蜿蜒前行，又如海浪一般起伏。一條接一條的光帶一刻不停地掠過站在原地的女孩，迅速將整個天地變成一片星海，細小的粒子穿過女孩的手指和髮間，沒有留下一點痕跡。\n「這是……什麼？」\n發光的塵埃在她周圍微微起伏，沒有回答。\n「我記得蠟像館，記得姐姐，我……好像是死了，這裡是天堂嗎？」她左右張望，「怎麼連個天使都沒有，該不會是地獄吧！」\n她的聲音落在自己耳邊，這一次，連回聲都不再出現。\n一種莫名的孤寂感從她心底而生，恍惚間，她好像回到了遇到姐姐，遇到布朗之前。陰暗的下水道臭味彌漫，她又冷又餓，卻無法離開，因為有人在將她推下來後，在下水道頂上壓了個大桶。\n她拍了拍自己的臉，邁開步子向前走去。\n塵埃在她身前分開，又在她身後聚攏。抬腿，落腳，抬腿，落腳。她就這麼一直走，一直走，不知道自己走了多久，也不知道自己走了多遠。在她前面的是更多的塵埃和黑暗，而在她身後，不論是來的方向還是走過的路，都已經了無痕跡，直到——\n「喚醒成功了，詹金，詹金，你聽得到嗎？」"
  },
  CollectionHall_127152_Desc = {
    Text = "創生的父神自星空中來。\n那時的地是赤焰熱土，烈火熊熊。父神的足踏在火上。\n父神說，火終將熄，火便這麼做了。\n流動的土成了地，父神在地上寫下神言：\n地將做生靈的基。\n山谷就成了山谷，平原就成了平原。\n神言穩固，這是第一塊石板。\n\n父神看雲厚重，說，雲終落雨，雲便這麼做了。\n雨彙聚成流水，父神在其上寫下神言：\n水將做溫床。\n水就成了湖、成了海，海就淹沒了地。\n神言穩固，這是第二塊石板。\n\n父神看水暗淡，說，光當降臨，光便這麼做了。\n光落在水上，父神在光上寫下神言：\n光將滋養。\n光就帶來溫暖。\n神言穩固，這是第三塊石板。\n\n父神見地、水、光皆有了，說，生命將臨。\n祂讓自己的血流下，在其上寫下神言：\n血將孕育新生。\n父神的血散了去，成了有生命的物，在海中繁衍。\n神言穩固，這是第四塊石板。\n\n父神見生有了，說，生物將永恆地變化。生物便這麼做了。\n微不可見的物爬上退了海水的地。\n父在變化的物上寫下神言：\n變化不可停止。\n爬上陸地的物就長出根莖，長出四肢，長出各種模樣。\n神言穩固，這是第五塊石板。\n\n父神見生有了，變化也有了，說，死亦將至。死便來了。\n衰老的死去，病弱的死去。父神在死上寫下神言：\n死的將回歸到最初。\n死者的軀體就慢慢消了，回到父神的懷抱。\n神言穩固，這是第六塊石板。\n\n父神見生、死、變化都有了，說，這些都是我的造物，我將留下祝福。\n父神取出自己的骨，在上面寫下神言：\n在萬物的末路，可用我的骨，代行我的權。\n以血肉的代價賦予生機。\n神言穩固，這是第七塊石板。\n\n父神看一切都有了，就停下來休息。\n水將父神包裹起來，光為父神提供溫暖，地將父神遮蓋。\n而後父神長眠，萬物都依照父神的言生存，那就是現在的世界。"
  },
  CollectionHall_127153_Desc = {
    Text = "他即是通曉萬事之王，是利莫里亞的至高無上。\n青金石是他的王座，黃金是他的冠冕。靈魂是他的權柄，他在最高處安睡。\n侍奉神的祭司也侍奉他，在他身前跪拜，\n他們是他忠實的臣子，是他虔誠的信徒。\n\n神明在夜晚派遣月光，將他接到永眠的宮殿中做客，\n在那裡，祂們與他分享靈魂的食物，給予他神的智慧。\n祂們賜他無盡的夢境，讓他得以觀見萬物伊始，觀見時間末路。\n他於是知道了：萬物的初始皆是混沌，眾神在其中甦醒，建立懸浮在黑暗中的宮廷。\n他於是知道了：時間之末是一片黑暗，一切重歸混沌。\n\n眾王之王啊，神的寵兒，\n誰能與你相同？\n誰能如你一般自夢中統領，誰能如你威嚴？\n高貴的神王啊，年幼的主宰，\n請你盡情沉眠。\n你的臣民與信徒會耐心等待，你帶回神的預言。\n尊敬的螺湮主宰，號令深淵之主，\n請允許我們呼喚你的名，賜予我們庇護，\n圖魯，圖魯。"
  },
  CollectionHall_127153_Title = {
    Text = "神王的頌歌"
  },
  CollectionHall_127154_Desc = {
    Text = "多年來，我一直想著尤烏哈希。\n但只是在這些神廟的廢墟裡，我才第一次真正看清他。\n我看見他身上纏繞著沉重的枷鎖，因而不得不趴在地上，伸長脖頸，費力湊近早已變質的餐食。\n像條狗一樣。\n\n卡裡古拉死後，身為暴君的同謀，他被鎖在神廟的廢墟至今。\n我拖動手上的鎖鏈，將一個託雷斯的奴隸押送過來。\n他登時直立身軀，瞳孔放大，喉嚨裡發出急促的吞咽聲。\n\n「等等。」\n我拽住鎖鏈，將奴隸拉至他恰好無法夠到的距離。\n「幫我殺一個人。」\n他咧嘴笑了，露出一排尖利的獸齒。\n「你是第19個這麼和我說的人類，而我不得不拒絕你。」\n我竭力繃著臉，不讓他看出我的失落：\n「為什麼？」\n「如果你要我殺一千個人，我樂意至極。殺一個？你的籌碼遠遠不夠。」\n「如果那個人，是現在的皇帝呢。」\n我深吸一口氣。\n「這個籌碼足夠嗎？」\n尤烏哈希哈哈大笑：\n「這是數學問題，我的老夥計。一就是一，一千就是一千。」\n\n「著火了，金宮著火了！」\n遠方燃起熊熊火焰。\n暴君，暴君……\n我絕望地哭泣，為了塞內加，也為了那即將成為廢墟的華美宮殿。\n「這麼傷心？」\n尤烏哈希湊了過來。\n他已經享用了那個託雷斯的奴隸，正滿足地撮著嘴。\n是的，我向他許諾，只要能殺了暴君，除了自由，他還可以接著享用一千個無辜的生命。\n他能理解這場大火意味著什麼嗎？\n他能理解侍奉一個無可救藥的暴君意味著什麼嗎？\n恐怕不能。\n他只是個畜生罷了。\n\n「羅馬就像一個廢墟。」畜生說。\n「或者說，你們的國家，世界……\n在我看來，是既無意義也無止境的廢墟。\n你們為它流淚、互相殘殺，做了一切徒勞又無意義的事……\n說實話，我不理解。」\n\n我望向他傷痕累累的軀體。\n這是由數百萬血肉所鑄就的魔像，它在數百年的歲月裡，不斷被打碎、重組，就像羅馬一樣。\n「那你呢？你也是一座廢墟嗎？」\n「或許吧。」\n他伸了個懶腰，狹長的眼裡躍動著來自遠方的金色火光。\n「但我不在乎。」"
  },
  CollectionHall_127155_Desc = {
    Text = "螺湮的主宰啊，請聆聽我的禱告。\n降下你的預言，給予我啟示，\n讓我能夠復原你的國。\n在這無信仰的土地，在這海洋環繞的冰原，\n將你的石柱立起，將你的神殿搭建。\n\n號令深淵之主啊，台上的是獻給你的禮。\n純淨的血肉來自滿月的羔羊，強健的心來自成年的公牛，\n銳利的眼來自翱翔的雄鷹，堅硬的骨來自巡洋的鯨。\n青金石是你的王座，黃金是你的冠冕，\n請賜予我你的夢境，告予我神言，\n讓我能夠復原你的身。\n在這冰下的深淵，在這海下的領域，\n將正確時刻降生的母體奉獻。\n\n通曉萬事的利莫里亞之王啊，請回應我的禱告。\n自你入海長眠以來，已過了千百年，\n我以你的名，行你的事，宣揚你的美名，從未懈怠。\n堅定的是我的信仰，虔誠的是我的心。\n你是唯一的神王，是不朽者的化身，\n願你終結我的等待，再臨於世，讓我得以聆聽你智慧的言。"
  },
  CollectionHall_127155_Title = {
    Text = "虔誠的偉力"
  },
  CollectionHall_127156_Desc = {
    Text = "奧瑞塔出生時，大洪水帶給城市的影響已經完全褪去了，但在偏遠的鄉鎮上，人們還在為了活下去而掙扎著。\n\n洪災讓人們開始恐懼海洋與江河，能離開的早就離開了，如今還留在這個小漁村的，都是些在外難尋立足之地的婦孺。\n在這個沉悶冷清的地方，奧瑞塔是唯一的小孩。\n\n她執拗地相信著婆婆講的童話——爸爸媽媽都已經回到了大海，他們在等待奧瑞塔長大。等她長大了，大家就能團聚，再次成為幸福的一家。\n\n在她還不會說話的時候，好像曾在很溫暖的懷抱睡著過，但其他有關父母的事情，奧瑞塔已經不太能想得起來了。\n但身為在寂靜之地出生長大的孩子，奧瑞塔並不理解「孤單」或「寂寞」，她自有一批朋友。\n\n和那些被洪水嚇破了膽子的大人不一樣，奧瑞塔從來都不懼怕海洋。\n海洋國王的住民，自然要和大海做朋友。\n奧瑞塔學會了和「同鄉」一起玩。\n她模仿蛤蜊移動的樣子舞動，學著小丑魚在海草中梭巡。\n她趴在棱皮龜的背上，順著海浪漂流到了離陸地很遠很遠的地方。\n她在被傾注滿月光的大海中，與水母群在海中嬉戲。\n\n她是快樂，她是想像，她是精靈。\n\n她是夢。\n"
  },
  CollectionHall_127156_Title = {Text = "海之夢"},
  CollectionHall_127157_Desc = {
    Text = "眼見一個鄉下村姑穿戴浮誇的禮裙、金銀首飾、羽扇，潛入上流精英人士的世界……\n沒有比這更不得體的事情了。以下犯上，簡直是以下犯上……！\n要我說，應該強制下等人佩戴相應的標識和徽章，這樣才不至於和我們混淆在一起。\n——菲力浦·哈樂德公爵\n\n如果您生活在倫蒂尼恩，一定對所謂的「索蕾爾效應」有所了解。\n還在苦惱自家衣服賣不出去？那你最好祈禱自己有點門路，能獲得索蕾爾夫人的青睞——是的，哪怕是一頂愚蠢透頂的豬尾巴禮帽，只要戴在索蕾爾夫人的頭上，它就能大賣。\n她就是新時代的大眾偶像。\n——「索蕾爾夫人的名氣測驗」，《淑女指南》\n\n那是一個晴朗的夏夜。\n我們一起坐在大理石鋪就的露台上，喝著陳年釀造的貴腐酒，談論詩與世界和平。\n然後就發生了一些@4\n說重點？咳咳，對不起……\n總之，這個女人騙了我三千雷歐坊，兩份蘇里蘭的房產，以及一顆誠摯的心！\n——某不願透露姓名的心碎子爵"
  },
  CollectionHall_127157_Title = {
    Text = "以薔薇之名"
  },
  CollectionHall_127158_Desc = {
    Text = "分開。經歷。蜂擁而來。侵略。\n\n對於非利士人的閃族語詞根「p-l-sh」的真正涵義，經書學者們歷來分歧不斷。\n平生第一次，戈利亞覺得這些老學究還算有點真才實學，因為這四個簡短的詞彙幾乎概括了他作為非利士人的一生。\n\n非利士人是名副其實的海上民族。\n他們是群聚的長尾鯊，循著鮮血的味道找到可供棲息的島嶼，再殺光那裡所有的原住民。\n\n非利士人不知疲倦。\n他們從不逗留，當一切塵埃落定，躁動不安的基因又驅使他們離開，尋找新的獵物。\n\n非利士人不在乎明天。\n他們總是以驚人的速度揮霍掠奪來的財富，飲盡最後一滴葡萄酒，然後盡情繁衍、爭鬥、背叛……\n\n啟航的時候，戈利亞回望船隻在海面上拖曳而出的軌跡。\n非利士人的血，原住民的血，敵人的血，海鳥的血……\n它們匯到一處，就像暗紅的墨湧入無邊無際的藍。\n\n第二天，太陽照常升起，海水如萬片碎金動盪閃爍，一切都了無痕跡。\n他們身處海洋，海洋卻已將他們忘卻。"
  },
  CollectionHall_127159_Desc = {
    Text = "卡修利亞民間流傳著沉沒文明的傳說。\n\n相傳遠在歷史記錄前，星辰的異常移位使一個史前文明沉入了海底，而卡修利亞人就是那個文明的後裔。\n除了經商、漁業外，卡修利亞人出海的一大目的就是尋找失落的先祖文明。\n他們相信，在特定星位下出生的女孩會與先祖文明有感應，她們能指引沉沒文明的方位，也能從風浪中庇佑船隊。\n\n希萊斯特就是這樣被選中的。\n她被捆縛在高懸白帆的桅杆上，看著下方的人類忙忙碌碌。\n她既不關心，也不好奇。\n\n希萊斯特能從海風、海鳥的動向中感知海上的天氣，偶爾也能探知來自遙遠沉睡之地的氣息。\n她天生就是屬於大海，屬於航船的吧——希萊斯特時常這麼想，被禁錮的事實似乎在她的心裡沒有起任何波瀾。\n有時候她會離開桅杆，追尋海空中飛翔的白鳥，那時行船就會緊緊地追著她不放。\n人們相信少女是航行順利的象徵，受祝福的船只能夠平安返航，帶來鉅額的財富與先進的文明。\n而她對此一無所知。"
  },
  CollectionHall_127160_Desc = {
    Text = "噔，噔，噔。\n腳步聲由遠及近傳來，頭戴禮帽的紳士穿過廢墟，站在奄奄一息的看守面前。\n紳士：你在這裡做什麼？\n\n（紳士患了嚴重的口吃，看守則喜歡兜圈子。為了您的閱讀方便，筆者只摘錄談話重點。）\n\n看守：我在看守監獄。\n紳士望了望四周空無一人的原野，以及因沾染融蝕、正在緩慢塌陷的廢墟殘骸。\n紳士：可是這裡沒有監獄，也沒有囚犯。你的王國早就不存在了。\n看守：我在看守監獄。\n紳士：為什麼？\n看守抬起頭，稚氣未脫的臉上帶著茫然與堅定。\n看守：我不知道……我想回家。\n看守：我替那位大人看守監獄。大人高興了，我就能回家。\n至於那位大人是誰，為什麼要替他看守，她自己也搞不清楚。\n紳士並不追問，彷彿這是再自然不過的事情。\n紳士：你的家鄉，那是什麼樣的？\n看守：那裡只有冬天和黑夜，還有一望無際的森林與大海。\n紳士：聽上去不適合居住。\n看守：我討厭白天。看到了嗎，我是蠟做成的，如果接觸到太陽，我就消失了。\n看守：所以我只能躲在這裡，沒辦法自己回家。\n紳士若有所思地點點頭。他忽然興奮起來。\n紳士：真巧，你是由蠟製成的，而我剛好是個蠟像師。\n紳士：我們來做個約定吧——我可以讓你行走在日光下，我還可以幫你找到回家的路。作為交換，你要成為我的助手。\n看守：助手，那是做什麼的？\n紳士：你可以替我看守蠟像館。它和這座監獄不一樣，它是藝術，藝術是不會坍塌的。\n看守：藝術這麼厲害？\n紳士開心地笑了起來。\n紳士：是的，就是這麼厲害。\n\n故事的結尾，看守稀裡糊塗地跟著紳士走了，正如她稀裡糊塗地來到這所監獄一樣。\n她一直是個隨遇而安的傢伙。"
  },
  CollectionHall_127161_Desc = {
    Text = "你踏上了一片杳無人煙的荒原。\n人類活動的痕跡消亡已久，靈魂枯槁的生靈在灰燼與塵霾中艱難跋涉。\n這裡的存活不值得歆羨，無人知曉旅程的終點，只在無盡循環的光景中徘徊、徘徊、徘徊。\n直到他們的腳步滯澀，重重栽倒在地，仰望著天空伸出呼喚之手——\n\n願我的跋涉終結之後，\n以屍骨為沃土、為滋養、為源泉，孱弱的新芽重新破土。"
  },
  CollectionHall_127161_Title = {
    Text = "重生於湮土"
  },
  CollectionHall_127162_Desc = {
    Text = "她曾一萬次在深夜中發問，為什麼她要承受這無盡的痛苦？\n無人回答。\n呢喃穿過嘶啞的喉嚨變成碎屑，沒有傳達到任何一位神明耳中。\n她的痛長久難消，逐漸發酵成了膿汁，化作越來越濃郁的仇恨。\n忽然有一天，她發現周圍的人身上開始滲出黑色的液體，和自己身上流出的血液那麼相像。\n他們很快變得癲狂，就像自己一樣。\n或許那是他們的痛苦，她冷眼旁觀，又隱隱感到一絲快意。\n可如果那是痛苦，自己豈不是早就被黑色所淹沒。\n她接近了那些遺留下來的黑色，卻意外獲得了自由。\n自由沒有給她帶來解脫，她如同被流放在地獄千年的惡鬼，心中的願望早就由仇恨腐蝕殆盡。\n她的身體嵌進枷鎖，她的心靈墜滿鉛塊。\n唯有那些淒厲的叫喊能夠洗刷她沉重的靈魂，讓她得以暢快地呼吸。\n來吧，品嘗我曾品嘗的，讓你成為我。\n她發現紅色是多麼美妙的一種顏色。\n她終於明白，痛苦沒有緣由。\n要麼自己痛飲，要麼邀人共嘗。\n今夜她斟滿苦酒，與整座城鎮相邀。\n"
  },
  CollectionHall_127162_Title = {
    Text = "沉入殷紅"
  },
  CollectionHall_127163_Desc = {
    Text = "我的船被什麼緊緊纏繞，螺旋槳吃力地掙扎著，聲音可怖。\n積雨雲在我們頭頂彙集，烏黑的雲層中雷電翻湧。\n驚雷打在桅杆的瞬間，螺旋槳掙脫了束縛，再次轉動了起來。\n我鬆了一口氣，輪機長卻開始尖叫。\n\n海水中混入了一種粘稠的液體，暴風雨的野外，氣味隨著風被吹到了遠處去，我的鼻子只聞得到死亡。\n但我意識到，那閃爍著螢光的液體是某種血液。\n我最親愛的夥伴，我最信任的船，在沉沒前傾盡了全力——她那本應劈開海水的葉片，狠狠切下了怪物的觸手。\n\n這是幸運的預兆！我們很快就能駛離暴風雨！\n我正想以此安撫我的船員，可就在抬頭的瞬間，一道光芒出現在了暗海中央。\n那是燈塔嗎？怎麼會呢？不，不可能。\n這裡是大洋中央，最近的陸地在數百海里外，怎麼會有人，又怎麼能夠在這裡建造燈塔呢？\n\n我的水手們開始哭泣，開始祈禱，開始齊聲唱起了故鄉的歌謠。\n然後，那燈塔陡然熄滅了。\n一切的光都消失不見，咆哮的風暴也化為淅瀝小雨落在甲板上。\n水手們讚頌著仁慈的主，沉浸在劫後餘生的喜悅中。\n可我確是看清了的。\n\n那消失在光芒中的，確實是一個身姿曼妙的女人。"
  },
  CollectionHall_127163_Title = {
    Text = "於暴雨之中"
  },
  CollectionHall_127164_Desc = {
    Text = "當英雄終於結束他的偉大旅程，人們合上圖畫書的最後一頁，沉沉睡去。\n\n長夜將至，屬於希洛的故事才剛剛開始。\n\n她沿著悠長的海岸線一路向北，踏過溪流，翻越高山，直到極寒之地的盡頭。\n距那場震驚世人的反抗已過去多年，希洛所到之處風調雨順，諸事皆宜，奴隸和主人之間維繫著微妙的平衡，暴烈的反抗顯得尷尬又滑稽。\n她被質疑，被嘲弄，最後被遺忘。\n但她從不辯解。\n\n戰士希洛來去無蹤，她將自由的種子深埋在陸間海的腹地。五年、十年、一百年……\n總有一天，它們將破開土壤，茁壯成長。\n\n無人知曉這位斯巴達殺手最終的埋骨地，據說她的昔日密友伊巴密濃達收斂了她的屍體。\n多年以後，當你路過一個茉莉花盛開的青草坡，或許能見到一方小小墓碑，上面寫著：\n\n這塊草地下埋藏著一名戰士，或者說\n她曾是一名戰士\n她是老伯利克里之女，也是提洛島的驕傲\n詩人弗拉庫斯稱讚她作戰英勇無比\n黑髮的斯巴達人更清楚她的功績"
  },
  CollectionHall_127164_Title = {
    Text = "掙脫鎖鏈之日"
  },
  CollectionHall_127165_Desc = {
    Text = "A. F.@1年@1月@1日\n\n08：00\n\n對編號為107至133的部件進行組裝。\n\nC類型部件就差這一點了，完成後將作為自動人偶「嘀嗒人」的能源核心投入使用。\n\n我本想親自組裝的，但@2說，負責人要學會信任自己的工作夥伴。\n\n真好意思說，明明她才是那個檢查部件檢查到半夜的人。\n\n-------\n\nA. F.@1年@1月@1日\n\n00：21\n\n電機MF311000組裝完畢，齒輪吻合，管道通暢，目前各項機能正常。即將進行最後修正。\n\n13：07\n\n接入特殊能源S，電機MF311000運轉良好，與EA307850號人造軀體適配良好，人造軀體正常運轉。\n\n@2很樂觀，她覺得我們這次能比之前走得更遠。我提醒她不要忘記第五次喚醒嘗試時發生了什麼，她就堵著耳朵說聽不見。那次要不是我反應快，能源核心自燃的火焰會把她的頭髮都燒光。\n\n真該讓她嚐嚐光頭的滋味，說不定這樣她還能學會謹慎。\n\n-------\n\nA. F.@1年@1月@1日\n\n14：55\n\n最終準備完畢，能源準備完畢，束縛裝置已開啟，束縛狀態：良。軀幹將在喚醒完成後進行安裝。\n\n15：00\n\n開始「嘀嗒人」第13次啟動嘗試。\n\n15：05\n\n軀幹EA307853運轉正常，電機MF311000運轉正常。「嘀嗒人」頸部關節活動正常，「嘀嗒人」頭部部件運轉正常。\n\n15：15\n\n「嘀嗒人」成功執行眨眼、視線跟隨、張嘴指令。電機存在發熱現象，但仍在可接受範圍內。\n\n即將進行四肢部件安裝，上天保佑我們這次順利。\n\n18：07\n\n執行行走指令時，電機核心熔解，線路燒毀。特殊能源S完好無損。\n\n@2對這個特殊能源很保護，即使是我都禁止觸碰。我想我可以理解，那確實是一個神秘的物件，看上去就像是普通的金屬銀，也不像有能量儲存的能力的樣子，卻真的能給自動人偶供能，而且那樣高的溫度也沒有對其造成損壞，實在是不可思議。\n\n如果這個東西能夠批量生產，或者大量開採……\n\n或許我該找一天再問問她，也不知道她在這個人偶上還要花多少時間。哪一天她自己變成一個人偶，我都不會感到意外。\n"
  },
  CollectionHall_127166_Desc = {
    Text = "「我們用凡俗的銅與鐵，丈量星辰的軌跡，但無盡的深淵有自己的算法，陰晴不定。」\n逐漸沉沒的遊輪裡，克珀珊特吟誦起《領航員挽歌》。\n她早已知曉自己的命運，也早已選擇自己的命運，因此對面死亡，她沒有恐懼，只有平靜——平靜地燃燒，平靜地完成最後一次的領航。\n但焚燒的火光太過熾熱，她看不見前路，發不出聲音，也無法揮舞旗幟，這樣殘缺的指引下，船隻是否能夠正確航行？\n她不知道，並因此產生出恐懼與憂慮。\n這時《領航員挽歌》給出了指引：「年輕的領航員啊，你終將被鹹水擁入懷中，化為引路的磷火。」\n引路的磷火？克珀珊特沉默。她確實聽聞過在水手間流傳的聖艾爾摩之火的故事，然而區區凡人之軀，如何化為照亮人世的聖火？\n但即便希望渺茫，克珀珊特也在內心中不斷祈求：祈求自己能夠履行職責，完成最後的指引工作。\n除了克珀珊特自己，沒有人能夠聽到這祈求，但這已經足夠了——\n黑暗中，銀芯以融蝕漿為養料，迸發出強烈的光芒，實現了她最後的心願。\n「潮汐黑冊將記載你的名諱，令咆哮的怒濤為你奏響永恆的安魂曲。」\n她最終如《領航員挽歌》所言，死亡於大海。\n但她又超越了《領航員挽歌》。\n那是人類領航員面對大海時的狂妄與勸誡，而如今，她已成為聖艾爾摩之火，永恆指引船隻。"
  },
  CollectionHall_127166_Title = {
    Text = "聖火中的指引"
  },
  CollectionHall_127167_Desc = {
    Text = "她被稱作伴隨著死亡出生的詛咒之子，不被祝福的女兒。\n屬於她和妹妹的「襁褓」剛剛破裂，絢爛的光便從縫隙中流出，在地上扎根。一瞬間，綠草枯萎，鮮花灰敗，連遠方的大樹，湖中的遊魚，都被她吸取了生機，成為一個個無魂的軀殼。\n她的族人大驚失色，趕忙將所有其他襁褓轉移。她努力破開襁褓，像雛鳥破開蛋殼，伸出的手卻被厭惡地躲開，目之所及的是一張張嫌惡的臉。\n只有她妹妹，那晚於她降生，又早於她成熟的妹妹，永遠會抱著她。為她用靈鳥一般的歌喉唱出一首又一首搖籃曲。\n睡吧，睡吧，我親愛的姐姐；\n睡吧，睡吧，好夢終將降臨。\n\n她不該存在的，如果她不存在，她那流光溢彩的妹妹就不會被染上罪惡的陰影。\n我可憐的妹妹啊，她總是想，你承擔了本不該承擔的生存的代價。\n我可憐的妹妹啊，她總是想，只要姐姐能夠做到，就一定為你竭盡全力。\n睡吧，睡吧，我親愛的妹妹；\n睡吧，睡吧，在夢裡我也愛你。"
  },
  CollectionHall_127167_Title = {
    Text = "吞噬搖籃曲"
  },
  CollectionHall_127168_Desc = {
    Text = "他看見教堂的尖塔如同蠟燭般融化，滴落在神父潔白的羽翼上。彩繪玻璃上的聖徒像以極快的速度腐爛成骷髏、又在瞬間倒退成為嬰孩。尖銳與圓柔的幾何體從信徒的口中頌念出，堆滿整個大廳。\n他看見火車站的空間反復摺疊成非歐幾里得空間，遠處的站臺近在咫尺，近處的檢票口遙不可及。大廳的鐘表逆時針旋轉，枯骨般的人群如同被看不見的線條提著倒退行走，濃稠的紫羅蘭般的煙霧從雲端飄進火車的煙口。\n他看見森林裡的「空」凝成實體，樹木、岩石、藤蔓只是「空」的邊界勾勒出的半透明的輪廓線。天鵝的羽毛是不斷變換的馬賽克色塊，它們遊過的地方，湖水凝固成半透明的彩色玻璃。情侶依偎的長椅下， 鮮豔的橙黃色的影子正試圖啃噬主人的腳踝。\n他看見歌劇廳的音符如雨點般砸向觀眾席，他看見墓地微微起伏，就像一隻呼吸著的巨怪的皮表……\n他看見了很多，很多。他將他所看見的告訴他的母親、老師、朋友，他將他看見的繪入畫裡。他想把他眼中的世界帶到人們面前，可他身邊的人越來越少，一個世界離他越來越遠。\n但這是為什麼呢？他只是將他所見到的東西記錄了下來。皮克曼怎麼想也想不明白。\n悲傷的皮克曼站在鏡子面前。他看見一隻食屍鬼衝他咧開長滿尖牙的嘴。\n「沒有什麼比看見目睹真實更加重要。瘋狂，混沌，貪婪……要去看看嗎，皮克曼？」\n明悟的皮克曼向他微笑著，跨入那面鏡子。\n他只想親眼目睹那最為極致的瘋狂的真實，將它們忠實地描繪在他的畫布之上。\n他不是人類，也不是食屍鬼。\n他只是寫實主義繪者皮克曼。"
  },
  CollectionHall_127168_Title = {
    Text = "寫實主義悖謬"
  },
  CollectionHall_127169_Desc = {
    Text = "當一個人能夠知曉全部的過去與未來，等待他的不是全知的喜悅，而是無盡的悲憫與絕望。\n她的雙眼能看到萬事萬物背後的絲線，線的這一頭連接過去，線的那一頭連接未來。\n那絲線被人們稱為命運。\n她是如何看待那一個個跟隨在她身邊的人呢？\n人們善良仁愛，人們傲慢多疑。\n但那些人的命運與人類的命運都在每次見面的開始就已經註定。\n她必定是喜愛他們的，否則何以一次次伸出援手、給予火種。\n她必定是期許他們的，否則何以在毀滅中堅定地走入輪回的陰影。\n因喜愛，她長懷悲傷。\n因期許，她屢屢失望。\n她深陷在黑色的泥沼，於無數的黑色絲線中不斷梳理著，不厭其煩。\n命運的輪盤一次次回轉。\n她看到貪婪的火焰席捲蒼穹。\n她看到盲愚的偏執走向自戕。\n她看到癡狂的妄念加速毀滅。\n無序的混沌總會姍姍而來。\n希望與絕望徒勞地輪轉，永無止境。\n直到她在黑暗之中看到一瞬的星光。\n那光微弱，但她已在黑暗中太久。\n直視的那一刻，竟然流下眼淚。\n"
  },
  CollectionHall_127169_Title = {
    Text = "隱世的轉輪"
  },
  CollectionHall_127170_Desc = {
    Text = "新的一年，你決定舉辦一場前所未有的儀式，以最莊重的方式，迎接時間的更迭。\n為此，你籌備良久。點燃蠟燭，讓溫暖的光暈照亮冬夜的校園；在訓練場中央搭起高臺，鋪上綴滿花紋的深紅絨毯。你甚至親手裁出無數條金箔與銀紗纏繞的彩帶，只願這倒數的時刻超越告別的悵然，化作歲末與新年相擁時永不褪色的印記。\n可是……還差些什麼。\n你走進舊倉庫深處，拂去層層塵埃，終於尋出那座古董時鐘。它的外殼斑駁，指針早已在時光的侵蝕下斷裂、脫落，顯然不能使用了。\n就在一籌莫展之際，泰旖絲出現了，身後悄然立著一座嶄新的時鐘。\n那座時鐘無比熟悉。她依舊輕佻地笑著，眼底卻藏著某種溫柔的篤定。\n「怎麼樣，這座時鐘，配上我的舞蹈，一定是最盛大的儀式。」\n「這……不會是塔薇的時鐘吧？」\n「哎呀，您也知道她孤零零地待在池水里，太沉悶了。」\n「這樣讓她加入我們的儀式，感受我的愛意，或許能讓她有點興致呢～」\n午夜悄然降臨，泰旖絲立在巨大的時鐘前，像被時間親手包裝的贈禮。\n彩帶如未燼的煙花纏繞她的身軀，在流轉的燈光下漾出金紅與銀藍的波紋。腰際那只飽滿的蝴蝶結，恰是新年親手繫上的最後一個繩釦——她就是歲末最盛大的獻禮，裹著歡愉的綢緞，等待被時間拆封。\n她的手臂緩緩升起，指尖溯著光影遊走，最終指向身後那枚懸垂的時鐘。十二個數字在錶盤上連成光暈，在她的指尖躍動。\n彌撒格的眾人仰望著泰旖絲縱情的舞蹈，彷彿被歡愉的氣氛感染，開始隨著她的韻律一同蕩漾。\n而當鐘聲落下，她指尖輕點，觸向永恆的起始。那被捆縛的禮物張開雙臂，將儲存在歲末的所有歡慶化作漫天紛揚的祝福，灑向人間。"
  },
  CollectionHall_127170_Title = {
    Text = "倒數時刻"
  },
  CollectionHall_127237_Title = {
    Text = "海城舊聞"
  },
  CollectionHall_127239_Title = {
    Text = "磐龍古國"
  },
  CollectionHall_129601_Desc = {
    Text = "<Title:簡介>\n生活在與世隔絕的海島上、開朗且充滿野性的少女。\n由於活潑的性格和天生的怪力、許多人在初次接觸時很難適應她過於熱情的親近。但只要相處過一段時間就會發現、她只是想要盡可能地幫助朋友。\n雖然有時她的幫助方式異於常人、不過就結果來看、大部分時候還是幫受助者解決了麻煩、大概？\n在解除抑制的狀態下無法控制自身能力、導致實驗室經常爆炸。\n因缺少必要的教育、有時莫絲需要比手畫腳半天才可以讓對話者理解自己的意思。當然、莫絲並不需要對方比劃半天、她那超絕的直覺可以很好地解決這個麻煩。\n非常親近諾締拉和守密人。據她所言、三人之間有過一起冒險的約定、不過諾締拉對此毫無印象、守密人則對那段經歷閉口不談。\n偶爾會在莫絲身邊看到一隻帶著彌薩格帽子的海獺、莫絲把它叫做「小煤球二世」。每當這時、某些本該完成的作業都會莫名其妙地消失。"
  },
  CollectionHall_129601_LockTip = {
    Text = "喚醒「莫絲」後解鎖"
  },
  CollectionHall_129601_Title = {Text = "莫絲"},
  CollectionHall_129803_LockTip = {
    Text = "需要通關限時活動「疾馳的歡愉專列：列車啟程」任一關卡"
  },
  CollectionHall_129803_Title = {
    Text = "疾馳的歡愉專列：列車啟程"
  },
  CollectionHall_129810_Desc = {
    Text = "在無法被記錄的某個循環中、環行·拉蒙娜踏過鐘樓後的花圃。\n餘光瞥見玫瑰園中、叢叢鮮花正綻放得妍烈。\n罕見的片刻停滯後、她便拋下所有無謂的遐思、繼續奔赴最終的戰場。\n泥濘潑濺在血色般濃烈的花瓣上、轉瞬被漆黑的融蝕漿吞噬、只留下風中傲然的背影。"
  },
  CollectionHall_129810_Title = {
    Text = "踏過泥濘的玫瑰"
  },
  CollectionHall_130218_LockTip = {
    Text = "需要通關限時活動「顛倒的新生：暗室手記」任一關卡"
  },
  CollectionHall_130218_Title = {
    Text = "顛倒的新生：暗室手記"
  },
  CollectionHall_130219_Desc = {
    Text = "這是一座沒有記錄在任何海圖上的島嶼。\n從它誕生之初、名為「文明」的病毒便從未踏上過這片淨土。\n這裡只有沙灘、叢林、一眼望不到頭的大海、以及……一位小小的少女。\n………………………………\n「爸爸、媽媽、魚！」\n「嗷~~」\n兩隻海豚不緊不慢地游到少女腳邊、發出優美清脆的叫聲。\n其中一隻將少女驮起、另一隻接過少女手中剛被打暈的魚、一口將其吞下。\n「嗷~~」\n「嘿嘿、莫絲！厲害！」\n像不諧世事的孩童、少女做了個很有力量感的動作、來回應「爸爸」「媽媽」的誇獎。\n「今天、太陽！好！」\n「莫絲！爸爸！媽媽！散步！」\n聽聞少女的話、驮著少女的海豚輕吟一聲、繞著小島開始緩緩遊動。\n溫暖的陽光灑在少女身上、驅散了數日前揮之不去的濕冷、輕柔的風拂過少女的髮絲、帶來了海洋慵懶的呼吸。\n笑聲、拍水聲、嬉鬧聲、與世隔絕的小島上沒有「文明」帶來的煩惱、只留下了最原始、最純粹的歡笑。\n兩獸一人如往常一樣、度過了原始又無憂的一天。\n………………………………\n直到那無邊的呼喚、將這份靜謐徹底吞噬。\n「回來吧……回來吧……」\n「@1需要你……@2……@4……需要你……」"
  },
  CollectionHall_130219_Title = {
    Text = "渺遠的伊甸園"
  },
  CollectionHall_130220_Desc = {
    Text = "蒲公英，比飛鳥更小，比微風更輕。\n\n當蒲公英經過第一片荒原，它詢問這裡四散的風滾草：你們如何繁衍？\n風滾草說：「我們讓種子漂泊四方，直到發現可以扎根的土壤。」\n漂泊的旅人是沒有家的，蒲公英這麼嘆息著搭上另一縷風飛走了。\n\n當蒲公英經過第二片沙漠，它詢問這裡零星分布的仙人掌：你們如何生存？\n仙人掌說：「我們將根系深埋地下，汲取珍稀的水源。」\n即使在嚴酷的環境中也頑強地活著啊，蒲公英這麼思索著離開了。\n\n不久後，蒲公英經過城市上空。\n暗夜中浮現的滿城燈光，是人類生活的印記。\n在漫長旅途的盡頭，蒲公英的種子終於要飄落到那片大地上了。"
  },
  CollectionHall_130220_Title = {
    Text = "願世界化作芬芳"
  },
  CollectionHall_130221_Desc = {
    Text = "阿拉克涅知道，自己正在做一件注定失敗的事。\n她輕輕轉動著紡輪，日復一日將人類的悲歡、王朝的興衰、星火般的詩與愛，織入那張橫跨時空的巨網。\n她做得極好，精準、剋制、溫柔。摒棄那些「錯誤的」，選擇那些「正確的」。\n一代代人展露新生的笑顏，無數文明在灰燼中寫下嶄新的歷史。而那些因編織而生的喜悅，因編織而起的倦怠，連同所有柔軟的情緒，早在永世苦役的磨蝕中悄然凋亡。她親手割捨了脆弱，只留下清醒的意志，只為確保每一次選擇都出於責任，而非軟弱。\n可最深的悲劇，並非苦役本身，而是她清楚地知道，無論她如何修補、編織，世界仍會走向那片寂靜的虛無。文明如脆弱的沙堡，潮水終至。她的努力，是一場沒有觀眾的演出，一次永無迴響的守望。\n「命運早已將我們定罪於永恆的孤獨，憑什麼要接受這殘忍的懲罰？」\n「撕裂它、破壞它……你就能從這苦役中逃脫……」\n她垂眸，將那些多餘的想法輕輕剪斷，繼續枯燥而專注地編織著、維繫著、痛哭著、忍受著……\n一切無謂的掙扎、一切無解的命運早已織在這張網中。\n而網的中心，她看到了自己。"
  },
  CollectionHall_130221_Title = {
    Text = "永世編織之網"
  },
  CollectionHall_131000_LockTip = {
    Text = "需要通關限時活動「默斯克斯的呼喚：莫絲與海」任一關卡"
  },
  CollectionHall_131000_Title = {
    Text = "默斯克斯的呼喚：莫絲與海"
  },
  CollectionHall_131388_Desc = {
    Text = "金碧輝煌的俱樂部門口、身穿白襯衫的迎賓員抬起一隻手、禮貌地攔住了萊克。\n「先生、您沒有邀請函、也並非我們的會員、無法進入。\n」\n「是嗎……這就難辦了啊……」\n萊克用手摸了摸下巴、裝出一副思考的樣子。實際上、他只是在等待。\n等待手中案件的嫌疑人。\n等待那注定的、命運的眷顧。\n果然、他等到了——\n「這不是聞名倫蒂尼恩的好運偵探嗎！來來來、我願意做你的引薦人。」\n「我早就想見識見識你那傳奇的運氣了、可千萬不要讓我失望啊……」\n紳士說著、露出看似溫和卻滿懷惡意的笑。\n這樣的神情在俱樂部很常見、畢竟你不能指望追求著狂歡的賭徒們循規蹈矩。所以當意識到自己被做局時、萊克並不在意、只是彎起嘴角、從容不迫地拿起了惠斯特牌。\n不要著急、遊戲才剛剛開始、不是嗎？\n於是、第一局、第二局、第三局……一場接著一場。\n直到萊克輸光所有籌碼。\n「好運偵探、看来你今天的運氣並不好。也對、沒有人能永遠受到命運的眷顧……」\n「還要繼續嗎？偵探、可惜你已經一無所有了。」\n「一無所有？並不見得。」連輸到底的偵探笑了笑、指了指自己、「我還有這套得體的禮服、還有這把昂貴的手杖、還有……」\n偵探頓了頓、從禮服的胸袋裡拿出一枚小巧的儀器、壓低聲音、微笑著把玩、「我承認你的出千手法極其巧妙、就連這家俱樂部的主人也無法破解、只能尋求我的幫助。但再精妙的手法也需要時間、需要操作、需要配合。」\n「真不巧、這個彌薩格出品的小玩意、已經清晰地記錄了你和你的同夥剛才在俱樂部出千的證據。」\n紳士愣了一下、驚愕又愠怒、他的同夥更是恼羞成怒、想要給偵探一個教訓。但眾目睽睽下、紳士不敢輕舉妄動、更何況、偵探給了他一個選擇、一個他無法拒絕的選擇。\n「再賭一把、怎麼樣？若是你贏了、這個小玩意和我的命、就都歸屬於你了。你明白我的意思。」\n「那若是我輸了呢？」\n「輸了就要麻煩你去自首了。」萊克笑著耸了耸肩、露出閃亮的獠牙、「你覺得自己會輸嗎？真正的賭徒、只願意相信自己會贏。」\n是的、每個賭徒都覺得自己會贏。所以無論是誰、都無法拒絕這個賭局。\n於是、惠斯特牌再次流轉於牌桌、出牌、墊牌、纂牌、最終、分出勝負。\n「Lucky~」\n沒有再看輸家一眼、萊克笑著揚手、將那些贏來的錢財扔向空中。於是、本就喧囂的俱樂部越發狂熱、充滿了人們爭搶的吶喊、獲得財富的尖叫和歡笑。\n而在這吶喊、尖叫和歡笑裡、萊克將彌薩格頒發的、人手一個的裝飾品收回胸袋、又拍了拍褲兜裡寫著自己姓名的邀請函、彎起嘴角壓了壓自己的帽子。\n真正的賭徒、只願意相信自己會贏。\n因為他堅信、無論做了什麼、命運的眷顧始終與他同行。\n"
  },
  CollectionHall_131388_Title = {
    Text = "豪賭的智慧"
  },
  CollectionHall_131663_LockTip = {
    Text = "通關意識潛遊「沉溺」任一關卡解鎖"
  },
  CollectionHall_131663_Title = {
    Text = "O-1841研究報告"
  },
  CollectionHall_131664_Desc = {
    Text = "讓妾身想想、 今天的故事、要說什麼呢……\n啊、妾身知道了、給小小姐和小先生們的故事應該是~夜半莫講虧心錯、三更冤魂上房樑。"
  },
