  CollectionHall_131672_Desc = {
    Text = "她祂她她她祂祂祂祂她她母親母美麗的眼睛母親母親母親親親親親母親母親母親她祂祂她她她她@4@3@4"
  },
  CollectionHall_131672_LockTip = {
    Text = "完成意識潛遊「扇下夜談」"
  },
  CollectionHall_132222_Desc = {
    Text = "如果願望真的能實現，龐托斯希望離別在來臨之前，能夠打個招呼。\n他的父母消失得悄無聲息，一個平靜的午後，姐姐蕾莎付錢雇來了一輛人力車，然後是長長的、他當時還不認識的鐵皮怪物，在柴油味和轟隆聲中，他抵達了那座海邊小鎮。\n關於父母的去向，蕾莎沒有透露一個字，劇烈的爭吵後，他衝進了瀰漫著鹹腥味的港口。\n眼距過寬的海民們正在販售形狀怪異，來自人力所不可能到達的深淵的魚類。\n「喂，離遠一點，這些魚說不定和抓來它的那些東西一樣染上了詛咒。」\n路人壓低聲音，沒有人想看著這個初來乍到的漂亮青年蹚渾水。\n他習慣性地衝對方笑了笑，目光卻不自覺地落在那支晦暗腐敗的擬餌上，它大張的口腔遍布利齒，醜陋、扭曲、張揚，某個臆想中的聲音講述著這死物的一生。\n在幽暗的、無光的海底，它引誘、掠奪、無所不用其極，它的身體是一座牢固的囚籠，鎖困著它的子嗣、愛人、仇人、和獵物。\n它生命中美好的東西本該轉瞬即逝，但它把祂們全都留住了，祂們以它的身體為載體，緊密相依，永不分離。\n龐托斯猛地甩了甩頭，驚恐地在耳邊尖銳的鼓噪聲中環顧四周。\n聲音如潮水般消失了，他把一切當成一次恍神，在心裡嘲笑自己的神經質。\n然後毫無察覺地向既定的命運裡墜去。"
  },
  CollectionHall_132222_Title = {Text = "活囚籠"},
  CollectionHall_133709_Desc = {
    Text = "晨間的騎行要與郡中的鄉紳們並轡，探聽改革案的立場；冷餐會上要同各家的夫人交換得體的恭維，長桌晚宴要在銀燭台的光影裡聆聽那些冗長而虛偽的餐前禱詞，歌劇散場後還要在包廂的走廊裡應付沒完沒了的社交寒暄。\n\n「唯有後園草坪上的下午茶，是真正屬於我自己的時光。」\n「這可是我第一次邀請下午茶嘉賓，我將選擇話題的權力讓渡予你。」\n\n索蕾爾端起剛斟滿的紅茶。\n「你想要知道德·克雷梅伯爵在最新提交的議院改革案上的立場？或者博蒙納家族在兩黨之間微妙的押注？又或者單純對某位子爵小姐的秘密感興趣？」\n「全都不用？你只想知道我桌上的粉色甜點的味道？」\n她輕啜一口，原本望向遠方的目光落回你的身上。\n「那就好好品嚐一下吧。」\n「有些滋味，確實要自己動手，才能感同身受。」\n「你說對不對啊，我尊敬的——那位大人？」\n\n身著彌薩格校服的來客的領口和袖口黑霧四溢，霧氣很快滾動成一團濃黑的混沌。\n「嘻嘻嘻，你當真覺得，自己可以逃脫宿命嗎？」\n「陽光正好，我想要先享受我難得的清閒時光。想要品鑑時下最流行的紅茶和海綿蛋糕，請便。其他事情，還請在午歇時間結束後再來吧。」"
  },
  CollectionHall_133709_Title = {
    Text = "私密午歇時間"
  },
  CollectionHall_133710_Desc = {
    Text = "作為彌薩格的優等生，拉蒙娜成功將理智與理性作為行事的絕對邏輯，保持著冷靜，保持著微笑，保持著無與倫比的可靠。\n但偶爾，這樣的拉蒙娜也會陷入迷思中，在面對世界的絕對恐怖，或者絕對的絢爛之時——\n注視著無邊無際，佔滿了所有視線的粉色，拉蒙娜無聲沉默。\n據她所知，不超過三週，櫻花就會從初開到落盡，所以這沉甸甸壓滿枝頭的花朵，縱橫而繁茂的枝葉，很快便會衰頹，陷入荒涼與蕭索。\n而人的可預期生命，遠不止三週，遠不止三年，遠不止三十年，卻也如這些櫻花樹，只有一次。\n人最大的幻覺，就是相信自己會永遠活著。\n拉蒙娜明白。\n花開花落，是自然界再普通不過的規律，而人的生死，歸根結底也只是自然界的現象罷了。\n拉蒙娜也明白。\n但生而為人，總是想要為自己的存在賦予意義，每個新生，也是為此，踏入了彌薩格的大門。\n他們是對抗融蝕的先行者，是守望人類未來的重要防線。\n他們的生命，不僅僅只是客觀的自然現象，哪怕注定消亡，也在切實改變著這個世界的軌跡。\n而在這期間，他們並肩戰鬥，風雨同行。\n就像一棵樹上的一朵花，依偎著另一朵花，一同含苞待放，一同飄搖墜落，一同盛開與枯萎。\n現在，該回去了。\n那朵可以依靠她，也值得她依靠的花朵，還在等著她。"
  },
  CollectionHall_133710_Title = {
    Text = "櫻花下的迷思"
  },
  CollectionHall_133768_Desc = {
    Text = "渦心冰冷，沉默且孤獨。\n那是連光都無法穿透的暗潮。"
  },
