  CollectionHall_133769_Title = {Text = "沉沒"},
  CollectionHall_133770_Desc = {
    Text = "各位旅客，大家好！\n祈歲佳節即將來臨，在這闔家團圓、辭舊迎新的美好時刻，本次列車全體乘務人員，向千里歸鄉、旅途勞頓的您，致以最誠摯的祝福——\n祝您祈歲快樂，闔家歡愉，一路疾馳，萬事如意！<(￣︶￣)↗[GO!]"
  },
  CollectionHall_133770_LockTip = {
    Text = "完成特遣紀錄「開往祈歲節的列車」"
  },
  CollectionHall_133770_Title = {
    Text = "疾馳：歡愉專列"
  },
  CollectionHall_133771_Desc = {
    Text = "各位旅客，大家好，非常抱歉地通知您，由於列車長的個人心情，本次歡愉專列將在此臨時停車。具體開車時間，我們將在自相殘殺結束後隨時為您廣播通知。\n停車期間，列車的空調、照明和衛生間均可正常使用，請您根據殺戮需求酌情占用，以免不發生危險。\n畢竟，歡愉專列的義務，就是給所有旅客帶去歡笑～(￣▽￣～)(～￣▽￣)～"
  },
  CollectionHall_133771_LockTip = {
