  },
  CollectionHall_133772_Desc = {
    Text = "請注意：列車前方到站，磐龍古國。請在磐龍古國下車的旅客提前學習《好一朵茉莉花》的演唱技巧。\n因為，你們已經沒機會下車了 φ(≧ω≦*)♪"
