  },
  CollectionHall_134293_Desc = {
    Text = "<Title:簡介>\n命運劇院的主人，劇作者，演員，命運永恆的編織者與永恆的囚徒……\n自出生起，阿拉克涅便擁有能夠看到命運絲線的能力。利用那台名為「摩伊賴」的紡輪，她無時無刻不在為世界編織命運，維護命運那脆弱的平衡。為此，她放逐了自己身上所有的美好與脆弱，為一切的命運做出最為正確的抉擇，獨自承擔著一切命運的罪責。\n她早已知曉，命運之網的盡頭，毀滅終究無可逃離。可她仍亘古不停的編織，看著自己深愛的一切緩緩地墜入那個湮滅一切的終點。\n她編織，等待，等待那道她從未預見的、將命網自深淵中挽救的絲線。"
  },
  CollectionHall_134293_LockTip = {
    Text = "喚醒「阿拉克涅」後解鎖"
  },
  CollectionHall_134294_LockTip = {
