  },
  CollectionHall_139856_LockTip = {
    Text = "通關多維連結「被遺忘的愛之種」解鎖"
  },
  CollectionHall_140337_Desc = {
    Text = "你漫步於星雲之間，見證流星一顆接一顆隕落。\n有些滾燙，有些耀眼，有些冰冷，有些灰暗——來不及告別，它們便拖著長尾，從天幕上逐一淡去。\n你捧起灰燼，想將存在的痕跡銘刻於心。\n但那些影像終究穿過指縫，穿過日漸稀薄的記憶，飛散在無垠時空裡。\n原來你也不過是萬千星雨中的一顆。\n但你不會停下。你要走下去，穿過漫長的寂滅，直至下一個紀元。\n直至繁星漫天。"
  },
  CollectionHall_140428_LockTip = {
    Text = "可於調查行動星辰篇5-1中解鎖"
  },
  CollectionHall_141369_LockTip = {
    Text = "需要通關限時活動「永遠的厄波揚斯·高屋巡獵」任一關卡"
  },
  CollectionHall_141369_Title = {
    Text = "永遠的厄波揚斯·高屋巡獵"
  },
  CollectionHall_141453_LockTip = {
    Text = "通關多維連結「被遺忘的愛之種：血ﾝ肉ｲw世ｮ」解鎖"
  },
  CollectionHall_141528_Desc = {
    Text = "傳說中只要孩子在森林裡追著一隻野兔奔跑，就有機率掉進通往異世界的樹洞。 莉莉光滑的小腳踩上鵝卵石的小徑。 「莉莉喜歡這裡……地面上不會有玻璃碎渣，空氣中也沒有消毒水的氣味。」 莉莉深吸了一口清新的空氣，掠過林間的風捲來奇異花香的氣息。 頭頂的樹冠交織成彩色玻璃般的穹頂，碎落的陽光像是滿地跳動的寶石，瑰麗而迷幻的景致讓莉莉幾乎不知道應該往哪個方向看。 「啊，剛才的兔子先生！」 草叢中冒出一雙熟悉的灰色長耳朵，莉莉急忙追了過去。 腳下的苔蘚每踩一步就綻開一朵細小的銀花，但莉莉也無暇顧及。她還有更重要的話要找兔子先生說。 淌過流著蜂蜜色光芒的小溪，穿過會唱歌的蘆葦叢。 氣喘吁吁的莉莉終於捉住了兔子先生絨球一樣的尾巴。 「兔子先生，你願意和麗莎做朋友嗎？」 「麗莎是我的朋友，可是其他人現在都很害怕她……如果是兔子先生的話，一定能和她成為朋友的！」 兔子先生回頭的瞬間，漫天螢火升騰而起。 「當然，@2是所有人的朋友。不過，現在，你該休息了。」 於是，莉莉抱著已經成為朋友的兔子先生，爬到森林深處那棵高大的巨樹下。 在飄散的螢火蟲溫暖的包圍中，莉莉倚著巨樹的根系，安靜地睡著了。 「受試者：莉莉。臨床表徵：呼吸平穩，眼球轉速正常。第359次意識干涉實驗，成功。」 那是如夢幻一般綺麗的奇幻世界。"
  },
  CollectionHall_141528_Title = {
    Text = "夢遊仙境"
  },
  CollectionHall_141832_LockTip = {
    Text = "需要通關限時活動「新月與深雪：烏摩鉢蒂的寶物」任一關卡"
  },
  CollectionHall_141832_Title = {
    Text = "新月與深雪：烏摩鉢蒂的寶物"
