  CollectionHall_142131_Title = {
    Text = "被遺忘的愛之種"
  },
  CollectionHall_142154_Title = {Text = "城鎮"},
  CollectionHall_142155_Desc = {
    Text = "被無法理解、無法辨識、令人作嘔的畸形之物逼近時，發起防禦式攻擊是生物的本能。\n因此，這不能算作罪孽。"
  },
  CollectionHall_142155_LockTip = {
    Text = "完成多維連接「被遺忘的愛之種」困難難度"
  },
  CollectionHall_142155_Title = {
    Text = "無罪的暴虐"
  },
  CollectionHall_142156_Desc = {
    Text = "「能聽見我的聲音嗎？即使身影消融在風中。」\n風中傳來遙遠的呼喚，那是跨越遙遠的時間，從廣闊而寒冷的冬夜，忘卻的彼岸傳來的探尋之聲。"
  },
  CollectionHall_142156_LockTip = {
    Text = "完成多維連接「被遺忘的愛之種」"
  },
  CollectionHall_142156_Title = {
    Text = "忘却の彼方(忘卻之歌-いとうかなこ Ver.)"
  },
  CollectionHall_142157_Desc = {
    Text = "回憶閃爍交疊，結局真偽不明。\n但這真的重要嗎？\n畢竟，未必所有的故事都以愛作為開頭，但都將以死亡作為終點。"
  },
  CollectionHall_142157_LockTip = {
    Text = "完成多維連接「被遺忘的愛之種」"
  },
  CollectionHall_142157_Title = {
    Text = "四重回憶"
  },
  CollectionHall_142158_Desc = {
    Text = "如果有一天，你也和我一樣，陷入血肉模糊、腐臭糜爛的光景。\n那麼你也一定能夠理解——\n與她的小巧指尖觸碰的瞬間，是人世間不可多得的奇蹟。"
  },
  CollectionHall_142158_LockTip = {
    Text = "完成多維連接「被遺忘的愛之種」"
  },
  CollectionHall_142158_Title = {Text = "奇蹟"},
  CollectionHall_142159_Desc = {
    Text = "你是否也厭倦了普通的、循環的、乏味的、日復一日的生活？\n來點新鮮的吧，另一個視界正敞開血盆大口，向你發出歡迎的邀約。"
  },
  CollectionHall_142159_LockTip = {
    Text = "完成多維連接「被遺忘的愛之種」"
  },
  CollectionHall_142160_Desc = {
    Text = "愛是崇高，愛是貪婪；愛是賜福，愛是詛咒。\n愛隨水而生，亦將隨水而逝。\n而雨季不再來。"
  },
  CollectionHall_142160_LockTip = {
    Text = "完成多維連接「被遺忘的愛之種」困難難度"
  },
  CollectionHall_142161_Desc = {
    Text = "一切生命帶著無知降生，自萬物中汲取養料，改造環境，掠奪資源，供養自我。\n這是無可逃避的原罪。"
  },
  CollectionHall_142161_LockTip = {
    Text = "完成多維連接「被遺忘的愛之種」"
  },
  CollectionHall_142162_Desc = {
    Text = "有一種叫蒲公英的植物，會讓種子乘著風漂流。\n毛絨絨的種子隨風流浪，離開故土好遠好遠。\n它孤身一人，會在什麼時候決定自己的歸宿呢？\n那就是，沙漠中有唯一的一個人愛著那株蒲公英的時候。"
  },
  CollectionHall_142162_LockTip = {
    Text = "完成多維連接「被遺忘的愛之種」"
  },
  CollectionHall_142162_Title = {
    Text = "蒲公英去往何處"
  },
  CollectionHall_142163_Desc = {
    Text = "廣闊天地，茫茫沙海。\n那是只有你我的無人之境。\n那是永恆自由的愛之漫遊。"
  },
  CollectionHall_142163_LockTip = {
    Text = "完成多維連接「被遺忘的愛之種」"
  },
  CollectionHall_142163_Title = {
    Text = "沙海漫遊"
  },
  CollectionHall_142164_Desc = {
    Text = "我能呼喚你的名字嗎？即使世界消逝。」\n如果回憶都將湮滅消散，漆黑的遺忘將吞噬所有未及緬懷的往事。\n那就牽起手來吧，讓銀色的光輝連結你我。\n在嶄新的幻夢中，在柔嫩的種子萌發的早春時節。"
  },
  CollectionHall_142164_LockTip = {
    Text = "完成多維連接「被遺忘的愛之種」"
  },
  CollectionHall_142164_Title = {
    Text = "Song of Memento(忘卻之歌-Emi Ver.)"
  },
  CollectionHall_142165_Desc = {
    Text = "高歌吧，閃耀的生命正讚頌自由，將希望的羽種播撒至遍及之地。"
  },
  CollectionHall_142165_LockTip = {
    Text = "完成多維連接「被遺忘的愛之種」困難難度"
  },
  CollectionHall_142165_Title = {
    Text = "揭幕頌歌"
  },
  CollectionHall_142868_Desc = {
    Text = "<Title:簡介>\n龐托斯始終記得自己在得知家族歷史那天的心情，在此之前，他從沒有做好承擔什麼責任的準備，每個人都喜歡他，他英俊、有趣、無憂無慮。\n@1王港終年往來的船隻令他不必面對日復一日枯燥的日常，他聽過太多故事，許多人說他見多識廣，以至於他不願承認自己會泯然眾人。\n所以，他被意料之外又順理成章的巨大狂喜淹沒了。更何況，那個在家族世世代代驅使的魇背後，更加莫測偉大的存在認可他——他生來與眾不同。\n然而「N」的一個玩笑，讓狂信者們在一場無差別的沿岸襲擊中，摧毀了整個村莊。\n無法面對突如其來的災難，為了獲得深淵的力量，龐托斯選擇了向@3獻祭自己的身體，也獻祭了自己所有的可能性。\n但這有什麼關係呢，再也不會有事物超出他的控制。\n他再也不會失去任何東西了。"
  },
  CollectionHall_142868_LockTip = {
    Text = "喚醒「龐托斯」後解鎖"
  },
  CollectionHall_142868_Title = {Text = "龐托斯"},
  CollectionHall_142901_Title = {
    Text = "永遠的厄波揚斯"
  },
  CollectionHall_143468_Desc = {
    Text = "喪鐘已然敲響，背棄者呈上最瘋狂的演出。\n無數的絲線，將會織就什麼樣的結局——\n由你決定。"
  },
  CollectionHall_143468_LockTip = {
    Text = "完成調查行動·困難 星辰篇5-11解鎖"
  },
  CollectionHall_143468_Title = {
    Text = "共織終局"
  },
  CollectionHall_143469_Desc = {
    Text = "快過來吧，快過來吧，所有人都在等你。\n行過漫長的回廊，踏上永恆的舞台。\n你可是整部戲，唯一的主角呀。"
  },
  CollectionHall_143469_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143469_Title = {
    Text = "無盡螺旋"
  },
  CollectionHall_143470_Desc = {
    Text = "他們共同歌唱，他們各司其職。\n但他們都是她。\n這是屬於她的永不落幕的獨角戲。"
  },
  CollectionHall_143470_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143470_Title = {Text = "獨角戲"},
  CollectionHall_143471_Desc = {
    Text = "Act I：紡絲\nAct II：衡量\nAct III：裁斷\n如此往復，如此往復......"
  },
  CollectionHall_143471_LockTip = {
    Text = "完成調查行動·困難 星辰篇5-11解鎖"
  },
  CollectionHall_143471_Title = {Text = "三幕戲"},
  CollectionHall_143472_Desc = {
    Text = "不過是一名狂熱青年，在一個尋常的街角開了槍。\n至少在那時，所有人都這樣想。"
  },
  CollectionHall_143472_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143472_Title = {
    Text = "戰火的前序"
  },
  CollectionHall_143473_Desc = {
    Text = "吱呀，吱呀。\n命運啊，你的輪盤轉動不歇。\n貧窮與權力都被你像冰一般消融。\n你遮蔽自己，又隱藏面目，\n卻也向我閃耀......"
  },
  CollectionHall_143473_LockTip = {
    Text = "完成調查行動·困難 星辰篇5-11解鎖"
  },
  CollectionHall_143473_Title = {
    Text = "命運啊，你何其殘酷"
  },
  CollectionHall_143474_Desc = {
    Text = "再會吧，在最後的旋律中。\n再會吧，在命運的注視下。\n故事的主人公，將踏上新的旅程。"
  },
  CollectionHall_143474_LockTip = {
    Text = "完成調查行動·困難 星辰篇5-11解鎖"
  },
  CollectionHall_143475_Desc = {
    Text = "親愛的，讓我們借著酒興，再共舞一曲吧。"
  },
  CollectionHall_143475_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143475_Title = {
    Text = "微醺舞會"
  },
  CollectionHall_143476_Desc = {
    Text = "觀眾為分別落淚，亦為重逢落淚。\n而舞台中央的犯人們，也該為她們彼此獻上掌聲。"
  },
  CollectionHall_143476_LockTip = {
    Text = "完成調查行動·困難 星辰篇5-11解鎖"
  },
  CollectionHall_143476_Title = {
    Text = "囚徒正謝幕"
  },
  CollectionHall_143477_Desc = {
    Text = "世人喜歡將一場戰爭歸咎於一聲槍響。\n但命運會嗤笑，這是全人類的自欺欺人。"
  },
  CollectionHall_143477_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143477_Title = {
    Text = "蝴蝶振翅時"
  },
  CollectionHall_143478_Desc = {
    Text = "沒有後日談的演出是不完整的。\n稍稍改動台詞，調整布景，輪換演員——每一次返場，都是嶄新的一幕。"
  },
  CollectionHall_143478_LockTip = {
    Text = "完成調查行動·困難 星辰篇5-11解鎖"
  },
  CollectionHall_143478_Title = {
    Text = "返場變奏"
  },
  CollectionHall_143479_Desc = {
    Text = "筆尖在白紙上飛奔，追逐著文字，而文字通往早已定好的結局。\n一切，都發生在你翻開每一本書之前。"
  },
  CollectionHall_143479_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143479_Title = {
    Text = "將定之事，已定之事"
  },
  CollectionHall_143480_Desc = {
    Text = "少許苦精，20ml甜味美思，一些雪莉酒，加滿冰塊攪勻——這是一杯上好的開胃酒，也是一場上演了五百次的戲。"
  },
  CollectionHall_143480_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143481_Desc = {
    Text = "你把命運當作丑角，便不會被命運奴役。\n用永不止歇的大笑來迎接祂吧，讓我們共同喚出祂的名諱——\n歡愉。"
  },
  CollectionHall_143481_LockTip = {
    Text = "完成調查行動·困難 星辰篇5-11解鎖"
  },
  CollectionHall_143481_Title = {
    Text = "弄臣蒞臨"
  },
  CollectionHall_143482_Desc = {
    Text = "“我恨你，恨你作繭自縛，恨你無能為力，恨你拋棄自己。”\n“...可這份仇恨也在灼燒我自己，因為，我也愛你。”"
  },
  CollectionHall_143482_LockTip = {
    Text = "完成調查行動·困難 星辰篇5-11解鎖"
  },
  CollectionHall_143482_Title = {
    Text = "復仇鬼的悲歌"
  },
  CollectionHall_143483_Desc = {
    Text = "世界給予你無數可選的岔路，但它們匯於同一點——名為毀滅，名為終焉。"
  },
  CollectionHall_143483_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143483_Title = {
    Text = "世界復本"
  },
  CollectionHall_143484_Desc = {
    Text = "帷幕起落，戲目更迭，她仍在劇院之中——她是劇作家，觀眾，亦是演員。\n命運的女主人啊，你如此殘忍，永遠緘默，卻又為何而垂淚？"
  },
  CollectionHall_143484_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143484_Title = {
    Text = "命定同織之戲"
  },
  CollectionHall_143485_Desc = {
    Text = "倘若毀滅終究無法避免，是否扯破命運的網，才能迎來真正的救贖？\n沒有人能回答，沒有神能夠回答。\n但至少，無邊的苦難也會一併消亡。"
  },
  CollectionHall_143485_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143485_Title = {
    Text = "瀆命演出"
  },
  CollectionHall_143486_Desc = {
    Text = "那些行於世間，無比真實、看似自由的面孔，不過是舞台上的固定裝置。\n一舉一動，皆被命運的絲線牽引。"
  },
  CollectionHall_143486_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143486_Title = {
    Text = "眾生之線"
  },
  CollectionHall_143487_Desc = {
    Text = "夢醒過後，一切都會消失，被徹底忘卻——莊園、花圃、歌謠、畫作......\n那是一個不存在的春天。"
  },
  CollectionHall_143487_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143487_Title = {
    Text = "紡春的幻夢"
  },
  CollectionHall_143488_Desc = {
    Text = "弦樂徐起，侍女吟唱。\n幕後之人來到台前，她向你行禮，邀你見證這既定的命軌。"
  },
  CollectionHall_143488_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143488_Title = {
    Text = "揭開她的面紗"
  },
  CollectionHall_143489_Desc = {
    Text = "這是一生僅能表演一次的即興舞蹈。\n但沒關係，它將有幸成為標本，永遠定格。"
  },
  CollectionHall_143489_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143489_Title = {
    Text = "舞劇：《天鵝之死》"
  },
  CollectionHall_143490_Desc = {
    Text = "幕布拉開，荒唐的角色輪番登場。\n他們高歌，她們舞蹈，在命運墮臨之前，執著地將戲碼呈上舞台，即使結局早已寫就。"
  },
  CollectionHall_143490_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143491_Desc = {
    Text = "為了讓一切位於正軌，總有事物該被剔除，被摒棄。\n未被選中的存在，盡數墜入漆黑的深淵，它們的哀嚎與咒罵，終究無人聽見。"
  },
  CollectionHall_143491_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143491_Title = {
    Text = "被遺棄的「我」"
  },
  CollectionHall_143492_Desc = {
    Text = "這樣死去，真美。她想。"
  },
  CollectionHall_143492_LockTip = {
    Text = "完成調查行動 星辰篇5-16解鎖"
  },
  CollectionHall_143492_Title = {
    Text = "至美的抵償"
  },
  CollectionHall_143592_LockTip = {
    Text = "通關意識潛游「永遠的厄波揚斯」任一關卡解鎖"
  },
  CollectionHall_143592_Title = {Text = "癮"},
  CollectionHall_144377_Desc = {
    Text = "漫長的駐守時光中，塔薇也曾踏入過一片土地。\n她悉心觀察每一個生物的行動，不露聲色地行走於人間的邊緣。\n\n某個平凡的日子，入夜時分，城郊的密集燈火吸引了她的目光。\n布景，歌舞，售賣點心的攤販，嬉笑打鬧的孩童，舉杯痛飲的閒人。那是生命的喘息，瞬間的閒暇。\n景象太過令人嚮往，她忍不住現出身形。\n\n「您好，請給我一支糖畫。」\n「好嘞，您稍等。想畫點什麼？」\n塔薇輕輕側頭。她只記得需要提供那些她偶然拾獲的無主貨幣，卻全然忘記了自己可以表露的期許。\n「如果您沒想好的話，不如我按照您的形象畫一支如何？您看起來就像仙女一樣美麗。」\n塔薇微笑著點頭，攤主吆喝一聲，舉起糖勺，開始落筆。\n\n嘀嗒。嘀嗒。\n落入石板的，卻不是蜜色的糖漿。\n而是雨，黑色的雨。\n黑色的黏液從目不可視的高空中滴落，將天空熔開一個觸目驚心的裂口。\n\n\n然後，塔薇開始向上墜落。\n那是世界在下沉。攤主的笑意在塔薇的記憶裡凝固成靜止的一幀，然後和萬物一起湮沒在黑色的汪洋裡，化為無數已逝星辰中微不足道的一顆，化為對她而言遙不可及的過往。\n這是她引發的震盪，也是她應當承受的懲戒。\n她遙望著，靜默不言。她只是向上墜落。\n這才是她應守的位置，那扇「超越時空」的銀扉。\n她將在此永恆俯瞰。"
  },
  CollectionHall_144377_Title = {
    Text = "向上墜落"
  },
  CollectionHall_144448_Desc = {
    Text = "你被許諾了一個永不可近的烏有鄉，那裡裝著你記憶裡所有親切的舊魂靈。"
  },
  CollectionHall_144448_LockTip = {
    Text = "完成意識潛游「永遠的厄波揚斯」"
  },
  CollectionHall_144448_Title = {Text = "舊魂靈"},
  CollectionHall_144449_Desc = {
    Text = "活著的人苦苦尋找著一座可以用於緬懷的墓碑。\n死去的人只是死去。"
  },
  CollectionHall_144449_LockTip = {
    Text = "完成意識潛游「永遠的厄波揚斯」"
  },
  CollectionHall_144450_Desc = {
    Text = "太陽已經墜入海面，最後一縷陽光藏進他的身後。\n晨與昏會在下一刻交替，他會讓此處的一切如常。"
  },
  CollectionHall_144450_LockTip = {
    Text = "完成意識潛游「永遠的厄波揚斯」困難難度"
  },
  CollectionHall_144450_Title = {
    Text = "夕陽將墜"
  },
  CollectionHall_144451_Desc = {
    Text = "月亮嘻嘻發笑，月亮竊竊私語。\n月亮說命運啊，命運啊，命運要落下來了。"
  },
  CollectionHall_144451_LockTip = {
    Text = "完成意識潛游「永遠的厄波揚斯」"
  },
  CollectionHall_144452_Desc = {
    Text = "他在無知無覺中讓人們留下了一些東西。\n他在無知無覺中，和他們一樣遺落了一些東西。"
  },
  CollectionHall_144452_LockTip = {
    Text = "完成意識潛游「永遠的厄波揚斯」"
  },
  CollectionHall_144452_Title = {
    Text = "祂們的厄洛斯"
  },
  CollectionHall_144453_Desc = {
    Text = "對於魚群來說，窒息是牠們離開海洋後，唯一能擁有的感受。"
  },
  CollectionHall_144453_LockTip = {
    Text = "完成意識潛游「永遠的厄波揚斯」困難難度"
  },
  CollectionHall_144453_Title = {
    Text = "困於海洋"
  },
  CollectionHall_144454_Desc = {
    Text = "愚蠢的、膚淺的、自高自大的、外強中乾的離群者建立了自己的國。\n一成不變的空殼們不會吐露出真話，因為沒有什麼，能從溝壑裡重新拼湊起那顆過於害怕變化，以至於過早破碎的心。"
  },
  CollectionHall_144454_LockTip = {
    Text = "完成意識潛游「永遠的厄波揚斯」"
  },
  CollectionHall_144454_Title = {
    Text = "無休的凱旋"
  },
  CollectionHall_144476_Desc = {
    Text = "讓這支短暫的舞於流淌中化為永恆吧。\n下一個祈歲之夜，我們終將在月光下重逢。\n*父女情深，感人肺腑 (ノへ￣、)"
  },
  CollectionHall_144476_LockTip = {
    Text = "完成特遣紀錄「開往祈歲節的列車」"
  },
  CollectionHall_144476_Title = {
    Text = "祈歲焰火"
  },
  CollectionHall_145434_LockTip = {
    Text = "需要通關限時活動「利維坦的遊戲：貪戮角逐」任一關卡"
  },
  CollectionHall_145434_Title = {
    Text = "利維坦的遊戲：貪戮角逐"
  },
  CollectionHall_145460_Desc = {
    Text = "自誕生之日起，祂便陷入永恆的飢餓。\n恆星的屍骨在祂齒縫間碎裂，文明的殘骸在祂腹中腐爛。祂的飢餓是一種比時間更古老的詛咒。祂一次次吞噬力量，驅使奴僕上演權欲的遊戲，可祂從不清楚自己的意義究竟是什麼。\n直到那名叫做蘿坦的戰士來到祂的面前。\n「利維坦。」\n祂不記得上一次聽見自己的名字是什麼時候。跪伏的國王不敢念出它，瘋癲的祭司只能用頌歌代替。\n而她輕易地呼喚祂，如同呼喚一位久候的對手。\n「到你出手的時候了！」\n祂存在了一萬兩千年，在這漫長的永恆中，星球是食糧，生靈是螻蟻，無數的強者們都只是短暫的消遣。沒有任何東西能讓祂感到飽足，也沒有任何東西能讓祂感到恐懼，直到今天。\n這位凡人、這名戰士，提起了巨劍，如風暴般向祂襲來。\n巨劍撕裂鱗甲。祂的耳邊，響起自己於混沌之中誕生時的咆哮。祂的怒火傾毀天體，祂的飢餓吞沒星雲。\n巨劍斬斷利爪。祂回憶起，那位著白紗的「神明」來到祂的面前，將祂的力量與意志分離。\n巨劍刺穿心臟的那一刻，利維坦笑了起來。\n一萬兩千年，那遺失的意志，終於重新來到祂的面前，將祂斬碎，將祂征服，將祂吞噬。她將帶領祂，踏過每一片疆域，走向更遠的星海，征服每一位強大的存在。\n在那一天，古老的混沌之獸重獲新生。回歸於她的一瞬間，祂徹底明白，祂與她，是因純粹的、徹底的力量而誕生。\n力量本身，便是全部的意義所在。"
  },
  CollectionHall_145460_Title = {Text = "天之隕"},
  CollectionHall_146400_Desc = {
    Text = "<Title:簡介>\n古老的神明無法平息那頭星天之鯨亙古的怒火，只能將祂的靈與肉分離。祂的意志落在荒土，化作名為蝕滅·蘿坦的戰士。\n她天性好戰，將追求極致力量視作唯一的本能與榮耀，為此，她踏入星天之鯨的選拔，與其締結契約，又在力量抵達頂點之時，以巨劍斬殺自己的主宰，將那吞星巨獸的權能納入己身。\n尖銳的鯨骨刺破血肉，幽暗的骨甲覆上軀殼，那雙容納星空的雙瞳只剩下對敵人的冷漠審視。\n她並不以毀滅為樂，也不屑於無意義的殺戮。她所渴求的，只有更令人興奮的敵人，只有更為強大的力量。\n那最為純粹的戰士，追逐著強敵的身影，踏遍星海的每一個角落，直到一切強者都倒在劍下，直到一切道路都走到盡頭。"
  },
  CollectionHall_146400_LockTip = {
    Text = "通關意識潛游「直至鯨天隕落」解鎖"
  },
  CollectionHall_146400_Title = {
    Text = "蝕滅·蘿坦"
  },
  CollectionHall_146412_Title = {
    Text = "直至鯨天隕落"
