  },
  CollectionHall_147986_Title = {
    Text = "垂死鯨歌"
  },
  CollectionHall_147987_Desc = {
    Text = "一片荒蕪之上，怒目相瞪的野獸徘徊著，它們都在尋找時機，一個把利齒刺穿脖頸，徹底將對方撕碎的時機。"
  },
  CollectionHall_147987_LockTip = {
    Text = "完成意識潛游「直至鯨天隕落」"
  },
  CollectionHall_147988_Desc = {
    Text = "收起你那無聊的王冠，我從未將它放在眼裡。拔刀吧，世界正為鮮血而癲狂！\n如此，只為如此——\n弒殺吧！蝕齧吧！滅亡吧！"
  },
  CollectionHall_147988_LockTip = {
    Text = "完成意識潛游「直至鯨天隕落」"
  },
  CollectionHall_147989_Desc = {
    Text = "彼時我仍是最低賤的童僕，曾親眼見證過一場堪稱殘酷的征途。\n那位傳奇的主人，力量鑄就了她的骨血，熱血沸騰成了不滅之火，火光又點燃了她的眼睛——\n請替我繼續銘記這段往事，我的孩子。……她最終獲勝，並征服了星空。"
  },
  CollectionHall_147989_LockTip = {
    Text = "完成意識潛游「直至鯨天隕落」"
  },
  CollectionHall_147990_Desc = {
    Text = "麵包與馬戲，世人只會為這二者雀躍不已。\n祂欣賞著，祂不在乎。\n她親歷著，她不在乎。"
  },
  CollectionHall_147990_LockTip = {
    Text = "完成意識潛游「直至鯨天隕落」"
  },
  CollectionHall_147990_Title = {
