  },
  CollectionHall_148015_LockTip = {
    Text = "通關意識潛游「直至鯨天隕落」任一關卡解鎖"
  },
  CollectionHall_148015_Title = {Text = "原則"},
  CollectionHall_148138_Desc = {
    Text = "空曠的實驗室內，各類精密的儀器均規整地擺放著，只有無數管線交錯，如同蜿蜒纏繞的蛇，伏在地面，吊在空中。\n思維的信號宛如一條無人可見的河流，但天才早已習慣於與之打交道。大腦是它們的源頭，再淌過機械的管線，最終匯聚在這具新造的軀殼中。\n意識被傳遞的同時，許多塵封的記憶也被久違地翻出，家人、彌薩格、未完成的實驗……恍惚間，天才想起許多年前，在她還未脫離最初的肉身桎梏時，曾有個無聊的學生，饒有興趣地圍著她轉來轉去，眼裡閃爍著名為好奇心的光芒。\n「您認為，人造的軀體能承載真正的魂靈嗎？」\n凡人總愛幻想一些遠超他們視野的事物，這是個庸俗的問題。但身為教師，她仍給出了幾句回應，縱然沒抬一下眼。\n「你的身體未嘗不是人造之物，心臟、四肢、五感這些器官的運行又和機械有何區別？」\n「好了，比起胡思亂想這些，不妨抽出時間，好好鍛鍊下你那生鏽的大腦，否則，你這具流通著血液的肉體只會更無用。」\n如今，發問之人早已被時間的砂礫掩埋，不復存在。唯有承載智慧的腦缸仍在思考，並永遠思考。\n世人口中所謂的魂靈不過是860億個神經元交錯而成的電化學活動，血肉也好，機械也罷，原材料的相異不會改變它們只是載體的本質。\n是啊，凡人無能為力，但身為天才的她能夠做到，且已經做到——唯有如此，才能解明世界的真理，抵達知識的頂端。\n視覺，不過是光線穿過眼球，最終於視網膜上聚焦成像。\n嗅覺，不過是氣味分子與受體結合，劃過神經的化學感知路徑。\n聽覺，不過是聲波經耳蝸換能，轉化為上傳至皮層的電信號。\n人偶身處之地太過昏暗，微弱的燈光搖曳，連影子也無法被映照。她雙目微閉，因為清楚哪怕睜開它們，映入眼簾的也不過是一成不變的畫面。\n房間被打掃得一塵不染，瓶罐中的藥液也被緊緊封存。機體不需要呼吸，更沒必要為了測試感官而去攝取這無味的空氣。\n唯有一聲冰冷的機械提示音，迴蕩在空曠的實驗室中：\n「意識同調完成，機體啟動確認。」\n足夠了。\n雖是無機質的聲音，但聽起來倒親切，彷彿錨定了物質世界的真實，又像隻是在單純提醒她，短暫的休憩結束，是時候投身於新一輪的研究中了。"
  },
  CollectionHall_148138_Title = {
    Text = "魂靈同調"
  },
  CollectionHall_148140_Desc = {
    Text = "<Title:簡介>\n冰風刺骨的雪夜，赤腳的女孩將靈魂獻給了蠕蟲。\n如果出賣這種廉價之物，就能換取多少人渴求不來的幸福，她沒有什麼好猶豫不捨的。\n從此她像一個白色的影子，遊走於荒蕪的人間，用謊言編織聖殿，用糖果偽造賜福，換取糊口的供奉。\n她和蠕蟲，就像是最好的搭檔。\n直到山巔傳來新的訊息，昭告世人足以實現所有願望的聖地。\n那根火柴被劃亮了。\n她將用它融化整座雪山。"
  },
  CollectionHall_148140_LockTip = {
    Text = "通關調查行動星辰篇第6章「山宴」解鎖"
  },
  CollectionHall_148143_Title = {
    Text = "終北大陸"
  },
  CollectionHall_149045_Desc = {
    Text = "「把花環戴好，這就是你的授勛禮了，親愛的小騎士。」\n雛菊開遍原野時，總有怠惰的兵士借著護衛的名頭，拉著少年在此遊蕩。\n亞奎丹公國最常見的花編做的飾品，被輕輕地放在金色的髮上。\n「閣下，也許……我們該訓練了？」\n少年這樣說著，卻乖巧地將潔白的花環戴正。\n這小巧的植物，總是沐浴於光明之中，在少年的國度，亦是希望的象徵。\n再度睜開雙眼時，那些明麗的畫面已不復存在。\n戰馬在嘶鳴，敵人不屑地一擁而上，在千軍萬馬中，他只有孤身一人。\n然後，刺耳的喧嘩聲戛然而止——\n黑色的潮水湧入他的靈魂。\n隨之響起的是長槍貫穿皮肉的撕裂聲，鮮血的湧動聲，敵人的哀嚎聲。\n那些面孔上的輕蔑蕩然無存，取而代之的是鋪天蓋地的畏懼與退縮。\n而少年只是機械地抬手，刺穿，拔出，再舉起。\n直到最後一名士兵倒下。\n煙塵隱沒了無數面孔，征伐者與被征伐者的殘骸堆積在地，再無分別。\n影子纏上他的脊背，嗤笑著：「繼續呀。落下你的槍，再多一次。」\n「守護者與毀滅者之間，本就只有一線之隔。如今，你已做出了選擇。」\n黑暗遮蔽了天空，血浸透了大地。\n他看向遠方的郊野——只是短短一夜，那裡便永遠失去了往日的色彩。\n風吹起少年的衣角，也掠過那片僥倖存留的草地。\n在無聲的夜色中，在惡魔也不知道的角落裡，一抹難察的純白仍留在他的眼底。\n那是這個國度的最後一朵雛菊，在無人在意之地默默生長。\n儘管沾染了赤色，花莖彎折，卻仍未倒下。"
  },
  CollectionHall_149045_Title = {
    Text = "而雛菊仍然盛開"
  },
  CollectionHall_149759_Desc = {
    Text = "<Title:簡介>\n奧吉爾終究還是承認，以他的年紀與力量，尚不足以成為護國的騎士。\n在這個世界，他沒能得到那句關鍵的支持。\n於是，在公主的勸導下，他回到了父親的領地，像普通貴族少爺那樣生活。\n\n戰火襲來之時，仍無法拋卻騎士身分的奧吉爾趕回王宮，卻為時已晚。\n公主以最殘酷的方式自我毀滅；熟悉的同僚無一生還——他們在最後一刻仍堅守陣地。\n當敵軍闖入早已破敗的宮殿，想將這裡劫掠一空時，他無法抑制憤怒與哀痛，選擇將身體交付給那充滿誘惑的黑暗力量。\n敵人來不及重整陣型，盡數斃於他手，可復仇之後，少年並未感到半分解脫。\n\n漆黑的影子佔據了他的軀體，侵染了他的靈魂，在那段渾渾噩噩的日子裡，他犯下了許多過錯。\n\n——殺戮，破壞，做一切有違誓言之事......直到一縷陽光將他從無邊的虛無中喚醒。\n\n或許，現在開始後悔還來得及。\n他仍有機會重新執起槍與盾，為守護美德而戰。"
  },
  CollectionHall_149759_LockTip = {
    Text = "喚醒「負誓·奧吉爾」後解鎖"
  },
  CollectionHall_149759_Title = {
    Text = "負誓·奧吉爾"
  },
