  },
  CollectionHall_48611_Desc = {
    Text = "<Title:物質維度>\n物質存在的維度，人類日常生活所處的「現實世界」。\n物質維度中，空間以三維呈現，時間線性，物質可感，情緒和精神抽象不可見。\n一切如此自然，彷彿那些不可理解的事物從未存在過。\n\n<Title:精神維度>\n精神所在的維度，又被稱為「幻夢維度」。\n精神維度中，情緒、記憶、執念等，都可能形成不同的個體。\n除物質維度個體的精神外，這裡還棲息著各種精神維度的生物。這類生物難以靠肉眼觀測，只能借助特殊儀器感知，或於密境中窺探。"
  },
  CollectionHall_48611_Title = {Text = "維度"},
  CollectionHall_48612_Desc = {
    Text = "<Title:定義與特性>\n一種物質特殊消解、溶解的現象。\n除卻少數個體，絕大多數人類無法通過肉眼觀測融蝕現象。\n隨著融蝕發展，被融蝕者的存在本身將被抹去。生活痕跡、書面記錄、乃至與其相關的記憶悉數消失。\n他們將被整個世界遺忘。\n\n<Title:融蝕傳播>\n無可考傳播途徑。\n融蝕的出現與消失似乎完全隨機，無法預測，也無跡可尋。當前僅可通過特定的方法和手段，如特殊儀式、遺物等，達到擴散融蝕的效果。\n\n<Title:融蝕干預>\n僅能通過銀芯及銀芯製品對其進行干預治療。\n大部分更易被融蝕侵蝕，可在徹底消解之前通過銀芯製品干預。\n極少數個體對融蝕有一定抗性，但其精神將受到不可逆的損傷，無法通過銀芯製品進行修復，目前尚未找到有效干預手段。"
  },
  CollectionHall_48612_Title = {Text = "融蝕"},
  CollectionHall_48614_Title = {Text = "門"},
  CollectionHall_48616_Desc = {
    Text = "<Title:創辦日期>\nA.F.187，前身彌薩格學院創辦於A.F.90\n\n<Title:創始人>\n華德·菲利普斯，刻拉爾克什，塔薇\n\n<Title:概述>\n以抵抗融蝕為己任的特殊大學。\n完全獨立於各國政府的第三方，不參與任何政治鬥爭，不歸屬任何派系。\n全體師生加上教職員工僅一千餘人，除開經濟、人文、科學等方面的普通課程，還針對調查員、守密人及喚醒體開設了特殊課程。\n主校區位於雷歐王國，當世界各地出現融蝕現象時，會派出調查隊與調查員、守密人前往解決。\n是一個理論與實踐並重的特殊組織，掛科的後果同樣很嚴重。"
  },
  CollectionHall_48616_LockTip = {
    Text = "通關序章解鎖"
  },
  CollectionHall_48616_Title = {
    Text = "彌薩格大學"
  },
  CollectionHall_48619_Desc = {
    Text = "<Title:創辦日期>\nA.F.186\n\n<Title:創始人>\n《密斯底亞協議》簽署國\n\n<Title:概述>\n普通人類構成的全球性組織。\n由各國政府共同出資建立，獨立於政府存在，是融蝕現象的官方管理者及第一回應者。\n成員多是沒有神秘學背景和超自然能力的普通人，以對抗融蝕為第一要務和唯一目標。\n在世界各國設有多個辦事處，分別負責不同的區域。\n嚴肅刻板是所有人對它的第一印象，漿洗過度的白色制服就和他們的背脊一樣筆挺。"
  },
  CollectionHall_48619_LockTip = {
    Text = "通關調查行動第2章「以蠟像之名」解鎖"
  },
  CollectionHall_48619_Title = {
    Text = "密斯底亞協議審查會"
  },
  CollectionHall_48622_LockTip = {
    Text = "可於調查行動1-2中解鎖"
  },
  CollectionHall_48622_Title = {Text = "聯絡點"},
  CollectionHall_48623_Title = {
    Text = "彌薩格大學"
  },
  CollectionHall_48624_LockTip = {
    Text = "通關序章解鎖"
  },
  CollectionHall_48624_Title = {Text = "銀芯"},
  CollectionHall_48625_LockTip = {
    Text = "通關意識潛遊「一步之遙：似雨之淚」解鎖"
  },
  CollectionHall_48625_Title = {
    Text = "生命的餘影"
  },
  CollectionHall_48628_Desc = {
    Text = "嗷嗚，嗷嗚！\n孤狼帶上面具，發出吼聲撲來。"
  },
  CollectionHall_48629_Desc = {
    Text = "所有人都會喜歡白色絨絨兔，包括可愛的愛麗絲。"
  },
  CollectionHall_48629_Title = {Text = "詛咒兔"},
  CollectionHall_48630_LockTip = {
    Text = "可於調查行動中解鎖"
  },
  CollectionHall_48630_Title = {
    Text = "<WhiteQuality:無名附肢>"
  },
  CollectionHall_48631_Desc = {
    Text = "這只小黃螺出身高貴，有著完美的、無可挑剔的來源。"
  },
  CollectionHall_48631_LockTip = {
    Text = "可於調查行動中解鎖"
  },
  CollectionHall_48631_Title = {
    Text = "<WhiteQuality:小黃螺>"
  },
  CollectionHall_48635_Desc = {
    Text = "<Title:簡介>\n彌薩格代理院長。\n師從克勞利·麥金農，是赫伯特的直系學妹。\n赫伯特弑師的見證者之一，在導師死後一直代為處理學院相關事宜。\n絕對的效率至上主義者，從不遲到，剪短髮是因為可以節省梳頭的時間。\n因戰亂從祖國埃爾克偷渡到雷歐。\n右手食指無法正常彎曲，據說是在集中營被殘忍對待的證明。"
  },
  CollectionHall_48635_LockTip = {
    Text = "通關序章解鎖"
  },
  CollectionHall_48635_Title = {Text = "訶勒特"},
  CollectionHall_48636_Desc = {
    Text = "<Title:簡介>\n三大創始人之一，與華德·菲力浦斯，刻拉爾克什一同創立了彌薩格大學的前身——彌薩格學院。\n是第一個「喚醒體」，也是提供喚醒體科技的存在。\n常年鎮守黑池，見過她的臉的人屈指可數，是彌薩格大學最高機密之一。\n「噓……不可試探你的@2。」"
  },
  CollectionHall_48636_LockTip = {
    Text = "通關序章解鎖"
  },
  CollectionHall_48941_LockTip = {
    Text = "可於調查行動1-8中解鎖"
  },
  CollectionHall_48941_Title = {
    Text = "銹蝕門扉"
  },
  CollectionHall_48942_Desc = {
    Text = "我的靈魂是一座墳墓。"
  },
  CollectionHall_48944_Desc = {
    Text = "不朽不敗。"
  },
  CollectionHall_48944_Title = {Text = "眷顧"},
  CollectionHall_48945_Desc = {
    Text = "至垂死之時，迸發出生之渴望。"
  },
  CollectionHall_48946_Desc = {
    Text = "眼見為實。"
  },
  CollectionHall_48947_Desc = {
    Text = "我們是空心人，我們是稻草人。"
  },
  CollectionHall_48948_Desc = {
    Text = "噓……止於此，止於我。\n不可試探其來歷。"
  },
  CollectionHall_48948_Title = {Text = "貪婪"},
  CollectionHall_48949_Desc = {
    Text = "荷蒙庫魯斯在上，為您奉上純潔無暇的軀殼。"
  },
  CollectionHall_48950_Desc = {
    Text = "致命的甜蜜在鼻腔擴散。\n小心——黏膩的死亡來了。"
  },
  CollectionHall_48968_Desc = {
    Text = "關於德克斯特勳爵的手杖，彌薩格校園內流傳著許多猜想。\n\n「毫無疑問，勳爵的手杖和他的笑容一樣藏有秘密。\n究竟是鑲有銀芯能夠調動喚醒體之力，還是暗藏火藥可以隨時化身槍械呢？\n就讓德克斯特勳爵為我們揭秘一下吧！」\n\n邊念邊速記下開場白後，漢娜將相機對準了德克斯特勳爵，期待著來自持有者本人的下文。\n\n「它嗎？沒什麼特殊的，只是德克斯特家族訂製的日用手杖罷了。\n我的這柄上所用的寶石，甚至不如我兄長的珍貴。\n如果一定要說它有什麼特殊之處的話……\n它曾經沾上我父母和兄弟的鮮血，這算不算？」"
  },
  CollectionHall_48968_Title = {
    Text = "勳爵手杖"
  },
  CollectionHall_48969_Desc = {
    Text = "倫蒂尼恩的地下世界流傳著這樣一個故事。\n\n繁忙的碼頭上、僻靜的巷道中、嘈雜的酒館內……\n你不知道何時、在哪裡能找到那個拿著相機，戴著眼鏡，穿著制服的少女，但只要找到她，就能買到任何你想要的資訊，而代價只有一個——\n\n提供一個僅有你知道的秘密。\n\n有人用吧檯邊聽到的酒後真言換來了競爭對手的致命弱點。\n有人用自己的弱點換來了情人閉口不談的過去。\n少女握有無數情報，唯有一個是用何等秘密都無法換來的。\n\n「關於我的事情？抱歉啊，這可是非賣品哦。」"
  },
  CollectionHall_48969_Title = {
    Text = "資訊就是生命"
  },
  CollectionHall_48970_Desc = {
    Text = "彌薩格校園中最不能招惹的人，如果朵爾自居第二，那麼第一名非茜爾維婭女士莫屬。\n\n身為彌薩格唯一的心理醫生，這位神秘的女士不僅要負責安撫任務中受驚的調查員，疏導喚醒體躁動的情緒也是她的職責。\n非但不畏懼喚醒體，還能在精神上與他們分庭抗禮——這究竟是怎樣的一位強者呢？\n\n懷著對未知的好奇，缺失了幾分敬畏之心的新生於深夜溜進了茜爾維婭女士的診療室。\n\n然後，他們就失去了意識。\n次日清晨在校園廣場上醒來時，他們頭疼欲裂，內心卻是前所未有的明朗。\n有人撿起了從他們口袋裡飄落的信箋：\n\n「如果需要心理諮詢，請提前向艾瑞卡小姐申請哦——\n茜爾維婭」"
  },
  CollectionHall_48970_Title = {
    Text = "心之壁壘"
  },
  CollectionHall_48971_Desc = {
    Text = "在貴族夫人憐憫又嫌惡地用手帕捂住鼻子，差遣僕人將不要的珠寶給她時，她想：\n多好啊，濟貧院的孩子們能吃上一餐肉了。\n\n在她將自己的餐食都分給孩子們，自己則因為長時間饑餓而暈倒在走廊後，她說：\n沒事的，別叫醫生，診金可值好幾個麵包呢。\n\n在好心的藝術家帶著相熟的醫生前來拜訪，並向她提出長期合作時，她想：\n必須讓他們先在我身上試試，不然我可不放心讓孩子們來接受他們的這個什麼治療。\n\n莎拉什麼都可以忍受，唯一不能忍受的便是所做的一切，最終卻導致了悲劇的結局。"
  },
  CollectionHall_48971_Title = {Text = "臨界點"},
  CollectionHall_48972_Desc = {
    Text = "手在黑暗中四處亂轉，尋找自己的主人。\n\n在那個血腥的夜晚，它被從主人身上殘酷剝離。\n此時此刻，帶走它的罪魁禍首在它四周流淌，發出奇特的嗡鳴。\n \n「放棄吧，和我們離開。蠟像師會將你徹底遺忘。」\n\n手不為所動，它撥動著自己引以為豪的、修長的手指。\n\n「主人不會忘記我。\n我是他藝術實現的唯一途徑——\n你們不明白我對他而言意味著什麼。」\n\n「就像人會遺忘愛人，遺忘時間，但不會遺忘自己。」\n\n黑暗中傳來同情的笑聲。\n「恰恰相反，人最先遺忘的總是自己。\n不過沒關係——」\n\n時間會解釋一切，手遲早會明白這個道理：\n沒有什麼是不能被遺忘的。\n它們流淌了一個又一個世紀，人間的故事在它們身邊發生，第二天就被遺忘。\n而它們依舊在不停地流淌。"
  },
  CollectionHall_48972_Title = {
    Text = "遺忘之手"
  },
  CollectionHall_48973_Desc = {
    Text = "自被華德·菲力浦斯先生收留以來，阿利斯泰爾陪同他出席過不少次彌薩格的高層會議。\n\n說是高層，實際上更像是每個月一次的辯論賽：\n菲力浦斯先生語氣溫和，循循善誘；\n刻拉爾克什言辭辛辣，寸步不讓。\n他們輪流做正方或者反方，為了彌薩格的未來或下個月喚醒系的資源配給爭執不休。\n塔薇小姐是個沉默的旁觀者，從不輕易給出自己的建議。\n他自己則努力做個正直的記分員，偶爾兼職裁判，甚至有一次得用上一些格鬥技巧，避免小小的會議桌遭遇不測。\n\n而今，會議成員僅剩兩個，一個永遠不能離開黑池，另一個也為了搏得那可能的「未來」而再也不能離開地下。\n至於那張桌子，早在那次事件後就再也找不著了。"
  },
  CollectionHall_48973_Title = {
    Text = "聚首時刻"
  },
  CollectionHall_48974_Desc = {
    Text = "塔薇沉睡於黑池之底。\n\n那裡終年無聲無光，只有一片令人絕望的黑暗。\n從未有客人造訪過這裡，從未有聲音抵達過這裡。\n這裡是毀滅無法企及之地——\n\n因為災厄已經降臨。\n\n身為時序的司掌者，她目睹過太多慘痛的終局。\n身為規則中的一員，她也無力阻止黑夜的降臨。\n既然如此，只能蟄伏於不存在之地，以不存在之姿等候堪稱「變數」之人到來。\n\n那個人終將到來。"
  },
  CollectionHall_48975_Desc = {
    Text = "科學是光譜分析，藝術是光合作用。"
  },
  CollectionHall_48975_Title = {
    Text = "光合祭禮"
  },
  CollectionHall_48976_Desc = {
    Text = "旋轉，然後遺忘——這是她生命的全部。"
  },
  CollectionHall_48976_Title = {
    Text = "36室之環"
  },
  CollectionHall_48977_Desc = {
    Text = "我唾棄你的墳墓。\n因你在死中尋得了難得的平靜。"
  },
  CollectionHall_48977_Title = {
    Text = "埋骨地絮語"
  },
  CollectionHall_48978_Desc = {
    Text = "永恆於啟示之中投來的一縷視線。\n純潔、無垢且真實。"
  },
  CollectionHall_48978_Title = {
    Text = "無垢啟示錄"
  },
  CollectionHall_48979_Desc = {
    Text = "臍帶連接著母體，供胎兒榨取無盡的未來。"
  },
  CollectionHall_48979_Title = {
    Text = "生機榨取"
  },
  CollectionHall_48980_Desc = {
    Text = "歸來吧，那終將重現的失落之城。\n歸來吧，@3！"
  },
  CollectionHall_48980_Title = {Text = "海歸線"},
  CollectionHall_48981_Desc = {
    Text = "鱗翅目正死於孤獨、愛與絕望。"
  },
  CollectionHall_48981_Title = {
    Text = "有機形態"
  },
  CollectionHall_48982_Desc = {
    Text = "他被埋葬在18@2年的春天。\n墓碑林立，如無聲的讚歌。"
  },
  CollectionHall_48982_Title = {
    Text = "四月禮讚"
  },
  CollectionHall_48983_Desc = {
    Text = "一千年前，五分鐘等於四十盎司細沙。"
  },
  CollectionHall_48983_Title = {
    Text = "入藥之夢"
  },
  CollectionHall_48984_Desc = {
    Text = "必然的，偶然的。有限的，無限的。"
  },
  CollectionHall_48985_Desc = {
    Text = "代理院長是彌薩格校園中的異類。\n\n在各具異能怪物橫行的彌薩格調查員中，她是極少數毫無任何超越人類基本能力的個體之一，卻擔任了代理院長這一重要職能。\n出身於埃爾克王國普通家庭的她，在當地特色文化熏陶下形成了勇猛兇悍的性格。\n\n後來，在戰俘營的同伴索菲亞點燃了她對學術研究的熱情。\n突出的學術成就讓她成為了她的導師、彌薩格大學生物學院前任院長的最認可的弟子。\n所以，在導師失蹤後，她便順理成章地接下了代理院長的職責。\n在她的堅守下，生物學院的研究有條不紊地運轉。\n\n「不畏懼暴力，不畏懼霸權，自然也不會畏懼職責所在。」"
  },
  CollectionHall_48985_Title = {
    Text = "職責所在"
  },
  CollectionHall_48986_Desc = {
    Text = "調查員間有個不成文的規定：\n\n鑰塚儀式後的那一夜，資歷更深的調查員會帶領新晉調查員在宿舍後院聚會。\n他們會點起蠟燭，圍著自己的銀鑰匙坐成一圈。\n資深的調查員會告訴每個新人，他們手上這個有著獨一無二編號的鑰匙有過怎樣的故事。\n\n這樣的活動最後都會變成某種故事大會，而I-0001及K-0001，這兩把代表「初代」的鑰匙，自然也會成為討論的中心。\n鮮有人知道的是，由初代守密人親手制作而成的K-0001號銀鑰匙，如今和它的主人一同永居地下，在無法分辨日夜的漫長等待中，聆聽那人對早已逝去之人的低語。\n\n「你知道他不是真的在這裡吧，阿利斯泰爾。」朵爾說，「它或許是用你老師的銀芯做的，但不能被視作他的靈魂。」\n「這只是一種專注精神的方式罷了，朵爾。」阿利斯泰爾笑了笑，「放心，我很穩定，可不能在我們的新晉守密人成長起來前就倒下，你說對吧？」"
  },
  CollectionHall_48986_Title = {
    Text = "專注精神"
  },
  CollectionHall_48987_Desc = {
    Text = "他生命的前半段是混沌、黑暗與血腥的。\n\n吃了睡，睡了吃......後來，他睜開雙眼，擁有了意識。\n\n他們說他吃掉了自己所有的兄弟姐妹，是唯一的生還者。\n他們還說他是偉大的蛇神與人類交合誕下的子嗣。\n他的脖頸上有一圈黑色的咒縛，它們維繫著他的生命，也控制他，使他此生都無法違抗教會。\n他對這個世界有諸般疑惑與好奇，卻在誕生伊始便被剝奪了所有其他的可能性。\n\n美麗的、危險的。隱匿的、張揚的。這些都是他。\n遺憾的是，以上供述尚未觸及他的本質的十分之一。\n任何因此供述對阿爾比諾產生的惻隱之心都將令你萬劫不復。"
  },
  CollectionHall_48987_Title = {Text = "苦咒縛"},
  CollectionHall_48988_Desc = {
    Text = "醫生的天職，本是治癒病人。\n\n但偏巧有那麼一種治癒手段，需要以最鋒銳的刀刃劃破皮膚，刺穿肌理，剖開胸膛，摘除病灶，然後許願人體憑藉自愈能力的重生。\n\n這原本不應當是她的罪。\n但每次完成手術後，她還是忍不住補償似的給那個女孩講點故事。\n她不是個好的講述者，話語支離破碎，但那些虛構的故事仍讓女孩認真專注地聽了進去。\n被她親手切割之處，彷彿緩慢而頑強地吸收著那些話語的力量，漸漸自然癒合……"
  },
  CollectionHall_48988_Title = {
    Text = "切割與傷害"
  },
  CollectionHall_48989_Desc = {
    Text = "巨獸潛伏於夜色之中。\n\n小屋之內，痛失愛女的哀哭聲在每個午夜衝破白日的隱忍與壓抑，毫無掩飾地劇烈迸發。\n從啜泣到哀嚎，最後訴說著那個已經不屬於巨獸的名字，以痛楚的呼喚聲貫穿巨獸那顆與人類一般無二的心臟。\n\n回家吧，麗莎。\n噢，我的麗莎。\n巨獸無聲，潛伏於夜色之中。蜷縮身形，沉沉睡去。\n終有一日，她要回去，回到那個名為「家」的地方。"
  },
  CollectionHall_48989_Title = {
    Text = "伏於夜色"
  },
  CollectionHall_48990_Desc = {
    Text = "沒有人一出生就是船長，至少埃爾頓不是。\n\n在成為一名船長前，他一直在海軍與商船間輾轉，好幾次險些成了海盜，好在最後，他在一艘探險船上安定了下來。\n\n探險船圍繞著極地大陸航行，每次登入都意味著一場新的冒險。\n他的職責是為體弱的科學家背負行囊，他曾為此感到自豪——行囊裡裝著的，說不定是能改變世界的東西。\n而他們，或許是即將改寫歷史的人。\n\n在一場冰風暴將他們困在冰洞之前，在一隊神秘教徒深夜襲擊了他們之前，埃爾頓一直是這麼認為的。"
  },
  CollectionHall_48990_Title = {
    Text = "冒險的行囊"
  },
  CollectionHall_48991_Desc = {
    Text = "他一直是個沉默、勤奮的學生。\n\n早上8點，當其他研究員叼著麵包急匆匆趕到時，他已經寫完了一篇實驗報告。\n晚上12點，當實驗樓的燈全部熄滅時，他才慢吞吞收拾東西離開。\n\n對了，他還會每天餵養附近的小野貓。\n後來小野貓不見了，沒人知道它們去了哪裡。\n\n導師克勞利剖析著他的實驗記錄和報告。\n簡潔、細緻，沒有任何閃光之處——但也沒有任何破綻。\n這個學生令他疑惑。\n但疑惑總是好的，它往往是通向好奇心的開關。\n\n當然，那時候的克勞利並未料到：它也可能是通向死亡的開關。"
  },
  CollectionHall_48992_Desc = {
    Text = "「不知不覺中，你已經離開這麼久了。\n\n我還是經常在夢裡回到那天，左臂槍傷的疼痛，失血造成的迷幻錯亂，暴亂鼠群的追擊……\n在那片混亂中，穿著彌薩格校服的你出現了，帶我逃離了那座早就充斥不詳的古堡。\n\n在那個夢的最後，你站在病床前告誡我，對調查員來說，死亡總是如影隨形的。\n我已經無法判斷那是真實還是我的幻想了。\n每當這個時候，我就會去觸摸我的左臂，如果能碰觸到冰冷精緻的金屬表層，那便是現實。\n\n但在更多的夢境裡，我只抓握住一片虛空。」"
  },
  CollectionHall_48992_Title = {Text = "致摯友"},
  CollectionHall_48993_Desc = {
    Text = "克勞利在任教期間一直蟬聯「最受歡迎導師」的榮譽稱號。\n\n他略顯笨拙的康斯坦西部口音與真誠的笑容為他贏得無數學生的好感，這其中也包括赫伯特。\n\nA.F.2@1年，克勞利力排眾議，將毫不起眼的赫伯特收為自己的學生。\n赫伯特與他一起翻越高山、跨過溪流、穿過沙漠，在一個又一個融蝕裂隙外留下足印。\n他猶記第一次見到融蝕裂隙時的震撼。\n\n克勞利站在蒸騰而上的黑色濃霧前，身形顯得如此渺小。\n「噓——你聽到了嗎？」\n赫伯特於是閉上雙眼，只聽到寂靜海洋不斷翻滾的聲音，世界似乎離他遠去了。\n克勞利興奮極了，他說：\n「這是詩。宇宙中最神秘、最深沉的詩。」\n\n多年以後，赫伯特對克勞利的記憶早已模糊。\n比如他們如何合作、爭執，比如他如何將他「失手」殺死。\n但他永遠記得那個黑霧之下的笑容。\n那一刻，他看見詩。"
  },
  CollectionHall_48993_Title = {
    Text = "記憶症候"
  },
  CollectionHall_48994_Desc = {
    Text = "只要我們的大腦仍是個謎，那麼裡面長滿觸腕也沒什麼好大驚小怪的。"
  },
  CollectionHall_48994_LockTip = {
    Text = "可於調查行動中解鎖"
  },
  CollectionHall_48994_Title = {
    Text = "<WhiteQuality:裂頭蚴>"
  },
  CollectionHall_48995_Desc = {
    Text = "夢想是星辰大海！"
  },
  CollectionHall_48995_LockTip = {
    Text = "可於調查行動中解鎖"
  },
  CollectionHall_48995_Title = {
    Text = "<WhiteQuality:潛水頭盔>"
  },
  CollectionHall_48996_Desc = {
    Text = "見不可視者，聽不可聞者。"
  },
  CollectionHall_48997_Desc = {
    Text = "一切惡的根源。"
  },
  CollectionHall_48997_Title = {Text = "懲戒"},
  CollectionHall_48998_Desc = {
    Text = "萬物化為己有。"
  },
  CollectionHall_48999_Desc = {
    Text = "不見往昔，不念未來。"
  },
  CollectionHall_48999_Title = {Text = "狂亂"},
  CollectionHall_49000_Desc = {
    Text = "將愛與死亡獻給世界。"
  },
  CollectionHall_49000_Title = {Text = "寵愛"},
  CollectionHall_49001_Desc = {
    Text = "積蓄良久，於此宣告——"
  },
  CollectionHall_49001_Title = {Text = "湧現"},
  CollectionHall_49002_Desc = {
    Text = "呼喚其名：厄瑞克斯。"
  },
  CollectionHall_49002_Title = {Text = "譫妄"},
  CollectionHall_49003_Desc = {
    Text = "與「祂」的交談。"
  },
  CollectionHall_49004_Desc = {
    Text = "賜予萌芽與胚胎的祝福。"
  },
  CollectionHall_49015_Desc = {
    Text = "在災厄憑空消失，危機宣告暫時解除後，彌薩格特別行動隊帶著「意外收穫」離開了阿庫特。\n德克斯特小姐最後回頭看了一眼爆炸中心的巨坑，不知名植物的嫩芽竟不知何時悄然破了土。\n她鬆了一口氣，心情愉悅。\n阿庫特林地將會迎來它的春天。\n楊柳會在下一個春天到來時抽條，鈴蘭會在下一個雨季後悄然綻放，所有的生命都將迎來新生。\n而他們對抗未知的旅途，也將踏上新的起點。\n"
  },
  CollectionHall_49015_Title = {
    Text = "阿庫特之春"
  },
  CollectionHall_49018_Desc = {
    Text = "A.F. 314，冬日的一個深夜，爆炸聲響徹阿庫特林地。\n大地震顫，林地亮如白晝。伴隨著生命的尖嘯與自然的哭嚎，村鎮被夷為平地。\n據參與了「阿庫特災厄調查」的喚醒系預科生德克斯特所言，那一夜沖天的火光中，閃耀著黑與銀的色彩。"
  },
  CollectionHall_49018_Title = {Text = "隕日"},
  CollectionHall_49025_Desc = {
    Text = "濃黑的血祭，願雙子庇佑你的肉體。"
  },
  CollectionHall_49025_Title = {
    Text = "扭曲雙子·黑"
  },
  CollectionHall_49026_Desc = {
    Text = "霧白的祝禱，願雙子庇護你的靈魂。"
  },
  CollectionHall_49026_Title = {
    Text = "扭曲雙子·白"
  },
  CollectionHall_49027_Desc = {
    Text = "盡情享受歡宴吧，於歌聲中，慶祝被毀滅的故鄉。"
  },
  CollectionHall_49027_Title = {
    Text = "遠方的歡宴"
  },
  CollectionHall_49028_Desc = {
    Text = "傳說中最初的魔偶創造者，以血液滋養魔偶。"
  },
  CollectionHall_49028_Title = {
    Text = "猩紅之悸"
  },
  CollectionHall_49029_Desc = {
    Text = "機械絕對純淨，神明至高無上。\n降臨的並非線團，而是偉大的阿里阿德涅。"
  },
  CollectionHall_49029_Title = {
    Text = "機械降神"
  },
  CollectionHall_49030_Desc = {
    Text = "繁衍吧，繁衍吧。讓流淌著母樹鮮血的靈魂遍及世界。"
  },
  CollectionHall_49031_Desc = {
    Text = "傳說中最初的魔偶創造者，以雙手殺死魔偶。"
  },
  CollectionHall_49031_Title = {
    Text = "猩紅之擁"
  },
  CollectionHall_49033_Desc = {
    Text = "時間的弦根根繃斷，流動的琴鍵紛紛碎裂。\n祂們立於現實之外，以現實為材縫補殘缺，讓永不謝幕的樂章再度奏響高天之上。\n至於那片刻夢醒時落的淚流向了何方，無人得知。"
  },
  CollectionHall_49033_Title = {
    Text = "靈魂誕生"
  },
  CollectionHall_49082_Title = {
    Text = "倫蒂尼恩室外"
  },
  CollectionHall_49084_Title = {
    Text = "02 以蠟像之名"
  },
