    Text = "通關調查行動6-1解鎖"
  },
  CollectionHall_49104_Title = {
    Text = "倒錯的群星"
  },
  CollectionHall_49105_LockTip = {
    Text = "通關特遣紀錄「血的顏色：悔過」解鎖"
  },
  CollectionHall_49105_Title = {
