  },
  CollectionHall_49740_LockTip = {
    Text = "通關調查行動7-0解鎖"
  },
  CollectionHall_49740_Title = {
    Text = "萬千子嗣之母"
  },
  CollectionHall_49747_Desc = {
    Text = "自融蝕傷痕中長出的贅生物。\n目前為止，贅生物的生長與否、不同類型贅生物的分佈等，都無法總結規律。\n可能是額外的肢體、觸手，也可能是齒輪、金屬等無機物。"
  },
  CollectionHall_49747_Title = {
    Text = "融蝕贅生物"
  },
  CollectionHall_49748_Desc = {
    Text = "<Title:定義與特性>\n直徑超過5米，且仍有擴大可能性的巨大融蝕痕。\n根據融蝕裂隙的大小可被分為C、B、A、S、SS、SSS類裂隙。\n隨時間推移將持續擴大，除去常規的融蝕擴散以外，還會引起異常自然現象，如海嘯、颶風等。\n\n<Title:應對方式>\n由銀芯精製而成的銀鑰匙可在一定程度上壓制甚至「關閉」裂隙。\n守密人通過銀鑰匙放大自身精神，使其與精神維度產生共鳴，在融蝕裂隙上形成一道高維度屏障，使其暫時「關閉」。"
  },
  CollectionHall_49748_Title = {
    Text = "融蝕裂隙"
  },
  CollectionHall_49749_Desc = {
    Text = "融蝕裂隙的核心，通常也是守密人在外勤任務中需要解決的主要敵人。\n可擴散融蝕現象，會根據自身特性影響附近的融蝕現象，使其具有區域性特徵。"
  },
  CollectionHall_49749_Title = {Text = "災厄"},
  CollectionHall_49750_Desc = {
    Text = "<Title:定義與特性>\n融蝕現象導致個體異變、消融、死亡的現象。\n會發生在人類、動植物等有機生物體上，也會出現在礦物、金屬等無機物上。融蝕裂隙附近的個體出現融蝕侵蝕的可能性更高。\n目前尚未發現能夠免疫融蝕現象的物質。\n\n<Title:各時期特徵>\n初期：體表出現倒三角形黑色融蝕痕，伴有融蝕漿析出。\n中期：融蝕痕擴大，持續析出融蝕漿，個體精神受損。可能產生融蝕贅生物。\n後期：融蝕痕迅速擴大，融蝕漿析出速度加劇。大部分個體在此階段將完全喪失理智。\n末期：個體軀體崩潰，生理上構成死亡，精神仍被侵蝕。當精神被侵蝕殆盡時，個體完全消失，徹底失去喚醒可能。\n\n<Title:特殊案例>\n軀體類特殊案例：被融蝕個體出現軀體、五感增強現象。還有個體受到贅生物、災厄等因素影響，具有飛行、精神影響、思維控制等特殊能力。\n精神類特殊案例：被融蝕個體精神受融蝕影響較小，保有基本理智。少數個體表現正常，與未融蝕個體無異。"
  },
  CollectionHall_49750_Title = {
    Text = "融蝕侵蝕"
  },
  CollectionHall_49751_Desc = {
    Text = "<Title:定義與特性>\n個體因為融蝕侵蝕而喪失軀體，化作融蝕漿及融蝕粉塵的現象。\n消解後的個體，其存在本身也將被從世上抹去。\n\n<Title:各時期特徵>\n初期：與被融蝕個體不相熟之人會遺忘其存在。\n中期：與被融蝕個體相熟之人對其記憶開始減弱，與其相關的書面記載開始出現融蝕痕，變得模糊。\n後期：與被融蝕個體相熟之人對其記憶進一步減退，只留下一個模糊的印象，直至完全遺忘該個體。\n\n<Title:存在性消除>\n當消解發展到最終時刻，被融蝕個體的存在，包括其存在痕跡，將被徹底抹除。\n沒有任何事物能證明他們曾存在於世，正如大多數人那樣。"
  },
  CollectionHall_49752_Desc = {
    Text = "銀芯或許是融蝕的終點：它是生命被融蝕侵蝕後，機率析出的類銀物質。 它不僅蘊含著巨大的物理能量，還能與精神維度產生一定聯繫。某些情況下，這種聯繫甚至可以對「精神維度」產生干擾。 銀芯是人類與融蝕對抗的關鍵之一。但因為形成方式的特殊性，銀芯不僅數量稀少，價值亦珍貴非常。"
  },
  CollectionHall_49752_Title = {Text = "銀芯"},
  CollectionHall_49753_Desc = {
    Text = "<Title:概述>\n所有對銀芯加以利用的技術，統稱銀芯科技。\n世上絕大多數人並不知道銀芯的存在，僅有彌薩格大學掌握著銀芯科技，並設有銀芯研究與應用專業，持續對銀芯進行研究與開發。\n依照《密斯底亞協定》，彌薩格大學會向密斯底亞協定審查會提供銀芯科技，以共同抵禦融蝕，應對危機。\n\n<Title:喚醒體？>\n在彌薩格大學的喚醒體技術中，喚醒體的塑造需要圍繞銀芯進行。\n雖然喚醒體塑造並未記錄在《銀芯技術指導手冊》中，但不少喚醒體會如此自嘲：\n「嘿，我們也是銀芯科技的一種吧？」\n\n<Title:融蝕觀察設備>\n有眼鏡、面具等多種款式。使用銀芯製造，能讓佩戴者觀測到密境、看見融蝕。\n\n<Title:彌薩格大學通訊器>\n最常見的款式為校徽形狀的胸針。其核心為特殊處理過的銀芯，通訊器不僅可以互相聯通，還能達成與彌薩格校內的超遠距離通訊。訊號穩定，<Italic:一般情況下>不受自然現象干擾。\n\n<Title:彌薩格准入憑證>\n內含銀芯的特殊憑證，只有持有憑證的人，才能避免迷失在彌薩格大學的迷霧屏障中。\n沒有憑證的人，只會在大學外的樹林中陷入無盡的知覺失調，等待輪值調查員的驅逐。"
  },
  CollectionHall_49753_Title = {
    Text = "銀芯科技"
  },
  CollectionHall_49754_Desc = {
    Text = "<Title:原理>\n或自銀芯中被喚醒，或受實驗改造，或誕生自一場意外……\n他們古老又嶄新。古老，是因為早在十幾個世紀前的紙草書上，巫師們就隱秘地記錄下了喚醒體在世間的行走。\n他們嶄新，是因為我們尚未完全理解喚醒體的本質，就要與他們踏上拯救世界的道路。\n除了給予他們信任外，謹記：不要毫無防備。\n\n<Title:特性>\n喚醒體具有完整的人格，且保有自己「生前」的記憶，卻因其具備的特殊能力，一度被視作人形兵器對待。\n為了維持世俗社會的穩定，喚醒體的存在在各國都是高度機密。\n目前，《協議》僅認可彌薩格大學喚醒的喚醒體，任何非彌薩格大學喚醒的喚醒體，被視作違反《協議》的存在，需要由官方進行記錄並收容。\n\n<Title:界域>\n喚醒體能力各異，但研究員們總能在不同能力間找到一定相似性。\n根據這些相似性，彌薩格大學人為劃分出了數個喚醒體界域。\n同一界域中的喚醒體能夠更好地配合彼此，不同界域之間可能存在一定的排斥，僅有混沌界域不存在此現象。\n界域之間互斥的原因不明，據彌薩格大學喚醒系教授朵爾分析，或與某些不可知存在對精神維度的影響有關，但目前尚無證據證明其猜想。"
  },
  CollectionHall_49754_Title = {
    Text = "喚醒體認知基礎"
  },
  CollectionHall_49755_Desc = {
    Text = "<Title:概述>\n以銀芯為唯一原料的鑰匙形道具。具有聚焦放大使用者精神、幫助聯通並影響精神維度的能力。\n銀鑰匙是彌薩格調查員與守密人的身分象徵，每一把銀鑰匙都有一個獨一無二的編號，普通調查員的銀鑰編號以I開頭，守密人的則以K開頭。\n若調查員因故無法繼續外勤行動，彌薩格校方將對其所持銀鑰進行回收，並在未來發放給其他調查員使用。\n但很可惜，回收記錄顯示，百年間僅收回了不足十把尚能正常運轉的銀鑰。絕大多數銀鑰，都隨著主人的逝去一同被破壞。\n\n<Title:製作與獲取>\n■■機密文件第■■■號\n銀■匙的塑造，需要在黑池中由■■■■■進行。\n■■■被塑造後，將進行編號篆刻，在鑰塚儀式上將其賦予給相應的使用者。"
  },
  CollectionHall_49755_Title = {Text = "銀鑰匙"},
  CollectionHall_49756_Desc = {
    Text = "<Title:概述>\n密境，一個由現實世界與精神維度共同構築出的特殊區域。\n彌薩格大學的菲力浦斯先生曾在筆記中寫道：世界上的一切異常，若非來自人心，便是誕生自密境。\n這裡交織著生與死、現實與幻夢，它排斥真相，它藏匿真相。\n\n<Title:定義與特性>\n密境是人類能夠肉身進入的最接近精神維度的空間，但人們對它仍知之甚少，正如人們對融蝕也一知半解一樣。\n但可以確定的是，融蝕與密境總是同時出現：融蝕現象越嚴重，密境維度覆蓋範圍則越大。\n\n<Title:密境中的事物>\n作為脆弱的交界地帶，密境極易受到影響。\n在密境中出現的特殊存在，如幻象、融痕、迷霧等，被認為是情感與思維的投射。借助這種特殊的投影機制，彌薩格得以在密境中投射了一部分聯絡點，以穩定調查員的精神，彌合喚醒體的傷口。\n不過現實中確實存在的事物，如地面、建築等，在密境中通常不受影響。（別擔心，密境中的道路<Italic:大部分時間>是安全的。）"
  },
  CollectionHall_49757_Desc = {
    Text = "<Title:創辦日期>\n洪積前\n\n<Title:創始人>\n不詳\n\n<Title:概述>\n泛勞拉西亞大陸最廣泛的信仰。\n信徒眾多，規模盛大。每年的特定時節各地都會舉行慶祝儀式，其中最廣泛的有銀霜夜與冬渡節。\n組織內的神職人員自稱「父神的代行者」，即代父神踐行其意志之人，以消除世界的苦難為己任。\n認為人死後可以回歸父神的懷抱，永棲無盡樂土，脫離世界上的苦難。\n擁有如此普世的教義，它理所當然地成為了一個受歡迎的宗教。"
  },
  CollectionHall_49757_LockTip = {
    Text = "通關特遣紀錄「血的顏色：悔過」解鎖"
  },
  CollectionHall_49758_Desc = {
    Text = "<Title:創辦日期>\n洪積前\n\n<Title:創始人>\n彌利亞姆\n\n<Title:概述>\n源自舊大陸的古老組織。\n成員多表現出上半身為魚、下半身為人的特徵，他們主要活躍在海洋及沿岸一帶，未曾深入過陸地。\n據說他們蹈海而去，隻為追尋王的足跡。他們蹈海而來，隻為帶來王的國度。\n所有的犧牲皆是為了那個失落的國度——利莫里亞，以及它困倦的王。"
  },
  CollectionHall_49758_LockTip = {
    Text = "通關調查行動第5章「風暴之眼」解鎖"
  },
  CollectionHall_49759_Desc = {
    Text = "<Title:創辦日期>\n洪積災變時期\n\n<Title:創始人>\n不詳\n\n<Title:概述>\n隱秘的宗教組織。\n將融蝕視作神的饋贈，將銀芯視作神的軀體，認為融蝕能夠淨化罪惡，將人度往無罪淨土。\n人數眾多但行蹤隱蔽，有融蝕的地方總能隱約窺見他們的身影。\n據說源自一個古老的顯赫家族，其家族成員集體消失的原因至今仍是史學家爭論的焦點。"
  },
  CollectionHall_49759_LockTip = {
    Text = "通關調查行動第4章「於無聲處」解鎖"
  },
  CollectionHall_49759_Title = {
    Text = "提燈教會"
  },
  CollectionHall_49760_Desc = {
    Text = "<Title:諾斯指數>\n一種量化精神碎片在銀芯中的穩定性的數值。\n諾斯指數高的喚醒體，精神碎片的穩定性就強，癲狂的程度較低，更不易發生失控現象，失控後可能造成的傷亡也會更少。\n不同喚醒體的諾斯指數不同，有的喚醒體由於個體情況特殊，會出現諾斯指數波動乃至無法準確測定的現象。\n\n<Title:喚醒體失控>\n作為核心，銀芯為喚醒體們帶來了世間不應存在的力量，卻也為他們埋下了瘋狂的種子。\n喚醒體被塑造時大多處於難以控制的瘋狂之中，若無調查員的及時連結，失控的他們將對世界造成難以想像的破壞。因此，連結不僅是「增幅器」，更是不可或缺的「穩定器」。\n根據彌薩格大學的檔案記錄，目前校內僅有朵爾·@2在成為喚醒體初期便保持了理智。\n另外，「門內之物」塔薇及初代守密人阿利斯泰爾共同維繫了L-01號融蝕裂隙下巨型銀芯的穩定，所以在彌薩格大學校內，喚醒體們得以保持長久的理智。即使斷開連結，也不會失控。\n\n<Title:喚醒體死亡>\n喚醒體在軀體機能上遠強於人類，但面對來自異變體、災厄、乃至融蝕裂隙及融蝕本身的威脅，仍會受到傷害，其軀體有被摧毀的可能。\n研究員相信，喚醒體軀體被摧毀後，其銀芯中的意識會回歸精神維度，等待被二次喚醒。\n銀芯的損毀，或許意味著真正的「死亡」。\n\n<Title:二次喚醒>\n二次喚醒後，喚醒體的外表、性格、喜好與能力一般不會改變，記憶也會得到保存。但有些喚醒體會認為那與現在的自己是兩個獨立個體，彌薩格大學對這些聲音持保留態度。"
  },
  CollectionHall_49760_Title = {
    Text = "喚醒體認知進階"
  },
  CollectionHall_49761_Desc = {
    Text = "<Title:概述>\n某些喚醒體在能力、外形異變性狀上表現出了高度的一致。研究員們由此推測，在喚醒過程中曾有某些未知存在影響（有些人認為是污染）了這些喚醒體的精神，並賦予了他們強大的力量。\n目前，研究員們將這些影響了喚醒體存在的力量稱為「本源」。\n\n<Title:本源喚醒體>\n本源喚醒體是同名喚醒體的「另一個自己」。\n他們有著相似的特質，但卻有著可能截然不同的人生經歷，性格、愛好、表現乃至力量上都帶有更多「本源」的特徵。\n關於本源喚醒體的記載十分有限，彌薩格對這類現象的成因也知之甚少。有研究員根據本源喚醒體的出現，推測並發展出了「平行世界」存在的理論，但該理論目前尚未得到公佈與進一步研究。"
  },
  CollectionHall_49762_Desc = {
    Text = "<Title:核心>\n喚醒體的核心是銀芯。即使軀體完全解體，只要銀芯尚存，便能對該喚醒體進行二次喚醒。\n\n<Title:軀體>\n喚醒體的軀體可能由各種材料構成，具體構成材料與結構與喚醒體自身的偏好及特徵相關。\n喚醒體的軀體不由彌薩格大學工作人員事先提供，而是在喚醒儀式上，由銀芯中的精神能量熔鍊而成。因而喚醒儀式上，除去必要的銀芯及銀鑰匙外，還需準備大量的材料，以供喚醒體進行軀體合成。常見材料詳見第3號附錄。\n另，彌薩格大學設有專業的部門及研究人員，負責維護喚醒體的軀體損傷。"
  },
  CollectionHall_49762_Title = {
    Text = "喚醒體構成"
  },
  CollectionHall_49763_Desc = {
    Text = "<Title:日常>\n喚醒體在彌薩格大學內享有與教職工同等的權益。他們擁有使用校內設施，獲取調查報酬的權利。\n在搭檔調查員沒有外勤任務時，喚醒體們可以在校園範圍內自由活動。多數喚醒體會遵循自己生前的愛好與習慣，找到自己想做的事；也有部分喚醒體會選擇走進課堂，了解這個時代，或者與調查員們交朋友。\n除了少部分特殊情況外，喚醒體原則上不需要進食和睡眠。但如果喚醒體願意做這些事，也不會造成任何影響。\n\n<Title:作戰>\n為了平衡作戰指揮與維持連結的精力消耗，彌薩格大學研發了一種名為「靈知轉印器」的特殊儀器。\n內置在外勤手提箱中的「靈知轉印器」，可以將喚醒體的能力轉印成卡片的形態，以此實現對喚醒體的指揮。"
  },
  CollectionHall_49763_Title = {
    Text = "喚醒體行為"
  },
  CollectionHall_49764_Desc = {
    Text = "<Title:創辦日期>\nA.F.306\n\n<Title:創始人>\n赫伯特·羅森塔爾\n\n<Title:概述>\n激進的民間科研組織。\n妄圖通過將人類與融蝕產物結合的方式實現進化，以求在災厄世界中生存。\n由20餘名激進人員組成，他們將無辜者視作實驗素材，手段極其殘忍。\n創辦者是彌薩格大學臭名昭著的叛徒赫伯特·羅森塔爾，與提燈教會存在密切合作關係。\n組織標誌是一把用於雕刻的平頭鑿刀，據說是為了向那位愛上雕像的塞浦路斯國王致敬。"
  },
  CollectionHall_49764_LockTip = {
    Text = "通關調查行動第3章「謹防惡犬」解鎖"
  },
  CollectionHall_49764_Title = {
    Text = "雕塑家協會"
  },
  CollectionHall_49765_Desc = {
    Text = "<Title:概述>\n由彌薩格大學通過特殊流程篩選培養的專業人員，擁有強大的精神力，可以承受連結喚醒體帶來的消耗，對其下達精神指令。\n他們直面融蝕，為人類的存續而戰，卻不為人知。死於融蝕的調查員，甚至連名字和檔案都無法完整留下。\n他們的名字無人知曉，但願他們的功績能夠與世長存。\n\n<Title:篩選>\n基於《調查員精神構成與其潛力》的理論基礎，彌薩格通過觀察個體與銀鑰匙之間的精神共鳴強度，篩選出擁有強大精神力的個體，進行培養。\n\n<Title:培養>\n通過篩選後，調查員要先進入預科班進行為期一年的培訓。\n培訓內容包括融蝕基礎理論、銀芯科技入門、喚醒體理論等基礎課程，以及基礎體能、喚醒體連結、喚醒體指揮等作戰相關訓練。\n\n<Title:鑰塚儀式>\n經過一年的學習並通過考核後，調查員將統一參加於校慶日舉辦的鑰塚儀式。\n儀式上，調查員們宣讀誓言，並將自己的姓名刻在墓碑上。\n隨後，每位調查員將被授予擁有獨一無二編號的銀鑰匙，其開頭字母統一為「I」。\n自此，他們將與過去作為普通人的自己道別。在他們死後，這個承載了他們名字的石碑，將成為他們存在過的證明。\n\n<Title:卸任>\n若調查員出於種種原因無法執行外勤任務，彌薩格會予以尊重，將其轉入後勤部、資訊支援部等更安全的部門工作。\n即便如此，那些卸任的調查員們也常常飽受身心的折磨。\n對這些瞥見過世界真實一角的人而言，安度餘生是一個奢侈的幻想。"
  },
  CollectionHall_49765_Title = {Text = "調查員"},
  CollectionHall_49766_Desc = {
    Text = "<Title:概述>\n調查員中的特殊個體，擁有比普通調查員更為強大的精神。\n擁有比調查員更高的權限，從而接觸到更深的隱秘。他們所接手的，也往往是最複雜、最艱難的任務。\n在這場與融蝕的漫長戰爭中，他們站在所有人類身前。\n\n<Title:篩選>\n通常是彌薩格在進行調查員篩查時選出的特殊個體。\n在發現對銀鑰匙反應格外強烈的個體時，篩選人員會根據《守密人精神構成及其潛力》中的描述和條目，輔以一定時間的觀察，最後評判該個體是否能被培養為守密人。\n\n<Title:培養>\n除開基礎的理論課程與作戰訓練，守密人還將進行額外的精神力訓練。\n他們會比其他調查員更早地接觸喚醒體、執行外勤任務，以磨練自身能力。\n\n<Title:鑰塚儀式>\n通過考核後，守密人會與普通調查員一同參加鑰塚儀式，獲取屬於自己的銀鑰匙。\n與調查員不同，守密人的銀鑰匙編號開頭為「K」。\n自此，銀鑰匙將成為守密人身分的標識，也將為後續的外勤任務帶來強大助力。\n\n<Title:守密人與喚醒體>\n守密人可以借助喚醒體的力量與融蝕對抗。因此，指揮喚醒體作戰的能力尤為重要。\n他們在預科階段就會接受嚴格的指揮作戰訓練，且在鑰塚儀式後，需與所搭檔的喚醒體進行一次有教師監督的外勤任務，以確保具備日後獨立執行外勤任務的能力。\n\n<Title:卸任>\n若守密人出於種種原因無法執行外勤任務，彌薩格會予以尊重，將其轉入後勤部、資訊支援部等更安全的部門工作。\n守密人可通過交還鑰匙、封存檔案、簽署保密協議的方式卸任，但迄今為止很少有人這麼做。"
  },
  CollectionHall_49767_Desc = {
    Text = "<Title:喚醒體連結>\n喚醒體在塑造過程中會受到未知污染，他們極易陷入瘋狂，故而需要調查員進行精神連結以穩定心神。而對絕大多數調查員來說，與喚醒體的連結需要借助銀鑰匙的力量。\n銀鑰匙可以增強持有者的精神，使其得以長時間連結喚醒體，指揮喚醒體進行作戰，併為持有者提供精神力輔助。此外，持有者亦可通過銀鑰匙給予喚醒體一定的幫助。\n理論上，持有者自身的精神強度越大，可以連結的喚醒體越多。但迄今為止，能夠承受與複數喚醒體連結帶來的精神負擔的人，僅有一位。\n\n<Title:喚醒儀式>\n使用銀鑰匙主持的喚醒儀式，是每位調查員的必修課。\n喚醒儀式中，銀鑰匙能夠放大使用者與目標銀芯的感知，幫助加強銀芯的塑造，使其最終成為具有特殊能力的喚醒體。\n\n<Title:精神追溯與定位>\n在與喚醒體失散時，持有者可以使用銀鑰匙，通過「精神追溯」大致定位符合喚醒體特徵的精神。\n但這並不意味著尋到的每個精神都是你的朋友，所以在進行「精神追溯」時，請一定保持冷靜。\n\n<Title:裂隙關閉>\n持有者可以使用銀鑰匙將融蝕裂隙關閉。詳見融蝕裂隙-應對方式。"
  },
  CollectionHall_49767_Title = {
    Text = "銀鑰匙應用"
  },
  CollectionHall_49768_Desc = {
    Text = "<Title:概述>\n每個守密人都擁有不盡相同的特殊能力。\n據彌薩格檔案記載，目前已知的守密人能力有記憶讀取、情緒共用、心理感知等。\n\n<Title:初代守密人>\n初代守密人即為阿利斯泰爾·歐文斯。\n對大多數人而言，他是僅存在於歷史夾縫中的一抹殘影，只有極少數人知道他至今依然堅守在彌薩格的地底。\n無法直立行走，據說是為了彌薩格而做出的「必要犧牲」。\n彌薩格最具性價比的工具——他的胃早已被完全切除，無需吃喝，節省了一大筆伙食費。\n\n<Title:新任守密人>\n新任守密人擁有的能力無疑最為獨特。\nTA能通過某一物件、情緒或回憶觸發感悟，刺激銀鑰匙迸發出新的力量——這幾乎顛覆了專業學者與史學家的認知。\n所有人都知道，這位守密人註定會掀起新一輪的風暴。\n問題是，這場風暴會將他們帶向何方？"
  },
