  CollectionHall_50265_Title = {Text = "蠟像館"},
  CollectionHall_50271_Title = {
    Text = "拉伊小鎮"
  },
  CollectionHall_51019_Desc = {
    Text = "<Title:創辦日期>\n洪積前\n\n<Title:創始人>\n不詳\n\n<Title:概述>\n自亞述帝國分化而來的遊牧民族。\n深藏於勒姆瓦希沙漠終年劇烈的風暴之中，生活極為原始，鮮少與外人通信往來。亞蘭人信仰「豐穰母樹」，依賴豐穰母樹和聖河之水的異常繁衍能力維繫種群規模。\n「勒姆瓦希行動」後，亞蘭族銷聲匿跡，再無音訊。"
  },
  CollectionHall_51019_LockTip = {
    Text = "通關調查行動第7章「欲河」解鎖"
  },
  CollectionHall_51019_Title = {Text = "亞蘭族"},
  CollectionHall_51373_Title = {
    Text = "莫測之物"
  },
  CollectionHall_51374_Desc = {
    Text = "<Title:簡介>\n彌薩格大學教授，社會活動家，貴族。\n曾是揮金如土的花花公子，犯下過一些無傷大雅的罪行，在黑白兩道都享有名聲。\n後來家族被邪教徒滅門，成為唯一的倖存者。那以後發生的事，只有本人能說清楚了。\n雖是拉蒙娜的養父，卻對拉蒙娜的來歷三緘其口。\n年輕時門門課程都不及格，卻搖身一變成為彌薩格的教授。\n為人風流不羈，卻從未與任何女性或者男性傳出緋聞。\n總之是個充滿矛盾的傢伙。"
  },
  CollectionHall_51374_LockTip = {
    Text = "通關序章解鎖"
  },
  CollectionHall_51375_Desc = {
    Text = "<Title:簡介>\n德克斯特的養女，主角最信賴的調查夥伴。\n從小混跡在學院各個學系的教室中，對融蝕現象、喚醒體等知識有著相當程度的了解。\n\n年紀尚小時，拉蒙娜也曾對「親生父母」有過嚮往，但在德克斯特及老師們的照料和關愛下，她早已把學院當做真正的家。\n\n冷靜、理性以及恰到好處的良善，使她身上沒有任何「怪異」之處——在彌薩格這群怪人的襯托下，她的「正常」反而脫穎而出。\n雖然總是冷著一張臉，但熟悉她的人都知道，這只是身為「天才」的乏累罷了。"
  },
  CollectionHall_51375_LockTip = {
    Text = "喚醒「拉蒙娜」後解鎖"
  },
