  },
  CollectionHall_56359_LockTip = {
    Text = "通關特遣紀錄「玫瑰的棲居：故鄉」解鎖"
  },
  CollectionHall_56359_Title = {
    Text = "獻給春天的花束"
  },
  CollectionHall_56369_Title = {
    Text = "詩中世界"
  },
  CollectionHall_57597_Desc = {
    Text = "<Title:簡介>\n倫蒂尼恩大區的現任主教，也是被前代主教意外喚醒的喚醒體。\n是創生父神的虔誠信徒，以生命踐行父神的教導，以仁愛寬容之心對待世間萬物，在民眾間享有很高的聲譽，甚至被一些信徒稱為“倫蒂尼恩的聖徒”。\n諷刺的是，正是這份對萬物的憐愛與悲憫奪去了他作為人時的生命。\n生前也曾試圖治癒融蝕，為此不惜向生命石板獻出自己的血肉，為教區內的“患者”緩解痛苦，延續生命。在他死後，石板不知所蹤——直到他作為喚醒體再次甦醒。\n蒙在布條與繃帶下的雙眼能夠看到靈魂的光輝，因而在他見到守密人後便確定：守密人正是父神預言中的蒼白使者，能挽救這個即將陷入黑暗的世界。"
  },
  CollectionHall_57597_LockTip = {
    Text = "通關特遣紀錄「血的顏色」解鎖"
  },
  CollectionHall_57597_Title = {
    Text = "薩爾瓦多"
  },
  CollectionHall_57598_Desc = {
    Text = "<Title:簡介>\n史前文明利莫里亞最年輕的幼王。\n自幼天賦異稟，每天昏睡二十小時以上，清醒時也總是顯得困倦不已。\n偶爾能感受諸神的喜惡，夢見各種時空的殘片，因而被崇拜、被敬畏、被尊為王。\n年幼的王並不在乎。他只是消極逃避著神的啟示與預言。\n\n最終預見到了利莫里亞毀滅的宿命，卻不知如何改變，只得保持緘默。\n直到災難降臨的那一天，人們都陷入了絕望。為了回應臣民的期望，他編造了一個虛假的預言。\n有關不朽的王，以及他重降於世的預言。\n最終，舊世界被洪水淹沒。滄海桑田，新的人類重新在陸地上繁衍生息，史前之事再也無人知曉。\n恐怕他也沒料到，自己無心的預言會被人不斷演繹。\n他終究是低估了信仰的力量。"
  },
  CollectionHall_57598_LockTip = {
    Text = "喚醒「圖魯」後解鎖"
  },
  CollectionHall_57598_Title = {Text = "圖魯"},
  CollectionHall_57599_Desc = {
    Text = "<Title:簡介>\n亞蘭族的異鄉使者，自稱循夢的啟示來到勒姆瓦希。\n率領亞蘭族的隊伍長久徘徊於風暴之壁外，尋求令亞蘭族聖樹——豐穰母樹復甦的可能性。\n實質隸屬於提燈教會。尚無人知曉她那永恆的悲憫微笑後潛藏的真實動機，或許當旅程繼續之時，能夠窺破一二。"
  },
  CollectionHall_57599_LockTip = {
    Text = "通關調查行動第7章「欲河」解鎖"
  },
  CollectionHall_57599_Title = {
    Text = "於麗埃特"
  },
  CollectionHall_57600_Desc = {
    Text = "<Title:簡介>\n生活在史前文明利莫里亞，一家都是虔誠敬神的精神修行者。\n自幼勤奮修行，長大後如願進入首都的神殿，成為一名祭司。\n她渴求神蹟，渴求靈幻的體驗，可它們卻從未降臨。\n\n圖魯即位為王的時候，她成為侍奉左右的大祭司。\n第一次見到新王的時候，她感到極度的恍惚和喜悅，她立刻明白這就是她渴求的、神在人間的化身。\n是的。她存在的意義就是侍奉這位幼王。\n\n直至洪水將大陸與利莫里亞的文明沉入海底，她也未曾動搖過這一信念。"
  },
  CollectionHall_57600_LockTip = {
    Text = "通關異夢視界「褻瀆」解鎖"
  },
  CollectionHall_57600_Title = {
    Text = "彌利亞姆"
  },
  CollectionHall_57601_Desc = {
    Text = "<Title:簡介>\n為了散播種子跨越次元之壁，又因為「愛」放棄了來自種族的繁衍本能。\n意外流落到這個宇宙的沙耶，被穿行在星際的汀克特從銀芯裡喚醒，迷茫地尋找著方向，滯留在一顆荒蕪的星球上，直到與彌薩格的守密人相遇。\n在探尋中，在深談中，兩個不相似的存在，對關於「愛」的定義，得出了一個相似的答案。\n記憶或許會模糊不清，但曾經與重要之人產生的聯繫，會再次為她引領前路。\n在這個瀰漫著遺忘的世界裡，她固守著自己以愛為名的疾病。"
  },
  CollectionHall_57601_LockTip = {
    Text = "喚醒「沙耶」後解鎖"
  },
  CollectionHall_57602_Desc = {
    Text = "<Title:簡介>\n在古老的傳說中，世界上存在兩隻巨獸，分別盤踞於水底深淵、伊甸之東。\n這兩隻巨獸只有時間迎來盡頭時才能相遇，他們將作為祭品獻給生命之母提亞馬特，以換取生命的輪回。\n\n蘿坦便是隱藏於傳說背後的「獸」。\n她是星球的自然產物，與傳說不同的是，她既是深淵之水，也是伊甸之魂。\n她是純粹的混沌力量，是不羈的自由靈魂，是未被定義的秩序。\n破壞與規則是世界賦予她的權能，兩種截然相反的本能在蘿坦體內碰撞，為了平衡足以撕碎她的力量，她需要用戰鬥來釋放破壞欲望。\n蘿坦被星球託付了守護歷史的職責。她的“工作”就是順應星球的意志，掃清、討伐影響星球命運之人，但這樣的人千萬年難出其一。\n在無盡的，等待使命降下的無趣中，蘿坦渴望著一名對手的出現。\n\n為此，她曾將目光投向那位年輕的幼王，甚至招來隕落的災殃。\n然而一切都無損她洶湧的戰鬥意志，它們只會因她的復甦愈發猛烈。"
  },
  CollectionHall_57602_LockTip = {
    Text = "喚醒「蘿坦」後解鎖"
  },
  CollectionHall_57602_Title = {Text = "蘿坦"},
  CollectionHall_57603_Desc = {
    Text = "<Title:簡介>\n葬骸城曾經的王儲，如今是被奉為神明的食屍鬼之王。\n他雖然是一名聰慧、公正的青年，但是因為獨特的進食「品味」——食屍，遭受王室的忌憚。\n父王在退位前夜將杜勒賽因毒殺。在被分解吞噬的過程中，他的意識與神殿供奉的祂融合，從而品嘗到了自己肉身的滋味，那驚人的甜蜜使他魂牽夢繞。\n他將進食視作浪漫的藝術，這不止是口舌之慾的滿足，更是為了被忘卻的紀念。\n融蝕會將一切摧毀，讓往事隨風消散，但是杜勒賽因會見證一切生者的傳奇與平凡，讓血與肉在自己的記憶中留存，直至永恆。"
  },
  CollectionHall_57603_LockTip = {
    Text = "喚醒「杜勒賽因」後解鎖"
  },
  CollectionHall_57603_Title = {
    Text = "杜勒賽因"
  },
  CollectionHall_57604_Desc = {
    Text = "<Title:簡介>\n曾是統領一方的莊園領主。\n據說母星被融蝕毀滅後，乘坐巨大的隕石墜入坎布裡安河谷。\n擅長家畜管理、土地兼併和風險投資管理。\n每次外出，身後必然跟著浩浩蕩蕩的不死者僕從。\n1個當踏腳凳，2個吟遊詩人逗樂，還有4個馬車伕……\n教皇見了都會為自己的簡陋排場感到羞愧。"
  },
  CollectionHall_57604_LockTip = {
    Text = "通關意識潛遊「燃燒的群宴」解鎖"
  },
  CollectionHall_57604_Title = {Text = "旺達"},
  CollectionHall_57605_Desc = {
    Text = "<Title:簡介>\n汀克特摯愛的孿生姐姐。\n在孵化之初便展現了不一樣的「天賦」，因為其不受控的能力，菲茵特只能在永遠蜷曲在「襁褓」中無法長大。\n被認為是將給族類帶來不幸的個體，因此與汀克特一起被逐出了原本的生活空間。\n\n妹妹依靠上流階層的施捨換來生活所需的養料，她將絕大多數物資都用來供養菲茵特。\n在某個災難發生後，賺來了唯一一張「機票」，將菲茵特哄騙上了離開荒蕪行星的行程。\n起飛之際，菲茵特作出了第一次，也是最後一次的反抗：\n她以離開襁褓，吸收所有人生命能量為代價，要脅汀克特離開……\n因為自己是「有缺陷的」，所以十分自卑。\n\n曾一度拒絕進食，希望自己早點餓死，以免成為汀克特的拖累。\n長此以往，養成了挑食的壞毛病。\n\n喜歡陰暗的角落。一般需要到地下室之類的地方才能找到菲茵特。"
  },
  CollectionHall_57605_LockTip = {
    Text = "喚醒「菲茵特」後解鎖"
  },
  CollectionHall_57606_Desc = {
    Text = "<Title:簡介>\n凱蒂古拉是一名出生在沙漠地區的孤兒，在她還是個少女的時候，就已經收留了許多當地同樣身世悲慘的孩童。\n為了帶領這些孩子們在世界上掙扎求生，她精心打造了一幅虛假的外殼，用來抵禦惡意的侵害。\n許多人眼中，她便是殘忍和瘋狂的化身。\n無論是哪場衝突，她都會用最瘋狂的熱情和最殘忍的手段，去回應那些敢於站在她槍口前的敵人。\n隨著時間過去，即使是當地牙牙學語的孩童，都知曉在無邊的沙海上，存在一名琥珀色的死神。\n在一場與N的交鋒中，她不出意料地輸掉了那場遊戲，也因此失去了所有。\n但就連N都不知道，她早已受到群星中某位的注視。\n在經歷命中註定的死亡後，她如約繼承了祂的力量，以及祂為自己定下的使命。\n她體內蘊含著群星之中的存在，她早可以成為祂們中的一員。\n若那最終時刻的到來註定無法阻止，祂便會拋下一切，重新歸於極天，成為那最初，也是最後的港灣。"
  },
  CollectionHall_57606_LockTip = {
    Text = "通關意識潛遊「不朽極晝」後解鎖"
  },
  CollectionHall_57606_Title = {
    Text = "凱蒂古拉"
  },
  CollectionHall_57607_Desc = {
    Text = "<Title:簡介>\n熔燬·朵爾原本是彌薩格乃至人類科學的驕傲，在與融蝕漫長的對抗中她意識到，融蝕現象在消解身體的同時，也鋪開了通向真理的道路。\n偶然接觸到一塊刻有奧秘箴言的遠古石板後，她決心走上這條暗黑無境之路，放棄了更換人偶身體延續生命，任由融蝕侵蝕腦缸。\n最終她得償所願，洞悉了融蝕的本質，卻也徹底走向毀滅與虛無。\n那明燈一般引領眾人的信念與理性消失後，熔燬·朵爾開始在學校師生看不見的地方大行毀滅之道，“協助”引起數起傷亡事件後才被彌薩格發現，被施行了等級最高的監視與壓制。\n只是在崩毀的人偶背後，天才不滅的靈魂似乎還在與世界背後更深遠、更黑暗的地方，遙遙呼應。"
  },
  CollectionHall_57607_LockTip = {
    Text = "喚醒「熔燬·朵爾」後解鎖"
  },
  CollectionHall_57607_Title = {
    Text = "熔燬·朵爾"
  },
  CollectionHall_57608_Desc = {
    Text = "<Title:簡介>\n出身卑微，因美貌頗受歡迎，勉強混跡於上流階層的歌女。\n\n在災劫發生時，憑藉一些憐憫和恩惠，賺來了唯一一張逃生的「機票」。\n\n所有人都默認這一名額應當屬於她自己，而她卻在暗中下定決心，打算將姐姐菲茵特護送上航線。\n\n然而，最後時刻姐姐以離開襁褓動用力量威逼，將其綁上了座位，送離荒星。\n\n\n被意外喚醒後，汀克特心中縈繞無盡愧悔，她相信姐姐沒有死去，或者以某種形態和自己一樣復甦。\n\n自那之後，她竭盡全力搜索姐姐的下落，不惜一切代價。"
  },
  CollectionHall_57608_LockTip = {
    Text = "喚醒「汀克特」後解鎖"
  },
  CollectionHall_57609_Desc = {
    Text = "<Title:簡介>\n被稱為「彌薩格之腦」的天才學者，彌薩格外勤顧問之一。\n14歲入學彌薩格，曾主持改進了阿利斯泰爾的維生裝置。\n在一次外出途中感染融蝕，寫下足足八十頁的喚醒步驟說明後，平靜離世。\n死後同伴依照說明，將她的銀芯投入喚醒儀器中，製作出「朵爾喚醒體」。\n被喚醒後，她平靜地起身穿衣，平靜地走進研究室，平靜地繼續生前遺留的研究。\n噯！天才的世界便是這樣枯燥且平淡。"
  },
  CollectionHall_57609_LockTip = {
    Text = "喚醒「朵爾」後解鎖"
  },
  CollectionHall_57609_Title = {Text = "朵爾"},
  CollectionHall_57610_Desc = {
    Text = "<Title:簡介>\n從被融蝕吞沒的星球逃亡而來的外星種族精神體，佔據了一個剛剛死去的少女的身體，避免了和父母一樣死去的命運。\n好景不長，在這具人類的軀體身上出現融蝕症狀後，她的精神體同樣被融蝕固定在了體內，無法再次逃逸。\n在融蝕侵染的恐懼下陷入精神崩潰，主動聯繫了彌薩格，要求將自己製成喚醒體，並答應用自己種族的知識技術作為回報。\n成為喚醒體後在學院進行機械、電學、精神相關研究，由於對融蝕的分外恐懼無法進行融蝕研究，甚至因為心理陰影害怕黑暗，不敢睡覺，每天活在敏感與神經質中。"
  },
  CollectionHall_57610_LockTip = {
    Text = "喚醒「溫柯爾」後解鎖"
  },
  CollectionHall_57610_Title = {Text = "溫柯爾"},
  CollectionHall_57611_Desc = {
    Text = "<Title:簡介>\n誕生於精神位面的精神體，原本孤獨漂浮於寬廣而空無一物的灰色海洋中，跟隨偶爾到來的精神旅者來到地球，體驗不同的願望，並把他們的頭顱斬下收集於海洋中，吸取他們的智慧、情感。\n早在一千六百多年前被喚醒，並附身喚醒者斬下了她的頭顱，由於吸食精神力的特質，依舊靠收集頭顱來維持存在，併為了消遣玩弄獵殺了遠超所需的頭顱。直到遇到了真正的店主後，被制服並達成交換，作為助手跟隨店主直到她生命結束。\n已經與店主建立了真正友誼的怪物明白了自己真正的渴求，斬下了店主的頭顱，並繼承了她的外貌和商店。從此不再隨意獵殺頭顱，改為交換商店的方式解決神秘學委託換取頭顱，並通過與顧客交流的方式緩解失去店主的孤獨。\n現在的願望是守護商店與店主喜愛的城市。"
  },
  CollectionHall_57611_LockTip = {
    Text = "通關特遣紀錄「雨鎮幽影」解鎖"
  },
  CollectionHall_57611_Title = {
    Text = "達芙黛爾"
  },
  CollectionHall_57612_Desc = {
    Text = "<Title:簡介>\n生前曾經是一名巡遊世界的魔術師。\n從小在馬戲團中長大，生活中充斥著許多「異類」，小偷，逃犯，棄兒，殘疾人，畸形兒……\n卡茜亞同樣是個「異類」：她無法感知情緒、也無法自發產生情緒。\n是不折不扣的表演天才，總能贏得觀眾的喝彩。\n即便後來遭遇@2，成為異端受害者的亡靈，她也照樣像生前那樣表演魔術，邀請觀眾進入「仙境般的神奇世界」。\n奇怪的是，每一個觀眾看完魔術秀以後，都覺得「缺了點什麼」，生活變得愈發了無生趣。\n他們困惑、麻木、甚至自殺。\n而我們的魔術師小姐呢？她躲在帷幕後，愉悅地吸食著自己收穫的甜美「報酬」。\n華麗的演出造價高昂，她只是為了可持續發展。"
  },
  CollectionHall_57612_LockTip = {
    Text = "喚醒「卡茜亞」後解鎖"
  },
  CollectionHall_57612_Title = {Text = "卡茜亞"},
  CollectionHall_57613_Desc = {
    Text = "<Title:簡介>\n偶然跨越世界線屏障的神秘個體，亦是拉蒙娜的另一種可能性。\n在「那起事件」中，為了守密人的安危，不得不放任喚醒體的力量掌控身體。\n\n事件結束後，@2在拉蒙娜身上留下的影響未曾消退。\n@2的意識留在了她的身體裡，逐日擠壓意識的存在空間。\n為此，她陷入無盡的掙扎與煎熬。\n\n因為不願讓人擔心，面上會裝成一切都好的樣子\n，將自己的頭髮與生活都打理得井井有條。\n偶爾意識會迷失，呈現出放空的狀態\n，甚至用另一種口吻說話。\n對此不必感到擔憂。即使來處不同，所行一切亦是為了守密人及這個世界的和平。"
  },
  CollectionHall_57613_LockTip = {
    Text = "通關意識潛遊「一步之遙」解鎖"
  },
  CollectionHall_57613_Title = {
    Text = "環行·拉蒙娜"
  },
  CollectionHall_57614_Desc = {
    Text = "<Title:簡介>\n她生於詩與玫瑰的國度，她是詩歌的精靈。\n精靈徜徉在文字編織的夢裡，為每一縷陽光的綻放欣喜，為每一支花的凋零落淚。\n她沉吟，她傷懷，她渴望另一個靈魂的陪伴。\n\n後來，在鮮花盛開的庭院裡，年輕的花匠將一支玫瑰放在了她的面前。\n於是她羞赧地笑了，輕輕接過這支花。\n「終於不是獨自一人了。」\n那時的她這樣堅信著。"
  },
  CollectionHall_57614_LockTip = {
    Text = "通關特遣紀錄「玫瑰的棲居」解鎖"
  },
  CollectionHall_57614_Title = {Text = "奧爾拉"},
  CollectionHall_57615_Desc = {
    Text = "<Title:簡介>\n自遠古之時而來，亞蘭族唯一的女王。\n年幼時被奉為樹的使者，為君王傳遞諭令。初次反抗後被視為祭品投入亞蘭族聖河之中，卻覺醒了樹的意志。\n她的血肉中融入了樹的乳汁，樹的根系中流淌著她的血脈。她即是豐穰母樹，豐穰母樹即是她。\n然而融蝕的力量污染了亞蘭族的血脈，她主動用自己的身軀代母樹承受污染，以求亞蘭族的一線生機。\n在亞蘭族已經湮滅在歷史的長河裡的今天，唯有拔地而起又轟然倒塌的豐穰母樹見證了與她有關的故事。"
  },
  CollectionHall_57615_LockTip = {
    Text = "喚醒「泰旖絲」後解鎖"
  },
  CollectionHall_57615_Title = {Text = "泰旖絲"},
  CollectionHall_57616_Title = {
    Text = "群星之間"
  },
  CollectionHall_57617_Desc = {
    Text = "<Title:簡介>\n彌薩格大學的心理老師，負責調查員們的心理疏導。\n溫柔和善，廣受校內師生喜愛，某些彌薩格成員卻對她十分畏懼。\n且不說那些成分不明的紅茶——沒人見過她不笑的模樣，單是這一點就足夠令人毛骨悚然了。"
  },
  CollectionHall_57617_LockTip = {
    Text = "通關序章解鎖"
  },
  CollectionHall_57617_Title = {
    Text = "茜爾維婭"
  },
  CollectionHall_57618_Title = {Text = "愚癡者"},
  CollectionHall_57619_Title = {Text = "混種"},
  CollectionHall_57620_LockTip = {
    Text = "喚醒「皮克曼」後解鎖"
  },
  CollectionHall_57620_Title = {Text = "異鄉人"},
  CollectionHall_57621_Desc = {
    Text = "<Title:簡介>\n彌薩格的資深調查員，被守密人尊稱為「學長」的存在。\n曾因某些無法言說的原因害怕外出，在校內學習的同時兼任情報組人員。\n好友死後，一改以往的作風轉投前線，以「做他曾經做過的事」的方式來紀念逝去的朋友。\n隨身攜帶一把破碎的銀鑰匙，艱難地維持著那些日漸消逝的記憶。"
  },
  CollectionHall_57621_LockTip = {
    Text = "通關序章解鎖"
  },
  CollectionHall_57622_Desc = {
    Text = "<Title:簡介>\n西岱的花匠，奧爾拉的童年摯友。\n在奧爾拉最無助的時候，柯蕾特用一座花園帶給了她最難忘的快樂時光。\n在奧爾拉的才華生根發芽的時候，柯蕾特用一場大火奪走了她的財富、名望、以及生命。\n她與赫伯特合作，用奧爾拉的詩集創造了詩中世界。或許是為了緬懷，或許是為了掌控。沒人知道。\n柯蕾特從來都宣稱，在那些美麗的詩句裡，她唯一讀懂的只有欲望。\n她為此痛苦。她以此為榮。"
  },
  CollectionHall_57622_LockTip = {
    Text = "通關特遣紀錄「玫瑰的棲居」解鎖"
  },
  CollectionHall_57623_Desc = {
    Text = "<Title:簡介>\n彌利亞姆曾遇見過兩位黛博拉：一位是利莫里亞的祭司，一位是奧恩家族的侍女。一位是她的摯友，另一位也是她的摯友。\n相距上萬年的兩個時代，兩個不同的人，同樣的名字，同樣的容貌，同樣的良善。這是一個罕見的巧合，對彌利亞姆來說，這也是一個神聖的預兆。\n彌利亞姆見證了兩位黛博拉的結局：一位隨著利莫里亞沉入海底，一位被她親手送上祭臺，剖腹而亡。\n在這場關於神國的宏大敘事裡，黛博拉的故事，只是兩道簡短鮮紅的注腳。"
  },
  CollectionHall_57623_LockTip = {
    Text = "通關異夢視界「褻瀆」解鎖"
  },
  CollectionHall_57624_Desc = {
    Text = "<Title:簡介>\n彌薩格大學第一資訊掮客，校推理協會成員。\n擁有無與倫比的資訊收集與挖掘能力，在整個倫蒂尼恩內都小有名氣。\n本是亞格羅共和國人，因家庭變故來到倫蒂尼恩，並通過手裡掌握的彌薩格秘密成功入學。\n千萬別被她爽朗的笑容迷惑——她對彌薩格的了解可遠比一般人以為的要深。"
  },
  CollectionHall_57624_LockTip = {
    Text = "通關調查行動第1章「東區秘事」解鎖"
  },
  CollectionHall_57624_Title = {Text = "漢娜"},
  CollectionHall_57625_Desc = {
    Text = "<Title:簡介>\n前格林基金會研究員，拉伊療養院院長。\n丈夫和女兒死後，一直在四處追尋能夠復活女兒的方法。\n漫長求索的過程中，她忘記了女兒的模樣，也忘記了曾支撐她苦苦向前的愛意與溫暖。\n她只記住了痛苦本身。"
  },
  CollectionHall_57625_LockTip = {
    Text = "通關調查行動第4章「於無聲處」解鎖"
  },
  CollectionHall_57626_Desc = {
    Text = "<Title:簡介>\n索納尼爾號的船長。\n家鄉因融蝕而消散在人們的記憶裡，唯獨他記得一切。因此人們叫他瘋子。\n海邊的小鎮、親人、手足……它們都是瘋子極力想要找回的過往。\n他與彌利亞姆達成協議，運送她所需的貨物，作為回報，她將助他喚醒一份沉睡已久的記憶。\n於是，他看到了那名被清風與白鳥簇擁著的少女。\n\n「我的名字是希萊斯特，只要你還需要我，我就會存在於此。」\n她是故土曾經存在的痕跡，是他幼時從老人口中聽來的童話。\n\n原來，那些魂牽夢繞的過去是真實存在的。"
  },
  CollectionHall_57626_LockTip = {
    Text = "通關調查行動第6章「倒錯的群星」解鎖"
  },
  CollectionHall_57626_Title = {Text = "埃爾頓"},
  CollectionHall_57627_Desc = {
    Text = "<Title:簡介>\n父神濟世大聖堂的事務員，負責輔助主教及其他神職人員維護聖堂的日常運轉。\n父親病故後，能幹的姐姐挑起家業，成為小有名氣的商人，一切似乎都是如此美好順利——直到那場精心策劃的騙局。\n一夜之間，母女三人一無所有。但這沒關係，倫蒂尼恩的主教向她伸出了援手，只要有家人相伴，她不怕任何困難。\n而後她的姐姐死了。\n她的母親悲痛萬分，鬱鬱而終。\n與此同時，那個佔據她祖宅的無恥之徒正在舉辦藝術沙龍，尋歡作樂。\n困惑、憤怒、不解……無數情緒擠在她的胸口，化作要將她碾成灰燼的仇恨。但她不應該這樣，主教說過的，囿於過去的永遠也無法向前，唯有寬恕才能解脫。\n她做不到。\n「不要強迫自己容忍，」那位自稱提燈女士的人在她耳邊循循善誘，「寬恕即是放縱。善人才應稱義，惡人——惡人都當受到應有的懲罰。」\n於是她從她手裡接過鏡子，開始了審判的儀式。"
  },
  CollectionHall_57627_LockTip = {
    Text = "通關特遣紀錄「血的顏色」解鎖"
  },
  CollectionHall_57627_Title = {Text = "索菲婭"},
  CollectionHall_57628_Desc = {
    Text = "<Title:簡介>\n來歷不明的奴隸，曾接替戈利亞成為部族首領。\n8歲便殺死主人，躲在木桶裡，一路飄來非利士人的小島。\n體內流淌著卑賤的血脈，羸弱、下流、野心勃勃。\n成為首領後不到一個月便被斬首，在位時間與其他首領的相比，位列第13。\n非利士人的首領可不是什麼能隨便幹到退休的職位。"
  },
  CollectionHall_57628_LockTip = {
    Text = "通關意識潛遊「巨人的隕落」解鎖"
  },
  CollectionHall_57628_Title = {Text = "以葛籣"},
  CollectionHall_57629_Desc = {
    Text = "<Title:簡介>\n\n\n她曾是永恆國度的中繼站，把握著王國與外部世界的出入口，負責將迷途的臣民指引回鄉。\n當王國陷入沉睡，不斷向海渦深處墜落時，法洛思與她的故鄉斷開了連結。\n她無法與王都取得聯繫，也無法在蒼茫海洋中尋得任何蹤跡。\n\n身為海上燈塔，卻無法照亮歸鄉之路，這是何等諷刺。\n\n在漫長而孤獨的時間中逐漸發狂失能，造成了歷史上多起海洋災害，直到力竭後被某個古代英雄討伐。\n\n後日的研究中，甚至有學者認為正是法洛思的發狂導致了大洋洲的沉沒。\n一切都只是猜測。直到現在，這位狂熱信徒的過去仍是一個謎。"
  },
  CollectionHall_57629_LockTip = {
    Text = "喚醒「法洛思」後解鎖"
  },
  CollectionHall_57630_Desc = {
    Text = "<Title:簡介>\n是某個公國小貴族家的兒子，雖然出身貴胄，父親卻毫無建樹，未來人生肉眼可見的平淡。\n直到一次聖誕晚宴時被父親帶去拜見大公，因晚宴時對生病的同齡公主的愛護照顧令大公另眼相看，在大公的玩笑話中成為了公國騎士預備役，開始正式參加騎士團的訓練。\n直到戰火來襲，公國羸弱的軍隊無法阻擋鐵騎的入侵，在一片死傷中，奧吉爾是最後一位守護公主的“騎士”。\n他握著尚且過於高大的長槍，永遠擋在了公主的門前。"
  },
  CollectionHall_57630_LockTip = {
    Text = "通關意識潛遊「騎士的願望」解鎖"
  },
  CollectionHall_57630_Title = {Text = "奧吉爾"},
  CollectionHall_57631_Desc = {
    Text = "<Title:簡介>\n在烈焰中起舞的天才舞者。\n數百年來，她的家族都作為宮廷舞者存在著。是以即便王國更迭，學校不再，她也從未失去高雅唯美的舞蹈靈魂。\n十八歲那年，她加入了當地的芭蕾舞團，很快成為當之無愧的首席。\n\n然而首演成功後，舞團經理竟以「介紹」的名義，將莉茲送進富商的房間。\n原來，芭蕾早已變得不再純粹，高雅底蘊成為了女孩們抬高身價的資本。\n於是她出走、被抓回、然後繼續出走……終於，她的「清高」觸怒了那些位高權重的大人物。\n他們從身心上折磨莉茲，她必須不停地旋轉，不停地跳，就算足尖崩裂，黑色污血滴落滿地也不能停。\n\n終於，在一個尋常的演出裡，當舞蹈進行到最高潮時，烈火從她足底蔓延升起。\n她將燒毀一切不公與罪惡。"
  },
  CollectionHall_57631_LockTip = {
    Text = "喚醒「莉茲」後解鎖"
  },
  CollectionHall_57631_Title = {Text = "莉茲"},
  CollectionHall_57632_Desc = {
    Text = "<Title:簡介>\n被奴役，被收養，被拋棄……故事到這裡和另一個世界線的希洛沒有什麼區別，但一樣的血，終於澆灌出了不一樣的殘枝。\n直到落入牢獄後，真正的地獄才開始。她驚恐地發現，原本應該一起仇恨奴隸主的族人們同樣在仇恨著她，甚至那份惡意還要更甚。\n每天每天，她落入了無盡的折磨與痛苦，命運的禮物連本帶息地摧垮了她的精神。\n她本應針對奴隸主的仇恨變成了對所有人的仇恨，同樣她也被所有人憎恨著，失去了自己存在的位置。\n直到利用融蝕逃出監獄的時候，她的心中已經只剩下瘋狂，她握著忽然得到的力量，迫不及待地釋放自己無盡的憤恨。\n那一夜，整座城池下起紅色的血雨，她站在紅色的河流中，仰頭暢快地大笑。"
  },
  CollectionHall_57632_LockTip = {
    Text = "喚醒「血鏈·希洛」後解鎖"
  },
  CollectionHall_57632_Title = {
    Text = "血鏈·希洛"
  },
  CollectionHall_57633_Desc = {
    Text = "<Title:簡介>\n雕塑家協會創始人、會長。\n幼年罹患脊髓炎，只能在家自學，從那時起便意識到了人類身體的局限性。\n長大後進入彌薩格學習，在導師的幫助下找到了研究方向，順便治癒了自己的疾病。\n總是面帶和煦的微笑，事實上對人類情感漠不關心。\n疏於形象管理，頭髮和辦公桌一樣亂。\n書桌抽屜裡存放著一個文件夾，裡面整齊地收藏了克勞利歷年發表過的論文——這是赫伯特做過最有條理的一件事。"
  },
  CollectionHall_57633_LockTip = {
    Text = "通關調查行動第1章「東區秘事」解鎖"
  },
  CollectionHall_57634_Desc = {
    Text = "<Title:簡介>\n非利士人心目中，有史以來最勇猛的首領。\n身材高大、魁梧有力，上位短短几年間，就帶領著非利士人橫掃周遭各大部落，至今未嘗敗績。\n在讚美與鮮花之中，他威名遠揚，竟不顧族人的勸阻，犯下輕敵大罪。\n微小的失誤導致非利士人潰不成軍。於是他甘願受罰，帶著唯一的追隨者流亡海上。\n憤懣、不甘……這恥辱的時刻必將被銘記，他寧願將脆弱的脖頸獻予「女巫」，只求奪回屬於自己的一切。\n他已然踏上血腥的復仇之路。"
  },
  CollectionHall_57634_LockTip = {
    Text = "通關意識潛遊「巨人的隕落」解鎖"
  },
  CollectionHall_57634_Title = {Text = "戈利亞"},
  CollectionHall_57635_Desc = {
    Text = "<Title:簡介>\n原本是下賤的奴隸，從小的聰穎與美貌彷彿註定了她悲慘的命運。\n然而突如其來的幸運讓她代替掌政官夫婦死去的女兒成為了他們乖巧的養女，再也沒有人對她投以看奴隸的眼神。\n她太小就離開了家，多年的相處讓她把那位溫柔的夫人當作了真正的母親，直到她偶然對曾經的族人伸出援手，極度厭惡奴隸結盟的掌政官夫婦立刻拋棄了她。\n命運殘忍地露出了不曾改變的真容，她一夕成為了階下囚，在囚籠中發酵著仇恨，度過了整個青春期。\n當融蝕在監獄中爆發後，她發現這黑色的液體能夠腐蝕鐐銬，於是復仇女神終於離開了監牢，再次出現時，她用掌政官的頭顱換來了提洛人的全面解放。\n她的餘生都在追殺那些曾經的奴隸主中度過，直到化作一座無名的、刻著讚歌的墳塋。"
  },
  CollectionHall_57635_LockTip = {
    Text = "喚醒「希洛」後解鎖"
  },
  CollectionHall_57637_Desc = {
    Text = "<Title:簡介>\n不同於那個時代多以醫護身分出現在戰場上的女性，她生前是一名驍勇的戰士，並以此為傲。\n她堅信祖國是聖潔的，祖國對其他土地的征服將為世界帶來更好的未來。\n一場激烈的戰鬥中，她為了救回一名新兵身受重傷，事後雖然勉強活了下來，卻留下了不良於行的後遺症。為了繼續報效祖國，她沒有離開軍隊，而是退出了前鋒部隊，轉職新兵教練。\n\n隨著時間推移，那些傲慢的新兵不滿自己的教官是個“殘廢”，軍隊中逐漸有了關於她的竊竊私語。\n當她意識到這點後試圖向那名自己救下的新兵提出意見——他現在已經是一名少校了。然而那名士兵竟然也同其他人一般，譏諷著她的傷腿。\n被如此羞辱讓她怒不可遏地離開了軍隊。\n在軍隊和戰場外，她終於看到了世界的全貌：“戰爭英雄”被同胞所背離，自己曾自豪的“解放”只給當地居民帶來了殖民與苦難。\n她的內心天翻地覆，在這之後，她全身心地投入進了真正的解放中，強烈的正義感和愧疚指引著她去做真正“正確”的事。\n可惜的是，傷腿的潰爛始終未曾治癒，她甚至在贖罪完成前就痛苦死去。\n再度被喚醒後感懷泰旖絲的恩情，始終盡力幫助亞蘭部落延續下去。"
  },
  CollectionHall_57637_LockTip = {
    Text = "喚醒「艾爾瓦」後解鎖"
  },
  CollectionHall_57637_Title = {Text = "艾爾瓦"},
  CollectionHall_57638_Desc = {
    Text = "<Title:簡介>\n曾是古羅馬魔像、明星角鬥士、最後的唯一戰士。\n為了貫徹皇帝卡裡古拉的瘋癲意志而生，為其除掉了全部的政敵：叔父、哥哥、妹妹……\n少年皇帝跪倒在親人的屍山面前，高舉雙臂，又哭又笑。\n尤烏哈希感到困惑：魔像會哭，會笑，卻無法做到大笑的同時淚如雨下。\n後來，暴虐的皇帝被處死。臨刑前，他抱住尤烏哈希。\n但他什麼都沒說。\n失去主人的兵器從此不斷流浪，直到遇到下一個主人。\n他依舊對人類感到困惑。"
  },
  CollectionHall_57638_LockTip = {
    Text = "通關意識潛遊「血與沙」解鎖"
  },
  CollectionHall_57638_Title = {
    Text = "尤烏哈希"
  },
  CollectionHall_57639_Desc = {
    Text = "<Title:簡介>\n被譽為「倫蒂尼恩最耀眼的明珠」，一言一行皆受萬眾矚目。\n曾與最邪惡的神祇簽訂契約，又以自己的「死亡」重獲新生。\n關於她的身分，人們眾說紛紜。\n名媛、情婦、商人、政客，引領時尚的女王……\n她真實的面目早已模糊。\n亦或者，這般變幻不定，才是她的本來面貌？"
  },
  CollectionHall_57639_LockTip = {
    Text = "通關特遣紀錄「薔薇禮讚」解鎖"
  },
  CollectionHall_57639_Title = {Text = "索蕾爾"},
  CollectionHall_57640_Desc = {
    Text = "<Title:簡介>\n曾是古羅馬貴族小姐，父親經營一家角鬥士訓練營。\n仗著身邊環繞的強大角鬥士奴隸，在卡普亞橫行肆虐、不可一世。\n諷刺的是，最後不得不央求最討厭的奴隸殺死自己。\n更諷刺的是，成為喚醒體後，不幸又與那位「奴隸」在校園相遇。\n可想而知，迎接他們的自然不會是什麼溫情脈脈的場面。"
  },
  CollectionHall_57640_LockTip = {
    Text = "通關意識潛遊「蒼白後裔」解鎖"
  },
  CollectionHall_57641_Desc = {
    Text = "<Title:簡介>\n在水手們的愚昧傳統下被塑造的航船聖女，實際只是被貧困的家庭賣出的女兒，為庇佑航行日復一日被綁縛在桅杆上。\n毫無自由與選擇的人生讓她變得無悲無喜，幾乎沒有自我，只剩下航船是她最熟悉的歸宿。\n無力的人生卻被寄托著美好的祈願，因被禁止與船員交談而習慣了發呆，只有最強烈的願望與桅杆旁翱翔的海鳥能吸引她的目光。\n最後因庇佑的航船遭遇融蝕死傷慘重，被傾瀉怒火的人們處以了溺死之刑。"
  },
  CollectionHall_57641_LockTip = {
    Text = "喚醒「希萊斯特」後解鎖"
  },
  CollectionHall_57641_Title = {
    Text = "希萊斯特"
  },
  CollectionHall_57642_Desc = {
    Text = "<Title:簡介>\n來自西岱的雕砌者。\n據說出身名門，為了追求藝術與家族決裂，獨自前往西岱，師從著名的雕塑大師奧古斯特。\n擁有令人絕望的天資，卻從未在藝術史中留下隻言片語。\n成為喚醒體後，對雕塑和雕刻有了新的理解，成為了大家熟知的那一類「瘋狂藝術家」。\n將守密人當作新的靈感源泉，看向守密人的眼神總是透著一絲詭異的溫柔。\n噢，那是不摻一絲雜質的、打量心愛素材的眼神。"
  },
  CollectionHall_57642_LockTip = {
    Text = "通關意識潛遊「如歌的雕琢」解鎖"
  },
  CollectionHall_57643_Desc = {
    Text = "<Title:簡介>\n曾是古老的阿契美尼德王朝侍女。\n因沒能選中在百年宴會上服侍賓客，在湖中溺死了同伴並頂替了她。\n最後在宴會中被變成了醜陋的綠色怪物。\n擁有靈活的頭腦和身段，能同時端起十個盤子穿梭在人群中。\n對美食的定義與當代飲食文化嚴重脫節。\n偶爾也會懷疑自己是因為殺人而受到處罰，變成怪物。\n但絕不會汲取教訓，很快便會裝作無事發生。\n畢竟，埃裡溫人能從歷史中吸取的唯一教訓就是：\n埃裡溫人從來不會吸取教訓。"
  },
  CollectionHall_57643_LockTip = {
    Text = "喚醒「珈倫」後解鎖"
  },
  CollectionHall_57643_Title = {Text = "珈倫"},
  CollectionHall_57644_Desc = {
    Text = "<Title:簡介>\n位於@2的監獄獄警，以折磨犯人為樂。\n上級曾向她許諾，三年後會將她調回倫蒂尼恩，然而融蝕現象的惡化和地脈變遷，她被遺忘在這塊遙遠土地。\n少女並未氣餒。她堅守廢墟，等待著被召回的那一天。\n直到最後一名犯人離世，她成為島上唯一的活物。\n沒有犯人的獄警，和犯人又有什麼分別呢？\n少女拒絕思考。她依舊等待被召回的那一天。"
  },
  CollectionHall_57644_LockTip = {
    Text = "喚醒「潘狄婭」後解鎖"
  },
  CollectionHall_57644_Title = {Text = "潘狄婭"},
  CollectionHall_57645_Title = {
    Text = "超越萬古"
  },
  CollectionHall_57646_Desc = {
    Text = "<Title:簡介>\n弗朗西斯飼喂的「寵物」。\n本是名為「麗莎」的活潑少女，經雕塑家協會的改造轉變為人獸縫合的扭曲形態，後被莉莉收養，暫時生活在瘋人院內。\n儘管喪失了人類的外貌和發聲能力，庫姆仍保留著麗莎的部分心智，能夠通過簡單的肢體動作傳達自己的意圖。\n她做出了自己的選擇。"
  },
  CollectionHall_57646_LockTip = {
    Text = "通關調查行動第4章「於無聲處」解鎖"
  },
  CollectionHall_57646_Title = {Text = "庫姆"},
  CollectionHall_57647_Desc = {
    Text = "<Title:簡介>\n來歷不明的藥劑師，目前是雕塑家協會的科學顧問。\n據說母親是個鄉下農婦，她被選中懷上了偉大蛇神的子嗣。\n繼承了母親的白化病以及和善的性情，是赫伯特唯一信任的朋友。\n熱衷解剖學、芳香烴和顛茄燃燒的香氣。\n著作等身，代表作是被譽為毒理學聖經的《藥物志》。\n長期浸泡在各種毒物中，就連呼出的氣體也含有劇毒。離他遠點——這是筆者唯一的忠告。"
  },
  CollectionHall_57647_LockTip = {
    Text = "通關調查行動第2章「以蠟像之名」解鎖"
  },
  CollectionHall_57647_Title = {
    Text = "阿爾比諾"
  },
  CollectionHall_57648_Desc = {
    Text = "<Title:簡介>\n華德·菲力浦斯的學生，彌薩格第一位守密人。\n常年身居地下的秘密區域內，僅有極少數人知道其存在。\n精神力卓絕超群，多年來一直憑藉特殊秘法維繫生命，以此保證彌薩格的安全。\n預感到守密人在未來的變局中非常關鍵，破例讓守密人能夠隨時與自己接觸。\n既是培養，也是觀察。"
  },
  CollectionHall_57648_LockTip = {
    Text = "通關調查行動第2章「以蠟像之名」解鎖"
  },
  CollectionHall_57648_Title = {
    Text = "阿利斯泰爾"
  },
  CollectionHall_57649_Desc = {
    Text = "<Title:簡介>\n身懷稀薄蹈海者血脈的人類，出身於古老的奧恩家族。該家族曾遭遇變故，部分人會在成人後逐漸變成相貌醜陋的怪物，最終痛苦而死，父親也因受不了病變在他出生後自殺。\n從小在母親的厭惡與同齡人的欺辱下長大，性格變得陰暗孤僻。\n十六歲時因看到叔叔遺留手稿中隱晦提到的家族高貴血脈，從此獲得了精神的勝利，整日幻想自己有一天會獲得超然的力量，將周圍人的欺凌當作天選之子必經的磨難，期待著他們之後對自己搖尾乞憐的樣子。\n在成年時躲進山洞中迎接蛻變，卻停滯在了半人半魚的樣子，被母親尖叫驅趕無法回家。\n最終他跳入海中妄圖尋找族群，卻因未發育完全的腮部淹死。"
  },
  CollectionHall_57649_LockTip = {
    Text = "喚醒「凱刻斯」後解鎖"
  },
  CollectionHall_57649_Title = {Text = "凱刻斯"},
  CollectionHall_57650_Desc = {
    Text = "<Title:簡介>\n來自王國最古老的卡文迪許家族，曾是父母的掌上明珠，卻不幸感染融蝕。\n被鎖在地底三年，對鮮血的渴望日益加深。\n哥哥於是命人四處搜羅東區落單的流浪漢、站街女，以此作為妹妹每日的「食物」。\n一時城內人心惶惶，警局傾巢出動，終於將兄妹二人抓捕歸案。\n自此，震驚倫蒂尼恩城的「吸血鬼事件」終於告一段落。"
  },
  CollectionHall_57650_LockTip = {
    Text = "喚醒「雷婭」後解鎖"
  },
  CollectionHall_57650_Title = {Text = "雷婭"},
  CollectionHall_57651_Desc = {
    Text = "<Title:簡介>\n來自倫蒂尼恩東區的紡織女工。\n因感染融蝕，被雕塑家協會擄走並製成蠟像。\n「24」既是實驗編號，也是她首次被確診的人格數量。\n就在筆者記錄的當下，其人格數量還在不斷上漲。\n假以時日，由「24」們組成的王國必將人丁興旺，蔚為壯觀。"
  },
  CollectionHall_57651_LockTip = {
    Text = "通關特遣紀錄「寧靜的裂殖」解鎖"
  },
  CollectionHall_57652_Desc = {
    Text = "<Title:簡介>\n生前和父親感染融蝕，在一家人的痛苦中一直乖巧地忍受治療。\n母親因同時失去丈夫和女兒性情大變，在艾爾沃斯的勘探中誤入提燈教會的儀式，偶然喚醒了莉莉。因異常喚醒，莉莉變成了木然的人偶，只有聽到命令時才有動作。\n母親因融蝕而遺忘了莉莉的形貌，將被喚醒的莉莉視為怪物不停進行實驗，以期真正的女兒復活。\n最後跟隨守密人前往彌薩格，將守密人稱呼為母親，非常依賴守密人。"
  },
  CollectionHall_57652_LockTip = {
    Text = "通關特遣紀錄「故事的魔法」解鎖"
  },
  CollectionHall_57653_Desc = {
    Text = "<Title:簡介>\n羅傑斯的蠟像玩偶。\n\n和那些在車廂裡大聲喧嘩的孩子一樣，是個被寵壞的傢伙。\n所仰仗的，不過是那雙灰綠色的眼睛——它們是「蠟像先生」留給羅傑斯唯一的東西。\n曾在「24」的人工秘境裡遭遇不可違抗的力量，變成扁扁的喬治，成功激起了羅傑斯的怒氣。"
  },
  CollectionHall_57653_LockTip = {
    Text = "通關調查行動第2章「以蠟像之名」解鎖"
  },
  CollectionHall_57653_Title = {Text = "喬治"},
  CollectionHall_57654_Desc = {
    Text = "<Title:簡介>\n莉莉安濟貧院的孤兒，也是詹金最要好的夥伴。\n曾被雕塑家協會改造，又親眼目睹其他孤兒慘死，為自己的倖存與緘默感到罪惡不已。\n最後從鐘樓一躍跳下，獲得了徹底的解脫。\n懷裡總是抱著一隻玩偶熊，她給它取名為「波比」。\n喜歡禮物、小裙子和金色的糖果。\n有點怕黑，總是抱著「波比」才敢入睡。如果你能為她唱一首搖籃曲，女孩將永遠感激你、喜愛你。\n就像詹金曾經為她做過的那樣。"
  },
  CollectionHall_57654_LockTip = {
    Text = "喚醒「艾繼絲」後解鎖"
  },
  CollectionHall_57654_Title = {Text = "艾繼絲"},
  CollectionHall_57716_Desc = {
    Text = "<Title:簡介>\n原本是痴迷於製作自動人偶的研究員，從達芙黛爾處得到了以銀芯為核心的能源組件。\n因研究員好友對能源組件的覬覦，兩人屢次爭吵，最終在決裂般憤怒的搶奪中導致了實驗室爆炸。不知為何在人偶的軀體中甦醒的她驚恐地意識到：在應當無生命的自動人偶中，除了她，還有另一個意識。\n她是懷著怎樣的信念將好友從燃燒的廢墟中救出，又是懷著怎樣的信念走到郊外的，已經無人知曉。這位不為人知的機械天才就此從世上消失，只剩下一則關於爆炸的新聞，一地散落的零件，和一枚殘存的銀芯。\n從中喚醒的，又是怎樣的存在？"
  },
  CollectionHall_57716_LockTip = {
    Text = "通關意識潛遊「扭曲核心」解鎖"
  },
  CollectionHall_57717_Desc = {
    Text = "<Title:簡介>\n@2的使者兼代行者，常常化作人形行走世間。\n一個純粹的惡魔——沒有未來、沒有信念，沒有理想。\n以欲望為餌，混亂為食，熱衷欺騙、誘惑人類。\n擅長玩弄規則，與之簽訂契約的人類最後都賠得一乾二淨。\n最精明的律師都無法從祂身上討到半分好處。\n偶爾會扮作孩童的模樣，然而這並不會使人對祂放鬆警惕。\n畢竟祂的可怕之處遠不在於皮相。"
  },
  CollectionHall_57717_LockTip = {
    Text = "通關特遣紀錄「薔薇禮讚」解鎖"
  },
  CollectionHall_57718_Desc = {
    Text = "<Title:簡介>\n精神病醫師，專攻癲癇、癔症以及焦慮失眠等疾病。\n擅長用催眠的方式引導患者吐露心聲。\n相傳她的患者都以各種頗具「藝術性」的自殺告終，但她總能在員警上門前變換身分，重新開張。\n許多名流都曾慕名前往她的診所，被形容為「掌握了半個倫蒂尼恩城秘密的女人」。\n羅傑斯曾是她的長期客戶——或許，他那反常的藝術激情也和這位醫師脫不了干係？"
  },
  CollectionHall_57718_LockTip = {
    Text = "通關調查行動第1章「東區秘事」解鎖"
  },
  CollectionHall_57718_Title = {
    Text = "克萊門汀"
  },
  CollectionHall_57719_Desc = {
    Text = "<Title:簡介>\n追求卓越的蠟像師，羅傑斯蠟像館現任館長。\n幼年因口吃遭到排擠，曾被調侃「窮得只剩下錢了」。\n身居高位的父親，精神錯亂的母親，再加上那起震驚全國的綁架案……\n在種種悲慘因素的作用下，羅傑斯不負眾望地超越了他的母親，成為斯卡伯勒首屈一指的瘋子。\n雕塑家協會最受女士歡迎的成員，一位情緒極其穩定的紳士——只要不談及藝術。"
  },
  CollectionHall_57719_LockTip = {
    Text = "通關調查行動第2章「以蠟像之名」解鎖"
  },
  CollectionHall_57719_Title = {Text = "羅傑斯"},
  CollectionHall_57720_Desc = {
    Text = "<Title:簡介>\n母親是傑出的機修工，因技高價廉而備受歡迎。\n八歲時父親出海再也沒有回來，從此和母親經營機修店鋪相依為命，兩人用攢下來的零件嘗試製作獨輪摩托，期待以後一起騎車冒險，完成母親年輕時的夢想。\n十三歲時母親因病去世，為了獲得更多零件完成摩托而接下了報酬高昂的隨船任務。\n船隻返航時因風暴意外捲入大漩渦的渦流中，將船上唯一的潛水服讓給好友後，握著母親留下的鸚鵡螺掛墜死在了充滿融蝕的水流中，只剩殘骸和銀芯在洋流中飄蕩旅行。"
  },
  CollectionHall_57720_LockTip = {
    Text = "喚醒「諾締拉」後解鎖"
  },
  CollectionHall_57720_Title = {Text = "諾締拉"},
  CollectionHall_58148_Desc = {
    Text = "<Title:簡介>\n蹈海主祭豢養的小公主，亦被喚作「聖女」。\n自幼被嬌養長大，是名副其實的淑女。手中的小陽傘既能保護白嫩的肌膚，也將一切不淨不祥之物隔絕在外。\n即使她深知，自己也是某種「不祥」的產物——她的誕生並非自然規律，而是為了成為「母親」，誕下預言之子。\n吃不完的糕點、最時新的洋裝、無數圍著她轉的僕從……她穿梭在紛繁的物質世界裡，將內心的惶惑不安緊緊封鎖。\n這一嘗試最終以失敗告終，因為自由的心不接受任何妥協。"
  },
  CollectionHall_58148_LockTip = {
    Text = "喚醒「墨菲」後解鎖"
  },
  CollectionHall_59454_Desc = {
    Text = "<Title:簡介>\n來自某沿海漁村的小女孩，父母是遠洋船員，與祖母相依為命，並天真地相信了祖母編造的童話故事——他們一家是亞特蘭蒂斯的後裔，只要她乖乖長大，交到很多朋友，朋友們就會幫助她回到海底的故鄉。\n祖母去世後，一家水族館老闆來收魚時雇傭了開朗活潑的她作為講解員，令她幸運地度過了多彩的童年。\n在融蝕的魚類污染了整個水族館後，水族館宣佈破產，失業的她將最喜愛的水母裝進瓶子帶回了偏僻的村莊，但很快融蝕也侵蝕了她，侵蝕了整個村莊……\n被喚醒後記憶有些混亂，堅信自己是所謂的“海底人”，並孜孜不倦地邀請朋友們去她的故鄉參觀。"
  },
  CollectionHall_59454_LockTip = {
    Text = "通關意識潛遊「諸事如常」解鎖"
  },
  CollectionHall_59454_Title = {Text = "奧瑞塔"},
  CollectionHall_59455_Desc = {
    Text = "<Title:簡介>\n被譽為擁有「絕對好運」的男子。\n擁有這樣的天賦，成為一名賭徒當然是順理成章的事。\n可他同時又是一位還算優秀的偵探。\n不僅如此，他還是個窮光蛋，因為他總是能以最快的速度揮霍掉贏回的本金。\n矛盾、複雜。這便是我們對這位男子的全部評價。\n命運女神偏愛他，那位來歷不明的「N」偏愛他，就連最摳門的酒館老闆也願意給他一些折扣。\n所有人都偏愛他，他卻從未因此停下步伐，而是開啟新一輪的冒險遊戲。\n他只偏愛未知。"
  },
  CollectionHall_59455_LockTip = {
    Text = "通關特遣紀錄「狩獵愉快！」解鎖"
  },
  CollectionHall_59455_Title = {Text = "萊克"},
  CollectionHall_59456_Desc = {
    Text = "<Title:簡介>\n出生於一個沒落貴族家庭，雖然天生患有嚴重哮喘，但一直被父母給予充足的關愛。\n由於病痛的折磨足不出戶，經常浮現輕生的念頭，父母為了緩解她的心情難得帶她出了一趟遠門，卻意外讓她染上融蝕。\n歸鄉後，父母滿懷愧疚地將她送入療養院，一邊出海經商賺取醫療費，一邊遊歷世界尋找治療的方法。\n隨著融蝕的侵襲，她的求死之心也愈發加重，但她心懷著拖累了父母的內疚，為了不讓父母更加傷心而一直忍耐著對死亡與解脫的嚮往。\n接到父母在前來看望她的路上因船隻失事溺亡的消息後，對人世再無牽掛的她於夜中悄然離開了療養院，一步一步向著大海深處走去。\n海水淹沒顱頂的那一刻，三角蝕痕滴落的黑液被衝散，沉屙已久的病體得到了難以言喻的解脫——這是第一次，也是她唯一一次得以順暢地呼吸。"
  },
  CollectionHall_59456_LockTip = {
    Text = "喚醒「寧菲亞」後解鎖"
  },
  CollectionHall_59456_Title = {Text = "寧菲亞"},
  CollectionHall_61045_LockTip = {
    Text = "通關調查行動8-1解鎖"
  },
  CollectionHall_61045_Title = {
    Text = "A小調：終末交響曲"
  },
  CollectionHall_62183_Title = {
    Text = "08 終末交響曲"
  },
  CollectionHall_62184_Desc = {
    Text = "<Title:簡介>\n享譽世界的指揮家與音樂家。儘管看上去年輕輕、但所指揮的交響樂演出早已巡迴世界各地、每場演出都萬人空巷。\n作為古典音樂界最負盛名的天才、哈姆林的任何私人資訊都無人知曉、這引起了審查會的關注。他們在長久的調查中發現、哈姆林的演出場所與提燈教會的行動軌跡有著高度重合。\n在他們找到真相之前、真相主動找到了他們——在提燈教會對彌薩格的入侵事件中、哈姆林扮演了十分重要的角色。\n此時人們才明白、這位天才指揮家真正的舞台、從來都在劇場之外。"
  },
  CollectionHall_62184_LockTip = {
    Text = "通關調查行動第8章「終末交響曲」解鎖"
  },
  CollectionHall_65503_Title = {
    Text = "艾爾沃斯的歸人"
  },
  CollectionHall_65509_Desc = {
    Text = "<Title:簡介>\n來自東區的小混混，亦是「24」的妹妹。\n擁有三項獨門絕技：偷雞摸狗、吵架和見勢不妙就開溜。\n任何人在她身上都討不到半分好處。\n哦，對了。她還有一隻名為「布朗」的小老鼠常伴其身。\n布朗成熟、穩重，與詹金的個性形成了良好的互補。\n因此，即使倫蒂尼恩東區總有饑寒交迫者烹煮老鼠的慘案，詹金也從未動過這方面的心思。"
  },
