  CollectionHall_70839_Desc = {
    Text = "<Title:簡介>\n諂媚，市儈，虛偽。莉莉安濟貧院的院長如同一個笨拙的演員，在倫蒂尼恩的名利場上飾演一位卑微的乞討者。\n她四處奔波，用蠢笨的奉承從名流們指縫中求來一些零碎錢，以此維持濟貧院艱難的運轉。她將嘲笑與謾罵獨自咽下，用柔軟的歌聲哄濟貧院的孩子們入睡。\n倫蒂尼恩拋棄了他們，但莉莉安濟貧院沒有。莎拉做好了準備，將要儘自己的所能去保護這些孩子，讓他們在倫蒂尼恩的迷霧與寒風中順利地活下去。\n但她卑微的理想失敗了，她與孩子們死在了雕塑家協會的陰謀裡。對雕塑家協會而言，她與她所珍視的孩子們，是那宏偉的大廈中不值一提的砂礫，既欠奉價值，更缺乏美感。他們的生無關輕重，他們的死不足掛齒。\n她燃盡了自己的一切。那火光迅速熄滅，只剩倫蒂尼恩的風依舊冰寒徹骨。"
  },
  CollectionHall_70839_LockTip = {
    Text = "通關第一章解鎖"
  },
  CollectionHall_70884_Desc = {
    Text = "<Title:A.F.185>\n各國代表在康斯坦聯邦簽訂《密斯底亞協議》，決定共同合作，抵抗災厄，壓制融蝕裂隙。同時各國就隱藏災厄存在、隱瞞融蝕現象的保密方針達成共識。\n本次協議決定，學院保持獨立，不為任一國家所有，在各國有權建立分部，有權與各國領導直接溝通，有權獲取各國災厄和融蝕相關的資訊。\n彌薩格正式成為一個完全中立的跨國組織。\n\n<Title:A.F.186>\n參與協議修訂和簽署的人員在密斯底亞成立了常駐審查會，審查會擁有自己的行動隊，以確保協議的實施。密室會議成立，基本確立了組織架構。\n\n<Title:A.F.187>\n彌薩格學院正式更名為彌薩格大學。\n之後的時間裡，融蝕現象發生得越來越頻繁，規模也越變越大。彌薩格大學站在第一線，成為人類對抗融蝕的中流砥柱。"
  },
  CollectionHall_70884_LockTip = {
    Text = "通關調查行動9-13解鎖"
  },
  CollectionHall_70885_Desc = {
    Text = "<Title:A.F.75>\n阿利斯泰爾預見了巨大裂隙在雷歐王國境內的出現，華德帶領調查員前往應對。諸多調查員在此次事故中犧牲。\n\n<Title:A.F.77>\n裂隙無法關閉，但逐漸趨於穩定。在政府的配合與支持下，華德在巨大裂隙之上興建「真理之視」的駐地。\n巨大裂隙正式編號為L-01，別名「黑池」。\n\n<Title:A.F.88>\n「黑池」突發異變並向外擴散，此時已經處於周邊地區的「真理之視」損失慘重，華德也在應對過程中負傷。\n由於黑池無法關閉，塔薇沉入其中親自鎮守，維持了黑池的暫時穩定。\n\n<Title:A.F.90>\n「真理之視」駐地擴建，彌薩格學院成立，華德為首任院長。\n至此，人們開始系統性培養擁有足夠精神力的調查員，以更好地抵抗愈演愈烈的融蝕危機。\n\n<Title:A.F.92>\n華德於黑池事件中所受的傷進一步惡化，並因此身亡。\n華德的殘骸埋在學院內，墓碑造型為一把鑰匙，開啟了彌大鑰匙塚的傳統。\n死後析出的銀芯由阿利斯泰爾親手制成銀鑰匙，賦予編號K-0001，此後阿利斯泰爾成為初代守密人，在外界活躍。\n同年，為了尋求救治華德方法而前往勒姆瓦希進行調查的刻拉爾克什失蹤，從此下落不明。"
  },
  CollectionHall_70885_LockTip = {
    Text = "通關調查行動9-13解鎖"
  },
  CollectionHall_70886_Desc = {
    Text = "<Title:A.F.306>\n赫伯特收取格林基金會的資金，在提燈教會的幫助下建立雕塑家協會。\n同年，朵爾入學彌薩格。作為天才學者，朵爾甫一加入便直接參與到研究生及博士進行的研究中，並在隨後的日子裡極大地推動了彌薩格的銀芯科技發展。\n\n<Title:A.F.307>\n赫伯特與提燈教會襲擊彌薩格，試圖找回提燈教會當年被調包的「聖女」。\n\n<Title:A.F.309>\n某融蝕事件的倖存者威廉在調查員芬戈爾的引薦下加入彌薩格。\n\n<Title:A.F.310>\n彌薩格大學聯合審查會，在雕塑家協會能夠進一步壯大之前，將其大部分成員抓捕歸案。赫伯特及數個核心成員逃脫，轉入地下工作。此後，赫伯特找上羅傑斯，展開協作。\n同年，薩爾瓦多繼任大聖堂區主教，訶勒特擔任代理院長。\n\n<Title:A.F.313>\n在赫伯特的授意下，羅傑斯向莉莉安濟貧院捐款，成為了濟貧院的唯一資助人。\n\n<Title:A.F.314>\n阿庫特大爆炸發生。\n在阿利斯泰爾的派遣下，威廉和拉蒙娜前往阿庫特，在爆炸後的遺跡中找到失去全部記憶的@3，將其帶回彌薩格，進行特殊訓練。"
  },
  CollectionHall_70886_LockTip = {
    Text = "通關調查行動9-13解鎖"
  },
  CollectionHall_70887_Desc = {
    Text = "<Title:A.F.263>\n弗朗西斯出生。\n\n<Title:A.F.289>\n失去女兒後，弗朗西斯加入科考隊，前往艾爾沃斯。\n同年，探險隊全員覆沒。\n\n<Title:A.F.290>\n羅傑斯出生。\n同年，於艾爾沃斯意外召喚出莉莉後，弗朗西斯來到拉伊，在基金會的幫助下建立了精神病院，並搭建了一個停滯的時空。\n\n<Title:A.F.292>\n朵爾出生。\n\n<Title:A.F.297>\n赫伯特作為新生入學彌薩格，時年17歲。\n\n<Title:A.F.298>\n提燈使用雙生聖子進行降神儀式。德克斯特潛入儀式中，偷偷將即將被作為神誕之軀的拉蒙娜帶走，阻止了提燈的儀式。\n儀式宣告失敗。拉蒙娜成為德克斯特養女。\n\n<Title:A.F.300>\n羅傑斯被「蠟像」綁架。後「蠟像」死亡，羅傑斯獲救。\n同年，薩爾瓦多被當時的大聖堂區主教喚醒，作為助理神父在大聖堂區服務。\n\n<Title:A.F.304>\n訶勒特作為新生入學彌薩格。\n\n<Title:A.F.305>\n彌薩格大學喚醒體系學生赫伯特違規製造實驗體，行為暴露後，赫伯特殺死自己的導師克勞利後逃離，時年25歲。"
  },
  CollectionHall_70887_LockTip = {
    Text = "通關調查行動9-13解鎖"
  },
  CollectionHall_70888_Desc = {
    Text = "<Title:B.F.？？？>\n席捲全球的災難摧毀了大片陸地。地震、洪水、磁場紊亂、氣候異常等接二連三，城市與聚落沉入水中，原本深埋海底的堅石成了新的山峰。人類文明受到重創。\n\n<Title:A.F.0>\n舊的土地被海水淹沒，新的土地浮出水面。\n在這徹底改變了面貌的世界中，人們摒棄了舊日曆法，攜帶文明的殘骸艱難重建，邁入全新的紀元：洪積。"
  },
  CollectionHall_70888_LockTip = {
    Text = "通關調查行動9-13解鎖"
  },
  CollectionHall_70889_Desc = {
    Text = "<Title:A.F.55>\n刻拉爾克什憑藉自己的調查等方式主動找到銀鑰密會，並成功加入其中，希望能夠藉密會的力量幫助人類重建。\n同年，刻拉爾克什注意到華德與塔薇的行動，開始關注其動向。\n\n<Title:A.F.58>\n刻拉爾克什製作出一次性的銀鑰匙，成為新一任密會領袖：鑰匙匠，並開始利用密會悄悄將知識擴散出去，幫助人類重建。\n同年，刻拉爾克什與華德、塔薇接觸，承諾給予華德一定資金和人力方面的幫助。\n\n<Title:A.F.62>\n阿利斯泰爾·歐文斯出生於倫蒂尼恩郊區一個普通的鄉村醫生家庭。\n\n<Title:A.F.64>\n完成調查的刻拉爾克什認可華德的追求，面對不願意被密會規則束縛的華德，雙方在塔薇的建議與見證下達成平等的合作關係。\n獲得密會資金和人力等方面的幫助後，華德的研究更進一步，確認了融蝕的特點、融蝕與異變體之間的關係，並初步總結了融蝕侵蝕的不同階段特徵。\n\n<Title:A.F.65>\n刻拉爾克什、華德、塔薇，與數位密會成員共同組成了第一支以追查融蝕、阻止融蝕擴散為己任的調查員小隊，並將其命名為「真理之視」。\n\n<Title:A.F.70>\n華德再次總結融蝕及融蝕侵蝕的特點和規律，初次記錄下融蝕的區域性特徵，並寫成《融蝕與融蝕規律初考》，供新加入調查隊的成員翻閱使用。\n\n<Title:A.F.72>\n華德於一家因融蝕而破滅的家庭中救下阿利斯泰爾，將其收為學生。\n同年，華德及其手下的「真理之視」規模逐漸擴張，引起了當局的注意。"
  },
  CollectionHall_70889_LockTip = {
    Text = "通關調查行動9-13解鎖"
  },
  CollectionHall_70890_Desc = {
    Text = "<Title:A.F.30>\n華德·菲力浦斯出生於亞格羅共和國東部的古老城市沙洛姆的一個富商家庭。\n\n<Title:A.F.38>\n刻拉爾克什出生。出生後不久其父母便亡故，與姐姐相依為命，掙扎求生。\n\n<Title:A.F.48>\n華德從小展露出化學物理方面的天賦，於18歲考入莫斯偉圖塞州立大學化學系，成為著名化學家納撒尼爾·彌爾頓的學生。\n\n<Title:A.F.50>\n華德的祖父老羅傑·菲力浦斯神父離世，隨後其父親失蹤。華德到祖宅調查，並追隨父親的步伐抵達雷歐王國，在這裡發現了家族隱藏多年的秘密——一個在獵巫時期從異教徒（銀鑰密會）手上奪得的神秘配方。\n古老的配方記載在一張羊皮紙卷上，其中有不少部分損毀了，華德經過多年實驗將其勉強補全。\n\n<Title:A.F.53>\n根據補全的配方，華德成功做出第一把銀鑰匙。由於配方上的缺陷，這把銀鑰匙使用一次就毀壞了，無法再次使用。\n無論如何，憑藉這把一次性的銀鑰匙，華德面見了智之質體的代行者塔薇，從塔薇處得知了世界即將面臨「漆黑的災難」。\n決心阻止災難，華德與塔薇達成了一致，與塔薇進行連結，獲得了喚醒體制作方法以及完整的銀鑰匙配方。\n接下來的時間內，華德四處行走，研究融蝕及裂隙併為其命名，試圖找到抵禦融蝕的方法。"
  },
  CollectionHall_70890_LockTip = {
    Text = "通關調查行動9-13解鎖"
  },
  CollectionHall_70891_Desc = {
    Text = "經過為期一年的預科學習與訓練，@3正式繼任守密人，開始帶領喚醒體與其他校內力量進行融蝕相關事件調查。\n同年，提燈教會聯合彌校內鬼再次入侵彌薩格，引發黑池動盪，開啟窮極之門，吸引無上意志投來目光。\n在卡達斯即將被融蝕吞噬之時，@3吸收三質體之權柄，在門扉內與無上意志的目光對決。\n最終，無上意志再度沉睡，卡達斯獲救。\n@3殉身。\n因其所有相關記錄將被融蝕，無法保留，彌薩格決定破例將其生前所使用的銀鑰封存，存於校史紀念館，用以紀念其功績。\n%hisorher%名字無人知曉，但K-0617這個編號，將與世長存。"
  },
  CollectionHall_70891_LockTip = {
    Text = "通關調查行動9-13解鎖"
  },
