    Text = "孤獨援救"
  },
  CollectionHall_89351_Desc = {
    Text = "你聽到某人在你耳邊不斷輕柔地絮語，唇齒間的呢喃沙沙作響。\n你仔細聆聽，試圖分辨那模糊的言語，直到同樣的沙沙聲在耳膜內側的顱中響起，你才意識到，那是億萬只蟲類的翅膀在一同密集共振的聲音——嘩啦，嘩啦啦，回家，回家。"
  },
  CollectionHall_89351_LockTip = {
    Text = "完成調查行動 星辰篇2-18解鎖"
  },
  CollectionHall_89351_Title = {
    Text = "億萬蟲鳴"
  },
  CollectionHall_89352_Desc = {
    Text = "人生中的關鍵時刻，似乎總是有如絲細雨相伴。\n與那些霏霏細雨中的回憶告別吧，把釀成的苦酒深藏心底，握緊手中的銀鑰，踏上新的征程。\n願銀鑰指引我們。"
  },
  CollectionHall_89352_LockTip = {
    Text = "完成調查行動·困難 星辰篇1-10解鎖"
  },
  CollectionHall_89352_Title = {
    Text = "再見霏霏"
  },
  CollectionHall_89353_Desc = {
    Text = "春日的暖陽、夢幻的宮殿、旋轉的禮裙、充滿歡笑的舞會，以及美麗又溫柔的公主。\n這些就是騎士想要守護的全部。"
  },
  CollectionHall_89353_LockTip = {
    Text = "完成意識潛遊「騎士的願望」"
  },
  CollectionHall_89353_Title = {
    Text = "宮廷春日宴"
  },
  CollectionHall_89354_Desc = {
    Text = "鮮血，殺戮，變革……埋藏在無盡黃沙下的，是時間長河中殘酷而常見的歷史。"
  },
  CollectionHall_89354_LockTip = {
    Text = "完成意識潛遊「蒼白後裔」困難難度"
  },
  CollectionHall_89354_Title = {
    Text = "黃沙之下"
  },
  CollectionHall_89355_Desc = {
    Text = "當不知道如何回答時，只要賣萌就好了，哎嘿~"
  },
  CollectionHall_89355_LockTip = {
    Text = "完成調查行動3-14解鎖"
  },
  CollectionHall_89356_Desc = {
    Text = "戰略性撤退雖可恥，但有用。"
  },
  CollectionHall_89356_LockTip = {
    Text = "完成意識潛遊「蒼白後裔」"
  },
  CollectionHall_89356_Title = {
    Text = "迷宮逃亡"
  },
  CollectionHall_89357_Desc = {
    Text = "深淵中綻放的潔白之花，牢牢擋在眾人身前。\n“即使是這樣，那也是我唯一的媽媽。”\n“把我的媽媽——還給我！”"
  },
  CollectionHall_89357_LockTip = {
    Text = "完成調查行動·困難4-12解鎖"
  },
  CollectionHall_89357_Title = {
    Text = "悲愴的綻放"
  },
  CollectionHall_89358_Desc = {
    Text = "在她成為冰冷的機械前，也曾有過鮮活的靈魂。"
  },
  CollectionHall_89358_LockTip = {
    Text = "完成意識潛遊「扭曲核心」"
  },
  CollectionHall_89358_Title = {
    Text = "機械之心"
  },
  CollectionHall_89359_Desc = {
    Text = "少女身著單衣走在雪地上，渴望一個溫暖的懷抱。"
  },
  CollectionHall_89359_LockTip = {
    Text = "完成調查行動3-14解鎖"
  },
  CollectionHall_89360_Desc = {
    Text = "居民們熱情洋溢，與來賓打成一片。"
