  },
  CollectionHall_89399_Title = {
    Text = "窒息煙塵"
  },
  CollectionHall_89400_Desc = {
    Text = "打開你的顱腔，與萬千腦缸共振吧。\n答案或許就隱藏其中。"
  },
  CollectionHall_89400_LockTip = {
    Text = "完成調查行動·困難 星辰篇1-10解鎖"
  },
  CollectionHall_89400_Title = {
    Text = "顱腔共振"
  },
  CollectionHall_89401_Desc = {
    Text = "冬日，女巫，孩子們，一場永不停歇的雪。"
  },
  CollectionHall_89401_LockTip = {
    Text = "完成調查行動3-14解鎖"
  },
  CollectionHall_89401_Title = {
    Text = "雪落噬影之鎮"
  },
  CollectionHall_89402_Desc = {
    Text = "詭異的密語在空氣中迴蕩，黑色的粘液將祭品吞噬，舊日的存在期待著神明的歸來。"
  },
  CollectionHall_89402_LockTip = {
    Text = "完成調查行動4-16解鎖"
  },
  CollectionHall_89402_Title = {
    Text = "極地祭壇"
  },
  CollectionHall_89403_Desc = {
    Text = "光芒驅散了黑暗，平等地照耀著每位孩子。\n它蒼白，虛弱，卻無比溫暖，充滿力量。\n願這微弱之光，能消去你的苦難，撫平你的內心，我的孩子。"
  },
  CollectionHall_89403_LockTip = {
    Text = "完成特遣紀錄「血的顏色」困難難度"
  },
  CollectionHall_89403_Title = {
    Text = "濟世的白焰"
  },
  CollectionHall_89404_Desc = {
    Text = "列車驟然停下，雙子追尋血脈氣息而來。"
  },
  CollectionHall_89404_LockTip = {
    Text = "完成調查行動3-14解鎖"
  },
  CollectionHall_89404_Title = {Text = "急刹車"},
  CollectionHall_89405_Desc = {
    Text = "王啊，我已遵循預言等待了萬年，可未來為何依舊遙不可及？\n我本應繼續祈禱，但請原諒我，我已經等不及了。"
  },
  CollectionHall_89405_LockTip = {
    Text = "完成調查行動5-15解鎖"
  },
  CollectionHall_89405_Title = {
    Text = "億萬禱言"
  },
  CollectionHall_89406_Desc = {
    Text = "卑賤的小偷盜取了王的力量，妄圖阻礙偉大的儀式。\n不敬之贗品，當以死謝罪！"
  },
  CollectionHall_89406_LockTip = {
    Text = "完成調查行動·困難5-10解鎖"
  },
  CollectionHall_89406_Title = {
    Text = "瀆神誓言"
  },
  CollectionHall_89407_Desc = {
    Text = "在那濃郁不可見日的迷霧中，我將獨身踏向未知的前路。\n我從那霧中撈起塵土、鮮血與火焰，平息那些孤獨的、茫然的、愁怨的淚水。\n我將不再懼怕，只因永恆的太陽早已高懸於我的心間。"
  },
  CollectionHall_89407_LockTip = {
    Text = "完成調查行動 星辰篇2-18解鎖"
  },
  CollectionHall_89407_Title = {
    Text = "我將行至"
  },
  CollectionHall_89408_Desc = {
    Text = "孩子們都曾聽過：不要用肉眼直視太陽。\n即便此刻，祂已經淪陷。"
  },
  CollectionHall_89408_LockTip = {
    Text = "完成調查行動 星辰篇1-14解鎖"
  },
  CollectionHall_89408_Title = {
    Text = "復甦黑日之世"
  },
  CollectionHall_89409_Desc = {
    Text = "歡迎來到克萊門汀醫生的私人神經療養院，請跟隨醫生的指引，釋放你心靈所有的痛苦，走向最終的痊癒。"
  },
  CollectionHall_89409_LockTip = {
    Text = "完成調查行動 星辰篇2-18解鎖"
  },
  CollectionHall_89409_Title = {
    Text = "迷幻蟲巢之夢"
  },
  CollectionHall_89410_Desc = {
    Text = "曾經的輝煌已經過去，只剩下記憶中的斷壁殘垣。"
  },
  CollectionHall_89410_LockTip = {
    Text = "完成意識潛遊「蒼白後裔」"
  },
  CollectionHall_89410_Title = {
    Text = "過往餘輝"
  },
  CollectionHall_89411_Desc = {
    Text = "你於深淵中沉沒,從你的口袋裡,飛出她最後的留言。於是你在無盡的黑暗裡,得見一刹的光明。"
  },
  CollectionHall_89411_LockTip = {
    Text = "完成調查行動·困難 星辰篇2-12解鎖"
  },
  CollectionHall_89412_Desc = {
    Text = "曾在你身前的，如今在你身後。\n你始終相信，在你全力奔跑後，在那時空盡頭等待的，一定是那雙熟悉的、溫暖的手。"
  },
  CollectionHall_89412_LockTip = {
    Text = "完成調查行動·困難 星辰篇2-12解鎖"
  },
  CollectionHall_89412_Title = {
    Text = "不變的抉擇"
  },
  CollectionHall_89413_Desc = {
    Text = "地下鐵中遭到攻擊雖然不幸，但作為滿足女孩好奇心的餘興節目，卻是剛剛好。"
  },
  CollectionHall_89413_LockTip = {
    Text = "完成調查行動3-14解鎖"
  },
  CollectionHall_89413_Title = {
    Text = "隧道奇遇記"
  },
  CollectionHall_89414_Desc = {
    Text = "英雄和公主奔跑在夜幕下，腳下的砂礫訴說著生的喜悅。那顆封閉千年的心，也隨著流星的劃過，緩緩地開始跳動。"
  },
  CollectionHall_89414_LockTip = {
    Text = "完成意識潛遊「蒼白後裔」困難難度"
  },
  CollectionHall_89415_Desc = {
    Text = "不必言語，當你來到這裡，便會獲得最真誠的幫助。\n那微笑的引路人已向你伸出手，她將帶你走入你自己也不曾看清的、心靈密林的深處。"
  },
  CollectionHall_89415_LockTip = {
    Text = "完成調查行動 星辰篇2-18解鎖"
  },
  CollectionHall_89415_Title = {
    Text = "心靈密林"
  },
  CollectionHall_89416_Desc = {
    Text = "當河谷的第一縷晨光照入迷宮之時，千足千子沉睡千年的公主，迎來了她最後一位信徒。"
  },
  CollectionHall_89416_LockTip = {
    Text = "完成意識潛遊「蒼白後裔」"
  },
  CollectionHall_89416_Title = {
    Text = "坎布裡安的晨曦"
  },
  CollectionHall_89417_Desc = {
    Text = "天才的腦回路總有那麼一些蜿蜒、曲折、與眾不同，但那正是她的可愛之處，不是嗎？"
  },
  CollectionHall_89417_LockTip = {
    Text = "完成意識潛遊「扭曲核心」"
  },
  CollectionHall_89417_Title = {
    Text = "天才的煩惱"
  },
  CollectionHall_89418_Desc = {
    Text = "來陪我玩個遊戲吧，放心，沒那麼危險，只是為了打發這無聊的時間。"
  },
  CollectionHall_89418_LockTip = {
    Text = "完成意識潛遊「蒼白後裔」"
  },
  CollectionHall_89418_Title = {
    Text = "猜謎遊戲"
  },
  CollectionHall_89419_Desc = {
    Text = "幻光的海潮在天體的牽引下編織成帷幕，蹈海的詭物踏浪而來。"
  },
  CollectionHall_89419_LockTip = {
    Text = "完成調查行動5-15解鎖"
  },
  CollectionHall_89419_Title = {
    Text = "幻海潮湧"
  },
  CollectionHall_89420_Desc = {
    Text = "王至高無上，王威權無邊，王遙坐於輝煌之上，孤獨的俯視他的國。"
  },
  CollectionHall_89420_LockTip = {
    Text = "完成調查行動5-15解鎖"
  },
  CollectionHall_89420_Title = {
    Text = "眠於深淵之王"
  },
  CollectionHall_89706_Desc = {
    Text = "<Title:簡介>\n孤兒，來歷不明，自有記憶開始就被船員收養，生活在船上。\n因為這樣的經歷，克珀珊特從小就對海洋充滿了渴望與好奇。\n當她長大時，理所當然地選擇了與海洋、船相關的職業——領航員。\n從此，熱愛海洋的少女永恆地漂流於海上，她將在繁星相伴下，指引船隻的方向。\n她在海洋裡、在船上「降生」。\n她也無懼在海洋裡、在船上「死亡」。\n這就是她的生活。"
  },
  CollectionHall_89706_LockTip = {
    Text = "喚醒「克珀珊特」後解鎖"
  },
  CollectionHall_89968_Desc = {
    Text = "殺戮、仇恨、瘋狂與痛苦，戰場從不缺少這些。當你將性命賭上怪物的牌桌時，就理應想到會引起一場怎樣的猩紅漩渦。"
  },
  CollectionHall_89968_LockTip = {
    Text = "完成意識潛遊「血與沙」"
  },
  CollectionHall_89968_Title = {
    Text = "猩紅漩渦"
  },
  CollectionHall_89969_Desc = {
    Text = "傳說中領航員死後，會在桅杆之上化作一團藍白色的閃光，繼續指引船隻的航行。\n那麼她在桅杆的最頂端點燃了自己的生命時，是否看見了那一道希望的歸路？"
  },
  CollectionHall_89969_LockTip = {
    Text = "完成意識潛遊「最後的引航」"
  },
  CollectionHall_89969_Title = {
    Text = "聖艾爾摩之火"
  },
  CollectionHall_89970_Desc = {
    Text = "她生來的宿命中便充滿仇恨、殺伐與無盡的爭鬥。\n當她拋棄一切溫軟的、暖和的幻影，選擇拿起刀與槍時，命運的凱歌就已為她而奏響。\n她註定成為一個戰士，用敵人的鮮血洗刷仇恨，而後度過或許並不光榮，卻無畏無悔的一生。"
  },
  CollectionHall_89970_LockTip = {
    Text = "完成特遣紀錄「艾爾沃斯的歸人」"
  },
  CollectionHall_89971_Desc = {
    Text = "血紅的夕陽下，是浸滿鮮血的黃沙。\n最強大的戰士佇立在即將沉入黑夜的戰場，回憶舊日裡金色的火焰與榮光。\n無數尖叫的禿鷲飛起，遮擋住了最後的日光。偉大的東征之下，盡是擠滿沙漠的亡靈，為他共同陪葬。"
  },
  CollectionHall_89971_LockTip = {
    Text = "完成意識潛遊「血與沙」困難難度"
  },
  CollectionHall_89971_Title = {
    Text = "沐浴鮮血的紅日"
  },
  CollectionHall_89972_Desc = {
    Text = "如若這世界已陷入黑暗，那我將做最後的炬火。\n如若人群中已再無正義，那我將為最弱者發聲。"
  },
  CollectionHall_89972_LockTip = {
    Text = "完成意識潛遊「最後的引航」"
  },
  CollectionHall_89972_Title = {
    Text = "長夜炬火"
  },
  CollectionHall_89973_Desc = {
    Text = "那是她宿命的戰鬥，那是她必須前往的戰場。\n她將所有懦弱、猶豫、恐懼都隨過往拋卻。\n她並不後悔，只因她已明白此生戰鬥的真諦。\n她並不孤獨，那手中的劍刃倒映的，正是另一個自己張狂的面龐。"
  },
  CollectionHall_89973_LockTip = {
    Text = "完成特遣紀錄「艾爾沃斯的歸人」困難難度"
  },
  CollectionHall_89973_Title = {
    Text = "向群山發問"
  },
  CollectionHall_89974_Desc = {
    Text = "嘿喲，嘿喲，拉起船錨，升起船帆，解開最後一根纜繩。\n我們的領航員已爬上桅杆，鮮豔的旗幟已高高掛起。\n啟航，啟航，向著她指引的方向，我們就要啟航！"
  },
  CollectionHall_89974_LockTip = {
    Text = "完成意識潛遊「最後的引航」"
  },
  CollectionHall_89974_Title = {
    Text = "領航手記"
  },
  CollectionHall_89975_Desc = {
    Text = "她在每一次出航時，都準備好了最新的遺書。\n那首代代相傳的歌謠如夢中的搖籃曲，將她的靈魂輕柔擁抱。\n鮮豔的旗幟在風中飄蕩，她的肉體或會崩解、腐爛、沉入深海，她的靈魂必將佇立在她的船上，向著星辰與大海發出永恆的光芒。"
  },
  CollectionHall_89975_LockTip = {
    Text = "完成意識潛遊「最後的引航」"
  },
  CollectionHall_89975_Title = {
    Text = "領航員挽歌"
  },
  CollectionHall_89976_Desc = {
    Text = "在庫西沙漠之中，風沙是永不停歇的常客，漫天飛舞的沙礫會灌進活人的口鼻，也會掩埋死去的、不知姓名的屍體。\n只有渴求血肉的野獸，會在風中細細嗅尋、那份甘美盛宴的氣息。"
  },
  CollectionHall_89976_LockTip = {
    Text = "完成意識潛遊「血與沙」"
  },
  CollectionHall_89976_Title = {
    Text = "黃沙與野獸"
  },
  CollectionHall_89977_Desc = {
    Text = "沙漠裡的太陽和其他地方並不一樣，它蒼白、刺眼而酷烈，從未有過溫柔的一面。野獸無法想像你口中描述的春天，那麼就請你替他去看一看，那所謂真正的太陽吧。"
  },
  CollectionHall_89977_LockTip = {
    Text = "完成意識潛遊「血與沙」"
  },
  CollectionHall_89977_Title = {
    Text = "無還的血與沙"
  },
  CollectionHall_89978_Desc = {
    Text = "大雪無盡落下，紛紛揚揚，將戰士的頭髮覆上霜白。\n她一生的回憶於此時流淌，她從人心幽微之處走過，要去往群山磅礴之中。\n背叛、拋棄與守護，一切痛苦與憤怒，不過是一場又一場戰鬥。與人、與山、與自我。\n她看向自己的引領者，看向陌生又熟悉的新同伴，露出了並不熟練的笑容。\n她或有一天會凱旋，或許會永遠倒在戰場，但哪怕升入天國或墮入地獄的那一刻，她也不會放下手中的利刃。\n為了不再失去這一切，這次她選擇在復仇之前，舉起名為守護之劍，獨自奔赴她的戰場。"
  },
  CollectionHall_89978_LockTip = {
    Text = "完成特遣紀錄「艾爾沃斯的歸人」"
  },
  CollectionHall_89978_Title = {
    Text = "為了不再失去的明天"
  },
  CollectionHall_89998_LockTip = {
    Text = "需要通關限時活動「窺覷神國的陰影：異動海潮」任一關卡"
  },
  CollectionHall_89998_Title = {
    Text = "窺覷神國的陰影：異動海潮"
  },
  CollectionHall_89999_LockTip = {
    Text = "需要通關限時活動「鏡像囚徒：飛躍青空」任一關卡"
  },
  CollectionHall_89999_Title = {
    Text = "鏡像囚徒：飛躍青空"
  },
  CollectionHall_90245_LockTip = {
    Text = "通關異夢視界「天邊之外·上」任一關卡解鎖"
  },
  CollectionHall_90245_Title = {
    Text = "飛鳥尚未墜落之時"
  },
  CollectionHall_90415_Title = {
    Text = "天邊之外·上"
  },
  CollectionHall_90416_Desc = {
    Text = "<Title:簡介>\n提燈教會為了降神儀式而培養的一系列實驗品之一，因作為雙生子幸運地降生，而免於了被丟棄於垃圾堆的命運。\n與弟弟波呂克斯從小被尊為聖子，接受嚴格的規訓，整日被灌輸有關持燈者的神學，唯一接觸過有關外界的資訊就是一本由信徒供奉的、精美厚重的手抄本。\n少年時在弟弟被教會施行殘忍的改造儀式後，二人決定一起出逃追尋自由，但很快就被抓回。\n他被浸泡在名為「罪潭」融蝕水池中，用「罪孽療法」治癒傷口，經歷了漫長的折磨。\n最終因此被於麗埃特之外的人遺忘了，包括波呂克斯，與弟弟的關係也變得僵硬。\n從此蟄伏下來，表面裝作順從教會，內心從沒放棄再次帶弟弟逃走的執念，一直等待著重獲自由的機會。"
  },
  CollectionHall_90416_LockTip = {
    Text = "喚醒「卡斯托爾」後解鎖"
  },
  CollectionHall_90416_Title = {
    Text = "卡斯托爾"
  },
  CollectionHall_94552_LockTip = {
    Text = "需要通關限時活動「偉大的征服：神聖的獵食」任一關卡"
  },
  CollectionHall_94552_Title = {
    Text = "偉大的征服：神聖的獵食"
  },
  CollectionHall_94553_Desc = {
    Text = "<Title:簡介>\n提燈教會為了降神儀式而培養的人造雙子實驗品，就在被判定為實驗失敗，即將被殘忍拋棄之時，從哥哥的血肉之中分裂誕生。\n那樣求生的依戀並非幸運，而是將兩人的命運從短促的悲劇，更改為了一場更加漫長的悲劇。\n或許源於雙生的奧秘，他與哥哥的膚色、性格都截然相反。作為雙子中更活潑機靈的那一個，總是做出與規訓相悖的頑劣行為，就像一個平凡家庭中調皮的少年那樣——直到被選中作為神格的容器培養，開始定期進行痛苦而血腥的「神聖改造」儀式。\n因無法忍受痛苦而無望的命運，在他的哀求和謀劃下，兄弟二人用暗語計劃了數年，終於破開重重險阻成功出逃。\n然而他們沒能高興太久就被教會的追兵抓回，於麗埃特下令拔掉了他那自由的翅膀，並對他進行極端的洗腦，最終使他徹底忘記了哥哥，享受起了身為聖子、被人追捧的感覺。\n直到在第二次出逃後因哥哥的死去和降神儀式的作用重新找回了記憶，被仇恨與怒火點燃了那顆「聖心」，將對抗提燈教會當作了人生新的方向。"
  },
  CollectionHall_94553_LockTip = {
    Text = "通關異夢視界「天邊之外·下」解鎖"
  },
  CollectionHall_94553_Title = {
    Text = "波呂克斯"
  },
  CollectionHall_95436_Desc = {
    Text = "飛啊，飛啊，鳥兒用那雙翅膀對抗著沉重的引力，不斷攀升、攀升，穿過一股又一股亂流與漩渦，向著越來越高的地方飛去。\n然而他不知道，他的腳上一直系有一條無形的絲線，他或許從不曾真正成為飛鳥，縱使飛翔，也不過是一只可憐的風箏。\n現在，風箏線收緊了。"
  },
  CollectionHall_95436_LockTip = {
    Text = "完成異夢視界「天邊之外·上」"
  },
  CollectionHall_95436_Title = {Text = "風箏"},
  CollectionHall_95437_Desc = {
    Text = "你看到了那張臉，那張溫柔的、寧靜的、美麗的臉。\n它很快消融在你的記憶中，但你仍會一直記得那場漫長的夜雨結束後，晨曦柔軟光暈的顏色。"
  },
  CollectionHall_95437_LockTip = {
    Text = "完成特遣紀錄「雨鎮幽影」"
  },
  CollectionHall_95437_Title = {
    Text = "雨幕深處"
  },
  CollectionHall_95438_Desc = {
    Text = "做一隻貓，做一隻無憂無慮的貓，只與愛的人待在一起，每天蜷在她身邊曬太陽。\n這是她心底美好的小小夢想，然而美夢啊，一直都是那樣脆弱易碎的東西。"
  },
  CollectionHall_95438_LockTip = {
    Text = "完成特遣紀錄「寧靜的裂殖」"
  },
  CollectionHall_95438_Title = {
    Text = "貓的願望"
  },
  CollectionHall_95439_Desc = {
    Text = "哪怕世界灰飛煙滅，哪怕一切都被融蝕漿浸染，無邪的水母也可以永恆沉浸於自己的幻夢中。\n那裡，一切如初。只有歡笑。只有快樂。"
  },
  CollectionHall_95439_LockTip = {
    Text = "完成意識潛遊「諸事如常」困難難度"
  },
  CollectionHall_95439_Title = {
    Text = "沉淪於混沌爛漫"
  },
  CollectionHall_95440_Desc = {
    Text = "倫蒂尼恩的冬天並不常下雪，每一次飄雪都會引起孩子們興奮的狂歡。\n你從一場溫柔的長夢中醒來，將手伸出窗外。一朵雪花落在手心，於溫暖中甘心地消融。\n紛紛揚揚的雪花，經過天空中短暫的旅途，回歸向大地，回歸向暗河，回歸向所有水滴的家與輪回。\n在今年的第一場大雪中，又一位她也回到了她們的家。\n晚安，雪；晚安，「24」。"
  },
  CollectionHall_95440_LockTip = {
    Text = "完成特遣紀錄「寧靜的裂殖」"
  },
  CollectionHall_95441_Desc = {
    Text = "白色的珊瑚蔓延出枝椏，生長出純白的宮殿。\n畸形的廊柱中，有多彩的遊魚自在穿梭。\n身體在下沉、靈魂在飄蕩。\n你心甘情願地失去呼吸，與她一起沉溺、沉溺，沉溺在白色的幻夢裡。\n那是海的奇蹟，那是溫暖的藍色家鄉。"
  },
  CollectionHall_95441_LockTip = {
    Text = "完成意識潛遊「如歌的雕琢」"
  },
  CollectionHall_95441_Title = {
    Text = "純白宮殿"
  },
  CollectionHall_95442_Desc = {
    Text = "滴滴——小火車出發！\n讓我帶著朋友們，前往永遠沒有痛苦的歡樂童話王國吧。"
  },
  CollectionHall_95442_LockTip = {
    Text = "完成意識潛遊「諸事如常」"
  },
  CollectionHall_95442_Title = {
    Text = "童真的癡夢"
  },
  CollectionHall_95443_Desc = {
    Text = "她是兇手嗎？她看起來又像是你久別重逢的情人。\n雨水、枯葉和一股迷幻的花香，你翕動鼻翼，試圖從那些潮濕的味道中嗅出一絲血腥氣，以敲定她有罪的證明。然而你什麼都沒有聞到。\n她亦從未想過解釋，一片朦朧的霧中，你墜入她的灰色夢境。"
  },
  CollectionHall_95443_LockTip = {
    Text = "完成特遣紀錄「雨鎮幽影」"
  },
  CollectionHall_95444_Desc = {
    Text = "那同樣的饑渴她也曾經歷。\n懵懂、野蠻又孤獨。\n她是幸運的，她已結束了漫長的流浪，擁有了可供咀嚼一生的溫暖回憶。\n現在她執起同類的手，將這個彷徨的靈魂送往寧靜的夢鄉。"
  },
  CollectionHall_95444_LockTip = {
    Text = "完成特遣紀錄「雨鎮幽影」困難難度"
  },
  CollectionHall_95444_Title = {
    Text = "野獸之夢"
  },
  CollectionHall_95445_Desc = {
    Text = "來自我的尖刀，捅向我的心臟。\n在無情的命運、苦澀的生活面前，我是那樣渺小、軟弱而無力。\n我憑什麼成為我？我有沒有做好我？\n來自我的質問，我亦無法回答。"
  },
  CollectionHall_95445_LockTip = {
    Text = "完成特遣紀錄「寧靜的裂殖」"
  },
  CollectionHall_95445_Title = {Text = "問我"},
  CollectionHall_95446_Desc = {
    Text = "咦？你好像和剛剛變得不一樣了？\n是眼神更加明亮了？是舉止更加活潑了？還是這具平庸的軀殼內，已經改換了靈魂的主人？"
  },
  CollectionHall_95446_LockTip = {
    Text = "完成意識潛遊「如歌的雕琢」"
  },
  CollectionHall_95446_Title = {
    Text = "靈魂轉移"
  },
  CollectionHall_95447_Desc = {
    Text = "無論下雪、下雨、晴天、陰天，今日的河水依然靜靜流淌。"
  },
  CollectionHall_95447_LockTip = {
    Text = "完成特遣紀錄「寧靜的裂殖」"
  },
  CollectionHall_95447_Title = {
    Text = "寧靜的河流"
  },
  CollectionHall_95448_Desc = {
    Text = "潮水奔湧，頭顱尖嘯。\n一雙雙眼凝視著你，一張張嘴怒斥著你。\n它們要將你淹沒，它們要將你吞噬。\n你恐懼地閉上雙眼，再睜眼時，你發現它們就在你的身邊。"
  },
  CollectionHall_95448_LockTip = {
    Text = "完成特遣紀錄「雨鎮幽影」"
  },
  CollectionHall_95448_Title = {Text = "頭顱海"},
  CollectionHall_95449_Desc = {
    Text = "她答應過你，一定會帶你一起回家。\n——以恆久的姿態，回到靜謐的、奇蹟和美的家鄉。"
  },
  CollectionHall_95449_LockTip = {
    Text = "完成意識潛遊「如歌的雕琢」"
  },
  CollectionHall_95449_Title = {
    Text = "石化藝術"
  },
  CollectionHall_95450_Desc = {
    Text = "那位尊貴的客人曾望著卡斯托爾滿懷希望的背影，於月光下輕輕呢喃宿命的預言：「他會走出去，會在暴風中拼命地掙扎。那讓他高飛的，也必將讓他墜落。」"
  },
  CollectionHall_95450_LockTip = {
    Text = "完成異夢視界「天邊之外·上」"
  },
  CollectionHall_95450_Title = {
    Text = "於暴風中"
  },
  CollectionHall_95451_Desc = {
    Text = "生於美，死於美。\n她是天才、瘋子、魔鬼，她是冷漠的劊子手，也是你溫情脈脈的家人。\n她用熾熱的愛，將你炮製成一件完美的作品。\n她把你擁抱，將你冰冷的手牽起。她會帶著你，與她一起回到藝術的家鄉。"
  },
  CollectionHall_95451_LockTip = {
    Text = "完成意識潛遊「如歌的雕琢」困難難度"
  },
  CollectionHall_95452_Desc = {
    Text = "大海聽到了我的呼喚，所以將你送至我的身邊。\n從此，我們盡情談話、嬉戲、歡鬧，註定成為世界上最好的朋友。\n在這滿是融蝕的死寂之城。"
  },
  CollectionHall_95452_LockTip = {
    Text = "完成意識潛遊「諸事如常」"
  },
  CollectionHall_95452_Title = {
    Text = "請成為我的朋友"
  },
  CollectionHall_95453_Desc = {
    Text = "歸來吧，所有勇敢的、怯懦的、聰明的、愚笨的、強大的、弱小的我。\n讓所有快樂的、悲傷的、憤怒的、痛苦的、疲憊的心都融化。\n我們在一起。\n她們永遠在一起。"
  },
  CollectionHall_95453_LockTip = {
    Text = "完成特遣紀錄「寧靜的裂殖」困難難度"
  },
  CollectionHall_95453_Title = {Text = "歸於她"},
  CollectionHall_95454_Desc = {
    Text = "這來自靈魂的空虛與裂隙唯有最純真的童話才能填補。\n終有一日，她會告別痛苦，回到童話中充滿歡樂的「故鄉」。"
  },
  CollectionHall_95454_LockTip = {
    Text = "完成意識潛遊「諸事如常」"
  },
  CollectionHall_95454_Title = {
    Text = "天真的驚悚童話"
  },
  CollectionHall_95455_Desc = {
    Text = "那些潛伏著黑暗的、幽深又狹窄的小巷，總是承載著許多命運轉折的時刻。重逢、爭吵、決裂，乃至暴力、欺凌、謀殺。\n所幸的是，今日的故事沒有發生後半部分血腥的場面，但誰又能說前者所招致的，不是真正的悲劇呢？"
  },
  CollectionHall_95455_LockTip = {
    Text = "完成異夢視界「天邊之外·上」"
  },
  CollectionHall_95469_LockTip = {
    Text = "限時活動「黑陽垂照的永夏：徹夏狂歡」中領取第 1 天獎勵"
  },
  CollectionHall_95469_Title = {
    Text = "黑陽垂照的永夏"
  },
  CollectionHall_95981_LockTip = {
    Text = "需要通關限時活動「死靈的美學：噬靈之饗」任一關卡"
  },
  CollectionHall_95981_Title = {
    Text = "死靈的美學：噬靈之饗"
  },
  CollectionHall_95982_LockTip = {
    Text = "通關調查行動星辰篇3-11解鎖"
  },
  CollectionHall_96314_Title = {Text = "饜饗"},
  CollectionHall_96790_LockTip = {
    Text = "通關調查行動星辰篇3-1解鎖"
  },
  CollectionHall_97150_LockTip = {
    Text = "需要通關限時活動「畫布的暗面：異界畫卷」任一關卡"
  },
  CollectionHall_97150_Title = {
    Text = "畫布的暗面：異界圖卷"
  },
  CollectionHall_97158_LockTip = {
    Text = "需要通關限時活動「墜臨的萬千耀光：燼滅追獵」任一關卡"
  },
  CollectionHall_97158_Title = {
    Text = "墜臨的萬千耀光：燼滅追獵"
  },
  CollectionHall_97208_LockTip = {
    Text = "通關意識潛遊「畸世繪」任一關卡解鎖"
  },
  CollectionHall_97208_Title = {
    Text = "真正的藝術"
  },
  CollectionHall_97736_LockTip = {
    Text = "需要通關限時活動「神誕的祭禮：創生七日」任一關卡"
  },
  CollectionHall_97736_Title = {
    Text = "神誕的祭禮：創生七日"
  },
  CollectionHall_97896_LockTip = {
    Text = "需要通關限時活動「如果一切如常：日光下新事」任一關卡"
  },
  CollectionHall_98502_LockTip = {
    Text = "通關意識潛遊「不朽極晝」任一關卡解鎖"
  },
  CollectionHall_98502_Title = {
    Text = "永燃不燼的追獵"
  },
  CollectionHall_98636_Desc = {
    Text = "褻瀆者掀起幽藍的海嘯，單薄的王者孤身迎向千米巨浪。\n他的髮絲於風中飛揚，他的骨與血即是他莊嚴的宣告，於輕蔑的笑容中，他將自己亦獻於死亡與月亮。\n於是整片海在此刻凝結，倒懸的冰川靜止於滿月之下，一切歸於寂靜，一切安寧重回他的國度。"
  },
  CollectionHall_98636_LockTip = {
    Text = "完成調查行動·困難 星辰篇3-10解鎖"
  },
  CollectionHall_98636_Title = {
    Text = "滿月祭禮"
  },
  CollectionHall_98637_Desc = {
    Text = "烹飪死者，是一項莊嚴的藝術。\n他用刀與鏟探問未竟的遺言，他用水與火滿足最後的遺願。\n每一塊難堪的、痛苦的、酸澀的記憶，都將化作閃耀而芬芳的作品，供人品味珍藏。"
  },
  CollectionHall_98637_LockTip = {
    Text = "完成調查行動 星辰篇3-11解鎖"
  },
  CollectionHall_98638_Desc = {
    Text = "孩子哭鬧、尖啼、蠻不講理。\n祂即宇宙之中心，祂即此地一切法。\n祂要一切目光所及的，都圍繞、依從、敬獻於祂。"
  },
  CollectionHall_98638_LockTip = {
    Text = "完成調查行動·困難6-10解鎖"
  },
  CollectionHall_98638_Title = {
    Text = "神明降誕"
  },
  CollectionHall_98639_Desc = {
    Text = "他收殮每一份死亡時，並不是無情地揮舞著鐮刀。 \n他也曾有溫熱的雙手，也曾有善感的心靈。\n當他品味到那靈魂的悲傷，他會隨之一同落淚。\n當他飽嘗到那刻骨的仇恨，他會代之降下審判。\n他以葬骸之主的名義許諾：一切褻瀆死亡之人，都將消散於冰寒的濃霧。"
  },
  CollectionHall_98639_LockTip = {
    Text = "完成調查行動 星辰篇3-11解鎖"
  },
  CollectionHall_98640_Desc = {
    Text = "血肉腥甜的滋味與肌腱斷裂的口感是他最熟悉、也最刻骨銘心的記憶。\n他早已明白，這座葬骸城得以延續至今日，並不源於生者的力量，而是源自於亡者的犧牲。\n又一抹殷紅吞咽於喉舌，他閉上雙眼，仔細品嘗著每一絲不同的香氣，將每個靈魂的味道牢牢記下，於是他的親朋與子民都在他的身軀中永生。\n他們約定永遠相聚。"
  },
  CollectionHall_98640_LockTip = {
    Text = "完成調查行動·困難 星辰篇3-10解鎖"
  },
  CollectionHall_98640_Title = {
    Text = "血色契約"
  },
  CollectionHall_98641_Desc = {
    Text = "月光下的祭祀刀閃爍著誘人的光亮。\n她用一場決絕的死亡，證明了她夢寐以求的自由意志。"
  },
  CollectionHall_98641_LockTip = {
    Text = "完成調查行動6-15解鎖"
  },
  CollectionHall_98642_Desc = {
    Text = "他教導族人們如何戰鬥、如何殺戮、如何生存，卻從未教過，當面對數倍於自己的強敵時，如何逃命。\n因此他也不會逃。\n不過是首級而已，拿去！\n他早已看透：一心追求力量的野心家，死於追逐的途中，只是既定的結局與宿命。"
  },
  CollectionHall_98642_LockTip = {
    Text = "完成意識潛遊「巨人的隕落」"
  },
  CollectionHall_98642_Title = {
    Text = "我無懼死亡"
  },
  CollectionHall_98643_Desc = {
    Text = "哢嚓、哢嚓。\n神明咧開嘴巴，欣然收下了信徒所有的虔誠，以及信徒本身。"
  },
  CollectionHall_98643_LockTip = {
    Text = "完成調查行動6-15解鎖"
  },
  CollectionHall_98644_Desc = {
    Text = "曾經的族人一擁而上，意圖絞殺他們戰敗又流亡的統領。而非利士史上最勇猛的領袖，擁有不屈意志的偉力巨人，以殺戮作為了回應。\n無盡的哀嚎裡，巨刃渴飲鮮血，以一個又一個殘缺的屍骨，詮釋他的戰鬥風格——專橫、狂妄、野蠻、殘暴。\n對於敵人，無需憐憫。\n它們只是他重新走回權利至高點的，必要的階梯。"
  },
  CollectionHall_98644_LockTip = {
    Text = "完成意識潛遊「巨人的隕落」"
  },
  CollectionHall_98644_Title = {
    Text = "必要的殺伐"
  },
  CollectionHall_98645_Desc = {
    Text = "轉身離開的那一刻，埃爾頓彷彿又變成了那個剛剛出海的少年，藍天與一望無際的大海連接在一起，世界大得足夠裝下所有抱負與美夢。\n不一樣的是，這次他已清楚地見過了美夢實現的樣子，並擁有了一條通往那滿是白鳥的、夢鄉的歸途。"
  },
  CollectionHall_98645_LockTip = {
    Text = "完成調查行動·困難6-10解鎖"
  },
  CollectionHall_98645_Title = {
    Text = "白鳥之鄉"
  },
  CollectionHall_98646_Desc = {
    Text = "時間已至，銀月高懸。\n快把僵硬的腳尖點起，今夜要歡度這宴會時光。\n她已走到最後的旅程，而我們用胃袋為她送葬。\n一口給你，一口給我，從今往後誰都不會遺忘。"
  },
  CollectionHall_98646_LockTip = {
    Text = "完成調查行動 星辰篇3-11解鎖"
  },
  CollectionHall_98647_Desc = {
    Text = "神跡若有形狀，應如她合十的雙手。\n神明若有樣貌，應如她安寧的面龐。"
  },
  CollectionHall_98647_LockTip = {
    Text = "完成調查行動6-15解鎖"
  },
  CollectionHall_98647_Title = {
    Text = "純白神女"
  },
  CollectionHall_98648_Desc = {
    Text = "歡慶吧，我的朋友♪\n月光下的骸骨悄然綻放，一位摯愛被送上餐盤♪\n所有的賓客都已到來！唱呀，跳呀♪\n我們從不為亡靈祈禱，我們從不為屍首哀悼♪\n她將記憶交予了我，她將眼淚交予了我♪\n讓我們咽下她的魂靈與腐肉♪\n在死亡的盛宴中，我們再度重圓♪"
  },
  CollectionHall_98648_LockTip = {
    Text = "完成調查行動 星辰篇3-11解鎖"
  },
  CollectionHall_98648_Title = {
    Text = "食屍鬼之歌"
  },
  CollectionHall_98649_Desc = {
    Text = "人們因他的強大恐懼他、崇拜他，因他的殘酷憎恨他，唾棄他，更因他的失敗嘲諷他、放逐他。\n但弱者的聒噪毫無意義，巨人的目光隻為強者停留。\n於荒蕪的流亡之海，他將自身性命作為賭注，踏上尋求絕對力量的征程。"
  },
  CollectionHall_98649_LockTip = {
    Text = "完成意識潛遊「巨人的隕落」"
  },
  CollectionHall_98650_Desc = {
    Text = "他記得她。\n那個在風暴中被自己緊緊抱於襁褓中的孩子，最終被自己親手送往了深淵——用以與自己的良心一起，交換那個白鳥翱翔的夢境。\n他祈盼一生的美夢已經實現，接下來，是時候該用餘下的生命，去償還所有漆黑的罪孽。"
  },
  CollectionHall_98650_LockTip = {
    Text = "完成調查行動6-15解鎖"
  },
  CollectionHall_98650_Title = {Text = "償還"},
  CollectionHall_98651_Desc = {
    Text = "別離與死亡，都是世間無法逃離的常態。\n從無數犧牲與死亡中脫離，走向渺茫的前路，淡淡的悲傷縈繞在你的心頭。然而在目睹了生活於死亡之中的人們，目睹了將死亡賦予溫柔結局的王者後，你已不再畏懼未知的結局。\n一朵紫色的勿忘我飄落在你的肩頭，替他遙遙相送。\n你知道，無論如何，你的歸途並不孤獨。"
  },
  CollectionHall_98651_LockTip = {
    Text = "完成調查行動·困難 星辰篇3-10解鎖"
  },
  CollectionHall_98651_Title = {
    Text = "勿忘我的送別"
  },
  CollectionHall_98652_Desc = {
    Text = "「以你們的朋友、王、這片安眠之地主人的名義，我邀請你們——甦醒吧！回到你們眷戀的故土！將這些打擾我們親人安寧之人，永遠驅逐出去！」"
  },
  CollectionHall_98652_LockTip = {
    Text = "完成調查行動 星辰篇3-11解鎖"
  },
  CollectionHall_98652_Title = {
    Text = "萬靈之怒"
  },
  CollectionHall_98653_Desc = {
    Text = "她與祂，不可共存，於是一柄匕首刺入兩顆心臟，那是她向神明奉上的報償。"
  },
  CollectionHall_98653_LockTip = {
    Text = "完成調查行動6-15解鎖"
  },
  CollectionHall_98653_Title = {
    Text = "神明誕生之日"
  },
  CollectionHall_98654_Desc = {
    Text = "你從沒想到，與一位王者的對談是由一場共舞開始。\n強勢的入侵，遊離的試探，進攻與防守，對峙與退讓，你們在旋轉的衣襬中隱秘交鋒。\n一場交易優雅結束在最後的謝幕，王的髮絲翩翩垂落，你看到那雙霧氣縈繞的眼中閃爍著愉悅的笑意。\n咦？剛剛是不是被他牽著鼻子走了？"
  },
  CollectionHall_98654_LockTip = {
    Text = "完成調查行動 星辰篇3-11解鎖"
  },
  CollectionHall_98655_Desc = {
    Text = "你見過最可怖而褻瀆的啖食，卻是他們生命中最溫柔的重逢。"
  },
  CollectionHall_98655_LockTip = {
    Text = "完成調查行動 星辰篇3-11解鎖"
  },
  CollectionHall_98655_Title = {
    Text = "骸骨長眠之所"
  },
  CollectionHall_98656_Desc = {
    Text = "星星只是如常運轉在它的軌道，而塵埃中的生命已因此幾經沉淪。"
  },
  CollectionHall_98656_LockTip = {
    Text = "完成調查行動6-15解鎖"
  },
  CollectionHall_98656_Title = {
    Text = "倒錯的星辰"
  },
  CollectionHall_98657_Desc = {
    Text = "面對瞬間置人於死地的女巫，弱者恐懼、崇拜、皈依，祈求庇護。\n但他絕不。\n他看到了這股力量，渴求著這股力量，且無論需要付出怎樣的代價，都要得到這股力量。\n而後，他將東山再起，再次讓自己的名頌揚於非利士人所踏足的每一寸土地。"
  },
  CollectionHall_98657_LockTip = {
    Text = "完成意識潛遊「巨人的隕落」困難難度"
  },
  CollectionHall_99651_Desc = {
    Text = "<Bold:銀鱈魚24>\n每次路過那家炸魚餐廳，我都忍不住想要尖叫。\n為什麼受傷的總是銀鱈魚呢？我們甚至不是真正的鱈魚！\n肉質緊實、味道鮮美難道也是我們的錯嗎？\n\n<Bold:貓咪24>\n吸溜吸溜……喵，喵喵（贊成）！\n\n<Bold:銀鱈魚24>\n在雷歐王國，每分鐘就有一條銀鱈魚死於非命，成為人類的盤中餐。\n是的，就在我們說話的間隙，已經有10只銀鱈魚壯烈犧牲了。\n整整10只！父神在上，你聽到它們的慘叫聲了嗎？\n\n<Bold:貓咪24>\n呃……喵？喵喵喵，喵喵（哪裡）？\n\n<Bold:銀鱈魚24>\n只是個比喻罷了，傻瓜。你雖然蠢了點，卻有一顆金子般的心，能夠戰勝貓的獸慾和短視。\n聽著，接下來我有個計劃，需要你和我一起實施……\n\n——節選自《大約翰炸魚餐廳爆炸事件·案卷綜述：證詞B-03》。由於該時期伯利恆精神病院人滿為患，嫌犯被拒收，在倫蒂尼恩塔內關押23天后釋放。"
  },
  CollectionHall_99651_Title = {
    Text = "銀鱈魚的決心"
  },
  CollectionHall_99653_Desc = {
    Text = "為了等待「那個時刻」，少女沉睡於冰川之底。艾爾沃斯的千尺寒冰封凍了她的軀殼，卻未能全然封閉她的神識。\n那縷神識來自一個孩子，也來自一位母親。在祂女兒黑暗的子宮中，神明延續萬古長夢。\n二十五年的時光中，她思考過什麼，眷戀過什麼，期待過什麼嗎？\n時至今日，這些問題已經無人能夠回答。至於那位少女本人……她會否向身邊之人傾訴真心呢？就讓一切交給時間和未來吧。"
  },
  CollectionHall_99654_Desc = {
    Text = "唯有安靜死去的靈魂，才值得被細細品嘗。活人的掙扎只會讓味道變得雜亂無章。\n圓盤被端上來時仍有余溫，一顆心臟安穩地躺在中央，表面微微鼓起，彷彿剛剛跳動完最後一拍。兩枚眼球在一旁點綴，瞳孔中封存著死前那一秒鐘的驚愕，被燉煮成了溫順的乳白。\n他舉起刀，緩緩劃開心尖，卻忽然停住了。\n它的靈魂仍在嘶啞地尖叫，那一縷執念還在血管裡滯留，未能完全散去。他放下刀，合起雙手，靜靜地聆聽亡靈的聲音。\n這枚心臟來自一位死前飽受病痛折磨的詩人，長久的失意於死亡之中解脫，卻仍有對生的遺憾留存。他知道，要讓這顆心真正“入味”，需要給予美食足夠的尊重，唯一的辦法是等——\n等那纏繞在肉中的執念，於死亡中徹底崩解；等亡者記憶的最後回聲化為沉香，在血管壁上默默滲出。\n他將雙手優雅地交疊放在膝頭，閉上眼睛，深吸一口。\n香氣在空氣中緩緩擴散，那是一種複雜而溫柔的氣味，既有情人的顫抖，又有離別的苦澀。混雜著墨香、草藥味與一絲清晨露水般的膽怯。\n他靜靜坐在生命枝繁葉茂的樹下，等待著成熟的果實如期墜下。"
  },
  CollectionHall_99654_Title = {Text = "珍饈"},
  CollectionHall_99655_Desc = {
    Text = "一束放置太久而枯萎乾涸的花。\n永遠等不來它的主人。"
  },
  CollectionHall_99656_Desc = {
    Text = "從誕生起，雙子就不被允許隨意使用翅膀飛翔，他們背上生長的第二雙手臂更像是兩對展示聖子威儀的禮器，被時時刻刻規定著應有的姿態。\n小時候，波呂克斯是兩人之中最為愛護那雙翅膀的，每日梳理、塗抹精油，將那些羽毛養護得綢緞一般閃閃發亮。\n他總是趁著短暫的無人時刻，偷偷地撲騰起那雙羽翼初豐的翅膀，在卡斯托爾的驚駭中搖搖晃晃地離地，去觸碰那些繪著雕飾的穹頂。\n比起波呂克斯能使雙翼做出種種舞蹈般的靈活姿勢，卡斯托爾常常覺得自己的翅膀笨拙如兩塊木板。雙子每天就寢後的秘密時光裡，卡斯托爾就這樣靜靜地注視著波呂克斯於黑暗中跳躍、旋轉，於狹小的籠中模仿飛翔。\n「弟弟的翅膀真好看，不過我的話，可能一輩子也學不會飛翔了。」卡斯托爾想。\n於是在後來他們出逃的那一夜中，卡斯托爾第一次感受到晚風托舉著雙翼的涼爽與輕鬆。更加熟練的波呂克斯緊緊抓著飛得歪歪扭扭的哥哥，在高空開懷地大笑，飛出一條條俯衝、旋轉的弧線，就像一隻真正的、屬於天空的飛鳥。\n卡斯托爾偏過頭，看月光鍍在波呂克斯那雙纖長而有力的翅膀上，在羽毛間反射出令人目眩的青綠色光暈。\n「那一定是世界上最美的東西，無論面對什麼，我一定要保護波呂克斯，保護住那雙翅膀。」\n很快，艱難的野外生活讓波呂克斯的翅膀被野獸所傷，卡斯托爾心疼地拾起波呂克斯掉落的飛羽，將它收在了懷裡，默默發誓不會讓這種事發生第二次。但他不知道的是，日後這片孤單的羽毛將變成他最珍貴的東西，變成他最後留住的、關於那雙翅膀的遺物。"
  },
  CollectionHall_99657_Desc = {
    Text = "嘟——嘟——\n鳴笛聲中，遊輪在克珀珊特的指引下安全靠岸。\n乘客們歡笑著走下舷梯，舉帽向她感謝，水手們則湧了過來，表達誇讚。\n「幹得好，克珀珊特，要不是你提前預警，我們就要被風暴吞沒了。」\n「是啊，多虧你的正確指引，我們才沒有迷失在大海上！」\n水手們笑起來，拍她的肩，向她豎大拇指。\n事實上，克珀珊特始終無法適應這樣近距離的社交，她古板而基於理性的大腦，沒有「工作」與「職責」外的任何思考。\n於是，她只好將這也歸於「工作」與「職責」的一部分。\n「我只是完成了自己的工作而已。身為領航員，我的職責便是引導你們平安歸航。」\n客套而無趣的回復，但熟知她為人的水手們卻是大笑起來，向她道別，唱著船歌，勾肩搭背離開海港。\n「諾第留斯號終於能出航了。出發，諾第留斯號。」\n歌聲漸漸遠去，而克珀珊特仍留在岸邊。她在為未來的啟航做準備。\n大海喜怒無常，沒有領航員能保證自己每次都能勝利，她也是。但她願意為了增加哪怕一絲的勝算而付出無數的時間。\n檢查、巡邏、學習、核對，她的生命裡似乎只剩下了「工作」這一件事情。\n但她心甘情願，因為這一切，都是為那一刻，那成功領航，帶領大家平安歸來的那一刻。"
  },
  CollectionHall_99657_Title = {
    Text = "海上領航者"
  },
  CollectionHall_99658_Desc = {
    Text = "在無盡的深淵中，青色王座屹立，\n天幕低垂，星辰顫抖，萬物沉默。\n\n古老而又神秘的存在已然湮沒，\n世世代代，眾生在夢中頌歌。\n幽暗的水域，塵封的秘密，\n你的低語如潮水湧來，淹沒心靈的溝壑。\n\n在那無邊的夢境，先知與狂徒同遊，\n追尋無形的靈魂，恐懼與敬畏交織。\n青藻纏繞的軌跡，宛如命運的編撰，\n將迷失者的心，逐漸引向那青色王座。\n啊，宇宙的荒謬與真理，\n在夢與現實交錯之處，永恆的輝光閃爍。"
  },
  CollectionHall_99660_Desc = {
    Text = "人人都想戰勝命運，人人卻也畏懼命運。\n勇敢者發出戰鬥的怒吼，怯懦者發出順從的低吟，然而只有他發現了戰勝命運的秘密。\n那就是不斷邀請命運共赴賭局，催促命運開盤下一場。\n他從未畏懼過命運，因為他相信自己不會輸。\n他從不詢問要賭什麼，無論要擺上什麼籌碼他都毫不猶豫，包括自己的生命。\n憑藉一把輪盤賭的手槍，他嚇退了無數賭紅眼的手下敗將，成為了倫蒂尼恩臭名昭著的賭瘋子。\n真遺憾啊，沒有勢均力敵的對手是多麼寂寞。\n直到他遇到了那個男人。\n他打敗了無數凡人，終於坐上了命運的賭桌。\n很快他失去了自己的一切，又連本帶利地重獲了所有。\n直到重生為野獸時，他又在地上看到了那把終於射出最後一顆子彈的手槍。\n他將一顆子彈重新裝填，對著自己的頭再次按下了扳機。\n在一片寂靜中，他咧開了嘴。\n他還沒有輸，那麼總有一天他會贏到最後。\n他始終這樣相信著，即便要賭上所有。"
  },
  CollectionHall_99660_Title = {
    Text = "命運輪盤賭"
  },
  CollectionHall_99663_Desc = {
    Text = "那位神秘的女士是在葬禮後找上她的。\n「可憐的孩子，」她說，「你本不用受這無妄之災。」\n「你不知道嗎？在他害死米莉後，湯普森找上了他。那個名為愛德華的渣滓本該在去年就死了，但一個人給予了他幫助。」\n「你說為什麼？喔，這我又如何能知道呢。或許，他們本就是蛇鼠一窩，或許……那位罪人自己也不知道自己所做的是罪。他是怎麼說的來著？對，寬恕。對罪人的寬恕，對他們犯下的罪行的寬恕。」\n「他相信人都應該有第二次機會，你怎麼看？我們應當再給愛德華一次機會嗎，在他先後害死米莉，害死你姐姐，你母親之後？」\n「沒錯，這種人不會改，永遠也不會。所以，你知道怎麼做吧？」\n沒錯，這種人不會改，想要終結這種人，這種罪惡，這樣的悲劇，只能……\n將他們的欲望暴露，讓他們醜態盡顯，看他們彼此廝殺、彼此爭鬥，把他們徹底淨化——\n迎來無罪的淨土。"
  },
  CollectionHall_99663_Title = {Text = "鏡中人"},
  CollectionHall_99666_Desc = {
    Text = "茫茫多的羊群徘徊在茫茫大的草原上。\n這世上有太多太多的羊，而羊生來就是需要牧者引領的。\n她一直是這世界的先知，手中握著知識的權杖。\n她一直是一個好牧人，始終決心將羊群引向正確的道路。\n她用那杖管教羔羊，她用那杖趕走豺狼。\n她高舉著牧羊人的手杖，因她總能提前看清前路。\n曾經她引領羊群走向豐沛的水源、走向鮮嫩的草場。\n現在她目睹了世界的真相，於是引領羊群走向終極的懷抱。\n向這邊走，不要回頭。\n她笑著揮舞智慧的手杖。\n於是羊們看不到前方的懸崖。\n一隻，兩隻。\n羊兒墜下，牧人歡唱。\n請跟隨著無私的牧羊人吧，她已為你指明瞭最真切的前路。\n不必害怕，即便行過死蔭的幽谷，她的杖依然與你同在。\n直到一同步入湮滅的深淵。\n"
  },
  CollectionHall_99667_Desc = {
    Text = "祂伏行於無垠的混沌中，偶爾才對匍匐世間的眾生投去一縷瞥視。\n\n那些尚可入眼的，譬如索蕾爾，祂向他們提供難以被拒絕的「契約條款」。\n那些粗陋乏味的，祂褪去他們的肉身，留下一隻再也無法落淚的眼睛。\n這些眼睛又被喚作「蒙寵者」。\n\n它們在洞穴中忽明忽暗，既滿懷希望，又充滿絕望，等待祂的召喚。\n然而一千年過去，一萬年過去，蒙寵者繼續被遺忘在黑暗的角落。\n\n「那……你們一定是因為某種理由才被留下吧。你們的使命是什麼？」\n「我們在等待。」\n「等待什麼？」\n「等待……就只是等待而已。」\n「會感到痛苦嗎？」\n「恰恰相反。對大人的愛充盈我們全身。因為這是我們唯一能做的事。」\n「只有理解這一點，才能成為真正的信徒。」"
  },
  CollectionHall_99667_Title = {
    Text = "百萬蒙寵之眼"
  },
  CollectionHall_99668_Desc = {
    Text = "她的名字即是智慧的化身。\n她知曉世上的一切知識，是彌薩格所有學者嚮往的終極。\n只要能聆聽隻言片語，便能獲得醍醐灌頂的開悟。\n但她說，自己只是一個守門人。\n那是一扇什麼樣的門？\n沒有人見過那扇門，學者們便將其稱為真理。\n她是真理的守門人，是守護著彌薩格的雅典娜。\n塔薇並沒有否定這樣的猜測，只是始終如一地注視著這裡，注視著這個世界。\n無言而悲憫。\n如果你有一天看到了那扇門，你會看到門上有一隻極其熟悉的眼睛。\n那目光沉靜而恆久。\n穿透了時間，穿透了你的靈魂。"
  },
  CollectionHall_99668_Title = {
    Text = "真理之門"
  },
  CollectionHall_99670_Desc = {
    Text = "沐浴黑血而重獲新生的少女，在沙漠縈繞千年的風沙之中，托舉起豐穰母樹神聖的血之種。\n\n「只要這顆種子存活於世，樹的血脈就不會斷絕。」\n\n自那之後又是千年，這顆種子隨著樹的後裔見證了榮辱興衰，體驗了流離失所，經歷了不知所蹤，消亡而後重生，直到滔滔河水化為黏稠的黑血，它也完成了最後一次傳承。\n那是個熾熱滾燙而糾纏不休的吻，飽含尚未滿足的渴望和未及啟齒的離愁別緒，與溫暖的心跳一起將新的傳承者重重包裹。\n那瑪瑙般的色彩、白玉般的光澤，將隨著生命的搏動一起跨越黑色的終末。\n然後新世界的第一顆樹種，將在她的祝福下拔地而起，化作覆蓋天地的巨木。"
  },
  CollectionHall_99670_Title = {
    Text = "灼熱的吻別"
  },
  CollectionHall_99671_Desc = {
    Text = "獲得新生後的克萊門汀就像一隻懵懂的幼蟲，穿行於人間，穿行於不屬於她種族的繁華世界，感到迷茫，感到困惑。\n直到那帶來啟迪般的聲音響起——\n「請問，你是夏洛蒂醫生嗎？我來找、找夏洛蒂醫生做心理諮詢……」\n克萊門汀終於回過神。她不在乎夏洛蒂是誰，只是好奇來者口中的新名詞：「心理諮詢」。\n但她是個成熟的獵手，絕不會暴露自己的無知，因此她笑了起來，彷彿她就是夏洛蒂，就是來者口中的救贖。\n淚水、折磨、無助，無需撩撥，來者就已經榨出了靈魂深處的痛苦。\n離開前，對方一臉輕鬆地看向克萊門汀，感慨：「謝謝你願意傾聽這些。我感覺自己好多了。」\n然後，就是關門聲，以及克萊門汀因初次品嘗到甘美而響起的笑聲。\n這笑聲起初些微，猶如幼蟲的嗡鳴，隨後越來越大，仿若成蟲的嘶叫。\n而於這笑聲裡，名為克萊門汀的蟲族，也迅速成熟。\n隨後的一切，順理成章。她成為了心理醫師，帶著笑容與靈擺，深入一個個患者的內心。\n她依舊行走於人間，依舊不屬於這個繁華的世界，但卻不再迷茫和困惑。\n因為整個人間和世界，都是她的催眠獵場。"
