  CollectionHall_99673_Desc = {
    Text = "「還不夠完美，今晚再練十遍，你的天賦平平，想進入樂團就要更加勤奮，知道嗎？」\n「是，父親。」\n什麼樣的演奏才叫完美？\n他的雙手不停飛舞，不容許自己出現一個失誤。\n他斥責自己的雜念，鄙夷自己的平庸。\n無數音符環繞在眼前，每天，每天，他生活中的一切只有音樂。\n好在他每天都離完美的演奏距離更近了一些，他望著夢中道路盡頭的光芒，又彷彿永遠也無法觸及。\n渴求完美已經刻入他的靈魂，然而不是所有人都願意這樣。\n「為陛下、為世人呈現最完美的音樂，這難道不是樂團的職責嗎？」\n他望著一張張暗含不滿的臉，如同鄙視曾經的自己。\n父親，宮廷樂團也不過如此。\n他拋下了曾經仰望的目標，執拗地繼續走上追尋完美的路。\n他無法停下雙手去拉住他們的手，正如他無法停住曾經那個自己的手。\n每天，每天，他都在不停演奏著。\n音樂就是他的生命。\n除了音樂，他一無所有。"
  },
  CollectionHall_99674_Desc = {
    Text = "她站上山峰，舉起手中的黑刺。\n在漫天的風雪裡，她迎上了那座瘋狂的山脈，迎上了自己被拋棄、被背叛、被踐踏的命運。\n她終將勝利，冰雪終將消融，到那時，她將以一個嶄新的姿態，重現於世。她是這樣說的。\n艾爾沃斯是極寒之地，那裡的風雪終年不散。這是常識。就像再強大的戰士也無法與崇高的存在抗衡，就像再強大的人也無法戰勝自己的命運。\n可那雪山終究還是消融了，不是嗎？"
  },
  CollectionHall_99676_Desc = {
    Text = "第一任王夫來自伊薩拉烏。\n他長著一對伊薩拉烏人特有的眼珠，淡淡的金色，在遠空漆黑的夜裡閃耀著微弱的光。\n但那光芒隨著伊薩拉烏的陷落而消失，旺達從漆黑的泥沼中撈起最後的載體，珍而重之地仔細收藏。\n她與第二、三任王夫相遇於弗蘭高地。\n那是一對貪婪的領主雙胞胎，旺達曾希望借助他們的力量，重建那失落的湖中之城。\n她受到了欺騙，因此，脊刺深深埋入了他們的骨髓。在麻痺中，旺達取出了那兩對卑賤而無禮的眼睛，而後留下它們，作為自己來過的痕跡。\n第四任王夫，旺達記得他叫「約翰」。\n他是個無趣的啞巴，但伺候得她足夠舒心。更讓她開心的是，「約翰」也有雙淡金色的眼睛，和她的幾乎一模一樣。\n\n「把王夫的眼睛剮出來吧。」\n「謹遵您的希望……但，王夫是做錯了什麼嗎？」\n旺達搖晃著杯中渾濁的水，感受毒素在舌尖徜徉。真是個蠢材，連下毒都做得如此粗劣。\n看著「約翰」爬滿融蝕的身體，她想起了還在遙遠星外時，目送著她離開了故鄉的一雙雙死寂之眸。\n和「約翰」此時的眼睛如出一轍。\n「……就說他，缺少幽默感吧。」"
