  CollectionHall_99683_Desc = {
    Text = "王座的幻夢中，王聆聽神明的啟示：\n利莫里亞的風暴將平息。利莫里亞的深淵將消逝。\n以夢境為庭，以星辰為燭。王將庇護他良善的子民，帶來神的國度。\n\n吾主之信徒，敞開你的心懷，接納吾主。\n在遙遠的黯淡深淵，古老的偉大靈魂沉眠，傾聽諸神的低語。\n祂的意志如星辰之網交織，祂在永恆的虛無中候汝入夢。\n\n風暴靜伏，水波不興；\n地震平息，大地安寧。\n災禍在祂的寧靜夢境中化為虛無，\n子民在祂的庇護下安然無恙。\n願我們的歌聲穿越深海，願祂賜予我們免受災難的神諭，\n領我們前往無盡的安寧與極樂之境。\n我們的信念與祂同在，直至星辰消亡，直至時間盡頭。\n"
  },
  CollectionHall_99683_Title = {
    Text = "深海的呼喚"
  },
  CollectionHall_99684_Desc = {
    Text = "開始向食屍鬼轉變的第七日，他在四肢日漸糜爛的劇痛中呻吟。每一次細微挪動都牽扯著敏感神經，迸發出撕裂般的痛楚……與令人戰慄的靈感火花。\n然而，惶惑的陰影始終籠罩著這位藝術家——究竟要怎樣的畫筆，才能描繪出那最為極致的真實？\n皮克曼虛弱的眼睛四處搜尋著，從宅邸邊的磚石到墳墓上的樹枝，終於，目光鎖定在他萎縮潰爛的右腿中那截裸露的白骨。\n如同聽見了某種神聖的召喚，皮克曼將腿骨取出，指腹一遍遍磨去粘連的血肉，將它製成堅硬的畫筆。\n他將筆尖磨成鋒利的獠牙，但筆尖在咬上畫布前，卻先刺入了主人枯瘦的指尖。皮克曼吃痛鬆手，畫筆逃脫了他的控制。\n飛舞！跳躍！旋轉！它在畫布上狂舞，刻下錯亂癲狂的線條。線條增殖瘋長，拖曳出一團不斷膨脹、形態詭異的暗色污跡，緩慢而堅決地噬咬住皮克曼的咽喉。\n瞬間的狂喜如利刺穿透他殘存的心臟——那腫脹的器官、混沌不堪的形態，令他顫慄驚怖，卻也復甦了行將枯萎的感官。它們以顛倒無序的方式，直接、銳利地昭示著痛苦、怪異與欲望，爆發出不加掩飾的震撼力量。\n在這倒錯之中，皮克曼彷彿更接近了「美」的聖境。\n待一切平息，皮克曼伸出已被腐蝕的利爪，反復摩挲著那支蒼白的畫筆。這具尚存人形的軀殼裡，噴薄出更熾熱、更迫切的渴望。\n他將與這只畫筆一同，完成那幅曠世畫作的最後一筆。"
  },
  CollectionHall_99684_Title = {
    Text = "渴求的畫筆"
  },
  CollectionHall_99687_Desc = {
    Text = "「聖子是持燈者注視之人，生而受到祂的眷顧。」\n「聖子應傳播祂的旨意，將光明賜予虔誠的義人。」\n「聖子需保持靈魂的潔淨。」\n「聖子應戒除俗欲、虔誠修行，全心侍奉光明。」\n「聖子不可多言、不可妄語。」\n「聖子應遠離罪孽、遠離有罪之人，不可被污濁的靈魂污染。」\n「聖子……」\n從他有記憶開始，一條又一條戒律就如鎖鏈般束縛著他，將他捧上尊崇的高臺，又令他不可失儀、不可低頭、不可放縱喜怒。\n他被披上寬大而華麗的衣袍，簇擁在無數侍從之中，按照要求扮演那個神聖的代表，俯視著虔誠的信徒匍匐跪倒、小心親吻他的衣角。\n聖子本應如此，無人在意那副高傲而不變的面容下，究竟有怎樣的情緒與喜好。\n正如他習慣了那高傲的笑容，在無人之時亦不知自己真正想擺出怎樣的表情。\n「波呂克斯聖子，您該前往賜福儀式了。」低垂頭顱的侍女恭敬地安排著他一成不變的生活。\n他轉過身，昂起頭，露出那同樣一成不變的笑容，如同親手戴上一張神聖的面具。\n那些迷茫、空虛和寂寞，都被遮蓋在面具之下，如同從未存在。"
  },
  CollectionHall_99687_Title = {
    Text = "聖子尊容"
  },
  CollectionHall_99691_Desc = {
    Text = "故事中存有魔法，弗朗西斯曾這麼告訴莉莉。\n那時她會捧著故事書坐在窗邊，初夏的陽光將白大褂烤得微微發燙，散發出溫暖柔和的馨香。\n她語調輕緩，娓娓道來，但昨夜長時間精神專注於手術積累了太多疲勞，故事尚未抵達終點，弗朗西斯便沉沉睡去。\n莉莉從未因此責怪母親，因為母親倚靠窗沿的疲憊睡顏如此令人安心。\n\n如今膠片代替書本承載了故事與魔法，正如新的膠片取代因孩子們的不慎而曝光破損的膠片，正如新夥伴們的嬉鬧取代了過往溫暖和疼痛交雜的小憩時光。\n但那些被埋藏的回憶依然如曝光的膠片般，沉睡在某個不為人知的角落，縱使永不見天日，依然熠熠生輝。"
  }
})
